package com.ascent.climb.data.i18n

/**
 * Banco de preguntas en español (629 preguntas / 3.954 entradas).
 * Claves idénticas a PackEnQuiz.kt; cifras, dosis y escalas sin cambios.
 */

internal val PACK_ES_QUIZ: Map<String, String> = mapOf(

    // ---------- l1 Entender el riesgo en montaña ----------
    "q.l1#0.p" to "¿Cuál de los siguientes es un peligro objetivo?",
    "q.l1#0.o0" to "Caídas de piedras y de hielo",
    "q.l1#0.o1" to "Un error de juicio",
    "q.l1#0.o2" to "Quedarse sin energía",
    "q.l1#0.o3" to "Una mentalidad competitiva",
    "q.l1#0.e" to "Los peligros objetivos son factores del medio que no cambian con tu nivel ni con tu actitud: caídas de piedras, caídas de hielo, aludes, meteorología, grietas. Los otros tres son peligros subjetivos que el entrenamiento y la disciplina pueden controlar.",

    "q.l1#1.p" to "Al aumentar la altitud, ¿cómo cambian la temperatura del aire y la presión parcial de oxígeno?",
    "q.l1#1.o0" to "La temperatura sube y la presión parcial de oxígeno baja",
    "q.l1#1.o1" to "La temperatura baja unos 6,5 °C por cada 1.000 m, y la presión parcial de oxígeno baja con ella",
    "q.l1#1.o2" to "Ninguna de las dos cambia",
    "q.l1#1.o3" to "La temperatura baja y la presión parcial de oxígeno sube",
    "q.l1#1.e" to "Por cada 1.000 m de ascenso el aire se enfría unos 6,5 °C, mientras la presión atmosférica y la presión parcial de oxígeno bajan al mismo ritmo. Por eso el mal de altura y el frío llegan juntos.",

    "q.l1#2.p" to "¿Qué afirmación sobre el papel del entrenamiento es correcta?",
    "q.l1#2.o0" to "Un buen entrenamiento elimina todos los peligros objetivos",
    "q.l1#2.o1" to "El entrenamiento reduce los peligros subjetivos, pero no puede eliminar los objetivos",
    "q.l1#2.o2" to "Los peligros objetivos son pura cuestión de suerte",
    "q.l1#2.o3" to "Si estás en buena forma no hay peligro",
    "q.l1#2.e" to "El entrenamiento técnico mejora cómo juzgas y cómo reaccionas, pero las piedras, los aludes y el tiempo no desaparecen porque tengas experiencia. La actitud correcta ante los peligros objetivos es evitarlos y mantener una salida.",

    "q.l1#3.p" to "¿Por qué los alpinistas insisten en dejar margen en lugar de arreglar las cosas sobre la marcha?",
    "q.l1#3.o0" to "Porque el margen aumenta tu porcentaje de cumbres",
    "q.l1#3.o1" to "Porque el margen actúa al principio de la cadena de accidente, mientras que arreglar las cosas ocurre en el último eslabón",
    "q.l1#3.o2" to "Porque el margen ahorra dinero",
    "q.l1#3.o3" to "Porque la normativa exige una reserva",
    "q.l1#3.e" to "El margen adopta muchas formas: tiempo, energía, víveres, una ventana meteorológica. Lo que comparten es que creas ese espacio cuando todavía puedes elegir. La reparación siempre empieza después de que algo haya fallado, cuando quedan pocas opciones.",

    "q.l1#4.p" to "¿Cuál es la mejor medida del nivel de una cordada?",
    "q.l1#4.o0" to "La mayor altitud que alguien haya alcanzado",
    "q.l1#4.o1" to "Cuántas salidas hace al año",
    "q.l1#4.o2" to "Si es capaz de retirarse con seguridad cuando hace falta y de mantener el riesgo aceptable",
    "q.l1#4.o3" to "El valor total de su material",
    "q.l1#4.e" to "Un historial de cumbres solo demuestra que algo funcionó una vez; la capacidad de retirarse demuestra control. En alta montaña la próxima oportunidad siempre llega, un accidente grave no. Lo que realmente distingue a los equipos es lo bien que deciden en condiciones desfavorables.",

    "q.l1#5.p" to "La normativa china de alpinismo limita la actividad a «picos independientes». ¿Cómo se define un pico independiente en un mapa topográfico?",
    "q.l1#5.o0" to "Cualquier macizo de más de 5.000 m",
    "q.l1#5.o1" to "Un macizo rodeado por una curva de nivel cerrada",
    "q.l1#5.o2" to "Un macizo con un glaciar visible",
    "q.l1#5.o3" to "Un macizo que nadie ha coronado",
    "q.l1#5.e" to "En un mapa topográfico un pico independiente aparece como una curva de nivel cerrada, lo que significa que el macizo cae por todos sus lados. Esa definición separa el «alpinismo» de «subir a un punto alto», y sostiene cómo se administra y se contabiliza la actividad.",

    "q.l1#6.p" to "¿Cuál es el patrón más habitual en los análisis de accidentes?",
    "q.l1#6.o0" to "Casi todos los accidentes vienen de un único error grave",
    "q.l1#6.o1" to "Los accidentes graves suelen ser varios errores pequeños acumulados",
    "q.l1#6.o2" to "Los accidentes no tienen relación con la experiencia",
    "q.l1#6.o3" to "El fallo del material es la causa principal",
    "q.l1#6.e" to "Un accidente típico es una cadena: una decisión de ruta demasiado optimista, luego ir más tarde de lo previsto, luego simplificar la protección para ganar tiempo, luego la fatiga degradando el movimiento. Rompe cualquier eslabón y el accidente no ocurre — por eso el margen vence a la reparación.",

    "q.l1#7.p" to "[Elección múltiple] ¿Cuáles de estos son peligros objetivos en montaña?",
    "q.l1#7.o0" to "Caídas de piedras y de hielo",
    "q.l1#7.o1" to "Aludes",
    "q.l1#7.o2" to "Un cambio brusco del tiempo",
    "q.l1#7.o3" to "Las grietas",
    "q.l1#7.o4" to "Una mentalidad competitiva",
    "q.l1#7.e" to "Los cuatro primeros no cambian con tu nivel ni con tu actitud — son propiedades del entorno. Contra los peligros objetivos solo puedes evitarlos, elegir el momento y mantener una salida. Los peligros subjetivos —mal juicio, mala preparación, compararse con otros— son la parte que el entrenamiento sí puede reducir.",

    "q.l1#8.p" to "Antes de una ascensión de alta montaña, ¿qué tres cosas debes confirmar primero?",
    "q.l1#8.o0" to "Forma física, material, itinerario y seguro",
    "q.l1#8.o1" to "La reputación de tus compañeros, la fama del pico, las marcas del material",
    "q.l1#8.o2" to "Fotos, vídeo y tu plan de redes sociales",
    "q.l1#8.o3" to "El pronóstico, los vuelos y los hoteles",
    "q.l1#8.e" to "La forma física decide si puedes terminar, el material decide si sobrevives a malas condiciones, y el itinerario más el seguro deciden si existe ayuda cuando algo falla. Los tres están totalmente bajo tu control antes de salir — por eso no hay excusa cuando fallan.",

    "q.l1#9.p" to "¿Por qué los alpinistas experimentados siguen metiéndose en problemas?",
    "q.l1#9.o0" to "Porque la experiencia eleva poco a poco lo que aceptas como riesgo normal",
    "q.l1#9.o1" to "Porque la gente con experiencia intenta rutas más difíciles",
    "q.l1#9.o2" to "Porque la experiencia no tiene nada que ver con la seguridad",
    "q.l1#9.o3" to "Porque la gente con experiencia se cansa antes",
    "q.l1#9.e" to "Se llama normalización del riesgo: después de pasar muchas veces por las mismas condiciones sin daño, las reclasificas inconscientemente como «seguras» y amplías el criterio poco a poco. Cuanta más experiencia tienes, más necesitas reglas explícitas —una hora de regreso, por ejemplo— para contener tu juicio.",

    // ---------- l2 Equipo básico: piolet y crampones ----------
    "q.l2#0.p" to "¿Para qué sirve principalmente un piolet tipo T (técnico)?",
    "q.l2#0.o0" to "Para pasear por pendientes suaves de nieve",
    "q.l2#0.o1" to "Para paredes de hielo inclinadas y escalada técnica",
    "q.l2#0.o2" to "Solo para fotografía",
    "q.l2#0.o3" to "Solo para acampar en nieve",
    "q.l2#0.e" to "El mango de un piolet tipo T se puede clavar en el hielo y aguanta un tirón, lo que sirve en hielo inclinado. El mango tipo B es más débil: está calculado para cargas de marcha y detención y no debe usarse como anclaje técnico.",

    "q.l2#1.p" to "¿Qué clase de crampón corresponde a una bota B3 totalmente rígida?",
    "q.l2#1.o0" to "C1, con correas completas",
    "q.l2#1.o1" to "C2, correa delante y enganche detrás",
    "q.l2#1.o2" to "C3, enganche total",
    "q.l2#1.o3" to "Cualquier clase sirve",
    "q.l2#1.e" to "Una bota B3 tiene rebordes delantero y trasero, y un crampón C3 de enganche total es la combinación más segura. B1 con C1, B2 con C2 y B3 con C3 es la regla básica de correspondencia.",

    "q.l2#2.p" to "¿Qué ocurre si pones crampones C3 de enganche total en una bota blanda de senderismo?",
    "q.l2#2.o0" to "Ningún problema, y además se colocan más rápido",
    "q.l2#2.o1" to "La bota se deforma bajo carga, los enganches pierden agarre y el crampón puede salirse: una configuración peligrosa",
    "q.l2#2.o2" to "Caminarás más rápido",
    "q.l2#2.o3" to "Solo queda mal estéticamente",
    "q.l2#2.e" to "Los crampones de enganche total cuentan con una bota rígida para mantener su forma. En una bota blanda, la bota flexa, los enganches pierden mordida y el crampón puede salirse en una pendiente inclinada. Es un desajuste claramente peligroso.",

    "q.l2#3.p" to "La longitud del piolet se elige normalmente por estatura. ¿Qué se recomienda para un alpinista de unos 173–180 cm?",
    "q.l2#3.o0" to "50 cm",
    "q.l2#3.o1" to "55 cm",
    "q.l2#3.o2" to "60 cm",
    "q.l2#3.o3" to "70 cm",
    "q.l2#3.e" to "Referencia habitual: por debajo de unos 157 cm, 50 cm; de 157 a 170 cm, 55 cm; de 173 a 180 cm, 60 cm; por encima de 183 cm, 65–70 cm. Solo la longitud correcta permite clavar el pico con eficacia en la nieve durante la detención.",

    "q.l2#4.p" to "Al elegir crampones, ¿cuál es el requisito más básico y más importante?",
    "q.l2#4.o0" to "Que sean lo más ligeros posible",
    "q.l2#4.o1" to "Que encajen en la bota, preferiblemente de acero de 12 puntas y con placas antizueco",
    "q.l2#4.o2" to "Que el color combine con el resto del equipo",
    "q.l2#4.o3" to "Cuantas más puntas mejor — 20 o más",
    "q.l2#4.e" to "Un crampón vale lo que vale su unión con la bota. Más puntas no siempre es mejor; lo que importa es el encaje y las placas antizueco (que evitan que la nieve se apelotone bajo el pie). Un mal encaje es la forma clásica de perder un crampón en una pendiente inclinada.",

    "q.l2#5.p" to "[Situación] Para un día de cumbre técnico en altura con crampones, piolet, una capa de abrigo de repuesto, comida, agua y botiquín de emergencia, ¿qué volumen neto de mochila se recomienda?",
    "q.l2#5.o0" to "15–25 litros",
    "q.l2#5.o1" to "35–50 litros",
    "q.l2#5.o2" to "60–75 litros",
    "q.l2#5.o3" to "90 litros o más",
    "q.l2#5.e" to "Para «material técnico propio + abrigo de repuesto + botiquín de emergencia», 35–50 litros es el rango habitual, preferiblemente con un bolsillo específico para crampones.\nPero el volumen no es fijo: en una pendiente de nieve muy transitada, con el equipo de grupo a cargo del personal y tiempo estable, una mochila de cumbre de 15–25 litros puede ser suficiente; si tienes que cargar tú la tienda o las cuerdas, necesitas más.\nEl criterio es siempre lo que realmente tienes que llevar, no un número universal.",

    "q.l2#6.p" to "¿Cuál es la finalidad principal de la dragonera del piolet?",
    "q.l2#6.o0" to "Decoración e identificación de cordada",
    "q.l2#6.o1" to "Evitar que pierdas el piolet, para que sigas pudiendo controlarlo tras un resbalón",
    "q.l2#6.o2" to "Añadir peso para que el piolet presione más",
    "q.l2#6.o3" to "Colgar el piolet en la mochila",
    "q.l2#6.e" to "La dragonera importa en el instante del resbalón: en cuanto el piolet sale de tu mano pierdes lo único que puede frenar. La dragonera lo mantiene contigo a través de movimientos violentos — por eso tantos manuales insisten en llevarla.",

    "q.l2#7.p" to "[Elección múltiple] ¿Qué factores importan al elegir crampones?",
    "q.l2#7.o0" to "Cómo se fijan a la bota (correa / semi-enganche / enganche total)",
    "q.l2#7.o1" to "Si el número y la forma de las puntas se ajustan al terreno",
    "q.l2#7.o2" to "Si tienen placas antizueco",
    "q.l2#7.o3" to "La fiabilidad de las fijaciones y las correas",
    "q.l2#7.o4" to "Si el color combina con la mochila",
    "q.l2#7.e" to "Los cuatro primeros importan. La fijación decide si se pueden poner, la forma de las puntas decide si sirven al terreno (puntas frontales para hielo inclinado, puntas planas para nieve suave), las placas deciden si la nieve se apelotona debajo y las fijaciones deciden si se quedan puestas.",

    "q.l2#8.p" to "¿Por qué revisar las correas y fijaciones de los crampones antes de cada salida?",
    "q.l2#8.o0" to "Para mantener el material ordenado",
    "q.l2#8.o1" to "Porque que un crampón se salga en una pendiente inclinada es una amenaza directa para la vida",
    "q.l2#8.o2" to "Porque las correas envejecen y cambian de color",
    "q.l2#8.o3" to "Porque la disciplina de cordada lo exige",
    "q.l2#8.e" to "Los crampones tienden a fallar en el peor momento: en una cara inclinada, durante un traverso, en el primer paso con peso. Perder el agarre bajo un pie desplaza tu centro de masas al instante. Revisar cuesta casi nada; la consecuencia es totalmente desproporcionada.",

    "q.l2#9.p" to "¿Qué afirmación sobre la forma del pico del piolet es correcta?",
    "q.l2#9.o0" to "Todos los picos de piolet son rectos",
    "q.l2#9.o1" to "Un pico curvado entra con más facilidad en el hielo y es menos probable que salte, por eso es habitual en herramientas técnicas de hielo",
    "q.l2#9.o2" to "Un pico curvado sirve solo para caminar por nieve",
    "q.l2#9.o3" to "La forma del pico no tiene relación con el uso",
    "q.l2#9.e" to "Un piolet de montaña largo suele tener el pico curvado hacia abajo, de modo que muerde al golpear o al detener y no se sale fácilmente. Las herramientas de escalada en hielo tienen picos más afilados e inclinados para colocarlos rápido y retirarlos con facilidad en hielo vertical. El uso dicta la forma.",
    // ---------- l3 Calzado y capas ----------
    "q.l3#0.p" to "¿Cuál es la principal ventaja de las botas dobles frente a las simples?",
    "q.l3#0.o0" to "Son más ligeras",
    "q.l3#0.o1" to "Son más cálidas y la bota interior se puede sacar para secarla",
    "q.l3#0.o2" to "Son más baratas",
    "q.l3#0.o3" to "Son más fáciles de poner y quitar",
    "q.l3#0.e" to "La bota interior se saca, se puede secar contra el cuerpo o dentro del saco durante la noche y no se congela — lo decisivo en rutas altas de varios días. El precio es peso y coste.",

    "q.l3#1.p" to "¿Cuál es la especificación más importante de unas gafas de nieve?",
    "q.l3#1.o0" to "Lo oscuro que sea el cristal",
    "q.l3#1.o1" to "Protección ultravioleta UV400",
    "q.l3#1.o2" to "La marca de la montura",
    "q.l3#1.o3" to "Si el cristal es espejado",
    "q.l3#1.e" to "La nieve refleja muchísima radiación ultravioleta. UV400 significa un bloqueo casi total de los UV y es la clave para prevenir la ceguera de la nieve; el tinte del cristal solo afecta al confort visual.",

    "q.l3#2.p" to "¿Qué importa al elegir la talla de una bota de alpinismo?",
    "q.l3#2.o0" to "Que quede más apretada, para que el pie no se desplace",
    "q.l3#2.o1" to "Que los dedos no toquen la puntera, con un poco de holgura para que las bajadas no los lesionen",
    "q.l3#2.o2" to "Que sea más grande, para poder llevar calcetines más gruesos",
    "q.l3#2.o3" to "Exactamente la misma que tu zapato de diario",
    "q.l3#2.e" to "En una bajada el pie se desliza hacia delante. Si los dedos chocan contra la puntera, una bajada larga puede magullarlos o incluso hacer perder una uña. Deja algo de holgura y bloquea el talón con el cordón.",

    "q.l3#3.p" to "¿Cuál es el rasgo de diseño clave de una bota de cumbre de 8.000 m?",
    "q.l3#3.o0" to "Que sea lo más ligera posible",
    "q.l3#3.o1" to "Un forro aislante desmontable con un corte impermeable, cortavientos y resistente a la abrasión",
    "q.l3#3.o2" to "Que sea de una sola capa",
    "q.l3#3.o3" to "Cuanto más blanda la suela, más cómoda",
    "q.l3#3.e" to "Un forro desmontable se puede sacar de noche para secarlo o mantenerlo caliente contra el cuerpo, de modo que nunca se congela — la clave para que los pies sigan funcionando en rutas altas de varios días. El corte suele ser un laminado de tres capas por impermeabilidad, resistencia al viento y durabilidad.",

    "q.l3#4.p" to "¿Por qué la primera capa nunca debe ser de algodón?",
    "q.l3#4.o0" to "Porque el algodón es demasiado caro",
    "q.l3#4.o1" to "Porque el algodón retiene el sudor y se seca despacio, así que el tejido húmedo contra la piel acelera la pérdida de calor",
    "q.l3#4.o2" to "Porque el algodón provoca alergias",
    "q.l3#4.o3" to "Porque el algodón no transpira y por eso da más frío",
    "q.l3#4.e" to "La función de la primera capa es alejar el sudor de la piel. El algodón absorbe agua y apenas la suelta, así que el tejido húmedo y frío sigue robando calor. Elige poliéster o lana merina, que transportan la humedad rápido.",

    "q.l3#5.p" to "¿Qué material se recomienda para una bota de 6.000 m?",
    "q.l3#5.o0" to "Cuero normal",
    "q.l3#5.o1" to "Un material impermeable y transpirable como GORE-TEX",
    "q.l3#5.o2" to "Tejido de algodón puro",
    "q.l3#5.o3" to "Una carcasa de plástico rígido",
    "q.l3#5.e" to "Una bota de 6.000 m busca ligereza, comodidad y agarre, y además tiene que caminar bien durante horas. Una membrana impermeable y transpirable como GORE-TEX deja fuera el agua y permite salir el vapor — impermeable sin transpirabilidad solo encierra el sudor, y acabas mojado y frío igual.",

    "q.l3#6.p" to "¿Qué material deben evitar los calcetines de alpinismo?",
    "q.l3#6.o0" to "Lana merina",
    "q.l3#6.o1" to "Fibras sintéticas como el poliéster",
    "q.l3#6.o2" to "Algodón",
    "q.l3#6.o3" to "Nailon",
    "q.l3#6.e" to "La misma lógica que la primera capa: el algodón absorbe el sudor y apenas lo suelta, así que el tejido húmedo y frío sigue drenando calor y dispara el riesgo de ampollas. Elige sintéticos (sin algodón) o merina, con un corte hasta la rodilla que equilibre abrigo y circulación.",

    "q.l3#7.p" to "¿Cuál es el enfoque correcto al elegir polainas?",
    "q.l3#7.o0" to "Usar las mismas polainas cortas en todas las salidas",
    "q.l3#7.o1" to "Para picos altos, preferir polainas largas que impidan la entrada de nieve en la bota",
    "q.l3#7.o2" to "Las polainas son solo para la lluvia",
    "q.l3#7.o3" to "Cuanto más cortas y ligeras, siempre mejor",
    "q.l3#7.e" to "Las polainas son un tubo de tejido sobre la bota que impide la entrada de nieve y suciedad. Con nieve profunda de altura, unas cortas quedan sepultadas enseguida y no sirven, por eso se recomiendan largas; las cortas van bien en rutas de trekking conocidas y con poca nieve de estilo alpino.",

    "q.l3#8.p" to "¿Para qué sirven las botas de campamento y las zapatillas, y qué necesitan?",
    "q.l3#8.o0" to "Para la cumbre; deben ser muy rígidas",
    "q.l3#8.o1" to "Para moverse por el campamento; deben ser cálidas, impermeables y antideslizantes",
    "q.l3#8.o2" to "Para escalada técnica; necesitan puntas frontales",
    "q.l3#8.o3" to "Puramente decorativas; opcionales",
    "q.l3#8.e" to "Permiten que tus botas principales descansen: te cambias a botas de campamento o zapatillas dentro de la tienda para que los forros se sequen y los pies no estén comprimidos todo el día. No cumplen función técnica, pero influyen directamente en el estado de tus pies a la mañana siguiente.",

    "q.l3#9.p" to "¿Qué aporta un calcetín de caña alta en una expedición larga?",
    "q.l3#9.o0" to "Da un aspecto más profesional",
    "q.l3#9.o1" to "Mantiene el pie caliente y favorece la circulación",
    "q.l3#9.o2" to "Es más fácil de poner",
    "q.l3#9.o3" to "Añade grosor de amortiguación",
    "q.l3#9.e" to "En jornadas largas los pies se hinchan y la circulación sufre. Un calcetín hasta la rodilla cubre la pantorrilla, la calienta y, mediante una presión uniforme, ayuda al retorno venoso — lo que en una salida de varios días decide si tus pies siguen funcionando al tercer día.",

    // ---------- l4 Técnica de progresión en nieve ----------
    "q.l4#0.p" to "¿Cuál es la forma correcta de escalonar en la nieve?",
    "q.l4#0.o0" to "Dar zancadas largas para necesitar menos pasos",
    "q.l4#0.o1" to "Hacer escalones pequeños con ritmo constante y mantener el centro de masas estable",
    "q.l4#0.o2" to "Usar solo las puntas de los pies",
    "q.l4#0.o3" to "Clavar el talón en la nieve todo el camino",
    "q.l4#0.e" to "Escalones pequeños con ritmo constante mantienen estable el centro de masas y gastan menos energía. Las zancadas largas balancean el cuerpo de un lado a otro: la forma más fácil de perder el equilibrio en una pendiente de nieve.",

    "q.l4#1.p" to "¿Con qué mano se lleva el piolet al avanzar?",
    "q.l4#1.o0" to "Con la mano del lado de abajo",
    "q.l4#1.o1" to "Con la mano del lado de arriba, listo para pasar directamente a la detención",
    "q.l4#1.o2" to "Con ninguna mano",
    "q.l4#1.o3" to "En el exterior de la mochila",
    "q.l4#1.e" to "Llévalo en la mano del lado de arriba en posición de piolet-bastón, con el pico hacia atrás y la cabeza hacia delante. Si resbalas puedes presionar hacia la detención sin cambiar de mano — y esos pocos segundos de cambio suelen ser toda la ventana del accidente.",

    "q.l4#2.p" to "¿Qué técnica alivia la falta de aire en altura durante la subida?",
    "q.l4#2.o0" to "Aguantar la respiración mientras avanzas",
    "q.l4#2.o1" to "Respiración a presión: inspiración profunda y espiración enérgica, sincronizadas con el ritmo de los pasos",
    "q.l4#2.o2" to "Respiración rápida y superficial",
    "q.l4#2.o3" to "Respirar a través del guante",
    "q.l4#2.e" to "La respiración a presión eleva la presión positiva en los pulmones al espirar activamente, lo que mejora el intercambio gaseoso. Combinada con el ritmo de los pasos —una respiración cada dos o tres pasos, por ejemplo— reduce notablemente la sensación de asfixia de la altura.",

    "q.l4#3.p" to "Cuando una cordada sube por una pendiente de nieve, ¿cómo se debe escalonar?",
    "q.l4#3.o0" to "Cada uno hace su propia línea",
    "q.l4#3.o1" to "El primero hace una escalera regular y todos los de detrás usan los mismos escalones",
    "q.l4#3.o2" to "Cada uno hace lo que quiera",
    "q.l4#3.o3" to "Hacerlos lo más profundos y anchos posible",
    "q.l4#3.e" to "Un único juego de escalones reduce mucho el esfuerzo de todos los de detrás y mantiene a la cordada en una línea y un ritmo. Una escalera nivelada y con espaciado regular es en sí misma una marca de eficiencia y seguridad del equipo.",

    "q.l4#4.p" to "En altura, ¿cuál es el principio central del ritmo de marcha?",
    "q.l4#4.o0" to "Ir lo más rápido posible y descansar antes",
    "q.l4#4.o1" to "Mantener un ritmo regular y sostenible, y evitar esfuerzos explosivos repetidos",
    "q.l4#4.o2" to "Alternar rápido y lento para ahorrar energía",
    "q.l4#4.o3" to "Seguir a tu compañero e ignorar tu propio estado",
    "q.l4#4.e" to "La captación de oxígeno es limitada en altura, así que los esfuerzos explosivos repetidos acumulan lactato y agravan la hipoxia. Un ritmo constante con respiración a presión te lleva más lejos y evita que una sola persona corriendo desorganice a toda la cordada.",

    "q.l4#5.p" to "¿Quién debe marcar el ritmo de la cordada en una pendiente de nieve?",
    "q.l4#5.o0" to "La persona más en forma del equipo",
    "q.l4#5.o1" to "Debe seguir al miembro más lento para que la cordada se mantenga unida",
    "q.l4#5.o2" to "El jefe de cordada, ajustado al horario",
    "q.l4#5.o3" to "Cada uno a su propio ritmo",
    "q.l4#5.e" to "En cuanto se abren huecos en una pendiente de nieve, los de detrás pierden protección y apoyo; y un ritmo demasiado rápido agota a los más débiles antes de que lleguen siquiera al terreno peligroso. Avanzar al ritmo del más lento mantiene el margen de seguridad con toda la cordada.",

    "q.l4#6.p" to "Al cruzar una pendiente de hielo con inclinación apreciable, ¿qué recomienda el manual?",
    "q.l4#6.o0" to "Avanzar como una cordada normal",
    "q.l4#6.o1" to "Instalar una cuerda fija o usar aseguramiento alterno; en general, no progresar encordados juntos",
    "q.l4#6.o2" to "Cruzar corriendo lo más rápido posible",
    "q.l4#6.o3" to "Quitarse los crampones para tener más fricción",
    "q.l4#6.e" to "Detenerse en hielo es mucho menos fiable que en nieve, y una cordada en hielo puede arrastrar a todo el grupo hacia abajo. Lo correcto en hielo inclinado es instalar una cuerda fija o usar aseguramiento alterno: protección del sistema, no de la capacidad individual de frenar.",

    "q.l4#7.p" to "¿Cuál es la principal ventaja de subir en zigzag por una pendiente de nieve en lugar de ir recto?",
    "q.l4#7.o0" to "Una distancia más corta",
    "q.l4#7.o1" to "Reduce el ángulo efectivo de cada tramo y ahorra energía",
    "q.l4#7.o2" to "Mejores vistas",
    "q.l4#7.o3" to "No hace falta el piolet",
    "q.l4#7.e" to "El zigzag divide una pendiente inclinada en varios tramos más suaves, lo que reduce mucho la carga sobre gemelos y tobillos y encaja con la técnica francesa (pie plano). El coste es distancia, así que ajusta tu presupuesto de tiempo — una razón más para dejar margen en la hora de regreso.",
    // ---------- l5 Técnicas de crampón ----------
    "q.l5#0.p" to "¿Cuál es el punto clave de la técnica francesa (pie plano)?",
    "q.l5#0.o0" to "Clavar el hielo solo con las puntas frontales",
    "q.l5#0.o1" to "Apoyar todas las puntas inferiores del crampón planas sobre la pendiente, con el pie plano",
    "q.l5#0.o2" to "Saltar sobre un solo pie",
    "q.l5#0.o3" to "Clavar el canto de la bota en el hielo",
    "q.l5#0.e" to "La técnica francesa va de plano: las doce puntas inferiores muerden y la carga se reparte por el muslo y todo el cuerpo, así que es la menos cansada. Por eso sirve para tramos largos de nieve suave.",

    "q.l5#1.p" to "¿Por qué la progresión en puntas frontales (técnica alemana) es la más agotadora?",
    "q.l5#1.o0" to "Porque usa los brazos",
    "q.l5#1.o1" to "Porque la carga se apoya en las puntas frontales y el gemelo tiene que trabajar de forma continua",
    "q.l5#1.o2" to "Porque hay que aguantar la respiración",
    "q.l5#1.o3" to "Porque la fricción es mayor",
    "q.l5#1.e" to "Las puntas frontales ponen tu peso sobre dos o tres puntos, así que el gemelo mantiene una contracción sostenida para conservar la posición. Cansa muchísimo y no se puede mantener mucho tiempo — exactamente por eso se reserva para terreno inclinado.",

    "q.l5#2.p" to "¿Qué técnica de pies se usa al atravesar una pendiente de nieve?",
    "q.l5#2.o0" to "Puntas frontales, clavándolas rectas",
    "q.l5#2.o1" to "El paso de pato: talones juntos, puntas hacia fuera, para que todo el crampón quede apoyado en la pendiente",
    "q.l5#2.o2" to "Saltos laterales",
    "q.l5#2.o3" to "Avanzar de rodillas",
    "q.l5#2.e" to "El paso de pato permite que las puntas laterales y las inferiores muerdan a la vez, de modo que el peso no se concentra en las puntas interiores, donde puede resbalar. Inclínate ligeramente hacia la pendiente al atravesar.",

    "q.l5#3.p" to "¿Qué terreno le sienta mejor a la técnica francesa (pie plano)?",
    "q.l5#3.o0" to "Hielo vertical",
    "q.l5#3.o1" to "Nieve dura de ángulo bajo a moderado, donde avanzas durante horas",
    "q.l5#3.o2" to "Techos extraplomados",
    "q.l5#3.o3" to "Solo terreno llano",
    "q.l5#3.e" to "La técnica francesa reparte la carga por todo el cuerpo y el muslo, así que es la menos cansada y la herramienta de trabajo en ángulos bajos o moderados y en pendientes de nieve largas. El terreno inclinado exige puntas frontales, pero las puntas frontales no se pueden sostener.",

    "q.l5#4.p" to "¿Qué ocurre si progresas mucho tiempo en puntas frontales por una pendiente inclinada?",
    "q.l5#4.o0" to "Se vuelve más fácil a medida que avanzas",
    "q.l5#4.o1" to "El gemelo se fatiga rápido hasta que ya no puedes mantener la posición",
    "q.l5#4.o2" to "Los crampones se salen solos",
    "q.l5#4.o3" to "Nada en absoluto",
    "q.l5#4.e" to "Las puntas frontales concentran tu peso en dos o tres puntos y mantienen el gemelo en contracción sostenida, así que la fatiga llega pronto. Por eso solo sirven para tramos cortos e inclinados — y por eso tu presupuesto de energía debe tenerlo en cuenta al planificar una ruta.",

    "q.l5#5.p" to "En la técnica mixta (americana), ¿cómo se reparten el trabajo los dos pies?",
    "q.l5#5.o0" to "Los dos pies permanecen planos sobre la pendiente",
    "q.l5#5.o1" to "Los dos pies usan las puntas frontales",
    "q.l5#5.o2" to "Un pie plano para sostener y el otro impulsando en puntas frontales, alternando",
    "q.l5#5.o3" to "Un pie hace todo el trabajo mientras el otro descansa",
    "q.l5#5.e" to "La técnica mixta tiende un puente entre la francesa y la alemana: el pie plano da estabilidad y un momento de descanso, el pie en puntas frontales da impulso. En pendientes de moderadas a inclinadas mantiene la eficiencia sin agotar los gemelos como la progresión pura en puntas.",

    "q.l5#6.p" to "[Asociación] Asocia cada clase de crampón con la bota que le corresponde.",
    "q.l5#6.l0" to "C1, correas completas",
    "q.l5#6.r0" to "Bota blanda B1",
    "q.l5#6.l1" to "C2, correa delante y enganche detrás",
    "q.l5#6.r1" to "Bota semirrígida B2",
    "q.l5#6.l2" to "C3, enganche total",
    "q.l5#6.r2" to "Bota totalmente rígida B3",
    "q.l5#6.e" to "Bota y crampón deben corresponderse: botas blandas con C1, semirrígidas con C2, rígidas con C3. Un crampón de enganche total en una bota blanda hace que la bota flexe, los enganches pierdan mordida y el crampón pueda salirse en una pendiente inclinada: una configuración claramente peligrosa.",

    "q.l5#7.p" to "¿Cuáles son las dos técnicas más básicas para progresar sobre hielo?",
    "q.l5#7.o0" to "Pie plano y pasos laterales",
    "q.l5#7.o1" to "La técnica de crampón plano (francesa) y la de puntas frontales (alemana)",
    "q.l5#7.o2" to "Saltar y deslizarse",
    "q.l5#7.o3" to "Técnica de ascenso y técnica de descenso",
    "q.l5#7.e" to "La técnica de crampón plano usa todas las puntas verticales menos las frontales; la de puntas frontales clava estas directamente en el hielo. El terreno complejo suele mezclar las dos — por eso dominas ambas antes de tocar la técnica mixta.",

    "q.l5#8.p" to "Con la técnica de crampón plano (francesa), ¿qué músculos soportan la carga?",
    "q.l5#8.o0" to "Los gemelos",
    "q.l5#8.o1" to "Los muslos",
    "q.l5#8.o2" to "Los antebrazos",
    "q.l5#8.o3" to "La zona lumbar",
    "q.l5#8.e" to "Como el pie se mantiene plano, son los muslos y todo el cuerpo los que llevan la carga, así que es económica y se puede sostener durante horas. Las puntas frontales son lo contrario: la carga recae en dos o tres puntos y el gemelo hace todo el trabajo — dos cuentas energéticas muy distintas.",

    "q.l5#9.p" to "¿A qué ángulo de pendiente se adapta especialmente la técnica de crampón plano (francesa)?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Por encima de 70°",
    "q.l5#9.e" to "Los manuales indican 0°–30° de forma explícita. Con más inclinación el pie ya no puede mantenerse plano y hay que pasar a las puntas frontales. Conocer el rango de ángulo de cada técnica es, en realidad, saber cuándo hay que cambiar de técnica.",

    // ---------- l6 Detención con el piolet ----------
    "q.l6#0.p" to "¿Dónde deben estar los pies durante la detención?",
    "q.l6#0.o0" to "Clavados en la nieve para frenar",
    "q.l6#0.o1" to "Levantados de la nieve, con las puntas hacia arriba, para que todo el peso pase por el piolet",
    "q.l6#0.o2" to "Puntas clavadas en la nieve para anclar",
    "q.l6#0.o3" to "Juntos y planos sobre la nieve",
    "q.l6#0.e" to "En el momento en que un pie toca la nieve le quita peso al piolet, la eficacia del frenado se hunde y te arriesgas a lesionarte el tobillo o la rodilla. Levanta los dos pies para que todo el peso corporal pase por el pico hacia la nieve.",

    "q.l6#1.p" to "Vas deslizándote de cabeza y con los pies por encima. ¿Qué es lo primero que hay que hacer?",
    "q.l6#1.o0" to "Intentar agarrar la cuerda",
    "q.l6#1.o1" to "Girar de inmediato a posición prona con los pies abajo y luego establecer la detención",
    "q.l6#1.o2" to "Seguir deslizándose y esperar a que baje la velocidad",
    "q.l6#1.o3" to "Tirar primero la mochila",
    "q.l6#1.e" to "De cabeza el pico no se puede presionar con eficacia en la nieve, y un impacto de cabeza es extremadamente peligroso. Usa el tronco y el centro del cuerpo para girar primero a la posición prona de detención y luego presionar el pico.",

    "q.l6#2.p" to "¿Cuál es la forma correcta de aprender la detención?",
    "q.l6#2.o0" to "Basta con ver un vídeo",
    "q.l6#2.o1" to "Leer el manual y memorizar los puntos clave",
    "q.l6#2.o2" to "Practicar repetidamente en una pendiente de nieve blanda y segura, con un instructor asegurando, hasta que sea instinto",
    "q.l6#2.o3" to "Aprenderla cayéndose una vez en una pendiente inclinada real",
    "q.l6#2.e" to "La detención es una habilidad de nivel reflejo: requiere cientos de repeticiones en condiciones controladas para volverse fiable. Practica en una pendiente suave, con salida limpia, nieve blanda y un instructor asegurando.",

    "q.l6#3.p" to "¿Cuál es la forma más eficaz de aplicar fuerza en la detención?",
    "q.l6#3.o0" to "Presionar fuerte con los brazos",
    "q.l6#3.o1" to "Presionar el pico hacia abajo con el peso del cuerpo, en vertical",
    "q.l6#3.o2" to "Arrastrar el mango de lado sobre la nieve",
    "q.l6#3.o3" to "Barrer el pico rápidamente por la superficie",
    "q.l6#3.e" to "La fuerza de brazos falla con la fatiga y el pánico; solo el peso del cuerpo clava el pico. Por eso la posición —prono, pies levantados— importa más que la fuerza bruta.",

    "q.l6#4.p" to "¿Qué tal funciona la detención en nieve dura o hielo?",
    "q.l6#4.o0" to "Mejor: se detiene de inmediato",
    "q.l6#4.o1" to "La distancia de frenado crece mucho y puede fallar por completo",
    "q.l6#4.o2" to "Igual que en nieve blanda",
    "q.l6#4.o3" to "Se convierte automáticamente en un deslizamiento controlado",
    "q.l6#4.e" to "Al pico le cuesta morder en nieve dura y hielo. Por eso no se camina sobre una pendiente inclinada de nieve dura sin protección: la técnica no puede sustituir a la evitación, y conocer los límites de una técnica importa igual que la técnica misma.",

    "q.l6#5.p" to "En la detención, ¿cómo se reparte el trabajo entre las dos manos?",
    "q.l6#5.o0" to "Las dos manos en el mango",
    "q.l6#5.o1" to "Las dos manos presionando la cabeza",
    "q.l6#5.o2" to "Una mano presionando la cabeza junto al pico para la fuerza hacia abajo, la otra en el mango para la dirección y la estabilidad",
    "q.l6#5.o3" to "Con una mano basta; deja la otra libre",
    "q.l6#5.e" to "La mano en la cabeza transmite el peso del cuerpo al pico; la mano en el mango estabiliza y corrige la dirección. Con los papeles claros, la detención es a la vez potente y recta.",

    "q.l6#6.p" to "[Orden] Pon en el orden correcto los pasos de una detención.",
    "q.l6#6.o0" to "Agarrar el piolet con firmeza y presionar la cabeza bajo el cuerpo en la posición de detención",
    "q.l6#6.o1" to "Girar a posición prona, con la cabeza cuesta arriba y la cara hacia la nieve",
    "q.l6#6.o2" to "Presionar el pico en la nieve y el hielo con el peso del cuerpo, piernas abiertas, rodillas contra la superficie",
    "q.l6#6.o3" to "Levantar los dos pies para que los crampones no enganchen y te volteen",
    "q.l6#6.e" to "El paso que más se olvida es el último: levantar los pies. En el momento en que un pie toca la nieve le roba peso al piolet, y los crampones pueden morder de golpe y voltearte — interrumpiendo la propia detención.",

    "q.l6#7.p" to "Durante la detención, ¿dónde debe quedar la pala (la parte plana de la cabeza)?",
    "q.l6#7.o0" to "Fuera de la rodilla",
    "q.l6#7.o1" to "En el hueco del hombro",
    "q.l6#7.o2" to "En la cadera",
    "q.l6#7.o3" to "Bien separada, al lado de la cabeza",
    "q.l6#7.e" to "Con la pala en el hueco del hombro, el mango queda cerca de la línea media del cuerpo y la carga se centra bajo el tronco, que es donde la fuerza hacia abajo funciona mejor. Más hacia fuera, la carga se dispersa, el pico se desvía y la distancia de frenado crece mucho.",

    "q.l6#8.p" to "[Elección múltiple] ¿Qué determina principalmente que una detención tenga éxito?",
    "q.l6#8.o0" to "El ángulo de la nieve o el hielo",
    "q.l6#8.o1" to "La dureza de la nieve o el hielo",
    "q.l6#8.o2" to "La posición de quien cae",
    "q.l6#8.o3" to "La velocidad de reacción",
    "q.l6#8.o4" to "La marca y el precio del material",
    "q.l6#8.e" to "Los manuales son sinceros: además de la velocidad de reacción, el éxito depende del ángulo, la dureza y la posición — «a veces ni el gesto más entrenado consigue detener la caída». Aceptar ese límite es lo que deja claro por qué no caerse importa más que detenerse.",

    "q.l6#9.p" to "¿Cuál es la posición correcta de piernas y rodillas durante la detención?",
    "q.l6#9.o0" to "Piernas juntas, rodillas despegadas del suelo",
    "q.l6#9.o1" to "Piernas abiertas, rodillas presionadas contra la nieve y el hielo",
    "q.l6#9.o2" to "Una pierna estirada, la otra doblada",
    "q.l6#9.o3" to "Las dos piernas levantadas de la nieve",
    "q.l6#9.e" to "Las piernas abiertas dan estabilidad lateral y evitan que ruedes; las rodillas contra la superficie añaden un punto de apoyo que ayuda a mantener el peso sobre el piolet. Fíjate en la diferencia: las rodillas pueden tocar ligeramente, mientras que los pies —y los crampones— deben levantarse.",
    // ---------- l7 Resbalones y detención ----------
    "q.l7#0.p" to "¿Cuál es la forma más eficaz de evitar un resbalón mientras avanzas?",
    "q.l7#0.o0" to "Caminar más rápido",
    "q.l7#0.o1" to "Usar el piolet en autoaseguramiento, dándote un anclaje temporal a cada paso",
    "q.l7#0.o2" to "Guardar el piolet en la mochila",
    "q.l7#0.o3" to "Confiar solo en la cuerda",
    "q.l7#0.e" to "El autoaseguramiento es la defensa más directa durante la progresión: la mano del piolet clava el mango en la nieve a cada paso y crea un tercer punto de contacto. La inmensa mayoría de los resbalones ocurre en el instante en que falta ese apoyo.",

    "q.l7#1.p" to "Tu compañero cae de repente mientras avanzáis encordados. ¿Qué haces primero?",
    "q.l7#1.o0" to "Bajar corriendo a agarrarlo",
    "q.l7#1.o1" to "Pasar directamente a la posición de detención y recoger cuerda para sujetarlo",
    "q.l7#1.o2" to "Desencordarte para no ser arrastrado",
    "q.l7#1.o3" to "Gritar pidiendo ayuda y esperar",
    "q.l7#1.e" to "Una cordada funciona porque primero te sujetas a ti mismo; después la cuerda transmite la detención. Bajar corriendo o desencordarte manda a toda la cordada al deslizamiento: el fallo en cadena clásico de los accidentes de glaciar.",

    "q.l7#2.p" to "En el instante en que pierdes el pie, ¿cuál es la primera acción?",
    "q.l7#2.o0" to "Ordenar el material",
    "q.l7#2.o1" to "Gritar un aviso y girar de inmediato a prona para detenerte",
    "q.l7#2.o2" to "Calcular el ángulo de la pendiente",
    "q.l7#2.o3" to "Mirar qué hay abajo",
    "q.l7#2.e" to "Los dos primeros segundos deciden el resultado. El aviso pone a tus compañeros en actitud protectora en el mismo momento en que giras a prona: ese giro es la acción clave para limitar los daños.",

    "q.l7#3.p" to "Al avanzar en cordada, ¿en qué estado debe estar la cuerda?",
    "q.l7#3.o0" to "Lo más floja posible, para tener libertad de movimiento",
    "q.l7#3.o1" to "Moderadamente tensa, sin bucles grandes colgando",
    "q.l7#3.o2" to "Completamente tensa",
    "q.l7#3.o3" to "Como resulte más cómodo",
    "q.l7#3.e" to "Los bucles grandes hacen que quien cae se desplome primero en caída libre antes de que la cuerda tome carga, lo que multiplica el impacto y deja que la cuerda asierre la nieve. Una tensión moderada hace que la detención se active antes.",

    "q.l7#4.p" to "¿Por qué «no resbalar» es más fundamental que «aprender a detenerse»?",
    "q.l7#4.o0" to "Porque la técnica de detención es inútil",
    "q.l7#4.o1" to "Porque la detención puede fallar en nieve dura y pendientes inclinadas: no perder el pie es la protección fiable",
    "q.l7#4.o2" to "Porque detenerse cansa demasiado",
    "q.l7#4.o3" to "Porque los instructores prohíben practicarlo",
    "q.l7#4.e" to "La autodetención es imprescindible, pero tiene límites claros. La estrategia fiable es no entrar en terreno donde podrías deslizarte sin protección. La técnica es la última línea de defensa, no la primera.",

    "q.l7#5.p" to "Durante la detención el pico rebota en la nieve dura y no muerde. ¿Qué debes hacer?",
    "q.l7#5.o0" to "Levantarlo y volver a golpear",
    "q.l7#5.o1" to "Quedarte en prona y seguir presionando con el peso del cuerpo para que el pico muerda poco a poco",
    "q.l7#5.o2" to "Arrastrar el mango de lado sobre la nieve",
    "q.l7#5.o3" to "Renunciar a la detención y protegerte la cabeza",
    "q.l7#5.e" to "Levantar el piolet cancela por completo la detención y te hace perder la posición de presión que habías construido. Quédate en prona y sigue presionando: el pico se entierra más a medida que deslizas. La detención es un proceso progresivo, no un gesto único.",

    "q.l7#6.p" to "¿Por qué se dice que detenerse en hielo es muy difícil?",
    "q.l7#6.o0" to "Porque el hielo está demasiado frío",
    "q.l7#6.o1" to "Porque al pico le cuesta morder el hielo, así que en pendientes de hielo se instala una cuerda fija en lugar de confiar en la detención",
    "q.l7#6.o2" to "Porque la fricción sobre el hielo es demasiado alta",
    "q.l7#6.o3" to "Porque el hielo se rompe con facilidad",
    "q.l7#6.e" to "La detención depende de que el pico muerda, y el hielo es la superficie más difícil de morder. Los manuales responden de forma sistémica: en hielo inclinado se instala una cuerda fija o se asegura en alterno y, en general, no se progresa encordados juntos. Se resuelve con el sistema, no con la esperanza puesta en la técnica individual.",

    "q.l7#7.p" to "[Orden] Tu compañero cae mientras avanzáis encordados. ¿Cuál es la secuencia correcta?",
    "q.l7#7.o0" to "Pasar de inmediato a la posición de detención y sujetarte",
    "q.l7#7.o1" to "Recoger cuerda para detener la caída",
    "q.l7#7.o2" to "Construir un anclaje independiente (piqueta de nieve, piolet enterrado, etc.)",
    "q.l7#7.o3" to "Transferir la carga al anclaje y empezar el rescate",
    "q.l7#7.e" to "Estos cuatro pasos no se pueden reordenar: tienes que sujetarte antes de poder hacer cualquier otra cosa, y rescatar sin anclaje pone el peso de las dos personas sobre ti. En la realidad estos pasos llevan minutos, así que hay que ensayarlos de antemano.",

    "q.l7#8.p" to "La detención funcionó y el deslizamiento se ha parado. ¿Qué viene después?",
    "q.l7#8.o0" to "Levantarse y seguir",
    "q.l7#8.o1" to "Mantener la detención, construir protección paso a paso y transferir tu peso al anclaje",
    "q.l7#8.o2" to "Deshacer el nudo de la cuerda",
    "q.l7#8.o3" to "Comprobar si el material está dañado",
    "q.l7#8.e" to "Un deslizamiento parado no es seguridad: sigues en una posición sin protección y te costaría detenerte otra vez. Mantén la detención mientras construyes protección fiable, libérate y solo entonces ocúpate de las lesiones y de la ruta.",

    "q.l7#9.p" to "[Elección múltiple] ¿Cuáles de estos evitan eficazmente los resbalones?",
    "q.l7#9.o0" to "Autoasegurarse con el piolet de forma continua durante la progresión",
    "q.l7#9.o1" to "Instalar una cuerda fija en nieve dura o en pendientes de hielo",
    "q.l7#9.o2" to "Mantener un ritmo regular y sostenible, evitando esfuerzos bruscos que rompan el equilibrio",
    "q.l7#9.o3" to "Avanzar al ritmo del más lento para que la cordada no se estire",
    "q.l7#9.o4" to "Avanzar más rápido para reducir la exposición",
    "q.l7#9.e" to "Estos cuatro puntos actúan en niveles distintos: técnica personal, protección del sistema, gestión del ritmo y cohesión de la cordada. La prevención de resbalones nunca es una sola acción: es todo ese conjunto de capas a la vez.",

    // ---------- l8 Descenso ----------
    "q.l8#0.p" to "¿Por qué los accidentes son más frecuentes durante el descenso?",
    "q.l8#0.o0" to "Porque el terreno de bajada es más duro",
    "q.l8#0.o1" to "Porque la fatiga degrada la atención y la calidad del movimiento",
    "q.l8#0.o2" to "Porque el tiempo siempre empeora al bajar",
    "q.l8#0.o3" to "Porque el material falla",
    "q.l8#0.e" to "Con la cumbre alcanzada, la alerta baja mientras el cuerpo ya está casi vacío. Una gran parte de los accidentes de alpinismo ocurre en el descenso — de ahí el dicho de que la cumbre es solo la mitad del camino.",

    "q.l8#1.p" to "¿En qué condiciones puedes deslizarte sentado por la nieve?",
    "q.l8#1.o0" to "Siempre que la pendiente sea bastante inclinada",
    "q.l8#1.o1" to "Sin grietas, sin riesgo de caída de piedras, con salida limpia abajo y capacidad de detenerte en cualquier momento",
    "q.l8#1.o2" to "En cualquier pendiente de nieve",
    "q.l8#1.o3" to "Siempre que tus compañeros estén de acuerdo",
    "q.l8#1.e" to "Un deslizamiento es una aceleración irreversible: una vez iniciado es difícil pararlo. Debes descartar grietas, caídas de piedras y personas abajo, y estar seguro de poder pasar a la detención en cualquier punto. Si no, se baja como es debido.",

    "q.l8#2.p" to "¿Cuál es la forma preferida de descender un terreno técnico?",
    "q.l8#2.o0" to "Bajar de cara a la pendiente, manteniendo tres puntos de apoyo",
    "q.l8#2.o1" to "Bajar corriendo de cara al vacío",
    "q.l8#2.o2" to "Deslizarse sentado",
    "q.l8#2.o3" to "Sentarse y dejarse resbalar",
    "q.l8#2.e" to "De cara a la pendiente ves tus apoyos, mantienes el centro de masas cerca de la superficie y dejas las dos manos libres para ayudarte. De cara al vacío los apoyos quedan ocultos: un error muy habitual.",

    "q.l8#3.p" to "¿Cuál es el error más peligroso y más habitual en el descenso?",
    "q.l8#3.o0" to "Bajar de cara a la pendiente y en tres puntos",
    "q.l8#3.o1" to "Inclinarse hacia delante y bajar de cara al vacío",
    "q.l8#3.o2" to "Mantener un ritmo constante",
    "q.l8#3.o3" to "Autoasegurarse con el piolet",
    "q.l8#3.e" to "De cara al vacío no ves tus apoyos, e inclinarte hacia delante te hace aún menos estable. Súmale la fatiga que reduce el control de las piernas y tienes la verdadera razón de que los descensos sean tan propensos a accidentes.",

    "q.l8#4.p" to "¿Qué hay que hacer antes de iniciar un deslizamiento?",
    "q.l8#4.o0" to "Guardar el piolet en la mochila",
    "q.l8#4.o1" to "Confirmar que no hay nadie abajo, ni grietas ni caídas de piedras en la línea, y mantener el piolet listo para detenerse",
    "q.l8#4.o2" to "Apretar las correas de la mochila",
    "q.l8#4.o3" to "Avisar a la familia del itinerario",
    "q.l8#4.e" to "Un deslizamiento es una aceleración irreversible. Antes de empezar hay que descartar personas abajo, grietas y caídas de piedras, y mantener el piolet en la mano; si no, cuando algo vaya mal no tendrás forma de frenar.",

    "q.l8#5.p" to "¿Cómo se gestiona la fatiga de la cordada en un descenso largo?",
    "q.l8#5.o0" to "Caminar del tirón con las menos paradas posible",
    "q.l8#5.o1" to "Hacer paradas cortas programadas, beber y comer, y reevaluar el estado de la cordada",
    "q.l8#5.o2" to "Acelerar para reducir la exposición",
    "q.l8#5.o3" to "Parar solo si alguien se lesiona",
    "q.l8#5.e" to "El descenso es la mitad de riesgo, y la fatiga es su motor principal. Las paradas cortas y regulares recuperan energía y permiten releer el tiempo, la ruta y el estado de tus compañeros — juicios que son lo primero que desaparece en un esfuerzo largo.",

    "q.l8#6.p" to "[Orden] Pon en un orden sensato los pasos de preparación de un descenso.",
    "q.l8#6.o0" to "Confirmar la línea de descenso y el punto de llegada, y despejar a las personas de abajo",
    "q.l8#6.o1" to "Comprobar que están cuerda, dispositivo de aseguramiento, mosquetones y cintas",
    "q.l8#6.o2" to "Construir un anclaje fiable o confirmar la reunión existente",
    "q.l8#6.o3" to "Preparar la cuerda para evitar nudos y enredos, y empezar el descenso",
    "q.l8#6.e" to "Un descenso entrega tu vida a un único punto, así que el orden es: decidir adónde vas, confirmar el material y luego comprometerte. Preparar la cuerda importa igual: un nudo o un enredo te deja colgado de la cuerda mucho tiempo.",

    "q.l8#7.p" to "¿Qué decide principalmente entre rapelar y destrepar?",
    "q.l8#7.o0" to "Cuanto más corto el descenso, más hay que rapelar",
    "q.l8#7.o1" to "La dificultad del terreno, los anclajes disponibles y la capacidad de la cordada",
    "q.l8#7.o2" to "El tiempo",
    "q.l8#7.o3" to "Lo nuevo que sea el material",
    "q.l8#7.e" to "Rapelar es rápido pero depende de los anclajes y de la ejecución; destrepar es más lento pero autónomo. Terreno, fiabilidad de los anclajes y habilidad de la cordada deciden juntos. Recuerda que el rápel tiene una siniestralidad alta porque el margen de error del operador es muy pequeño.",

    "q.l8#8.p" to "¿Qué material técnico requiere normalmente un rápel?",
    "q.l8#8.o0" to "Un mosquetón y una cinta",
    "q.l8#8.o1" to "Varios mosquetones, una cinta larga o anclaje personal, cordeleta de prusik, etc.",
    "q.l8#8.o2" to "Solo una cuerda",
    "q.l8#8.o3" to "Solo un dispositivo de aseguramiento",
    "q.l8#8.e" to "Los manuales citan varios mosquetones, una cinta larga o daisy chain y cordeleta de prusik. Un descenso implica a menudo ir desmontando anclajes y mantener igualmente una seguridad: con demasiado poco material acabas improvisando en altura, que es exactamente donde nacen los accidentes.",

    "q.l8#9.p" to "[Elección múltiple] ¿Cuáles son los principales riesgos durante un descenso?",
    "q.l8#9.o0" to "Fallo del anclaje",
    "q.l8#9.o1" to "Salirse de la cuerda porque los extremos no estaban anudados",
    "q.l8#9.o2" to "Que la cuerda se atasque o se enrede",
    "q.l8#9.o3" to "Caídas de piedras y personas abajo",
    "q.l8#9.o4" to "El descenso es menos arriesgado que la subida porque la gravedad ayuda",
    "q.l8#9.e" to "Los cuatro primeros son las causas habituales de los accidentes de rápel. La más olvidada es el extremo de cuerda sin anudar: si la cuerda es corta y los extremos quedan libres, te sales del final sin darte cuenta y caes. Ese error es especialmente frecuente en un descenso cansado.",
    // ---------- l9 Nudos ----------
    "q.l9#0.p" to "¿Qué nudo une la cuerda al arnés y es la elección habitual en rutas de glaciar?",
    "q.l9#0.o0" to "Ocho reenhebrado",
    "q.l9#0.o1" to "Nudo llano",
    "q.l9#0.o2" to "Nudo simple",
    "q.l9#0.o3" to "As de guía",
    "q.l9#0.e" to "El ocho reenhebrado es resistente, fácil de leer y fácil de revisar por otros, y aún se deshace después de haber trabajado. Un nudo llano puede correrse o atascarse bajo carga y nunca debe usarse para una unión que soporte una vida.",

    "q.l9#1.p" to "¿Qué nudo permite ajustar la longitud con una sola mano para fijar la cuerda a un mosquetón?",
    "q.l9#1.o0" to "Pescador doble",
    "q.l9#1.o1" to "Ballestrinque",
    "q.l9#1.o2" to "Mariposa alpina",
    "q.l9#1.o3" to "Nudo de cinta",
    "q.l9#1.e" to "El ballestrinque se regula empujando y tirando sobre un mosquetón con una sola mano, y es la forma estándar de autoasegurarse en la reunión. El pescador doble une dos cuerdas; la mariposa crea un punto de unión a media cuerda.",

    "q.l9#2.p" to "¿Cuál es la propiedad clave de un nudo de fricción como el prusik?",
    "q.l9#2.o0" to "Muerde la cuerda bajo carga y se desliza por ella cuando no la hay",
    "q.l9#2.o1" to "Puede sustituir permanentemente a la cuerda principal",
    "q.l9#2.o2" to "Es solo decorativo",
    "q.l9#2.o3" to "Se deshace solo bajo carga",
    "q.l9#2.e" to "La mordida en un solo sentido es lo que hace útiles los nudos de fricción para ascender, para las seguridades y en los sistemas de ventaja mecánica. Y como la fiabilidad depende del diámetro cordeleta-cuerda y del número de vueltas, hay que probarlo en el terreno antes de confiar en él.",

    "q.l9#3.p" to "¿Cuánto chicote hay que dejar al terminar un nudo?",
    "q.l9#3.o0" to "Con unos 1 cm basta",
    "q.l9#3.o1" to "Al menos diez diámetros de cuerda",
    "q.l9#3.o2" to "No hace falta chicote",
    "q.l9#3.o3" to "Lo más largo posible: al menos 1 m",
    "q.l9#3.e" to "Un chicote suficiente es la salvaguarda básica contra que el nudo se corra bajo carga o se afloje con los zarandeos. Coge también la costumbre de revisaros mutuamente: los nudos son la única parte del sistema de protección hecha enteramente a mano, sin inspección de fábrica.",

    "q.l9#4.p" to "¿Qué nudo une dos cuerdas o cierra un anillo de cordeleta?",
    "q.l9#4.o0" to "Nudo llano",
    "q.l9#4.o1" to "Pescador doble",
    "q.l9#4.o2" to "Nudo simple",
    "q.l9#4.o3" to "As de guía",
    "q.l9#4.e" to "El pescador doble es muy estable y se afloja muy poco, pero cuesta deshacerlo tras trabajar — lo que encaja para unir cuerdas y cerrar anillos de cordeleta. Un nudo llano puede correrse bajo carga y nunca debe soportar peso.",

    "q.l9#5.p" to "¿Por qué la fiabilidad de un nudo de fricción depende del diámetro de la cordeleta?",
    "q.l9#5.o0" to "El diámetro no influye",
    "q.l9#5.o1" to "Si la cordeleta es mucho más fina que la cuerda, la superficie de contacto y la fuerza de apriete son demasiado pequeñas para morder",
    "q.l9#5.o2" to "Cuanto más fina la cordeleta, mejor muerde",
    "q.l9#5.o3" to "Cuanto más gruesa la cordeleta, mejor muerde",
    "q.l9#5.e" to "Un nudo de fricción muerde apretando la cuerda principal. Demasiado fino y fallan tanto la superficie de contacto como la fuerza de apriete; demasiado grueso y no se enrolla con fuerza. Revisa la combinación cada vez y pruébala en un lugar seguro antes de depender de ella.",

    "q.l9#6.p" to "¿Para qué sirve principalmente la mariposa alpina?",
    "q.l9#6.o0" to "Unir dos cuerdas",
    "q.l9#6.o1" to "Crear un anillo fijo a media cuerda que puede recibir carga en más de una dirección",
    "q.l9#6.o2" to "Sustituir el ocho como nudo de encordamiento",
    "q.l9#6.o3" to "Hacer un anillo de prusik",
    "q.l9#6.e" to "La mariposa forma un anillo en el centro de la cuerda que aguanta carga desde cualquiera de los dos sentidos, por eso aparece en cordadas, progresión glaciar y sistemas de rescate. También se hace entre alpinistas para añadir fricción donde la cuerda roza la nieve.",

    "q.l9#7.p" to "[Asociación] Asocia cada nudo a su uso principal.",
    "q.l9#7.l0" to "Nudo de ocho",
    "q.l9#7.r0" to "El encordamiento habitual a un anclaje o al arnés",
    "q.l9#7.l1" to "Pescador doble",
    "q.l9#7.r1" to "Unir dos cuerdas o cerrar un anillo de cordeleta",
    "q.l9#7.l2" to "Nudo de fricción (prusik)",
    "q.l9#7.r2" to "Nudo de fricción: muerde bajo carga, se desliza cuando no la hay",
    "q.l9#7.l3" to "As de guía",
    "q.l9#7.r3" to "Unir a un anclaje; también habitual para amarrar una embarcación",
    "q.l9#7.e" to "Estos cuatro cubren la mayor parte de la progresión glaciar y de la protección básica. Los manuales los agrupan por función: unir a un anclaje, unir cuerdas, nudo de fricción. Aprenderlos por función se retiene mucho mejor que aprenderlos por forma.",

    "q.l9#8.p" to "¿Qué afirmación sobre los nudos y la resistencia de la cuerda es correcta?",
    "q.l9#8.o0" to "Los nudos no afectan a la resistencia de la cuerda",
    "q.l9#8.o1" to "Cada nudo reduce la resistencia de la cuerda en ese punto, en distinta medida",
    "q.l9#8.o2" to "Los nudos hacen la cuerda más resistente",
    "q.l9#8.o3" to "Un nudo bien hecho no afecta a la resistencia",
    "q.l9#8.e" to "En un nudo la cuerda se curva y, bajo carga, las fibras trabajan de forma desigual, así que la resistencia siempre baja: solo varía la magnitud. Por eso los manuales publican una tabla de pérdida de resistencia por nudo: elige el nudo por cómo funciona y por lo que cuesta en resistencia.",

    "q.l9#9.p" to "El manual resume la utilidad de los nudos en una frase: «Un nudo da ( ) a la cuerda».",
    "q.l9#9.a0" to "vida",
    "q.l9#9.a1" to "la vida",
    "q.l9#9.e" to "El texto original dice «un nudo da vida a la cuerda». Capta la esencia: una cuerda por sí sola es solo un cabo, y solo mediante los nudos —que la unen a la protección, a los anclajes y a otras cuerdas— se convierte en un sistema capaz de sostener una vida.",

    // ---------- l10 Cordada en glaciar ----------
    "q.l10#0.p" to "¿Cuál es el tamaño ideal de una cordada en glaciar?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 o más",
    "q.l10#0.o3" to "Una persona sola",
    "q.l10#0.e" to "Una cordada de tres tiene gente suficiente para montar un anclaje y organizar un rescate cuando uno cae en una grieta. Con dos, si uno entra, el otro debe detener la caída, montar y izar a la vez: casi sin margen.",

    "q.l10#1.p" to "¿Qué separación de cuerda es habitual en progresión glaciar?",
    "q.l10#1.o0" to "2–3 m",
    "q.l10#1.o1" to "8–12 m",
    "q.l10#1.o2" to "Más de 30 m",
    "q.l10#1.o3" to "Lo más corta posible",
    "q.l10#1.e" to "De 8 a 12 m dan a los compañeros tiempo y distancia para reaccionar y detener, sin impedir la comunicación y la cooperación. Demasiado corta y casi no queda cuerda para absorber el impacto.",

    "q.l10#2.p" to "¿Qué necesita una cordada antes de aportar realmente protección?",
    "q.l10#2.o0" to "Basta con ir encordado para estar seguro",
    "q.l10#2.o1" to "Compañeros capaces de detener con eficacia y de montar protección",
    "q.l10#2.o2" to "Una cuerda suficientemente larga",
    "q.l10#2.o3" to "Una cordada suficientemente numerosa",
    "q.l10#2.e" to "La seguridad de una cordada viene de dos acciones ejecutadas con fiabilidad: la detención y el anclaje. Una cordada sin habilidades de detención ni técnica de anclaje es simplemente varias personas atadas que caen en el mismo agujero.",

    "q.l10#3.p" to "¿Por qué se hacen nudos (como la mariposa) entre los alpinistas en un glaciar?",
    "q.l10#3.o0" to "Puramente decorativo",
    "q.l10#3.o1" to "Para añadir fricción donde la cuerda pasa sobre la nieve y limitar cuánto cae quien resbala",
    "q.l10#3.o2" to "Para reconocer a tus compañeros",
    "q.l10#3.o3" to "Para que la cuerda pese menos",
    "q.l10#3.e" to "Cada nudo crea un punto extra de roce en la superficie de nieve, lo que acorta notablemente la caída y da tiempo a los compañeros de arriba para montar protección. Es un freno muy barato y muy eficaz.",

    "q.l10#4.p" to "¿Dónde debe llevarse el material de rescate al progresar por un glaciar?",
    "q.l10#4.o0" to "En el fondo de la mochila",
    "q.l10#4.o1" to "Al alcance, listo para usarlo en cualquier momento",
    "q.l10#4.o2" to "Dejado en la tienda del campamento",
    "q.l10#4.o3" to "Dárselo a un compañero para que lo lleve",
    "q.l10#4.e" to "La ventana de oro de un rescate en grieta son unos minutos. Si las cordeletas de prusik, los mosquetones y las piquetas están enterrados en el fondo de la mochila, para cuando los saques tu compañero puede estar hipotérmico o la cuerda haber aserrado el labio.",

    "q.l10#5.p" to "¿Cuál es el principal riesgo de una cordada de dos frente a una de tres?",
    "q.l10#5.o0" to "Avanza más despacio",
    "q.l10#5.o1" to "Si uno cae, la persona que queda no puede a la vez mantener la detención y conducir el rescate",
    "q.l10#5.o2" to "La cuerda no es lo bastante larga",
    "q.l10#5.o3" to "Hay que llevar más material",
    "q.l10#5.e" to "Con dos, si uno entra en una grieta el otro debe mantener la detención, montar un anclaje y manejar un sistema de izado al mismo tiempo: casi no hay margen. Si tienes que ir de dos, elige una ruta más conservadora y planifica con más antelación.",

    "q.l10#6.p" to "¿Por qué no hay que desencordarse a voluntad al progresar por un glaciar?",
    "q.l10#6.o0" to "Porque desencordarse y volver a encordarse es un engorro",
    "q.l10#6.o1" to "Porque el riesgo en terreno de grietas es continuo: en el momento en que te desencordas no tienes protección",
    "q.l10#6.o2" to "Porque la cuerda se puede perder",
    "q.l10#6.o3" to "Porque tus compañeros se quejarán",
    "q.l10#6.e" to "El riesgo en un glaciar está desigualmente repartido y es difícil de predecir, y la gente suele desencordarse con el juicio erróneo de que «este tramo está bien». Si de verdad hay que desencordarse, parad primero, confirmad el terreno y la nieve, y actuad como cordada.",

    "q.l10#7.p" to "[Asociación] Asocia las voces internacionales de cordada con su significado.",
    "q.l10#7.l0" to "Asegurado",
    "q.l10#7.r0" to "El aseguramiento está listo, puedes empezar",
    "q.l10#7.l1" to "Voy",
    "q.l10#7.r1" to "Empiezo a subir",
    "q.l10#7.l2" to "Caigo",
    "q.l10#7.r2" to "Me estoy cayendo (aviso)",
    "q.l10#7.l3" to "Libre",
    "q.l10#7.r3" to "Aseguramiento liberado, la protección ha terminado",
    "q.l10#7.e" to "El sistema de voces funciona porque no necesita explicación. En altura el viento suena fuerte y las distancias son largas, así que palabras cortas con significado idéntico en ambos lados eliminan la ambigüedad. El momento más peligroso del aseguramiento es cuando cada uno supone que el otro lo sabe. Los manuales listan las voces internacionales porque son el acuerdo mínimo entre cordadas y entre idiomas.",

    "q.l10#8.p" to "¿Qué material técnico básico necesita un asegurador?",
    "q.l10#8.o0" to "Un arnés, un mosquetón, un dispositivo de aseguramiento, un par de guantes y un casco",
    "q.l10#8.o1" to "Solo un dispositivo de aseguramiento y un mosquetón",
    "q.l10#8.o2" to "Un casco y gafas de sol",
    "q.l10#8.o3" to "Un arnés y una cuerda",
    "q.l10#8.e" to "La lista parece simple, pero cada elemento que falta tiene una consecuencia concreta: sin guantes te quemas las manos y pierdes control de la cuerda; sin casco no tienes respuesta a las caídas de piedras. El asegurador es quien atrapa a los demás, así que su propio equipo debe estar completo primero.",

    "q.l10#9.p" to "¿Para qué hacer una revisión mutua antes de empezar a escalar?",
    "q.l10#9.o0" to "Porque la disciplina de cordada lo exige",
    "q.l10#9.o1" to "Porque los errores en el arnés, el nudo y el dispositivo de aseguramiento suelen ser invisibles para quien los lleva puestos",
    "q.l10#9.o2" to "Para registrar el progreso",
    "q.l10#9.o3" to "Para calentar",
    "q.l10#9.e" to "Al revisarte a ti mismo ves lo que crees que has hecho. Un compañero mira desde detrás y desde el lado, en los sitios que tú no ves. Los manuales ponen la revisión mutua en primer lugar de la comunicación de aseguramiento: usa los ojos de otro para cubrir tu punto ciego.",
    // ---------- l11 Principios del anclaje ----------
    "q.l11#0.p" to "En los principios SRENE, ¿qué significa la R?",
    "q.l11#0.o0" to "Rápido",
    "q.l11#0.o1" to "Redundante",
    "q.l11#0.o2" to "Cuerda",
    "q.l11#0.o3" to "Rígido",
    "q.l11#0.e" to "Redundante significa que el sistema tiene varios puntos de protección independientes, de modo que si uno falla los demás siguen soportando la carga. Es el elemento más importante de la seguridad de un anclaje.",

    "q.l11#1.p" to "¿Qué significa el principio de «sin extensión»?",
    "q.l11#1.o0" to "Cuanto más larga la cuerda, mejor",
    "q.l11#1.o1" to "Si un punto falla, el sistema no debe alargarse y chochar el resto",
    "q.l11#1.o2" to "Los anclajes no deben montarse bajos",
    "q.l11#1.o3" to "No hace falta material de repuesto",
    "q.l11#1.e" to "Si hay holgura entre los puntos, un fallo deja caer la carga sobre los restantes como un choque súbito, muy superior a la carga estática. «Sin extensión» significa ecualizar y pretensar para que ese choque no entre nunca en el sistema.",

    "q.l11#2.p" to "¿Cuál es la idea central del diseño de un anclaje?",
    "q.l11#2.o0" to "Usar el menor material posible",
    "q.l11#2.o1" to "Que el fallo de un solo punto no hunda todo el sistema",
    "q.l11#2.o2" to "Montarlo lo más alto posible",
    "q.l11#2.o3" to "Usar solo la cuerda más gruesa",
    "q.l11#2.e" to "Un anclaje en roca o en nieve nunca es absolutamente seguro, así que el sistema se diseña para tolerar el error: ningún fallo único es fatal, lo que da al alpinista tiempo para reaccionar y una seguridad de respaldo.",

    "q.l11#3.p" to "¿Qué dos dimensiones añade EARNEST a SRENE?",
    "q.l11#3.o0" to "Eficiente y oportuno (Efficient, Timely)",
    "q.l11#3.o1" to "Fácil y apretado (Easy, Tight)",
    "q.l11#3.o2" to "Igual y agradable (Equal, Nice)",
    "q.l11#3.o3" to "Vacío y verdadero (Empty, True)",
    "q.l11#3.e" to "Un anclaje no solo tiene que ser seguro: tiene que montarse rápido y manejarse de forma sencilla, porque el tiempo que se tarda en montarlo es tiempo de exposición. Ahí es exactamente donde EARNEST se acerca más al terreno real que SRENE.",

    "q.l11#4.p" to "¿De qué depende principalmente la fiabilidad de un anclaje en nieve?",
    "q.l11#4.o0" to "De la marca del material",
    "q.l11#4.o1" to "De la calidad de la nieve y de lo bien enterrado que esté",
    "q.l11#4.o2" to "Del color de la cuerda",
    "q.l11#4.o3" to "De la altitud",
    "q.l11#4.e" to "La misma piqueta o el mismo anclaje enterrado aguanta cargas muy distintas en nieve profunda, en nieve húmeda y en el borde de un puente de nieve. Los anclajes en nieve exigen leer el manto sobre el terreno: un procedimiento fijo no sirve.",

    "q.l11#5.p" to "¿Por qué un anclaje necesita carga ecualizada?",
    "q.l11#5.o0" to "Para que el anclaje quede ordenado",
    "q.l11#5.o1" to "Para que la carga se reparta entre los puntos como estaba previsto y ningún punto quede sobrecargado",
    "q.l11#5.o2" to "Para ahorrar material",
    "q.l11#5.o3" to "Para que sea más fácil de desmontar",
    "q.l11#5.e" to "Ecualizar significa que cada punto lleva una carga cercana a la de diseño en lugar de que uno lo aguante todo. Si un punto llega a su límite y falla, la carga salta de golpe a los demás y puede desencadenar un fallo en cadena.",

    "q.l11#6.p" to "¿Cuál de estos casos viola el principio de redundancia?",
    "q.l11#6.o0" to "Usar piezas de distinta resistencia",
    "q.l11#6.o1" to "Dos puntos de protección que en realidad dependen de la misma fisura o del mismo bloque",
    "q.l11#6.o2" to "Unir los puntos con cintas",
    "q.l11#6.o3" to "Colocar tres puntos de protección",
    "q.l11#6.e" to "La redundancia exige que cada punto pueda fallar de forma independiente. Si dos puntos comparten una fisura, la apertura de esa fisura se los lleva a los dos a la vez: parece que hay dos, pero funciona como uno. Esta falsa redundancia es habitual y letal.",

    "q.l11#7.p" to "[Asociación] Asocia cada término de evaluación de un anclaje con su significado.",
    "q.l11#7.l0" to "S (Sólido)",
    "q.l11#7.r0" to "Fuerte: cada punto puede soportar la carga prevista",
    "q.l11#7.l1" to "R (Redundante)",
    "q.l11#7.r1" to "Redundante: varios puntos de protección independientes",
    "q.l11#7.l2" to "E (Ecualizado)",
    "q.l11#7.r2" to "Ecualizado: carga repartida de forma sensata entre los puntos",
    "q.l11#7.l3" to "Sin extensión",
    "q.l11#7.r3" to "Sin extensión: un fallo no crea un alargamiento que choque al sistema",
    "q.l11#7.e" to "Estos cuatro forman el marco básico, abreviado SRENE. Merece la pena recordar el orden: primero pregunta si cada punto es sólido, después si el sistema es redundante. Si un solo punto no es fiable, discutir la redundancia no tiene sentido.",

    "q.l11#8.p" to "Según los valores de carga, ¿qué ángulo entre los ramales de cinta hay que buscar?",
    "q.l11#8.o0" to "Menos de 60°",
    "q.l11#8.o1" to "Menos de 90°",
    "q.l11#8.o2" to "Menos de 120°",
    "q.l11#8.o3" to "El ángulo no afecta a la carga",
    "q.l11#8.e" to "A 0° cada punto lleva aproximadamente el 50 %, a 60° alrededor del 58 %, a 90° cerca del 71 %: cuanto más abierto el ángulo, mayor la carga que el peso de una persona pone en cada punto. La regla práctica «mantenerlo por debajo de 60°» sale directamente de esas cifras.",

    "q.l11#9.p" to "¿Por qué la eficiencia y la oportunidad forman parte de la evaluación del anclaje?",
    "q.l11#9.o0" to "Para que el trabajo quede mejor",
    "q.l11#9.o1" to "Porque montar el anclaje es en sí mismo tiempo de exposición al riesgo",
    "q.l11#9.o2" to "Para ahorrar material",
    "q.l11#9.o3" to "Para facilitar la enseñanza",
    "q.l11#9.e" to "Mientras montas un anclaje sueles estar sin protección o mal protegido. Cuanto más corta esa exposición, menor el riesgo — así que «rápido de montar, sencillo de manejar» no es pereza, es parte de la métrica de seguridad.",

    "q.l11#10.p" to "[Elección múltiple] ¿Cómo es un anclaje adecuado?",
    "q.l11#10.o0" to "Cada punto de protección es fuerte en sí mismo",
    "q.l11#10.o1" to "Los puntos fallan de forma independiente unos de otros",
    "q.l11#10.o2" to "La carga se reparte de forma sensata entre los puntos",
    "q.l11#10.o3" to "Se deja holgura en el sistema para absorber el choque",
    "q.l11#10.e" to "Los tres primeros son requisitos; el último es lo contrario. Un anclaje debe ir sin extensión, no con holgura de reserva: la holgura hace que un punto que falla choque a los demás, y las cargas de choque son mucho mayores que las estáticas.",

    "q.l11#11.p" to "Si las condiciones solo permiten un punto de protección, ¿cuál es el enfoque correcto?",
    "q.l11#11.o0" to "Abandonar la ascensión y volver por donde se vino",
    "q.l11#11.o1" to "Hacerlo lo más fiable posible y reducir al mínimo el tiempo que el sistema pasa sobre él",
    "q.l11#11.o2" to "Añadir cualquier segundo punto, para tener dos",
    "q.l11#11.o3" to "Atar la cuerda directamente al arnés",
    "q.l11#11.e" to "Las situaciones de punto único existen de verdad: un buen tornillo de hielo, por ejemplo. La actitud honesta es admitir que no hay margen: hacer ese punto lo mejor posible y hacer pasar a la gente rápido, en lugar de añadir un segundo punto inútil que fabrica una falsa confianza.",

    // ---------- l12 Rescate en grieta ----------
    "q.l12#0.p" to "Tu compañero cae en una grieta. ¿Cuál es el primer paso?",
    "q.l12#0.o0" to "Saltar detrás de él",
    "q.l12#0.o1" to "Pasar a autodetención, montar un anclaje y transferirle la carga",
    "q.l12#0.o2" to "Pedir ayuda primero",
    "q.l12#0.o3" to "Cortar la cuerda",
    "q.l12#0.e" to "Ahora mismo tienes encima todo el peso de quien ha caído. Detente primero para sujetarte, luego monta un anclaje independiente y transfiere la carga: solo entonces tendrás las manos libres para el sistema de rescate. Saltar o cortar la cuerda empeora las cosas de inmediato.",

    "q.l12#1.p" to "¿Cuál es el sistema de ventaja mecánica más habitual para izar en un rescate?",
    "q.l12#1.o0" to "Tracción directa 1:1",
    "q.l12#1.o1" to "El sistema en Z 3:1 (polipasto en Z)",
    "q.l12#1.o2" to "Un sistema 10:1",
    "q.l12#1.o3" to "No hace falta ninguna ventaja",
    "q.l12#1.e" to "El sistema en Z 3:1 usa un prusik y una polea para ganar tres veces la fuerza. Es sencillo, rápido de montar y necesita poco material, por eso es el estándar del rescate en grieta.",

    "q.l12#2.p" to "¿Por qué son especialmente peligrosos los puentes de nieve?",
    "q.l12#2.o0" to "Porque siempre hacen ruido",
    "q.l12#2.o1" to "Porque, cubiertos de nieve reciente, parecen terreno normal y son difíciles de identificar",
    "q.l12#2.o2" to "Porque solo aparecen de noche",
    "q.l12#2.o3" to "Porque siempre son finos",
    "q.l12#2.e" to "Un puente de nieve es el peligro más oculto del glaciar: la superficie parece lisa y gruesa mientras el hueco está debajo. Juzgarlo exige leer las líneas de fractura, la estructura del manto y la estación — precisamente por eso se progresa encordado.",

    "q.l12#3.p" to "¿En qué estado debe estar la cuerda al cruzar terreno de grietas?",
    "q.l12#3.o0" to "Completamente floja, para tener libertad de movimiento",
    "q.l12#3.o1" to "Moderadamente tensa, sin bucles grandes colgando",
    "q.l12#3.o2" to "Lo más tensa posible",
    "q.l12#3.o3" to "No hace falta encordarse",
    "q.l12#3.e" to "La holgura deja que quien cae se desplome en caída libre antes de que la cuerda cargue, lo que multiplica el impacto y aumenta la probabilidad de que la cuerda corte el labio. Una tensión moderada activa la detención antes y reduce ese riesgo.",

    "q.l12#4.p" to "¿Cuál es la forma más segura de cruzar un puente de nieve?",
    "q.l12#4.o0" to "Cruzarlo solo y corriendo",
    "q.l12#4.o1" to "Progresar encordados con la cuerda tensa, cruzando una persona mientras los demás están listos para detener",
    "q.l12#4.o2" to "Evitar todos los puentes de nieve",
    "q.l12#4.o3" to "Pisotearlo fuerte para probarlo y luego cruzar",
    "q.l12#4.e" to "No se puede juzgar un puente de nieve mirándolo. Encordarse y estar listo para detener convierte la incertidumbre en riesgo gestionado. Pisotearlo fuerte para probarlo puede simplemente hacerlo colapsar bajo tus pies.",

    "q.l12#5.p" to "Mientras un compañero cuelga de la cuerda dentro de una grieta, ¿cuál es el mayor peligro?",
    "q.l12#5.o0" to "Que tu compañero se duerma ahí abajo",
    "q.l12#5.o1" to "Que la cuerda cargada asierre el labio de nieve hasta que ceda de golpe",
    "q.l12#5.o2" to "Que se caiga material",
    "q.l12#5.o3" to "Un cambio brusco del tiempo",
    "q.l12#5.e" to "Una cuerda cargada corta de un lado a otro sobre el labio y excava una ranura cada vez más profunda. Es la principal fuente de presión de tiempo en un rescate: hay que izar o transferir la carga a un anclaje sólido antes de que el labio quede cortado.",

    "q.l12#6.p" to "Al montar un sistema en Z con prusiks, ¿por qué hace falta una seguridad?",
    "q.l12#6.o0" to "Para que el sistema parezca completo",
    "q.l12#6.o1" to "Si el prusik principal falla, pierdes la ventaja al instante y quien ha caído vuelve a desplomarse",
    "q.l12#6.o2" to "Para añadir fricción",
    "q.l12#6.o3" to "Para ahorrar cuerda",
    "q.l12#6.e" to "Un prusik muerde por fricción, y el hielo, la suciedad o el desgaste de la cuerda pueden vencerlo. Un prusik de seguridad atrapa la carga si falla el principal, evitando una segunda caída y las lesiones y el retraso añadidos que trae.",

    "q.l12#7.p" to "[Orden] Pon en orden la secuencia estándar de rescate en grieta.",
    "q.l12#7.o0" to "Detenerte de inmediato y sujetarte",
    "q.l12#7.o1" to "Montar un anclaje independiente",
    "q.l12#7.o2" to "Transferir el peso de tu cuerpo al anclaje",
    "q.l12#7.o3" to "Izar con un sistema de ventaja mecánica 3:1",
    "q.l12#7.e" to "Los cuatro pasos no se pueden reordenar. El tercero es el que más se salta: sin transferir la carga tienes que seguir sujetando a tu compañero con el cuerpo y no te quedan manos para manejar el sistema — la razón más frecuente de que un rescate fracase.",

    "q.l12#8.p" to "¿Qué debe hacer la persona que está en la grieta?",
    "q.l12#8.o0" to "Sacudir fuerte la cuerda para llamar la atención",
    "q.l12#8.o1" to "Mantener la calma, intentar subir con el prusik y evitar que la cuerda siga cortando el labio",
    "q.l12#8.o2" to "Desencordarse de inmediato",
    "q.l12#8.o3" to "Bajar a buscar una salida",
    "q.l12#8.e" to "La cooperación de quien ha caído facilita mucho el rescate. Sacudir la cuerda empeora el aserrado, y desencordarse corta tu única unión. Quédate quieto, reduce el corte y, si puedes, cuelga parte de tu peso de un prusik.",

    "q.l12#9.p" to "[Elección múltiple] ¿Qué elementos de rescate deben ir encima de ti y al alcance en un glaciar?",
    "q.l12#9.o0" to "Cordeleta de prusik",
    "q.l12#9.o1" to "Mosquetones y una polea",
    "q.l12#9.o2" to "Una piqueta de nieve o un tornillo de hielo",
    "q.l12#9.o3" to "Cintas",
    "q.l12#9.o4" to "Bastones de trekking",
    "q.l12#9.e" to "Estos cuatro forman juntos el sistema improvisado: cordeleta de prusik para la mordida en un sentido, mosquetones y polea para la ventaja mecánica, piqueta o tornillo para el anclaje, cintas para la unión y la extensión. Lo crítico es que estén al alcance: el material del fondo de la mochila bien podría no existir.",

    "q.l12#10.p" to "¿Por qué hay que transferir la carga al anclaje antes de izar?",
    "q.l12#10.o0" to "Para repartir mejor la carga en la cuerda",
    "q.l12#10.o1" to "Porque si no, tus manos siguen comprometidas sujetando la detención y no pueden manejar el sistema",
    "q.l12#10.o2" to "Para ahorrar energía",
    "q.l12#10.o3" to "Para proteger la cuerda",
    "q.l12#10.e" to "Con todo el peso de quien ha caído sobre ti, tienes que seguir manteniendo la detención: no puedes liberar las manos ni operar con regularidad. Pasar la carga al anclaje es la única forma de dejar de ser un anclaje humano y convertirte en el operador.",

    "q.l12#11.p" to "¿Qué papel juega el prusik en un sistema de rescate?",
    "q.l12#11.o0" to "Decoración",
    "q.l12#11.o1" to "Mordida en un solo sentido: aguanta bajo carga y se desliza por la cuerda cuando está libre",
    "q.l12#11.o2" to "Aumenta la resistencia de la cuerda",
    "q.l12#11.o3" to "Impermeabilización",
    "q.l12#11.e" to "Esa mordida en un solo sentido es exactamente lo que hace posible un sistema de ventaja mecánica: el prusik avanza por la cuerda pero no retrocede bajo carga. Su fiabilidad depende del diámetro de la cordeleta y del número de vueltas, así que pruébalo antes de confiar en él.",
    // ---------- l13 Mal agudo de montaña ----------
    "q.l13#0.p" to "Según los criterios de Lake Louise, ¿qué síntoma debe estar presente para diagnosticar un MAM?",
    "q.l13#0.o0" to "Cefalea más al menos uno de estos: náuseas, mareo, fatiga o insomnio",
    "q.l13#0.o1" to "Tos aislada",
    "q.l13#0.o2" to "Dolor de piernas aislado",
    "q.l13#0.o3" to "Apetito mejorado aislado",
    "q.l13#0.e" to "La cefalea es el síntoma central del MAM. La fatiga o el insomnio por sí solos no bastan: tienen que aparecer junto con la cefalea. El valor práctico de estos criterios es que puedes autoevaluarte en el campamento y actuar en consecuencia.",

    "q.l13#1.p" to "¿Cuál es la respuesta correcta cuando aparecen síntomas de MAM?",
    "q.l13#1.o0" to "Tomar un analgésico y seguir subiendo según el plan",
    "q.l13#1.o1" to "Dejar de ascender; descender de inmediato si los síntomas empeoran",
    "q.l13#1.o2" to "Beber más café para tener energía y seguir caminando",
    "q.l13#1.o3" to "Ignorarlo y aguantar",
    "q.l13#1.e" to "El MAM puede progresar a un ECA o un EPA mortales. Dejar de ascender da tiempo al cuerpo para adaptarse; en cuanto los síntomas empeoran, el descenso es el único tratamiento definitivo. Cualquier plan de aguantar es una apuesta con la propia vida.",

    "q.l13#2.p" to "La cefalea ha desaparecido tras un analgésico. ¿Puedes seguir subiendo?",
    "q.l13#2.o0" to "Sí, el síntoma ha desaparecido",
    "q.l13#2.o1" to "No: enmascarar un síntoma no significa que el cuerpo se haya aclimatado",
    "q.l13#2.o2" to "Sí, pero caminando más despacio",
    "q.l13#2.o3" to "Sí, siempre que bebas más agua",
    "q.l13#2.e" to "Un analgésico suprime la señal; la carga fisiológica de la altura sigue. Subir bajo esa cobertura puede dejar que el MAM progrese a ECA o EPA sin ningún aviso.",

    "q.l13#3.p" to "¿Cuánto tiempo después de llegar a la altura aparecen normalmente los síntomas del MAM?",
    "q.l13#3.o0" to "Inmediatamente",
    "q.l13#3.o1" to "6–12 horas",
    "q.l13#3.o2" to "Después de tres días",
    "q.l13#3.o3" to "Después de una semana",
    "q.l13#3.e" to "El momento importa: los síntomas suelen empezar cuando ya has llegado al campamento, has cenado y te preparas para dormir — y la noche es justamente cuando más fácil resulta pasarlos por alto y más probable que empeoren.",

    "q.l13#4.p" to "¿Cuál es el manejo correcto en el terreno de un MAM leve?",
    "q.l13#4.o0" to "Seguir subiendo según el plan",
    "q.l13#4.o1" to "Dejar de ganar altura, descansar a la altitud actual y descender si los síntomas persisten o empeoran",
    "q.l13#4.o2" to "Tomar un analgésico y seguir subiendo",
    "q.l13#4.o3" to "Descender 2.000 m de inmediato",
    "q.l13#4.e" to "En un MAM leve la primera opción es dejar de subir y dar tiempo al cuerpo. Un analgésico alivia la cefalea pero no modifica la aclimatación. Si los síntomas persisten o empeoran tras el descanso, el descenso es el tratamiento definitivo.",

    "q.l13#5.p" to "¿Por qué «subir alto, dormir bajo» mejora la aclimatación?",
    "q.l13#5.o0" to "Porque de día hace más calor",
    "q.l13#5.o1" to "La hipoxia diurna aporta el estímulo, mientras que bajar a dormir protege la calidad del sueño",
    "q.l13#5.o2" to "Porque llevas menos material",
    "q.l13#5.o3" to "Porque viajar de noche es más seguro",
    "q.l13#5.e" to "La aclimatación necesita estrés hipóxico, pero la calidad del sueño también es un requisito: una hipoxia nocturna severa agrava la respiración periódica y los síntomas. «Subir alto, dormir bajo» concilia las dos cosas, por eso funciona mejor que quedarse arriba todo el tiempo.",

    "q.l13#6.p" to "¿Cuál es la peor consecuencia de seguir subiendo con MAM?",
    "q.l13#6.o0" to "Te sientes algo más cansado",
    "q.l13#6.o1" to "La progresión a ECA o EPA, que puede amenazar la vida en pocas horas",
    "q.l13#6.o2" to "Menos apetito",
    "q.l13#6.o3" to "Peor sueño",
    "q.l13#6.e" to "El MAM suele resolverse con descanso o descenso, pero puede ser el precursor de una enfermedad crítica. Es exactamente por eso que «no subir con síntomas» se repite tanto: corta el primer eslabón de toda la cadena de deterioro.",

    "q.l13#7.p" to "Al juzgar si el MAM empeora, ¿qué hay que vigilar más?",
    "q.l13#7.o0" to "Si la cefalea ha desaparecido",
    "q.l13#7.o1" to "Si los síntomas empeoran progresivamente, en especial la consciencia, la marcha y la respiración",
    "q.l13#7.o2" to "Si la temperatura corporal es normal",
    "q.l13#7.o3" to "Si la lectura del oxímetro ha subido",
    "q.l13#7.e" to "El giro del MAM hacia ECA o EPA se manifiesta en tres dimensiones: consciencia, marcha y respiración. Vigilar esas tres es más fiable que seguir un síntoma aislado o un número del pulsioxímetro.",

    "q.l13#8.p" to "¿Qué caracteriza la cefalea del MAM?",
    "q.l13#8.o0" to "Suele ser el primer síntoma",
    "q.l13#8.o1" to "Solo aparece por la noche",
    "q.l13#8.o2" to "Solo aparece con el esfuerzo",
    "q.l13#8.o3" to "Suele ser el último síntoma en aparecer",
    "q.l13#8.e" to "La cefalea es a menudo la señal más temprana y es un elemento obligatorio de los criterios de Lake Louise. Como es tan común, se atribuye fácilmente al cansancio normal — así que la clave es el contexto: apareció después de ganar altura.",

    "q.l13#9.p" to "Cuando se usa acetazolamida para prevenir el mal de altura, ¿qué pauta recomienda el manual?",
    "q.l13#9.o0" to "250 mg tres veces al día",
    "q.l13#9.o1" to "125 mg dos veces al día, empezando aproximadamente un día antes de la ascensión y parando unos dos días después",
    "q.l13#9.o2" to "500 mg una vez al día",
    "q.l13#9.o3" to "Solo después de que aparezcan los síntomas",
    "q.l13#9.e" to "Siguiendo las recomendaciones médicas más recientes, la dosis recomendada es de 125 mg dos veces al día, inferior a la pauta antigua de 250 mg tres veces al día. La dosis menor funciona y es menos propensa a causar efectos adversos graves. Es un medicamento con receta: debe seguirse el consejo médico.",

    "q.l13#10.p" to "¿Por qué el alivio de los síntomas con medicación no justifica seguir subiendo?",
    "q.l13#10.o0" to "Porque el fármaco crea una ilusión",
    "q.l13#10.o1" to "Porque el fármaco alivia los síntomas pero no mejora la aclimatación a la hipoxia",
    "q.l13#10.o2" to "Porque el fármaco deja de funcionar",
    "q.l13#10.o3" to "Porque hay que ir aumentando la dosis",
    "q.l13#10.e" to "Es la idea más importante del manejo del mal de altura: el síntoma es la alarma, no la enfermedad. La medicación calla la alarma mientras la carga fisiológica de la hipoxia sigue acumulándose: subir bajo esa cobertura deja que la enfermedad avance en silencio.",

    "q.l13#11.p" to "[Elección múltiple] ¿Qué cuadros se confunden fácilmente con el MAM y necesitan una diferenciación cuidadosa?",
    "q.l13#11.o0" to "La deshidratación",
    "q.l13#11.o1" to "Infecciones respiratorias altas, como un resfriado",
    "q.l13#11.o2" to "El sobreesfuerzo",
    "q.l13#11.o3" to "La falta de sueño",
    "q.l13#11.o4" to "La ceguera de la nieve (queratitis ultravioleta)",
    "q.l13#11.e" to "Los cuatro primeros causan cefalea, fatiga, náuseas o mal sueño — un solapamiento amplio con el MAM. Los discriminadores útiles son: si los síntomas aparecieron con la ganancia de altura, si mejoran con el descanso, y si ha cambiado la marcha o la consciencia.",

    "q.l13#12.p" to "Según fuentes clínicas y guías, ¿qué proporción de personas por encima de 4.000 m desarrolla mal agudo de montaña?",
    "q.l13#12.o0" to "5–10 %",
    "q.l13#12.o1" to "20–30 %",
    "q.l13#12.o2" to "50–65 %",
    "q.l13#12.o3" to "Casi el 100 %",
    "q.l13#12.e" to "Cuanto más alto y más rápido se sube, más común es: alrededor del 50–65 % de las personas por encima de 4.000 m desarrolla mal agudo de montaña, y los estudios entre 2.500 y 4.300 m dan aproximadamente 25–43 %. El mal de altura es, por tanto, normal y no excepcional — por eso un plan de aclimatación es una necesidad, no un exceso de prudencia.",

    "q.l13#13.p" to "¿Qué afirmación sobre la edad y el riesgo de mal de altura es correcta?",
    "q.l13#13.o0" to "Los jóvenes no sufren mal de altura",
    "q.l13#13.o1" to "Cuanto mayor se es, más alto debe ser el riesgo",
    "q.l13#13.o2" to "La edad no aumenta significativamente el riesgo; lo que importa es la velocidad de ascensión y la altitud de sueño",
    "q.l13#13.o3" to "Solo lo sufren las personas poco entrenadas",
    "q.l13#13.e" to "Los estudios muestran que trekkers mayores a altitud moderada (65 años de media) tienen tasas similares a las de los más jóvenes. Lo que decide de verdad el riesgo es la velocidad de ascensión, la altitud de sueño y la fisiología individual: culpar a la edad o a la forma física es un juicio peligroso.",

    // ---------- l14 ECA y EPA ----------
    "q.l14#0.p" to "¿Qué signos deben hacer saltar las alarmas por un ECA?",
    "q.l14#0.o0" to "Marcha inestable (no puede caminar en línea recta) y alteración de la consciencia",
    "q.l14#0.o1" to "Una cefalea leve",
    "q.l14#0.o2" to "Un apetito algo escaso",
    "q.l14#0.o3" to "Molestias leves en las piernas",
    "q.l14#0.e" to "La ataxia y la alteración de la consciencia son los marcadores centrales del ECA: el edema cerebral ya afecta al movimiento y a la cognición. Con estos signos hay que descender de inmediato y buscar apoyo médico: ya no toca observar y esperar.",

    "q.l14#1.p" to "¿Cuál es el signo temprano más típico del EPA?",
    "q.l14#1.o0" to "Falta de aire en reposo, con una caída brusca de la capacidad de esfuerzo",
    "q.l14#1.o1" to "Un poco de moqueo",
    "q.l14#1.o2" to "Ligero adormecimiento de los dedos",
    "q.l14#1.o3" to "Sed",
    "q.l14#1.e" to "El EPA se caracteriza por quedarse sin aire incluso en reposo. A diferencia del cansancio simple, no mejora con el descanso, sigue empeorando y puede progresar a esputo espumoso y cianosis: una señal para descender de inmediato.",

    "q.l14#2.p" to "¿Cuál es el tratamiento fundamental del ECA y del EPA?",
    "q.l14#2.o0" to "Tomar un analgésico y seguir escalando",
    "q.l14#2.o1" to "Descender de inmediato a una altitud menor, con oxígeno y otras medidas de soporte",
    "q.l14#2.o2" to "Descansar en el sitio durante dos días",
    "q.l14#2.o3" to "Beber más agua y dormir más",
    "q.l14#2.e" to "El descenso es la única medida que revierte la enfermedad de forma fiable, porque elimina la causa: la hipoxia. El oxígeno, la cámara hiperbárica y los fármacos son complementos que ganan tiempo cuando el descenso no puede empezar de inmediato.",

    "q.l14#3.p" to "Según las fuentes clínicas, ¿cuál es la pauta habitual de dexametasona en el tratamiento del ECA?",
    "q.l14#3.o0" to "8–10 mg iniciales, después 4 mg cada 6 horas",
    "q.l14#3.o1" to "2 mg una vez al día",
    "q.l14#3.o2" to "10 mg cada 2 horas",
    "q.l14#3.o3" to "Solo si el paciente está inconsciente",
    "q.l14#3.e" to "Es una dosis de tratamiento y debe administrarse bajo supervisión médica. El fármaco gana tiempo para el descenso; nunca lo sustituye. El descenso sigue siendo el tratamiento fundamental tanto del ECA como del EPA.",

    "q.l14#4.p" to "¿Con qué frecuencia aparecen juntos el EPA y el ECA?",
    "q.l14#4.o0" to "Casi nunca",
    "q.l14#4.o1" to "Alrededor del 13–20 % de los casos de EPA desarrollan también ECA",
    "q.l14#4.o2" to "En el 100 % de los casos",
    "q.l14#4.o3" to "Solo en niños",
    "q.l14#4.e" to "La cifra muestra que las dos formas críticas del mal de altura aparecen a menudo juntas. Así que cuando un miembro de la cordada muestra signos de edema pulmonar, vigila también la consciencia y la marcha, prepárate para lo peor y desciende de inmediato.",

    "q.l14#5.p" to "Si un miembro de la cordada ya no puede caminar, ¿cuál es la prioridad?",
    "q.l14#5.o0" to "Animarle a seguir caminando",
    "q.l14#5.o1" to "Organizar un porte, dar oxígeno, considerar una cámara hiperbárica y descender lo más rápido posible",
    "q.l14#5.o2" to "Descansar en el sitio y esperar la recuperación",
    "q.l14#5.o3" to "Volver primero al campamento a por el material",
    "q.l14#5.e" to "Perder la capacidad de caminar significa enfermedad crítica. El descenso depende entonces de que la cordada porte al paciente o de un rescate exterior: la verdadera estrategia de seguridad es no dejar que nadie llegue a ese punto, que es exactamente el valor de reconocer el MAM a tiempo.",

    "q.l14#6.p" to "¿Qué hace una cámara hiperbárica portátil (como una bolsa Gamow)?",
    "q.l14#6.o0" to "Curar por completo el mal de altura",
    "q.l14#6.o1" to "Simular una altitud menor para estabilizar al paciente cuando el descenso inmediato es imposible",
    "q.l14#6.o2" to "Sustituir al descenso",
    "q.l14#6.o3" to "Sobre todo dar calor",
    "q.l14#6.e" to "Una cámara hiperbárica gana tiempo; no es el final del tratamiento. Puede contener la enfermedad con mal tiempo, mientras se espera un helicóptero o cuando el descenso no puede empezar enseguida — pero al final el descenso sigue siendo necesario.",

    "q.l14#7.p" to "¿Cuál es la actitud correcta ante la medicación del mal de altura?",
    "q.l14#7.o0" to "Si los síntomas aflojan, seguir subiendo",
    "q.l14#7.o1" to "Es un complemento que gana tiempo, se usa con consejo médico y nunca sustituye al descenso",
    "q.l14#7.o2" to "Se puede compartir libremente con los compañeros",
    "q.l14#7.o3" to "Cuanto antes mejor, sin necesidad de evaluación médica",
    "q.l14#7.e" to "Estos fármacos tienen indicaciones, contraindicaciones y efectos adversos concretos, y subir bajo su cobertura oculta los signos de progresión. La norma es usarlos tras evaluación médica, con el descenso como tratamiento fundamental.",

    "q.l14#8.p" to "¿Qué dosis de dexametasona es habitual en el edema cerebral de altitud?",
    "q.l14#8.o0" to "20 mg cada 12 horas",
    "q.l14#8.o1" to "4 mg cada 6 horas",
    "q.l14#8.o2" to "8 mg una vez al día",
    "q.l14#8.o3" to "10 mg cada 2 horas",
    "q.l14#8.e" to "El manual indica 4 mg cada 6 horas. Reduce la presión intracraneal y alivia el edema cerebral, normalmente con mejoría clara en seis horas — pero solo gana tiempo para el descenso y nunca lo sustituye.",

    "q.l14#9.p" to "¿Trata la dexametasona el edema pulmonar de altitud?",
    "q.l14#9.o0" to "Sí, es el fármaco de primera elección",
    "q.l14#9.o1" to "No, no tiene efecto terapéutico sobre el edema pulmonar",
    "q.l14#9.o2" to "Sí, pero hay que doblar la dosis",
    "q.l14#9.o3" to "Solo funciona en niños",
    "q.l14#9.e" to "Es fácil de confundir: la dexametasona actúa sobre el edema cerebral y es ineficaz en el pulmonar, mientras que el nifedipino actúa sobre el edema pulmonar y tiene un efecto limitado en el cerebral. Las dos enfermedades críticas necesitan fármacos distintos: el equivocado no es tratamiento en absoluto.",

    "q.l14#10.p" to "Para el edema pulmonar de altitud, ¿qué pauta de nifedipino se recomienda y qué efecto adverso importante tiene?",
    "q.l14#10.o0" to "20–30 mg de liberación retardada cada 12 horas; la tensión puede bajar rápido, así que levantarse de golpe puede provocar un desmayo",
    "q.l14#10.o1" to "4 mg cada 6 horas; da somnolencia",
    "q.l14#10.o2" to "125 mg una vez al día; sube la tensión",
    "q.l14#10.o3" to "Solo por vía intravenosa; sin efectos adversos",
    "q.l14#10.e" to "El nifedipino alivia la vasoconstricción pulmonar hipóxica y se usa para prevenir y tratar el edema pulmonar. Su efecto adverso es muy concreto: la tensión puede caer rápido, así que levantarse desde sentado o tumbado puede provocar un desmayo — especialmente peligroso en una pendiente inclinada o al levantarse de noche.",

    "q.l14#11.p" to "¿Cómo administrar dexametasona a un paciente con mal de altura que vomita sin parar?",
    "q.l14#11.o0" to "Por vía oral, a dosis más alta",
    "q.l14#11.o1" to "Hay que administrarla por inyección",
    "q.l14#11.o2" to "Debajo de la lengua",
    "q.l14#11.o3" to "No se puede administrar; hay que esperar",
    "q.l14#11.e" to "Los vómitos persistentes significan que los fármacos orales no se absorben y pueden acabar simplemente expulsados. El manual indica claramente que hace falta inyección — un recordatorio de que la vía de administración es también algo que hay que pensar de antemano en cualquier plan de emergencia en altura.",
    // ---------- l15 Aclimatación y medicación ----------
    "q.l15#0.p" to "Por encima de 3.000 m, ¿cuánto debe subir la altitud de sueño al día?",
    "q.l15#0.o0" to "No más de 500 m",
    "q.l15#0.o1" to "No más de 1.500 m",
    "q.l15#0.o2" to "Lo más rápido posible",
    "q.l15#0.o3" to "No hay límite",
    "q.l15#0.e" to "Mantener la subida diaria de la altitud de sueño dentro de 500 m, con un día de descanso aproximadamente cada 1.000 m, es la recomendación de base que repiten las guías internacionales. Da tiempo al cuerpo para compensar. (Las fuentes proponen valores entre 300 y 700 m; este curso usa uno de los más habituales.)",

    "q.l15#1.p" to "¿Qué significa «subir alto, dormir bajo»?",
    "q.l15#1.o0" to "Subir más alto durante el día y volver a una altitud menor para dormir",
    "q.l15#1.o1" to "Descansar de día y avanzar de noche",
    "q.l15#1.o2" to "Quedarse a la misma altitud todo el tiempo",
    "q.l15#1.o3" to "Dormir solo en el punto más alto",
    "q.l15#1.e" to "La exposición diurna a la altura estimula la producción de glóbulos rojos y la adaptación respiratoria, mientras que bajar a dormir alivia los síntomas y protege la calidad del sueño. Combinar las dos cosas es la forma más eficiente de aclimatarse.",

    "q.l15#2.p" to "¿Cuál de estos factores aumenta la carga de aclimatación?",
    "q.l15#2.o0" to "Beber suficiente agua",
    "q.l15#2.o1" to "El alcohol o los medicamentos sedantes",
    "q.l15#2.o2" to "Comer sobre todo hidratos de carbono",
    "q.l15#2.o3" to "Dormir lo suficiente",
    "q.l15#2.e" to "El alcohol y los sedantes deprimen el impulso respiratorio y agravan la respiración periódica nocturna y la hipoxia, lo que eleva mucho el riesgo de enfermedad. En altura, la calidad de tu respiración durante el sueño forma parte de la aclimatación.",

    "q.l15#3.p" to "¿Para qué sirve vigilar la saturación de oxígeno con un pulsioxímetro?",
    "q.l15#3.o0" to "Puede sustituir por completo la evaluación de síntomas",
    "q.l15#3.o1" to "Da una referencia objetiva, sobre todo para personas con antecedentes de mal de altura",
    "q.l15#3.o2" to "Solo para llevar un registro",
    "q.l15#3.o3" to "No tiene valor práctico",
    "q.l15#3.e" to "La saturación es una referencia útil, pero la variación individual es amplia y no puede ser la única base de las decisiones. Los síntomas y el estado funcional — ¿puede caminar en línea recta?, ¿puede funcionar? — siguen siendo el criterio principal.",

    "q.l15#4.p" to "Para personas con alto riesgo de EPA, ¿qué fármacos preventivos podría considerar un médico?",
    "q.l15#4.o0" to "Nifedipino o sildenafilo (un inhibidor de la PDE)",
    "q.l15#4.o1" to "Antibióticos de amplio espectro",
    "q.l15#4.o2" to "Analgésicos corrientes",
    "q.l15#4.o3" to "Suplementos de vitaminas",
    "q.l15#4.e" to "Ambas clases bajan la presión arterial pulmonar y se usan para prevenir el EPA en personas de alto riesgo, tras evaluación médica. Actúan en un punto distinto al de la acetazolamida y no pueden sustituirla.",

    "q.l15#5.p" to "¿Por qué subir demasiado rápido es uno de los factores de riesgo más fuertes del mal de altura?",
    "q.l15#5.o0" to "Porque cansa",
    "q.l15#5.o1" to "Porque el cuerpo no tiene tiempo de desarrollar la adaptación respiratoria ni el aumento de glóbulos rojos",
    "q.l15#5.o2" to "Porque llevas más peso",
    "q.l15#5.o3" to "Porque el tiempo en montaña cambia rápido",
    "q.l15#5.e" to "La aclimatación es la acumulación de una serie de compensaciones fisiológicas y necesita un tiempo que se cuenta en días. Cuando la ascensión supera a la compensación, la diferencia se manifiesta como síntomas: de ahí vienen todas las recomendaciones de velocidad de ascenso.",

    "q.l15#6.p" to "¿Para qué sirve beber suficiente agua en la aclimatación?",
    "q.l15#6.o0" to "Solo para quitar la sed",
    "q.l15#6.o1" to "Mantiene la circulación y el metabolismo; la deshidratación agrava notablemente los síntomas",
    "q.l15#6.o2" to "Previene el edema pulmonar",
    "q.l15#6.o3" to "Sustituye a la medicación preventiva",
    "q.l15#6.e" to "El aire seco y la respiración más rápida en altura aumentan bastante la pérdida de líquidos, y la deshidratación espesa la sangre, lo que agrava la sensación de hipoxia y la cefalea. Igualmente, evita beber en exceso: el objetivo es una ingesta regular y suficiente.",

    "q.l15#7.p" to "¿Por qué evitar el sobreesfuerzo en altura?",
    "q.l15#7.o0" to "Porque te cansas rápido",
    "q.l15#7.o1" to "El sobreesfuerzo puede desencadenar un EPA, sobre todo antes de la aclimatación",
    "q.l15#7.o2" to "Porque provoca deshidratación",
    "q.l15#7.o3" to "Porque frena a la cordada",
    "q.l15#7.e" to "El ejercicio intenso eleva la presión arterial pulmonar y es un desencadenante claro de EPA en personas aún no aclimatadas. Controlar el ritmo no solo sirve para ahorrar energía: reduce el riesgo de enfermedad.",

    "q.l15#8.p" to "¿Cuándo hay que empezar y parar la acetazolamida?",
    "q.l15#8.o0" to "Empezar al llegar a la altura y parar cuando estés aclimatado",
    "q.l15#8.o1" to "Empezar aproximadamente un día antes de la ascensión y parar unos dos días después",
    "q.l15#8.o2" to "Tomarla de forma continua durante todo el viaje",
    "q.l15#8.o3" to "Solo después de que aparezcan los síntomas",
    "q.l15#8.e" to "Empezar un día antes significa que el fármaco ya está actuando cuando subes; parar unos dos días después de la ascensión se debe a que el cuerpo ha empezado a aclimatarse por su cuenta. La acetazolamida acelera la aclimatación; no la sustituye.",

    "q.l15#9.p" to "¿Provoca el cese de la acetazolamida un rebote de los síntomas?",
    "q.l15#9.o0" to "Sí, hay que reducir la dosis progresivamente",
    "q.l15#9.o1" to "No, la aclimatación simplemente vuelve a su ritmo normal",
    "q.l15#9.o2" to "Sí, los síntomas vuelven multiplicados",
    "q.l15#9.o3" to "Depende de la altitud",
    "q.l15#9.e" to "El manual dice claramente que parar no provoca rebote: el ritmo de aclimatación vuelve sencillamente a la normalidad. Eso importa: demuestra que el fármaco no suprime nada, solo acelera el proceso durante un tiempo.",

    "q.l15#10.p" to "¿Cómo se usa la aspirina para aliviar la cefalea de altura?",
    "q.l15#10.o0" to "500 mg una vez, cuando empieza el dolor",
    "q.l15#10.o1" to "Empezar un día antes de la ascensión, 320 mg tres veces al día hasta completar la aclimatación",
    "q.l15#10.o2" to "100 mg una vez al día",
    "q.l15#10.o3" to "Solo al acostarse",
    "q.l15#10.e" to "Es un uso preventivo y no de tomar cuando duele: empezar pronto, dosificar con regularidad y continuar hasta que el proceso de aclimatación haya terminado. Ten en cuenta que la aspirina conlleva riesgos digestivos y hemorrágicos: es una decisión médica y debe valorarla un médico.",

    "q.l15#11.p" to "¿Qué opinión es correcta sobre el extracto de ginkgo para prevenir el mal de altura?",
    "q.l15#11.o0" to "Funciona mejor que la acetazolamida y puede sustituirla",
    "q.l15#11.o1" to "Tiene cierto efecto preventivo, pero los ensayos controlados muestran que es mucho menos eficaz que la acetazolamida",
    "q.l15#11.o2" to "Es totalmente ineficaz",
    "q.l15#11.o3" to "Solo sirve para el edema cerebral",
    "q.l15#11.e" to "El manual es prudente: algunos ensayos muestran alivio de síntomas, pero las dosis y las condiciones varían demasiado para establecer una pauta fiable, y los ensayos comparativos directos lo muestran mucho más débil que la acetazolamida. Ojo también a su interacción con los anticoagulantes.",

    // ---------- l16 Hipotermia y congelaciones ----------
    "q.l16#0.p" to "¿Qué significa que los escalofríos cesen?",
    "q.l16#0.o0" to "Que el cuerpo se ha adaptado al frío",
    "q.l16#0.o1" to "Que la hipotermia empeora: una señal de peligro",
    "q.l16#0.o2" to "Que puedes seguir moviéndote",
    "q.l16#0.o3" to "Que hay que beber agua de inmediato",
    "q.l16#0.e" to "Los escalofríos son el último medio del cuerpo para producir calor. Cuando cesan, la producción de calor ha fallado y la temperatura central cae más rápido: es el límite clave entre hipotermia leve y moderada o grave, y una razón para actuar de inmediato.",

    "q.l16#1.p" to "¿Cuál es el método correcto de recalentamiento de una congelación en el terreno?",
    "q.l16#1.o0" to "Frotar la zona con nieve",
    "q.l16#1.o1" to "Sumergirla en agua a 37–40 °C durante unos 30 minutos, hasta que la piel enrojezca y se ablande",
    "q.l16#1.o2" to "Calentarla junto al fuego",
    "q.l16#1.o3" to "Aplicar directamente una bolsa de agua caliente",
    "q.l16#1.e" to "El tejido congelado contiene cristales de hielo, y frotarlo provoca lesión celular secundaria; el calor fuerte quema una piel que ha perdido la sensibilidad. El recalentamiento rápido en agua templada es el único método de referencia: la mano sana o la axila sirven como medida de emergencia.",

    "q.l16#2.p" to "¿Cuándo no hay que recalentar una congelación en el terreno?",
    "q.l16#2.o0" to "Hay que recalentar siempre cualquier congelación",
    "q.l16#2.o1" to "Cuando existe riesgo de recongelación, porque congelar-descongelar-recongelar causa daños peores",
    "q.l16#2.o2" to "Nunca hay que recalentar de día",
    "q.l16#2.o3" to "Solo deben recalentarse las congelaciones leves",
    "q.l16#2.e" to "Un ciclo de recalentar y recongelar destruye mucho más tejido que permanecer congelado. Así que cuando es probable una nueva exposición al frío y no se puede garantizar calor, protege la zona, evita el roce y desciende a un lugar donde el calor pueda mantenerse antes de recalentar.",

    "q.l16#3.p" to "¿Por qué evitar mover vigorosamente las extremidades en hipotermia moderada o peor?",
    "q.l16#3.o0" to "Porque consume energía",
    "q.l16#3.o1" to "Porque el músculo cardiaco frío entra con facilidad en arritmia",
    "q.l16#3.o2" to "Porque irrita al paciente",
    "q.l16#3.o3" to "Porque agrava las congelaciones",
    "q.l16#3.e" to "Es el punto más contraintuitivo del manejo de la hipotermia: hacer caminar al paciente suele ser fatal. En un corazón frío el miocardio es muy irritable, y un movimiento brusco de las extremidades o una manipulación ruda pueden desencadenar directamente una fibrilación ventricular.",

    "q.l16#4.p" to "¿Qué temperatura del agua es correcta para recalentar una congelación?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Por encima de 60 °C",
    "q.l16#4.e" to "Demasiado fría y el recalentamiento fracasa; demasiado caliente y se quema una piel sin sensibilidad. 37–40 °C funden rápido los cristales de hielo sin causar lesión térmica. El recalentamiento duele mucho y necesita analgesia.",

    "q.l16#5.p" to "¿Por qué recalentar el tronco antes que las extremidades en hipotermia?",
    "q.l16#5.o0" to "Porque las extremidades no importan",
    "q.l16#5.o1" to "Recalentar las extremidades devuelve sangre periférica fría al centro y hace bajar aún más la temperatura central",
    "q.l16#5.o2" to "Porque el tronco es más fácil de tratar",
    "q.l16#5.o3" to "Porque las extremidades pueden estar ya congeladas",
    "q.l16#5.e" to "Es uno de los principios clave del manejo de la hipotermia. Tratar primero las extremidades empuja sangre periférica fría hacia el centro, lo que puede bajar más la temperatura central y provocar arritmia: primero el tronco, después las extremidades.",

    "q.l16#6.p" to "¿Cuál es el manejo en el terreno de una hipotermia leve?",
    "q.l16#6.o0" to "Llevarlo al hospital de inmediato",
    "q.l16#6.o1" to "Salir del viento y del frío, cambiar la ropa mojada, aportar calor y seguir vigilando el deterioro",
    "q.l16#6.o2" to "Hacerle caminar para generar calor",
    "q.l16#6.o3" to "Frotarle el cuerpo con nieve para estimular la circulación",
    "q.l16#6.e" to "Una persona con hipotermia leve aún puede generar calor, así que la prioridad es frenar la pérdida y aportar energía. Pero sigue vigilando: el cese de los escalofríos suele indicar progresión a hipotermia moderada, no mejoría.",

    "q.l16#7.p" to "¿Se puede aplicar una bolsa de agua caliente directamente sobre tejido congelado?",
    "q.l16#7.o0" to "Sí, cuanto más rápido el recalentamiento mejor",
    "q.l16#7.o1" to "No: una piel sin sensibilidad se quema con facilidad; usa solo agua a 37–40 °C",
    "q.l16#7.o2" to "Sí, siempre que esté envuelta en una toalla",
    "q.l16#7.o3" to "Sí, siempre que la temperatura no sea muy alta",
    "q.l16#7.e" to "La piel congelada ha perdido la sensibilidad al dolor y a la temperatura, así que no puede avisar de que algo está demasiado caliente. Una fuente de calor directa añade fácilmente una quemadura y puede destruir tejido que de otro modo se habría recuperado.",

    "q.l16#8.p" to "[Elección múltiple] ¿Cuáles de estas prácticas son erróneas en primeros auxilios de hipotermia?",
    "q.l16#8.o0" to "Dar alcohol al paciente para que entre en calor",
    "q.l16#8.o1" to "Hacer caminar a un paciente con hipotermia grave para generar calor",
    "q.l16#8.o2" to "Frotar con fuerza las extremidades congeladas",
    "q.l16#8.o3" to "Recalentar las extremidades antes que el tronco",
    "q.l16#8.o4" to "Sacar al paciente del viento y cambiarle la ropa mojada",
    "q.l16#8.e" to "Los cuatro primeros son erróneos, cada uno por su motivo: el alcohol dilata los vasos periféricos y acelera la pérdida de calor; caminar puede desencadenar arritmia en hipotermia grave; frotar provoca daño secundario en tejido congelado; y recalentar las extremidades envía sangre fría al centro y baja más la temperatura central.",

    "q.l16#9.p" to "¿Cuál es el orden de prioridad esencial en el manejo de la hipotermia?",
    "q.l16#9.o0" to "Recalentar primero las extremidades y luego el tronco",
    "q.l16#9.o1" to "Recalentar primero el centro del tronco, evitando manipulaciones rudas y movimientos vigorosos de las extremidades",
    "q.l16#9.o2" to "Dar primero agua caliente al paciente",
    "q.l16#9.o3" to "Quitar primero toda la ropa",
    "q.l16#9.e" to "El tronco primero es el primer principio: una vez caliente el tronco, el corazón y el cerebro pueden volver a funcionar y la sangre puede enviarse a las extremidades sin peligro. Invertir el orden baja directamente la temperatura central.",

    "q.l16#10.p" to "¿Cuáles son los cuidados correctos una vez recalentada una congelación?",
    "q.l16#10.o0" to "Pinchar las ampollas para aliviar la presión",
    "q.l16#10.o1" to "No pinchar las ampollas; cubrir sin apretar con material estéril y evitar apoyar",
    "q.l16#10.o2" to "Masajear con fuerza para mejorar la circulación",
    "q.l16#10.o3" to "Poner la zona junto a una fuente de calor de inmediato",
    "q.l16#10.e" to "El tejido recalentado es extremadamente frágil: las ampollas son un apósito natural y pincharlas invita a la infección, el masaje causa daño mecánico y el calor quema una piel sin sensibilidad. Protege, mantén seco, evita apoyar y busca atención médica.",

    "q.l16#11.p" to "¿Qué secuelas a largo plazo puede dejar una congelación?",
    "q.l16#11.o0" to "Normalmente una recuperación completa sin secuelas",
    "q.l16#11.o1" to "Sensibilidad al frío, alteraciones de la sensibilidad y sudoración anormal, que pueden tardar meses o más en estabilizarse",
    "q.l16#11.o2" to "Solo efectos estéticos",
    "q.l16#11.o3" to "Solo una pérdida de capacidad deportiva",
    "q.l16#11.e" to "La congelación daña tejido profundo y terminaciones nerviosas, así que incluso cuando la piel parece recuperada pueden persistir a largo plazo sensibilidad al frío, adormecimiento, hormigueo y sudoración anormal. Es exactamente por eso que prevenir una congelación importa mucho más que tratarla.",
    // ---------- l17 Escalada en hielo ----------
    "q.l17#0.p" to "¿Cómo hay que golpear con una herramienta de hielo?",
    "q.l17#0.o0" to "Golpear fuerte con la parte superior del brazo",
    "q.l17#0.o1" to "Golpear con la muñeca para que el pico entre vertical en el hielo",
    "q.l17#0.o2" to "Martillear la superficie con la pala",
    "q.l17#0.o3" to "Cortar el hielo en horizontal",
    "q.l17#0.e" to "Un golpe de muñeca clava el pico en vertical, rápido: muerde con más facilidad y cuesta menos energía. Golpear con todo el brazo hace que el pico llegue inclinado y rompe la superficie en una costra que ya no aguanta.",

    "q.l17#1.p" to "En escalada en hielo, ¿qué significa el contacto en tres puntos?",
    "q.l17#1.o0" to "Dos manos y un pie (o dos pies y una mano) mantienen tres apoyos estables mientras el cuarto se mueve",
    "q.l17#1.o1" to "Tres personas escalan juntas",
    "q.l17#1.o2" to "Tres nudos comparten la carga",
    "q.l17#1.o3" to "El material debe tener tres puntos de enganche",
    "q.l17#1.e" to "El contacto en tres puntos es la regla de progresión común al hielo y a la roca: mantén siempre tres apoyos fiables y mueve solo uno. Así, si un apoyo falla, todavía te quedan otros.",

    "q.l17#2.p" to "¿Qué caracteriza a WI4?",
    "q.l17#2.o0" to "Hielo poco inclinado por el que se puede caminar",
    "q.l17#2.o1" to "Casi vertical, con tramos verticales cortos, y una protección que puede ser mediocre",
    "q.l17#2.o2" to "Todo extraplomos",
    "q.l17#2.o3" to "Basta un bastón de trekking",
    "q.l17#2.e" to "WI4 significa terreno casi vertical con tramos verticales cortos, y lugares donde colocar un tornillo que no siempre son buenos. Exige mejor técnica y mejor juicio. WI1–WI2 es terreno de aprendizaje.",

    "q.l17#3.p" to "¿Por qué hay que economizar los golpes en escalada en hielo?",
    "q.l17#3.o0" to "Para ahorrar energía",
    "q.l17#3.o1" to "El hielo machacado se convierte en una costra que no aguanta",
    "q.l17#3.o2" to "Porque la herramienta se desgasta",
    "q.l17#3.o3" to "Porque molesta a los compañeros",
    "q.l17#3.e" to "Cada golpe fallido deja un cráter. Martillear sin parar destruye el hielo portante de todo un panel y te obliga a quedarte colgado de los brazos: un círculo vicioso.",

    "q.l17#4.p" to "¿Por qué es más peligrosa la escalada en hielo que la escalada deportiva?",
    "q.l17#4.o0" to "Porque hace más frío",
    "q.l17#4.o1" to "Los tornillos pueden arrancar bajo carga, y el hielo cambia de un día para otro",
    "q.l17#4.o2" to "Porque no hay protección",
    "q.l17#4.o3" to "Porque no se puede usar cuerda",
    "q.l17#4.e" to "Un empotrador o un parabolt bien colocado en roca sigue siendo fiable; un tornillo depende del hielo mismo, y el hielo se funde, se vuelve frágil y desarrolla huecos: una colocación sólida ayer puede no valer nada hoy.",

    "q.l17#5.p" to "¿Por qué estabilizar los pies antes de golpear con la herramienta?",
    "q.l17#5.o0" to "Porque los brazos se cansan antes que las piernas",
    "q.l17#5.o1" to "Los pies llevan el peso y permiten el descanso; los brazos solo ayudan",
    "q.l17#5.o2" to "Porque las herramientas de hielo son caras",
    "q.l17#5.o3" to "Porque queda más profesional",
    "q.l17#5.e" to "La fuerza de brazos se agota muy rápido en hielo; los pies son lo que puede llevar peso durante horas. Golpear antes de tener los pies puestos funde los brazos demasiado pronto y en realidad aumenta la probabilidad de caer.",

    "q.l17#6.p" to "¿En qué condiciones se estropea típicamente el hielo?",
    "q.l17#6.o0" to "Tras una noche fría",
    "q.l17#6.o1" to "Tras sol fuerte o subida de temperatura, cuando el hielo se ablanda y se vuelve alveolar",
    "q.l17#6.o2" to "Justo después de una nevada",
    "q.l17#6.o3" to "Cuando se levanta viento",
    "q.l17#6.e" to "El hielo es función de la temperatura. El hielo duro de la mañana exige colocaciones precisas; la sopa de la tarde parece fácil pero sus tornillos arrancan con más facilidad. Juzgar el hielo es sopesar la hora, la orientación, la temperatura y el sol de los días previos.",

    "q.l17#7.p" to "Antes de colocar un tornillo de hielo, ¿qué hay que comprobar?",
    "q.l17#7.o0" to "Si el tornillo tiene un color bien visible",
    "q.l17#7.o1" to "Si el hielo de ahí es compacto, sin huecos ni alveolos",
    "q.l17#7.o2" to "Si sale bien en las fotos",
    "q.l17#7.o3" to "A qué distancia está del suelo",
    "q.l17#7.e" to "La resistencia de un tornillo viene del hielo, no de la técnica. Un tornillo en un hueco o en hielo alveolar apenas aguanta una caída: es la diferencia más fundamental entre la protección en hielo y en roca.",

    "q.l17#8.p" to "Los antebrazos se te congestionan en un largo de hielo. ¿Qué hacer?",
    "q.l17#8.o0" to "Escalar más rápido para salir del paso",
    "q.l17#8.o1" to "Llegar cuanto antes a una posición de descanso, cargar el peso en los pies y sacudir los brazos",
    "q.l17#8.o2" to "Apretar más para mantenerse estable",
    "q.l17#8.o3" to "Retroceder de inmediato",
    "q.l17#8.e" to "La congestión es isquemia del antebrazo; si sigues, pierdes el agarre por completo. La respuesta correcta es pasar el peso a los pies mientras todavía lo controlas y dejar que vuelva la sangre — que es exactamente lo que significa en la práctica «no dejar los pies vagos».",

    "q.l17#9.p" to "[Asociación] Asocia cada cota WI de hielo a su carácter típico.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.r0" to "Hielo sostenido en torno a 60° con posibles bombé; buena protección",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.r1" to "Sostenido a 60–75°; protección normalmente buena pero exigente",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.r2" to "Casi vertical con tramos verticales cortos; la protección puede ser mediocre",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r3" to "Vertical sostenido; protección mediocre y muy exigente",
    "q.l17#9.e" to "Una cota WI combina tres variables: el ángulo, la calidad de la protección y el coste físico. Cuanto más alta la cota, menos margen queda para retroceder o autorrescatar: por eso la cota es solo una referencia y el hielo del día y el estado de la cordada deciden el resultado.",

    "q.l17#10.p" to "[Elección múltiple] ¿Qué material debe ir en el arnés, al alcance, en escalada en hielo?",
    "q.l17#10.o0" to "Varios tornillos de hielo",
    "q.l17#10.o1" to "Mosquetones y cintas exprés",
    "q.l17#10.o2" to "Cordeleta de prusik",
    "q.l17#10.o3" to "Un dispositivo de aseguramiento",
    "q.l17#10.o4" to "Un saco de dormir de repuesto",
    "q.l17#10.e" to "La escalada en hielo consiste en construir la protección mientras avanzas, así que lo que va enterrado en la mochila bien podría no existir. La lista de material de rescate del manual —tornillos, mosquetones, cintas, polea, prusiks, bloqueador— sigue la misma lógica: todo lo que puedas necesitar se queda al alcance.",

    "q.l17#11.p" to "¿Por qué puede arrancar un tornillo de hielo?",
    "q.l17#11.o0" to "Porque el tornillo es demasiado corto",
    "q.l17#11.o1" to "Porque el hielo mismo puede tener huecos, ser alveolar o estar fundiéndose, y no aguanta",
    "q.l17#11.o2" to "Porque hay demasiado colgado de él",
    "q.l17#11.o3" to "Porque el tornillo está romo",
    "q.l17#11.e" to "La resistencia viene del hielo, no de la colocación. Un tornillo en un hueco o en hielo alveolar apenas aguanta una caída: la diferencia esencial con la protección en roca, y la razón por la que se mira el hielo antes de colocarlo.",

    "q.l17#12.p" to "¿Por qué una cota de hielo es solo una referencia?",
    "q.l17#12.o0" to "Porque las cotas son arbitrarias",
    "q.l17#12.o1" to "Porque el hielo cambia cada día: el sol, la temperatura y la estación pueden alterar mucho la misma ruta",
    "q.l17#12.o2" to "Porque las cotas cambian según el país",
    "q.l17#12.o3" to "Porque las cotas solo describen la longitud",
    "q.l17#12.e" to "El hielo es función de la temperatura: el hielo duro de la mañana exige colocaciones precisas, mientras que el hielo blando de la tarde parece fácil pero sus tornillos arrancan con más facilidad. La misma ruta puede variar en más de una cota: lo que ves delante siempre está por encima del número de la guía.",

    "q.l17#13.p" to "[Orden] Pon en orden el ritmo de progresión en tres puntos sobre hielo.",
    "q.l17#13.o0" to "Leer el hielo y elegir dónde irán la herramienta y los pies",
    "q.l17#13.o1" to "Clavar las puntas frontales para establecer los dos pies",
    "q.l17#13.o2" to "Con los pies estables, golpear con la herramienta y confirmar que está firme",
    "q.l17#13.o3" to "Con tres puntos estables, mover el cuarto",
    "q.l17#13.e" to "Este orden explica por qué «no dejar los pies vagos» es la disciplina central de la escalada en hielo: los pies llevan el peso durante horas, los brazos solo ayudan. Golpear antes de tener los pies puestos agota los brazos demasiado pronto: en hielo inclinado, eso es fatal.",

    // ---------- l18 Aludes ----------
    "q.l18#0.p" to "¿En qué ángulos de pendiente se concentran más los aludes?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "El hielo vertical",
    "q.l18#0.e" to "Las estadísticas muestran que la gran mayoría de los aludes se produce entre 34° y 45° (el 96 % entre 30° y 50°). Es justo lo bastante inclinado para deslizarse y lo bastante para retener nieve: la ventana de peligro, y el ángulo que más a menudo cruzan las rutas de alpinismo.",

    "q.l18#1.p" to "¿Por qué ocurren más accidentes en el grado 3, marcado?",
    "q.l18#1.o0" to "Porque el manto está en su punto más inestable",
    "q.l18#1.o1" to "Porque las condiciones parecen aceptables y se subestiman con más facilidad",
    "q.l18#1.o2" to "Porque todo el mundo se queda en casa",
    "q.l18#1.o3" to "Porque el boletín es inexacto",
    "q.l18#1.e" to "La paradoja del grado 3 es que los aludes son realmente posibles mientras el terreno parece «correcto», así que mucha gente entra en terreno de aludes. En los grados 4 y 5 la mayoría se queda fuera, y la proporción de accidentes baja. La situación más peligrosa nunca es la extrema: es la moderada que se subestima.",

    "q.l18#2.p" to "¿Qué es el trío de alud?",
    "q.l18#2.o0" to "ARVA (detector de víctimas de alud), sonda y pala",
    "q.l18#2.o1" to "Casco, cuerda y arnés",
    "q.l18#2.o2" to "Piolet, crampones y tornillos de hielo",
    "q.l18#2.o3" to "Tienda, saco de dormir y esterilla",
    "q.l18#2.e" to "El ARVA localiza, la sonda precisa y la pala desentierra. Hacen falta los tres, y los tres hay que practicarlos si se quiere completar un rescate dentro de la ventana de oro de diez minutos escasos.",

    "q.l18#3.p" to "¿Por qué las pendientes que no parecen inclinadas son a menudo las más peligrosas?",
    "q.l18#3.o0" to "Porque la nieve es más profunda",
    "q.l18#3.o1" to "Porque entre 34° y 45° se concentran los aludes, y la gente subestima sistemáticamente el ángulo",
    "q.l18#3.o2" to "Porque se circula más rápido por ellas",
    "q.l18#3.o3" to "Porque el sol pega más",
    "q.l18#3.e" to "Por debajo de unos 30° es demasiado suave para aludes de placa; por encima de unos 50° la nieve no se acumula. La ventana de peligro cae justo en la franja que parece transitable, que es precisamente por lo que se subestima.",

    "q.l18#4.p" to "¿Cuál es la forma correcta de cruzar terreno de aludes?",
    "q.l18#4.o0" to "Pasar toda la cordada rápido y junta",
    "q.l18#4.o1" to "Espaciarse, cruzar de uno en uno, poner un vigía y prever una ruta de escape",
    "q.l18#4.o2" to "Tomar la línea más corta por el fondo del valle",
    "q.l18#4.o3" to "Quedarse donde la nieve es más profunda",
    "q.l18#4.e" to "De uno en uno limita el riesgo a una sola persona, y un vigía puede localizar y organizar el rescate de inmediato. Cruzar todos juntos significa que un solo desencadenamiento sepulta a toda la cordada: el peor resultado posible.",

    "q.l18#5.p" to "Oyes un «whumpf» y el manto se asienta. ¿Qué significa?",
    "q.l18#5.o0" to "Que solo has pisado un agujero",
    "q.l18#5.o1" to "Que hay una capa débil fácil de desencadenar y el manto es inestable",
    "q.l18#5.o2" to "Que la nieve es profunda y se avanza bien",
    "q.l18#5.o3" to "Que el manto se ha estabilizado",
    "q.l18#5.e" to "Un «whumpf» es el sonido del manto al colapsar cuando una capa débil cede. Es una señal de estabilidad muy directa: seguir hacia esa pendiente equivale a usarte a ti mismo para probar si va a soltar en placa.",

    "q.l18#6.p" to "¿Por qué son más letales los aludes de placa que los de nieve suelta?",
    "q.l18#6.o0" to "Porque son más fríos",
    "q.l18#6.o1" to "Toda la placa suelta a la vez y te sepulta, sin apenas posibilidad de autorrescate",
    "q.l18#6.o2" to "Porque hacen más ruido",
    "q.l18#6.o3" to "Porque ocurren más a menudo",
    "q.l18#6.e" to "Una placa rompe en toda la pendiente de golpe, así que pierdes el apoyo cuando todavía estás en la cara. Una vez sepultado, el peso de la nieve y su fraguado rápido hacen casi imposible el autorrescate: por eso el rescate por los compañeros tiene que ser inmediato.",

    "q.l18#7.p" to "¿Cómo hay que llevar y usar un ARVA?",
    "q.l18#7.o0" to "En cualquier sitio de la mochila vale",
    "q.l18#7.o1" to "Comprobar mutuamente el modo emisión antes de salir y ensayar las rutinas de búsqueda con regularidad",
    "q.l18#7.o2" to "Lo lleva solo el jefe de cordada",
    "q.l18#7.o3" to "Apagarlo para ahorrar batería",
    "q.l18#7.e" to "Un ARVA en la mochila es casi inútil: bajo la nieve puede que los brazos no se muevan en absoluto, así que debe llevarse en el cuerpo, normalmente en el pecho. La rutina de búsqueda también hay que ensayarla, o no localizarás a nadie en los diez minutos de oro.",

    "q.l18#8.p" to "Antes de entrar en terreno de aludes, ¿cuál es la preparación más importante?",
    "q.l18#8.o0" to "Llevar todo el material basta",
    "q.l18#8.o1" to "Leer el boletín de aludes del día y ajustar la ruta y el plan de forma continua con las observaciones de campo",
    "q.l18#8.o2" to "Confiar del todo en la experiencia personal",
    "q.l18#8.o3" to "Seguir las huellas que dejó otro",
    "q.l18#8.e" to "El boletín da un juicio regional, la observación de campo da pruebas a escala de pendiente: hacen falta los dos. Seguir huellas antiguas es especialmente peligroso: pueden tener horas y el manto ya ha cambiado.",

    "q.l18#9.p" to "Según las estadísticas, ¿qué causa provoca más muertes en alpinismo?",
    "q.l18#9.o0" to "Primero el alud, después las caídas",
    "q.l18#9.o1" to "Primero las caídas, después el alud",
    "q.l18#9.o2" to "Primero la enfermedad, después la caída de piedras",
    "q.l18#9.o3" to "Primero la hipotermia, después el alud",
    "q.l18#9.e" to "El manual es explícito: primero las caídas, después el alud. Ese orden importa: el alud da más miedo, pero es el resbalón cotidiano el que mata a más gente. Ordena los riesgos por datos, no por impresión.",

    "q.l18#10.p" to "Tras un enterramiento, ¿cuánto dura aproximadamente la ventana de oro?",
    "q.l18#10.o0" to "Unos diez a quince minutos",
    "q.l18#10.o1" to "Dos horas",
    "q.l18#10.o2" to "Seis horas",
    "q.l18#10.o3" to "24 horas",
    "q.l18#10.e" to "Diez a quince minutos: una escala de tiempo que implica que el rescate lo tienen que hacer tus compañeros, porque el rescate organizado llegará demasiado tarde. Por eso el trío hay que llevarlo puesto y practicarlo, no solo guardarlo en la mochila.",

    "q.l18#11.p" to "[Elección múltiple] ¿Qué señales de campo merece la pena vigilar al juzgar el riesgo de alud?",
    "q.l18#11.o0" to "Un «whumpf» cuando el manto colapsa",
    "q.l18#11.o1" to "Grietas frescas que aparecen en la pendiente",
    "q.l18#11.o2" to "Nieve reciente o una acumulación evidente por el viento",
    "q.l18#11.o3" to "Crujidos y hundimiento bajo los pies al subir",
    "q.l18#11.o4" to "Cirros y una visibilidad excelente",
    "q.l18#11.e" to "Son pruebas directas de que la estabilidad está bajando ahora mismo. Su valor es la inmediatez: el boletín da una imagen regional, mientras que estas señales describen la pendiente bajo tus pies en este instante. Hacen falta las dos.",

    "q.l18#12.p" to "La imagen muestra tres tramos de la misma montaña. Toca el tramo con mayor riesgo de alud.",
    "q.l18#12.e" to "Los aludes se concentran entre 34° y 45°. La pendiente suave de la izquierda (unos 16°) es demasiado plana para aludes de placa; la inclinada de la derecha (unos 60°) es demasiado vertical para que la nieve forme una placa gruesa. Solo la pendiente central, a unos 40°, está en la ventana donde la nieve se acumula y puede deslizarse — y es exactamente el ángulo que más a menudo cruzan las rutas de alpinismo, de ahí lo fácil que resulta subestimarlo.",
    // ---------- l19 Planificación y hora de regreso ----------
    "q.l19#0.p" to "¿Para qué sirve fijar una hora de regreso?",
    "q.l19#0.o0" to "Para dar media vuelta sin condiciones a esa hora y no quedar rehén del objetivo",
    "q.l19#0.o1" to "Para calcular tu velocidad de ascensión",
    "q.l19#0.o2" to "Para decidir cuánta comida llevar",
    "q.l19#0.o3" to "Es puro trámite",
    "q.l19#0.e" to "Una hora de regreso saca la decisión de la emoción del momento: una regla fijada cuando estabas razonable ejecuta el juicio por ti cuando estás cansado y reticente. Es la herramienta más eficaz contra la fiebre de cumbre.",

    "q.l19#1.p" to "¿Qué suele causar la fiebre de cumbre?",
    "q.l19#1.o0" to "Un tiempo buenísimo",
    "q.l19#1.o1" to "El coste irrecuperable más la presión del grupo, que distorsionan el juicio",
    "q.l19#1.o2" to "Material inadecuado",
    "q.l19#1.o3" to "Una altitud demasiado baja",
    "q.l19#1.e" to "El tiempo, el dinero y el esfuerzo ya invertidos hacen difícil admitir que hay que parar; el silencio o el ánimo mutuo en la cordada ahogan aún más la duda. Entender ese mecanismo es la condición previa para fijar reglas objetivas de antemano.",

    "q.l19#2.p" to "¿Cuándo debe decidir una cordada su criterio de retirada?",
    "q.l19#2.o0" to "Antes de salir, acordando disparadores objetivos y quién decide",
    "q.l19#2.o1" to "En la cumbre",
    "q.l19#2.o2" to "Cuando aparece el peligro, improvisando",
    "q.l19#2.o3" to "Sobre el terreno, la persona más en forma",
    "q.l19#2.e" to "Debatir la retirada cuando estás cansado, hipóxico y emocional casi siempre se inclina hacia seguir. Acuerda disparadores objetivos de antemano —una hora, un cambio de tiempo, un tipo de estado de la cordada— y nombra quién tiene la última palabra.",

    "q.l19#3.p" to "¿Por qué ocurren tantos accidentes en el descenso?",
    "q.l19#3.o0" to "Porque el terreno de bajada es más duro",
    "q.l19#3.o1" to "Porque la alerta baja una vez alcanzado el objetivo, mientras el cuerpo ya está al límite",
    "q.l19#3.o2" to "Porque el tiempo siempre empeora al bajar",
    "q.l19#3.o3" to "Porque el material falla",
    "q.l19#3.e" to "«La cumbre es solo la mitad del camino» significa en realidad que el riesgo de la salida se libera en el descenso. No se puede relajar el encordamiento, el aseguramiento ni el ritmo al bajar solo porque hayas hecho cumbre.",

    "q.l19#4.p" to "¿Qué valor tiene acordar la decisión de retirada de antemano?",
    "q.l19#4.o0" to "Ahorra tiempo",
    "q.l19#4.o1" to "Saca la decisión de la fatiga y la emoción y deja ejecutar el juicio que tenías antes de salir",
    "q.l19#4.o2" to "Da más autoridad al jefe de cordada",
    "q.l19#4.o3" to "Evita discusiones",
    "q.l19#4.e" to "Decidir en hipoxia, cansado y reticente casi siempre se inclina hacia seguir. Acordar de antemano disparadores objetivos y quién decide es dejar que la versión tranquila de ti mismo decida por la versión agotada.",

    "q.l19#5.p" to "¿Por qué un plan de retirada debe estar escrito en el plan de la salida?",
    "q.l19#5.o0" to "Para que el plan parezca completo",
    "q.l19#5.o1" to "Retirarse necesita material, una ruta y un presupuesto de tiempo; una decisión improvisada no deja tiempo para preparar nada",
    "q.l19#5.o2" to "Para cumplir una inspección",
    "q.l19#5.o3" to "Porque la normativa lo exige",
    "q.l19#5.e" to "La retirada es una operación técnica real: puede necesitar un anclaje, un rápel y progresión de noche. Si el plan nunca presupuestó tiempo ni material para ello, la retirada se convierte en una improvisación de alto riesgo.",

    "q.l19#6.p" to "Cuando los miembros discrepan sobre la ruta o el tiempo, ¿cuál es el enfoque correcto?",
    "q.l19#6.o0" to "Votar por mayoría",
    "q.l19#6.o1" to "Adoptar la visión más conservadora hasta que nuevas pruebas convenzan a todos",
    "q.l19#6.o2" to "Que decida la persona más en forma",
    "q.l19#6.o3" to "Votar y dejar de hablarlo",
    "q.l19#6.e" to "En entornos de alto riesgo, la visión más conservadora debe pesar. La votación por mayoría ahoga la preocupación legítima de una minoría, y la frase más repetida en los análisis de accidentes es «alguien no lo veía claro, pero nadie dijo nada».",

    "q.l19#7.p" to "¿Qué visión de «con guía vas seguro» es correcta?",
    "q.l19#7.o0" to "Un guía te hace absolutamente seguro",
    "q.l19#7.o1" to "Un guía reduce el riesgo pero no elimina los peligros objetivos; los miembros siguen teniendo que juzgar",
    "q.l19#7.o2" to "Los guías solo muestran el camino; la seguridad es cosa tuya",
    "q.l19#7.o3" to "Los miembros no necesitan juzgar nada",
    "q.l19#7.e" to "El valor de un guía es la experiencia y la calidad de sus decisiones, pero los aludes, las caídas de piedras y el tiempo no desaparecen porque alguien vaya delante. Los miembros que entienden el riesgo, detectan señales de peligro y hablan forman parte ellos mismos de la capacidad de seguridad de la cordada.",

    "q.l19#8.p" to "¿Qué es la deriva de objetivos en alpinismo?",
    "q.l19#8.o0" to "Bajar la cota de dificultad de la ruta",
    "q.l19#8.o1" to "Ir relajando poco a poco los criterios de seguridad que te habías fijado, para llegar a la cumbre",
    "q.l19#8.o2" to "Cambiar de pico objetivo a mitad de salida",
    "q.l19#8.o3" to "Reducir el tamaño de la cordada",
    "q.l19#8.e" to "La deriva de objetivos es la firma clásica de la fiebre de cumbre: la hora de regreso se va corriendo, la ventana meteorológica aceptable se va ensanchando, los síntomas se van tolerando. La única defensa es cuantificar los criterios de antemano, para que relajarlos sea explícito y haya que justificarlo ante los compañeros.",

    "q.l19#9.p" to "[Elección múltiple] ¿Qué debe contener un plan de salida completo?",
    "q.l19#9.o0" to "Ruta y horario, incluida la hora de regreso",
    "q.l19#9.o1" to "Plan de retirada y rutas alternativas",
    "q.l19#9.o2" to "Evaluación del estado de la cordada y reparto de roles",
    "q.l19#9.o3" to "Método de comunicación, persona de contacto y procedimiento de emergencia",
    "q.l19#9.o4" to "Un plan de medios y publicidad",
    "q.l19#9.e" to "Los cuatro primeros son necesarios. Los que más se omiten son el segundo y el cuarto, porque no hacen falta cuando todo va bien. Pero un plan vale precisamente cuando las cosas van mal, y para entonces ya no hay tiempo de escribirlo.",

    "q.l19#10.p" to "¿Por qué reservar días de margen en un itinerario?",
    "q.l19#10.o0" to "Para absorber retrasos como una ventana meteorológica más tardía o un miembro indispuesto",
    "q.l19#10.o1" to "Para descansar más",
    "q.l19#10.o2" to "Para ahorrar dinero",
    "q.l19#10.o3" to "Para que el itinerario parezca cómodo",
    "q.l19#10.e" to "Las salidas de alta montaña casi siempre se deslizan: el tiempo no colabora, alguien necesita un día más de aclimatación, la aproximación es más lenta de lo previsto. Sin margen, cualquier retraso obliga a recortar aclimatación o a alargar las etapas diarias: las dos cosas disparan el riesgo.",

    "q.l19#11.p" to "[Orden] Pon en un orden sensato los pasos para construir un plan de salida.",
    "q.l19#11.o0" to "Fijar el objetivo y la ruta; reunir información y el historial meteorológico",
    "q.l19#11.o1" to "Evaluar capacidad y tiempo de la cordada; programar el ritmo de aclimatación",
    "q.l19#11.o2" to "Fijar la hora de regreso y disparadores de retirada cuantificables",
    "q.l19#11.o3" to "Escribir el plan de retirada y el procedimiento de emergencia, e informar al contacto en casa",
    "q.l19#11.e" to "El orden dice: fijar el objetivo, comprobar la capacidad, trazar la línea roja y luego conservar la salida. Mucha gente lo invierte —objetivo primero, salida al final— y por eso la salida acaba en el fondo de la lista y nunca se diseña de verdad.",

    "q.l19#12.p" to "¿Por qué se subestima tanto el tiempo de descenso?",
    "q.l19#12.o0" to "Porque bajar es más rápido",
    "q.l19#12.o1" to "Porque estás agotado, la nieve puede estar peor y todavía hay que asegurar y recuperar el material",
    "q.l19#12.o2" to "Porque los mapas son inexactos",
    "q.l19#12.o3" to "Porque los guías te meten prisa",
    "q.l19#12.e" to "La subida puede haber costado seis horas, pero el descenso a menudo cuesta más: menos energía, nieve más blanda o más helada, peor visibilidad y, quizá, rápeles y recuperación del material. Estimar el descenso a partir del tiempo de subida es uno de los errores de planificación más habituales.",

    "q.l19#13.p" to "¿Por qué detallar en el plan las comunicaciones y los contactos?",
    "q.l19#13.o0" to "Para el registro",
    "q.l19#13.o1" to "Porque si desapareces, la gente de casa necesita saber dónde buscar y cuándo empezar",
    "q.l19#13.o2" to "Para informar a la empresa",
    "q.l19#13.o3" to "Para cumplir los requisitos del permiso",
    "q.l19#13.e" to "Lo más difícil de la búsqueda y el rescate es no saber dónde está la persona. El itinerario, la ruta, las alternativas y las horas de contacto son lo que comprime una búsqueda de días a horas, y esa información solo se puede dar antes de salir.",

    "q.l19#14.p" to "¿Cómo afecta el tamaño de la cordada al plan?",
    "q.l19#14.o0" to "El tamaño no tiene nada que ver con la planificación",
    "q.l19#14.o1" to "Más gente significa avance más lento, logística más pesada y aclimatación más difícil de sincronizar",
    "q.l19#14.o2" to "Más gente es más seguro, así que no hace falta ajustar nada",
    "q.l19#14.o3" to "Más gente es más rápido",
    "q.l19#14.e" to "Una cordada grande comparte fuerzas y recursos, a cambio de velocidad y flexibilidad: cada uno tiene su ritmo y el grupo solo puede avanzar al del más lento. El tamaño de la cordada forma parte de tu estimación de tiempos, no de las quejas posteriores.",

    "q.l19#15.p" to "Completa: los itinerarios de alta montaña suelen reservar alrededor de un ( ) % de días de margen.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "veinte",
    "q.l19#15.e" to "La recomendación habitual es un margen del 20–30 %. Una salida de diez días, por ejemplo, debería planificarse a doce o trece para víveres, permisos y días libres: parece excesivo hasta que lo comparas con la frecuencia real de los retrasos.",

    // ---------- l20 Rescate y primeros auxilios ----------
    "q.l20#0.p" to "¿Cuál es el primer principio del rescate?",
    "q.l20#0.o0" to "Mover a la víctima lo más rápido posible",
    "q.l20#0.o1" to "Asegurar la escena para no crear una segunda víctima",
    "q.l20#0.o2" to "Fotografiar la escena primero",
    "q.l20#0.o3" to "Dar agua a la víctima primero",
    "q.l20#0.e" to "Entre caídas de piedras, aludes, grietas o terreno inclinado, correr hacia la víctima convierte a menudo al rescatador en segunda víctima y reduce a la mitad la mano de obra disponible. Evaluar la escena es el primer paso y el que no se puede saltar.",

    "q.l20#1.p" to "¿Por dónde empieza la secuencia correcta de emergencia?",
    "q.l20#1.o0" to "Asegurar primero la escena y después evaluar las lesiones",
    "q.l20#1.o1" to "Mover primero a la víctima a un lugar seguro",
    "q.l20#1.o2" to "Buscar comida y agua",
    "q.l20#1.o3" to "Montar un sistema de cuerda",
    "q.l20#1.e" to "La secuencia estándar es: seguridad, evaluación, petición de ayuda, tratamiento y traslado. Saltarse la evaluación de seguridad e ir directo a la víctima es el error de rescate más frecuente.",

    "q.l20#2.p" to "¿Por qué la prevención importa mucho más que el rescate en altura?",
    "q.l20#2.o0" to "Porque el rescate es caro",
    "q.l20#2.o1" to "Porque el rescate está limitado por el tiempo, el oxígeno y los efectivos, y a menudo no puede llegar a tiempo",
    "q.l20#2.o2" to "Porque los equipos de rescate no quieren venir",
    "q.l20#2.o3" to "Porque no hay cobertura telefónica",
    "q.l20#2.e" to "La altura degrada a los dos lados: los helicópteros están limitados por turbulencias y altura, los equipos de tierra necesitan horas para llegar, y una víctima se deteriora más rápido con hipoxia y frío. Ese hueco de tiempo es el único recurso de rescate del que realmente dispones.",

    "q.l20#3.p" to "¿Por qué un rescate en montaña tarda a menudo horas o días?",
    "q.l20#3.o0" to "Porque los equipos no quieren ir",
    "q.l20#3.o1" to "Por límites estrictos de tiempo, oxígeno, comunicaciones y efectivos; los helicópteros están condicionados por turbulencias y altitud",
    "q.l20#3.o2" to "Porque las distancias son demasiado grandes",
    "q.l20#3.o3" to "Porque cuesta demasiado",
    "q.l20#3.e" to "En altura un helicóptero sufre con la sustentación y las turbulencias, y un equipo de tierra tarda horas en llegar hasta ti. Ese hueco significa una cosa: allá arriba, tú eres tu propio primer equipo de rescate.",

    "q.l20#4.p" to "¿Para qué dejar un itinerario y una persona de contacto?",
    "q.l20#4.o0" to "Es puro trámite",
    "q.l20#4.o1" to "Si desapareces, los rescatadores saben dónde buscar, lo que acorta mucho la búsqueda",
    "q.l20#4.o2" to "Para facilitar las notas de gastos",
    "q.l20#4.o3" to "Para cumplir las normas",
    "q.l20#4.e" to "Lo más difícil de la búsqueda y el rescate es no saber dónde está la persona. El itinerario, la ruta, los planes alternativos y los contactos son lo que comprime una búsqueda de días a horas.",

    "q.l20#5.p" to "En la evaluación de una víctima, ¿qué se trata primero?",
    "q.l20#5.o0" to "Entablillar las fracturas",
    "q.l20#5.o1" to "Los problemas que amenazan la vida, como la vía aérea y la respiración",
    "q.l20#5.o2" to "Registrar las lesiones con detalle",
    "q.l20#5.o3" to "Limpiar las heridas visibles",
    "q.l20#5.e" to "La evaluación sigue el orden de amenazas vitales: vía aérea, respiración y circulación antes que fracturas y heridas que no matan de inmediato. Si el orden está mal, todo lo demás importa mucho menos.",

    "q.l20#6.p" to "En altura, ¿por qué el aislamiento es una parte crítica de los primeros auxilios?",
    "q.l20#6.o0" to "Porque da comodidad a la víctima",
    "q.l20#6.o1" to "Porque una víctima inmovilizada pierde calor rápido, lo que agrava la lesión",
    "q.l20#6.o2" to "Porque la normativa lo exige",
    "q.l20#6.o3" to "Para facilitar el transporte",
    "q.l20#6.e" to "Con frío e hipoxia, una víctima que no puede moverse pierde rápido su producción de calor. La hipotermia profundiza el shock y enmascara los síntomas, así que aislar del suelo, cortar el viento y cambiar la ropa mojada importan tanto como parar una hemorragia.",

    "q.l20#7.p" to "¿Qué debe prever el plan de emergencia de la cordada si fallan las comunicaciones?",
    "q.l20#7.o0" to "Esperar en el sitio a que vuelva el contacto",
    "q.l20#7.o1" to "Acordar de antemano un punto de encuentro, una hora límite sin contacto y las acciones siguientes",
    "q.l20#7.o2" to "Separarse y buscar de inmediato",
    "q.l20#7.o3" to "Que todos desciendan a la vez",
    "q.l20#7.e" to "Perder las comunicaciones en montaña es normal, no excepcional. Acordar de antemano qué pasa si no se ha dado señales a una hora determinada evita el pánico abajo y dice al contacto en casa cuándo dar la alarma.",

    "q.l20#8.p" to "¿Cuál es la actitud correcta ante la formación en primeros auxilios y rescate?",
    "q.l20#8.o0" to "Ver un tutorial y memorizar los pasos es suficiente",
    "q.l20#8.o1" to "Hay que ensayarlo en la práctica con regularidad; solo leer no se sostiene en una escena real",
    "q.l20#8.o2" to "Solo lo necesita el jefe de cordada",
    "q.l20#8.o3" to "Es solo para rescatadores profesionales",
    "q.l20#8.e" to "Los primeros auxilios y el rescate son habilidades muy procedimentales, y bajo presión vuelves al nivel en el que realmente te entrenaste. Leer construye el marco; solo el ensayo repetido mantiene los gestos correctos cuando tienes miedo.",

    "q.l20#9.p" to "[Orden] Pon en orden la secuencia estándar de evaluación y tratamiento de una víctima.",
    "q.l20#9.o0" to "Asegurar la escena para no crear una segunda víctima",
    "q.l20#9.o1" to "Evaluar consciencia, vía aérea, respiración y circulación",
    "q.l20#9.o2" to "Tratar las amenazas vitales inmediatas: hemorragia, aislamiento, entablillado",
    "q.l20#9.o3" to "Pedir ayuda y organizar el traslado, o esperar un rescate profesional",
    "q.l20#9.e" to "Los pasos uno y cuatro son los que más se saltan: bajo estrés la gente corre directo hacia la víctima. Pero una escena insegura convierte al rescatador en segunda víctima y divide tu mano de obra, y sin pedir ayuda no hay respaldo para nada de lo que venga después.",

    "q.l20#10.p" to "[Elección múltiple] ¿Qué información clave debe incluir una petición de ayuda?",
    "q.l20#10.o0" to "Localización exacta (coordenadas o un punto identificable)",
    "q.l20#10.o1" to "Número de víctimas, consciencia y estado respiratorio",
    "q.l20#10.o2" to "Terreno y tiempo en la escena",
    "q.l20#10.o3" to "Medio de comunicación disponible y horas de contacto",
    "q.l20#10.o4" to "El historial alpinístico de la víctima",
    "q.l20#10.e" to "Estos cuatro deciden qué se envía, cuánto y por qué vía. Una localización vaga pierde horas, unas lesiones desconocidas implican material inadecuado, y un tiempo desconocido puede poner en peligro también al equipo de rescate. Pedir ayuda es una habilidad de comunicación que merece ensayarse.",

    "q.l20#11.p" to "¿Por qué el rescate en helicóptero suele ser imposible en altura?",
    "q.l20#11.o0" to "Porque es demasiado caro",
    "q.l20#11.o1" to "Porque el aire enrarecido reduce la sustentación y la carga útil, las turbulencias son fuertes y las ventanas meteorológicas cortas",
    "q.l20#11.o2" to "Porque los pilotos se niegan a volar allí",
    "q.l20#11.o3" to "Porque no hay aerovías en altura",
    "q.l20#11.e" to "La sustentación de un helicóptero viene del aire, y arriba el aire es escaso: eso limita directamente cuánto puede levantar y hasta dónde puede operar. Súmale aire montañoso turbulento y un tiempo que cambia rápido: la ventana de vuelo puede quedarse en decenas de minutos. Por eso el rescate no puede ser tu plan.",

    "q.l20#12.p" to "[Asociación] Asocia cada medida de primeros auxilios con cuándo se aplica.",
    "q.l20#12.l0" to "Aislamiento",
    "q.l20#12.r0" to "Prioridad para cualquier víctima en altura, para evitar que la hipotermia agrave el shock",
    "q.l20#12.l1" to "Control de hemorragia",
    "q.l20#12.r1" to "Primera respuesta ante una herida abierta o un sangrado en una extremidad",
    "q.l20#12.l2" to "Entablillado",
    "q.l20#12.r2" to "Sospecha de fractura o lesión articular, para evitar más daño al mover",
    "q.l20#12.l3" to "Oxígeno",
    "q.l20#12.r3" to "Dificultad respiratoria, saturación claramente baja o sospecha de edema pulmonar",
    "q.l20#12.e" to "Las cuatro son acciones básicas en altura, no procedimientos de especialista. Lo que comparten es que no necesitan material complejo pero sí el orden correcto: el aislamiento, por ejemplo, suele llegar tarde en primeros auxilios generales, pero arriba es prioritario.",

    "q.l20#13.p" to "¿Por qué evaluar el riesgo del propio rescate?",
    "q.l20#13.o0" to "Porque rescatar cansa",
    "q.l20#13.o1" to "Porque el rescate puede poner en peligro a más gente y bajar las probabilidades globales de supervivencia",
    "q.l20#13.o2" to "Porque el seguro lo exige",
    "q.l20#13.o3" to "Porque la normativa lo exige",
    "q.l20#13.e" to "Las decisiones de rescate son asignación de recursos: si llegar hasta la víctima lesiona a dos rescatadores, pasas de una víctima y dos rescatadores a tres víctimas y nadie. Eso no es frialdad, es la aritmética que maximiza la supervivencia global.",

    "q.l20#14.p" to "¿Cuándo hay que dejar el autorrescate y esperar a un rescate profesional?",
    "q.l20#14.o0" to "Seguir autorrescatándose mientras queden fuerzas",
    "q.l20#14.o1" to "Cuando el autorrescate arriesga más lesiones, o las condiciones superan la capacidad de la cordada",
    "q.l20#14.o2" to "Solo cuando estés completamente agotado",
    "q.l20#14.o3" to "Nunca dejar el autorrescate",
    "q.l20#14.e" to "El autorrescate sirve para ganar tiempo, no para correr riesgos. Cuando seguir podría lesionar más gravemente a la víctima o a los rescatadores, o cuando una tormenta hace más arriesgado moverse que quedarse, sostener la situación y esperar refuerzos es la mejor respuesta.",

    "q.l20#15.p" to "Completa: en la evaluación SAMPLE, la E corresponde a ( ).",
    "q.l20#15.a0" to "evento",
    "q.l20#15.a1" to "Evento",
    "q.l20#15.a2" to "el evento",
    "q.l20#15.a3" to "suceso",
    "q.l20#15.e" to "E significa Event: qué ocurrió. Este punto suele infravalorarse: el mecanismo (cómo se produjo la caída, si hubo golpe en la cabeza, cuánto duró el enterramiento) apunta directamente a las lesiones probables y es una pista clave de la evaluación.",
    // ---------- l21 Equipo: sistema de tres capas ----------
    "q.l21#0.p" to "En un sistema de tres capas, ¿cuál es la función principal de la primera capa?",
    "q.l21#0.o0" to "Bloquear el viento y la nieve",
    "q.l21#0.o1" to "Alejar el sudor de la piel y mantenerte seco",
    "q.l21#0.o2" to "Aportar la mayor parte del calor",
    "q.l21#0.o3" to "Guardar objetos de repuesto",
    "q.l21#0.e" to "La función esencial de la primera capa es evacuar la humedad. Va pegada a la piel, y si se queda húmeda, por muchas capas que lleves encima el calor sigue escapando: por eso se la llama segunda piel.",

    "q.l21#1.p" to "¿Por qué el forro polar es más fiable que el plumífero en condiciones húmedas?",
    "q.l21#1.o0" to "Porque el polar es más grueso",
    "q.l21#1.o1" to "Porque la fibra de poliéster es naturalmente hidrófoba y sigue aislando mojada",
    "q.l21#1.o2" to "Porque el polar es más barato",
    "q.l21#1.o3" to "Porque el plumón no se puede llevar como capa interior",
    "q.l21#1.e" to "El polar está hecho de fibra plástica (poliéster), que casi no absorbe nada, así que sigue atrapando una capa de aire y aislando cuando está húmedo. El plumón se apelmaza y pierde volumen en cuanto se moja: por eso hay que mantenerlo estrictamente seco.",

    "q.l21#2.p" to "¿Qué poder de relleno se recomienda para un plumífero destinado al frío extremo de alta montaña?",
    "q.l21#2.o0" to "Menos de 500",
    "q.l21#2.o1" to "Alrededor de 600",
    "q.l21#2.o2" to "800 de poder de relleno o más",
    "q.l21#2.o3" to "El poder de relleno no importa",
    "q.l21#2.e" to "Cuanto mayor el poder de relleno, más aire atrapa el mismo peso de plumón y más eficaz es el aislamiento. 800 o más es la recomendación habitual para salidas de alta montaña, junto con capucha y sin relleno sintético.",

    "q.l21#3.p" to "¿Cuál es la función esencial de una chaqueta de membrana?",
    "q.l21#3.o0" to "Aportar la mayor parte del calor",
    "q.l21#3.o1" to "Ser impermeable, cortavientos y transpirable, con capucha que quepa sobre el casco",
    "q.l21#3.o2" to "Evacuar el sudor",
    "q.l21#3.o3" to "Añadir peso para entrenar",
    "q.l21#3.e" to "La membrana deja fuera el viento, la lluvia y la nieve mientras permite escapar la humedad que generas. Si la transpirabilidad es mala, el vapor de sudor se condensa en las capas interiores: acabas creando tu propio ambiente húmedo.",

    "q.l21#4.p" to "¿Qué guante del sistema está pensado específicamente para usar pantallas táctiles?",
    "q.l21#4.o0" to "Guantes finos de polar",
    "q.l21#4.o1" to "Un guante cortavientos y resistente a la abrasión, con buena sensibilidad táctil",
    "q.l21#4.o2" to "Guantes gruesos de guía, aislados",
    "q.l21#4.o3" to "Guantes de cumbre",
    "q.l21#4.e" to "Usar un teléfono, un GPS o una cámara en altura exige un guante que sea a la vez cortavientos y compatible con pantalla táctil. Quitarse los guantes para manejar aparatos es uno de los desencadenantes de congelación más frecuentes: mejor llevar un par extra justo para eso.",

    "q.l21#5.p" to "¿Qué afirmación sobre los calentadores de manos y pies es correcta?",
    "q.l21#5.o0" to "Se pueden pegar en cualquier parte por fuera de los calcetines",
    "q.l21#5.o1" to "Úsalos solo en espacios cerrados como guantes o el interior de las botas; expuestos al aire ventilado pueden alcanzar unos 74 °C",
    "q.l21#5.o2" to "Cuanto más cerca de la piel, mejor",
    "q.l21#5.o3" to "Se pueden pegar por fuera de un gorro",
    "q.l21#5.e" to "Los calentadores dependen de un aire limitado para regular su temperatura. Expuestos al aire ventilado reaccionan con fuerza y pueden llegar a unos 74 °C, suficiente para causar quemaduras. Van por tanto en espacios cerrados —guantes, interior de las botas— y nunca directamente contra la piel ni sobre una superficie expuesta.",

    "q.l21#6.p" to "¿Por qué se recomiendan chaquetas aislantes y plumíferos con capucha?",
    "q.l21#6.o0" to "Porque quedan mejor",
    "q.l21#6.o1" to "Porque son más versátiles y reducen mucho la pérdida de calor por la cabeza",
    "q.l21#6.o2" to "Porque se guardan más fácilmente",
    "q.l21#6.o3" to "Porque las versiones con capucha pesan menos",
    "q.l21#6.e" to "La cabeza es una fuente importante de pérdida de calor, y una capucha es el aislamiento más ligero disponible justo en el centro del cuerpo. Una chaqueta con capucha se despliega al instante en el campamento, en las paradas o cuando la temperatura cae de golpe; sin capucha, hay que llevar un gorro aparte, más engorro y más peso.",

    "q.l21#7.p" to "[Elección múltiple] ¿Qué prácticas son correctas para usar y guardar un plumífero?",
    "q.l21#7.o0" to "Mantenerlo estrictamente seco; mojado pierde aislamiento muy rápido",
    "q.l21#7.o1" to "Guardarlo seco",
    "q.l21#7.o2" to "Con frío extremo, elegir una versión con capucha y sin relleno sintético",
    "q.l21#7.o3" to "Cuanto mayor el poder de relleno, más calor a igual peso",
    "q.l21#7.o4" to "Guardarlo a largo plazo en un saco de compresión para ahorrar espacio",
    "q.l21#7.e" to "El plumón aísla atrapando aire y se apelmaza en cuanto se moja. Es también por eso que el polar (poliéster hidrófobo) se prefiere como capa intermedia de trabajo en condiciones húmedas, dejando el plumón como aislamiento del centro del cuerpo para ambientes secos.",

    "q.l21#8.p" to "¿Qué especificación es razonable para una crema solar de alta montaña?",
    "q.l21#8.o0" to "FPS 15, una loción normal basta",
    "q.l21#8.o1" to "Alto contenido en óxido de zinc, nivel FPS 50",
    "q.l21#8.o2" to "Por debajo de FPS 30 transpira mejor",
    "q.l21#8.o3" to "Cualquier producto con filtro solar, sea cual sea el número",
    "q.l21#8.e" to "Los UV son intensos en altura y el reflejo de la nieve añade una segunda dosis, así que una crema normal deja de bastar enseguida. Alto contenido en óxido de zinc y FPS 50 es la recomendación habitual, y hay que reaplicarla con regularidad, porque el sudor, los secados y el roce degradan la protección.",

    "q.l21#9.p" to "¿Qué importa al elegir un protector labial para el aire libre?",
    "q.l21#9.o0" to "Cuanto más barato, mejor",
    "q.l21#9.o1" to "Rico en zinc, algo resistente al sudor, con FPS 30–50",
    "q.l21#9.o2" to "Que hidrate, ya basta",
    "q.l21#9.o3" to "El mentol da más sensación de frescor",
    "q.l21#9.e" to "La piel de los labios es fina y casi no tiene protección de melanina, así que en altura se quema y se agrieta con facilidad. El zinc aporta protección física, y la resistencia al sudor lo mantiene en su sitio a través del sudor, las comidas y la bebida: el equipo más pequeño, el que más se olvida y el que más afecta a cómo se siente la salida.",

    // ---------- l22 Equipo técnico y comunicaciones ----------
    "q.l22#0.p" to "¿Cuál es el equipo más básico para montar un sistema de rescate en grieta?",
    "q.l22#0.o0" to "Anillos de prusik (cordeleta)",
    "q.l22#0.o1" to "Prismáticos",
    "q.l22#0.o2" to "Un saco de dormir de repuesto",
    "q.l22#0.o3" to "Bastones de trekking",
    "q.l22#0.e" to "Los anillos de prusik sirven para hacer nudos de fricción y son el núcleo de un sistema de izado 3:1. Sin ellos solo tienes la tracción 1:1 de tus manos, y una sola persona casi nunca logra sacar a un compañero de una grieta por fuerza bruta.",

    "q.l22#1.p" to "En alta montaña, ¿cuál es normalmente la forma más fiable de pedir ayuda?",
    "q.l22#1.o0" to "La cobertura del móvil",
    "q.l22#1.o1" to "Un teléfono satelital o un localizador GPS",
    "q.l22#1.o2" to "Gritar",
    "q.l22#1.o3" to "Encender una hoguera con humo",
    "q.l22#1.e" to "La mayoría de las zonas de montaña no tienen cobertura móvil. Un teléfono satelital permite llamadas y mensajes directos, y un localizador GPS permite al exterior seguir tu posición: ambas cosas hay que resolverlas antes de salir, no en la montaña.",

    "q.l22#2.p" to "¿Qué luminosidad se recomienda para un frontal de repuesto?",
    "q.l22#2.o0" to "Menos de 100 lúmenes",
    "q.l22#2.o1" to "200 lúmenes bastan",
    "q.l22#2.o2" to "400 lúmenes o más",
    "q.l22#2.o3" to "La luminosidad no importa",
    "q.l22#2.e" to "Un frontal se usa para moverse por la tienda de noche y para las salidas antes del amanecer (las acometidas a cumbre suelen empezar de madrugada). Con viento, nieve, niebla y cuando hay que identificar la ruta, una luminosidad adecuada influye directamente en la calidad de tu juicio. Los modelos estancos son claramente mejores con mal tiempo.",

    "q.l22#3.p" to "¿Cuál es el requisito clave al elegir un arnés de alpinismo?",
    "q.l22#3.o0" to "Lo más ligero posible, sea cual sea la talla",
    "q.l22#3.o1" to "Suficientemente grande en cintura y perneras para ponerse por encima de la ropa más externa",
    "q.l22#3.o2" to "Debe tener varios portamaterial",
    "q.l22#3.o3" to "Un color bien visible",
    "q.l22#3.e" to "En altura sueles llevar ropa voluminosa, y el arnés tiene que cerrarse correctamente por encima. Un arnés estirado al máximo solo para cerrar sobre capas gruesas es una configuración habitual y peligrosa.",

    "q.l22#4.p" to "¿En qué se basa la alarma de tormenta de un reloj altímetro para detectarlas?",
    "q.l22#4.o0" to "En imágenes satelitales de nubes",
    "q.l22#4.o1" to "En una caída rápida de la presión barométrica en poco tiempo",
    "q.l22#4.o2" to "En la medición de la velocidad del viento",
    "q.l22#4.o3" to "En una caída brusca de temperatura",
    "q.l22#4.e" to "Una caída rápida de presión es la señal precursora de un empeoramiento del tiempo. Un reloj altímetro avisa vigilando de forma continua la variación de presión, algo muy práctico en altura, porque cómo se desplaza la ventana meteorológica suele ser la variable decisiva de una salida.",

    "q.l22#5.p" to "[Asociación] Asocia cada forma de mosquetón con su uso más adecuado.",
    "q.l22#5.l0" to "HMS en forma de pera",
    "q.l22#5.r0" to "Apertura amplia; admite un nudo dinámico para rápel, el más versátil",
    "q.l22#5.l1" to "En forma de D",
    "q.l22#5.r1" to "Se combina a menudo con una polea en sistemas de rescate",
    "q.l22#5.l2" to "En forma de X",
    "q.l22#5.r2" to "Simétrico, cierre sencillo, fácil de mosquetonear",
    "q.l22#5.l3" to "En forma de B",
    "q.l22#5.r3" to "El mosquetón básico para todo tipo de uniones temporales",
    "q.l22#5.e" to "Cada forma tiene su punto fuerte: el HMS abre lo suficiente para un nudo y un rápel, el D es resistente y admite bien una polea, el X es simétrico y manejable, el B es la base polivalente. Elegir mosquetón no es decidir cuál es «más fuerte», sino si su mecanismo encaja con el trabajo.",

    "q.l22#6.p" to "Al usar un bloqueador, ¿contra qué advierte específicamente el manual?",
    "q.l22#6.o0" to "Usarlo con humedad",
    "q.l22#6.o1" to "Empujar el bloqueador demasiado cerca del punto fijo (un nudo)",
    "q.l22#6.o2" to "Manejarlo con una sola mano",
    "q.l22#6.o3" to "Usarlo sobre nieve",
    "q.l22#6.e" to "Pegar el bloqueador justo contra un nudo o un punto fijo lo deja sin recorrido y a la vez difícil de liberar rápido: te quedas atascado ahí, sin poder subir ni soltarte. Ese tipo de bloqueo es muy peligroso cuando hay que ajustar rápido, así que resuélvelo mientras aún tengas margen.",

    "q.l22#7.p" to "¿Qué afirmación sobre elegir cuerda fija frente a progresar encordados es correcta?",
    "q.l22#7.o0" to "La cuerda fija siempre es más segura que ir encordados",
    "q.l22#7.o1" to "Las cordadas grandes tienden a usar cuerda fija; las pequeñas o los picos técnicos avanzan mejor encordados",
    "q.l22#7.o2" to "Progresar encordados solo sirve en pendientes de nieve",
    "q.l22#7.o3" to "La cuerda fija solo sirve para descender",
    "q.l22#7.e" to "La cuerda fija eleva la seguridad global pero exige más gente y material y tarda más en instalarse. Una cordada pequeña y eficiente, o un pico técnico, suele estar mejor servida por la progresión encordada. Es el caso de manual de «no hay una única respuesta mejor, solo una adecuación».",

    "q.l22#8.p" to "[Elección múltiple] ¿Cuáles de estos son dispositivos de comunicación y navegación de alta montaña?",
    "q.l22#8.o0" to "Teléfono satelital",
    "q.l22#8.o1" to "Emisora de radio bidireccional",
    "q.l22#8.o2" to "Localizador GPS",
    "q.l22#8.o3" to "Reloj altímetro con barómetro",
    "q.l22#8.o4" to "Prismáticos",
    "q.l22#8.e" to "Los cuatro primeros hacen cosas distintas: el teléfono satelital para pedir ayuda hacia fuera, la emisora para coordinar dentro de la cordada, el localizador GPS para que el exterior sepa dónde estás y el reloj altímetro para seguir la presión y la altitud. Los riesgos en altura son precisamente no poder pedir ayuda y no saber dónde estás: estos aparatos atacan directamente esos dos puntos.",

    "q.l22#9.p" to "¿Por qué un casco debe admitir soporte de frontal?",
    "q.l22#9.o0" to "Por coherencia visual",
    "q.l22#9.o1" to "Porque las acometidas a cumbre suelen empezar antes del amanecer y el frontal debe quedar estable en la cabeza",
    "q.l22#9.o2" to "Para reducir el peso del frontal",
    "q.l22#9.o3" to "Para aumentar la resistencia del casco",
    "q.l22#9.e" to "El día de cumbre suele empezar de madrugada, y el frontal es la única fuente de luz; con casco, hay que fijarlo a él para que alumbre de forma estable. Un frontal que baila o se suelta en marcha significa que no ves tus apoyos: un riesgo real en terreno técnico.",
    // ---------- m01 Ciencia del entorno de altura ----------
    "q.m01#0.p" to "¿Cuánto baja aproximadamente la temperatura del aire por cada 1.000 m de ascenso?",
    "q.m01#0.o0" to "Unos 1,5 °C",
    "q.m01#0.o1" to "Unos 3 °C",
    "q.m01#0.o2" to "Unos 6,5 °C",
    "q.m01#0.o3" to "Unos 10 °C",
    "q.m01#0.e" to "La temperatura baja unos 6,5 °C por cada 1.000 m: es el gradiente térmico vertical. Explica la altitud de la límite de las nieves y por qué un pico de 5.000 m sigue nevado incluso en verano.",

    "q.m01#1.p" to "¿Cuál es la causa fundamental de la hipoxia en altura?",
    "q.m01#1.o0" to "Que la proporción de oxígeno en el aire es menor",
    "q.m01#1.o1" to "Que la presión atmosférica baja, así que la presión parcial de oxígeno de cada respiración disminuye",
    "q.m01#1.o2" to "Que la radiación ultravioleta descompone el oxígeno",
    "q.m01#1.o3" to "Que el aire se enrarece y el oxígeno es sustituido por otros gases",
    "q.m01#1.e" to "Es un error muy extendido. El oxígeno sigue siendo aproximadamente el 21 % del aire en altura: la proporción no cambia. Lo que cambia es la presión: a menor presión hay menos moléculas de oxígeno en el mismo volumen, así que la presión parcial baja y el cuerpo recibe menos oxígeno.",

    "q.m01#2.p" to "[Elección múltiple] ¿Cuáles de estos rasgos son típicos del entorno de alta montaña?",
    "q.m01#2.o0" to "Baja presión y baja presión parcial de oxígeno",
    "q.m01#2.o1" to "Baja temperatura con gran oscilación día-noche",
    "q.m01#2.o2" to "Radiación ultravioleta notablemente más intensa",
    "q.m01#2.o3" to "Aire extremadamente seco",
    "q.m01#2.o4" to "Una proporción de oxígeno en el aire notablemente menor",
    "q.m01#2.e" to "Los cuatro primeros son correctos y se amplifican entre sí: frío más hipoxia significa que el cuerpo sufre a la vez para producir calor y para obtener oxígeno; sequedad más UV fuertes dañan más rápido las vías respiratorias, la piel y los ojos. El equipo y el itinerario tienen que cubrir los cuatro a la vez.",

    "q.m01#3.p" to "La presión al nivel del mar es de unos 1.013 hPa. ¿Cuál es la presión a 5.000 m?",
    "q.m01#3.o0" to "Unos 900 hPa",
    "q.m01#3.o1" to "Unos 700 hPa",
    "q.m01#3.o2" to "Unos 540 hPa",
    "q.m01#3.o3" to "Unos 300 hPa",
    "q.m01#3.e" to "A 5.000 m la presión es aproximadamente la mitad de la del nivel del mar. Cada respiración contiene por tanto cerca de la mitad de moléculas de oxígeno: el cuerpo compensa subiendo la frecuencia respiratoria y cardiaca, y esa es la razón física de que estés sin aire y más lento allá arriba.",

    "q.m01#4.p" to "Completa: la temperatura baja unos ( ) °C por cada 1.000 m de ascenso.",
    "q.m01#4.a0" to "6,5",
    "q.m01#4.a1" to "6.5",
    "q.m01#4.e" to "6,5 °C por 1.000 m. El dato es realmente útil para planificar: pasar de un campo base a 3.000 m a otro a 5.000 m significa unos 13 °C menos, lo que decide directamente el grosor necesario del plumífero y del saco de dormir.",

    "q.m01#5.p" to "[Orden] Pon en orden la cadena causal de la hipoxia de altura.",
    "q.m01#5.o0" to "Baja la presión atmosférica, lo que reduce la presión parcial de oxígeno que inspiras",
    "q.m01#5.o1" to "Cae la saturación arterial de oxígeno",
    "q.m01#5.o2" to "El cuerpo compensa aumentando la frecuencia respiratoria y cardiaca",
    "q.m01#5.o3" to "Una hipoxia mantenida puede progresar a mal de altura",
    "q.m01#5.e" to "Esta cadena es el esqueleto de la medicina de altura: entorno, fisiología, compensación, descompensación. Una vez que la ves, el MAM, el ECA y el EPA dejan de ser hechos separados y pasan a ser etapas distintas de una misma cadena.",

    "q.m01#6.p" to "¿Cuál es la reflectividad de la nieve reciente?",
    "q.m01#6.o0" to "Unos 20 %",
    "q.m01#6.o1" to "Unos 40 %",
    "q.m01#6.o2" to "Unos 60 %",
    "q.m01#6.o3" to "Unos 80–90 %",
    "q.m01#6.e" to "La nieve reciente refleja en torno al 80–90 % de la radiación solar. La exposición a UV en un campo de nieve es por tanto casi el doble: directa desde arriba más reflejada por la superficie. Por eso la ceguera de la nieve y las quemaduras solares graves son tan frecuentes en montaña.",

    "q.m01#7.p" to "¿Por qué la protección solar en altura es obligatoria y no opcional?",
    "q.m01#7.o0" to "Porque el sol está más cerca de la tierra allá arriba",
    "q.m01#7.o1" to "Porque los UV aumentan con la altitud y la nieve los devuelve a tu cara",
    "q.m01#7.o2" to "Porque la capa de ozono es más fina y la luz visible es más fuerte",
    "q.m01#7.o3" to "Porque el frío debilita la resistencia de la piel",
    "q.m01#7.e" to "La intensidad de los UV sube en torno al 10–12 % por cada 1.000 m, y la nieve añade otro 80–90 % de reflexión. Juntos, la dosis supera de largo la de un lugar de baja altitud en la misma latitud. Crema solar, protector labial y gafas UV400 son equipo, no extras.",

    "q.m01#8.p" to "El aire seco de la altura tiene una consecuencia fácil de pasar por alto. ¿Cuál?",
    "q.m01#8.o0" to "Mejor piel",
    "q.m01#8.o1" to "Pérdida insensible de agua por la respiración y el sudor, que agrava la deshidratación y los síntomas de altura",
    "q.m01#8.o2" to "Más apetito",
    "q.m01#8.o3" to "Sueño más profundo",
    "q.m01#8.e" to "El aire seco y la respiración más rápida van retirando humedad de las vías respiratorias de forma continua, y a menudo no sientes nada de sed. La deshidratación espesa la sangre y agrava la sensación de hipoxia y la cefalea: beber con regularidad forma parte de la aclimatación, no es un detalle secundario.",

    "q.m01#9.p" to "[Elección múltiple] ¿Cuáles de estas lesiones las causa directamente el entorno de alta montaña?",
    "q.m01#9.o0" to "Quemadura solar",
    "q.m01#9.o1" to "Ceguera de la nieve",
    "q.m01#9.o2" to "Deshidratación",
    "q.m01#9.o3" to "Labios agrietados",
    "q.m01#9.o4" to "Un esguince de tobillo",
    "q.m01#9.e" to "Las cuatro primeras son lesiones ambientales y comparten un rasgo: son casi totalmente evitables. A diferencia de los aludes, no son difíciles de prever: dependen solo del equipo y de los hábitos, así que verlas en una cordada suele significar que algo falló en la preparación.",

    "q.m01#10.p" to "¿Qué afirmación sobre la composición del aire en altura es correcta?",
    "q.m01#10.o0" to "La proporción de oxígeno baja a medida que se sube",
    "q.m01#10.o1" to "La proporción se mantiene más o menos igual; la presión más baja reduce la presión parcial",
    "q.m01#10.o2" to "La proporción de nitrógeno aumenta con la altitud",
    "q.m01#10.o3" to "El oxígeno es desplazado por otros gases en altura",
    "q.m01#10.e" to "Dentro de la troposfera la mezcla es esencialmente constante (unos 21 % de oxígeno, 78 % de nitrógeno). Lo que varía con la altitud es la presión: cuántas moléculas hay en esa misma bocanada. Con esa distinción clara, muchas preguntas de equipo y de fisiología se vuelven sencillas.",

    "q.m01#11.p" to "¿Por qué los picos de 5.000 m siguen nevados en verano?",
    "q.m01#11.o0" to "Porque los lugares altos están más lejos del sol",
    "q.m01#11.o1" to "Porque el aire de altura es mucho más frío que en las tierras bajas a la misma latitud, así que las precipitaciones caen en forma de nieve",
    "q.m01#11.o2" to "Porque los vientos fuertes en la cumbre impiden que se derrita",
    "q.m01#11.o3" to "Porque la nieve compactada se convierte en hielo y ya nunca funde",
    "q.m01#11.e" to "La regla de 6,5 °C por 1.000 m mantiene las temperaturas de verano a 5.000 m por debajo de cero. También explica por qué la misma montaña es más difícil en una estación que en otra: la límite de las nieves se mueve, y la ruta con ella.",

    "q.m01#12.p" to "De un campo base a 3.000 m a un campamento a 5.000 m, usando el gradiente medio, ¿cuántos grados menos hace aproximadamente?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. La cuenta: 2.000 m de desnivel a 6,5 °C por 1.000 m son 2 × 6,5 = 13 °C. Esa estimación es muy práctica antes de una salida: decide el grosor necesario del aislamiento y del saco de dormir.",

    // ---------- m02 Forma física y nutrición ----------
    "q.m02#0.p" to "¿Qué tipo de forma física importa más para el alpinismo de alta montaña?",
    "q.m02#0.o0" to "La potencia explosiva y los esprints cortos",
    "q.m02#0.o1" to "La resistencia aeróbica sostenida durante horas",
    "q.m02#0.o2" to "La fuerza máxima de agarre",
    "q.m02#0.o3" to "La flexibilidad",
    "q.m02#0.e" to "El alpinismo de alta montaña es un trabajo largo y de baja intensidad: de seis a diez horas al día, nunca empinado pero sin tregua. La hipoxia limita mucho la capacidad anaeróbica, así que lo que te sostiene es una base aeróbica y la capacidad de mantener un ritmo regular.",

    "q.m02#1.p" to "¿Cómo hay que organizar el entrenamiento antes de salir?",
    "q.m02#1.o0" to "Meter un bloque grande la semana anterior",
    "q.m02#1.o1" to "Hacer afinamiento en las dos o tres últimas semanas y salir descansado",
    "q.m02#1.o2" to "Entrenar a intensidad máxima hasta el día anterior",
    "q.m02#1.o3" to "No entrenar nada y confiar en aclimatarse allí",
    "q.m02#1.e" to "Las ganancias del entrenamiento se producen durante la recuperación. Llegar cansado socava a la vez el rendimiento y la aclimatación, y aclimatarse cuesta energía en sí mismo. El afinamiento es lo que convierte el entrenamiento en forma.",

    "q.m02#2.p" to "En altura, ¿en qué debe basarse la alimentación?",
    "q.m02#2.o0" to "En alimentos ricos en grasas",
    "q.m02#2.o1" to "En hidratos de carbono",
    "q.m02#2.o2" to "En alimentos ricos en proteínas",
    "q.m02#2.o3" to "Solo en líquidos",
    "q.m02#2.e" to "Los hidratos de carbono se metabolizan con más eficiencia y consumen menos oxígeno en condiciones de hipoxia, y el cuerpo los prefiere instintivamente allá arriba. Va contra la intuición de que la altura exige grasas muy calóricas: la restricción es la eficiencia en oxígeno.",

    "q.m02#3.p" to "¿Cuál es un indicador práctico de hidratación suficiente?",
    "q.m02#3.o0" to "La sed que sientes",
    "q.m02#3.o1" to "Que la orina siga clara",
    "q.m02#3.o2" to "Beber exactamente 1 litro al día",
    "q.m02#3.o3" to "Los cambios de peso corporal",
    "q.m02#3.e" to "La sed no es fiable en altura: el frío y la hipoxia la embotan. El color y el olor de la orina son un indicador diario más directo: clara significa más o menos suficiente, más oscura y fuerte significa beber más.",

    "q.m02#4.p" to "¿Por qué evitar el alcohol en altura?",
    "q.m02#4.o0" to "Porque hace engordar",
    "q.m02#4.o1" to "Porque deprime el impulso respiratorio y agrava la hipoxia nocturna",
    "q.m02#4.o2" to "Porque acelera el daño de los UV",
    "q.m02#4.o3" to "Porque no hay nevera",
    "q.m02#4.e" to "El alcohol y los sedantes deprimen ambos el centro respiratorio. Las noches en altura ya tienden a la respiración periódica, y añadir depresión respiratoria hace caer la saturación de forma notable: uno de los mecanismos clave por los que el mal de altura empeora de noche.",

    "q.m02#5.p" to "[Elección múltiple] ¿Cuáles son formas correctas de aportar energía en marcha en altura?",
    "q.m02#5.o0" to "Cantidades pequeñas y frecuentes, antes de estar hambriento",
    "q.m02#5.o1" to "Preferir comida fácil de digerir y con contenido moderado de agua",
    "q.m02#5.o2" to "Basarla en hidratos de carbono",
    "q.m02#5.o3" to "Hacer una sola comida grande para reducir el número de tomas",
    "q.m02#5.e" to "Poco y a menudo facilita la digestión y mantiene estable el azúcar en sangre. Una comida grande en hipoxia tiende a provocar hinchazón y náuseas, y como la pérdida de apetito es en sí un síntoma frecuente, forzarse con un comilona sale mal.",

    "q.m02#6.p" to "El apetito baja en altura. ¿Cuál es la respuesta correcta?",
    "q.m02#6.o0" to "Dejar de comer y esperar el hambre",
    "q.m02#6.o1" to "Comer de forma deliberada, eligiendo alimentos ricos en hidratos y fáciles de digerir",
    "q.m02#6.o2" to "Beber mucho café en lugar de comer",
    "q.m02#6.o3" to "Tomar solo electrolitos",
    "q.m02#6.e" to "La pérdida de apetito forma parte del mal de altura, y comer poco debilita la aclimatación: un círculo vicioso. Come de forma deliberada, en pequeñas cantidades y a menudo: no se trata de si tienes hambre, es una medida necesaria.",

    "q.m02#7.p" to "¿Qué afirmación sobre forma física y altura es correcta?",
    "q.m02#7.o0" to "Si estás en forma, no tendrás mal de altura",
    "q.m02#7.o1" to "La forma física mejora el rendimiento pero no sustituye a la aclimatación",
    "q.m02#7.o2" to "La gente poco entrenada no debería ir a la altura",
    "q.m02#7.o3" to "Cuanto más en forma estés, menos aclimatación necesitas",
    "q.m02#7.e" to "Forma física y aclimatación son dos líneas distintas. Una persona entrenada puede estar más cómoda a la misma altitud, pero la fisiología sigue necesitando un tiempo que se cuenta en días: tratar «estoy en forma» como «no me pondré enfermo» es la lógica que hay detrás de muchos accidentes.",

    "q.m02#8.p" to "[Orden] Pon en orden temporal una secuencia sensata de preparación antes de una escalada.",
    "q.m02#8.o0" to "Entrenamiento de base (dos o tres meses antes)",
    "q.m02#8.o1" to "Afinamiento y protección de la recuperación (dos o tres semanas antes)",
    "q.m02#8.o2" to "Revisión de material, itinerario y seguro (una semana antes)",
    "q.m02#8.o3" to "Aclimatación según el programa (durante la salida)",
    "q.m02#8.e" to "El orden es el método: entrenar pronto, dejar espacio para recuperar, preparar al detalle, aclimatarse despacio. Los pasos que más se trastocan son los dos últimos: mucha gente revisa el material a fondo y luego corre detrás del programa en la montaña y recorta la aclimatación.",

    "q.m02#9.p" to "¿Qué problema puede causar beber en exceso (un volumen grande en poco tiempo) en altura?",
    "q.m02#9.o0" to "Ninguno",
    "q.m02#9.o1" to "Diluye los electrolitos de la sangre y en casos graves provoca hiponatremia",
    "q.m02#9.o2" to "Previene eficazmente el edema pulmonar",
    "q.m02#9.o3" to "Puede sustituir al hecho de comer",
    "q.m02#9.e" to "«Beber suficiente» no es «beber a la desesperada». Un volumen grande en poco tiempo sin electrolitos puede diluir el sodio sanguíneo y causar cefalea, náuseas y alteración de la consciencia: síntomas que imitan de cerca el mal de altura y se leen mal con facilidad. La respuesta es una ingesta regular y suficiente.",
    // ---------- m03 Principio de mínimo impacto ----------
    "q.m03#0.p" to "¿Cuál es el significado central del principio de mínimo impacto?",
    "q.m03#0.o0" to "Llevar material más ligero para castigar menos el cuerpo",
    "q.m03#0.o1" to "Reducir al mínimo el impacto de la actividad humana en el medio montañoso",
    "q.m03#0.o2" to "Bajar la dificultad de la escalada para ir más seguro",
    "q.m03#0.o3" to "Reducir el número de personas de la cordada",
    "q.m03#0.e" to "El principio de mínimo impacto es la ética ambiental que promueve el alpinismo. No va de viajar ligero, sino de cuánto cambia la montaña por tu presencia: basura, pisoteo, fuego y molestias a la fauna cuentan todos.",

    "q.m03#1.p" to "Al salir del campamento, ¿cuál es el enfoque correcto con la basura?",
    "q.m03#1.o0" to "Los restos de comida se pueden enterrar allí mismo",
    "q.m03#1.o1" to "Bajarlo todo, incluido el papel higiénico y los artículos de higiene",
    "q.m03#1.o2" to "Llevarse solo el plástico",
    "q.m03#1.o3" to "Quemarla en un hoyo",
    "q.m03#1.e" to "El manual es explícito: embolsar todo lo que generes y bajarlo, revisar el campamento y la zona de actividad, y bajar los artículos de higiene como el papel. Enterrar y quemar dejan rastro, y con el frío de la altura los residuos se descomponen muy despacio.",

    "q.m03#2.p" to "¿Qué principio guía la ubicación de un baño en plena naturaleza?",
    "q.m03#2.o0" to "Cuanto más escondido, mejor: la intimidad primero",
    "q.m03#2.o1" to "Lejos de fuentes de agua, campamentos y senderos",
    "q.m03#2.o2" to "Donde la nieve sea más plana",
    "q.m03#2.o3" to "Cerca de un arroyo para que se lo lleve",
    "q.m03#2.e" to "El objetivo es no contaminar el agua y no hacer que el siguiente grupo se lo encuentre. En la práctica: una distancia definida respecto al agua y a los senderos, un hoyo poco profundo y bajar el papel usado; y por encima de la límite de las nieves, bajarlo todo, porque apenas se descompone.",

    "q.m03#3.p" to "¿Por qué cerrar bien la comida y la basura?",
    "q.m03#3.o0" to "Para que no se humedezca",
    "q.m03#3.o1" to "Para evitar que los animales la saqueen y se acostumbren",
    "q.m03#3.o2" to "Para ahorrar espacio en la mochila",
    "q.m03#3.o3" to "Para que sea más fácil pesarla",
    "q.m03#3.e" to "Los animales que saquean comida suelen haber sido enseñados por las cordadas: una vez que asocian campamento con comida, el riesgo en esa ruta sube para siempre. Cerrarla bien protege tu comida, a los animales y a todos los que vengan detrás.",

    "q.m03#4.p" to "¿A qué se refiere sobre todo la época sensible para la fauna?",
    "q.m03#4.o0" to "Las horas de alimentación diurnas",
    "q.m03#4.o1" to "Las épocas de celo y de lactancia",
    "q.m03#4.o2" to "La época de migración",
    "q.m03#4.o3" to "La dormancia invernal",
    "q.m03#4.e" to "Los animales son especialmente sensibles a las molestias durante el celo y la cría, y una madre que defiende a sus pequeños puede ser agresiva. Así que además de evitar su área de distribución, evita horarios y lugares fijos de abrevadero: los protege y te protege.",

    "q.m03#5.p" to "¿Por qué mantenerse en los senderos establecidos?",
    "q.m03#5.o0" to "Porque la normativa lo exige",
    "q.m03#5.o1" to "Porque el pisoteo crea nuevos caminos duraderos y desencadena erosión",
    "q.m03#5.o2" to "Porque los senderos son más fáciles de seguir",
    "q.m03#5.o3" to "Porque los guías los balizan",
    "q.m03#5.e" to "La vegetación de altura crece extremadamente despacio; una sola huella puede durar años. Los «atajos» paralelos cortan la vegetación y concentran el flujo de agua, y acaban excavando regueros: así empieza a degradarse una ruta.",

    "q.m03#6.p" to "[Elección múltiple] ¿Cuáles de estos residuos hay que bajar de la montaña?",
    "q.m03#6.o0" to "Envases de comida",
    "q.m03#6.o1" to "Cáscaras de fruta y restos de comida",
    "q.m03#6.o2" to "Papel higiénico usado",
    "q.m03#6.o3" to "Colillas",
    "q.m03#6.o4" to "La cinta y la cordeleta se pueden quemar allí mismo",
    "q.m03#6.e" to "Los cuatro primeros bajan contigo. El malentendido más habitual son las cáscaras y los restos: parecen biodegradables, pero en las condiciones frías y secas de la altura se descomponen muy despacio, atraen a los animales y cambian su comportamiento.",

    "q.m03#7.p" to "¿Cuál es la actitud correcta ante recoger objetos naturales (piedras, plantas, fósiles) como recuerdo?",
    "q.m03#7.o0" to "Los objetos pequeños se pueden coger",
    "q.m03#7.o1" to "No coger nada natural: hacer fotografías en su lugar",
    "q.m03#7.o2" to "Está bien siempre que no dañes el entorno",
    "q.m03#7.o3" to "Recoger muestras ayuda a la ciencia",
    "q.m03#7.e" to "«No coger más que fotografías, no dejar más que huellas» es la formulación clásica. Los objetos naturales forman parte de la ecología y del paisaje local, y en cuanto cada cordada se lleva un poco, el efecto acumulado es considerable.",

    "q.m03#8.p" to "¿Cómo afecta principalmente el alpinismo al medio montañoso?",
    "q.m03#8.o0" to "Solo mediante la basura",
    "q.m03#8.o1" to "Daño a la vegetación, reducción del área de la fauna, basura e impacto cultural de los visitantes externos en las comunidades locales",
    "q.m03#8.o2" to "Sobre todo por el ruido",
    "q.m03#8.o3" to "El impacto es despreciable",
    "q.m03#8.e" to "El manual divide el impacto en ecológico y social: daño a la vegetación, desplazamiento de fauna y basura por un lado, presión cultural sobre modos de vida locales por otro. Entenderlo explica por qué la etiqueta forma parte de la formación de alpinismo.",

    "q.m03#9.p" to "[Orden] Pon en el orden correcto la rutina de mínimo impacto al abandonar el campamento.",
    "q.m03#9.o0" to "Recoger el material personal y el de grupo",
    "q.m03#9.o1" to "Separar y embolsar toda la basura",
    "q.m03#9.o2" to "Gestionar los residuos humanos (enterrar o bajar)",
    "q.m03#9.o3" to "Recorrer el campamento y la zona de actividad y confirmar que no queda nada",
    "q.m03#9.e" to "El último paso —la vuelta de inspección— es el que más se salta y el más importante: la gente coge instintivamente «sus cosas», y así es exactamente como se quedan piquetas de tienda, cabos de cuerda y envoltorios caídos. Mirar atrás no cuesta casi nada.",

    // ---------- m04 Meteorología y mapas ----------
    "q.m04#0.p" to "¿Cuál es la señal más fiable de que el tiempo está cambiando?",
    "q.m04#0.o0" to "Si hace sol en este momento",
    "q.m04#0.o1" to "La tendencia de la presión, las nubes y el viento",
    "q.m04#0.o2" to "El pronóstico de antes de salir",
    "q.m04#0.o3" to "Cómo se sienten tus compañeros",
    "q.m04#0.e" to "El presente es una foto; la tendencia es la dirección. Presión que baja de forma sostenida, nubes que se espesan y bajan, viento que arrecia: cuando aparecen las tres juntas, el tiempo está cambiando. Ese es el valor práctico de llevar un barómetro, en el reloj o aparte.",

    "q.m04#1.p" to "¿Qué caracteriza al cumulonimbus y qué significa?",
    "q.m04#1.o0" to "Fino y uniforme: tiempo estable",
    "q.m04#1.o1" to "Desarrollo vertical con yunque: tormentas y precipitaciones fuertes",
    "q.m04#1.o2" to "Extendido en capas: solo llovizna",
    "q.m04#1.o3" to "Filamentos tenues: buen tiempo",
    "q.m04#1.e" to "El crecimiento vertical muestra una convección fuerte, y el yunque indica que ha alcanzado la madurez. Encontrarse uno en altura significa que rayos, granizo y precipitaciones fuertes son posibles: abandona de inmediato las crestas y el terreno alto expuesto.",

    "q.m04#2.p" to "¿Qué escalas de mapa se usan habitualmente en alpinismo?",
    "q.m04#2.o0" to "1:1.000 y 1:5.000",
    "q.m04#2.o1" to "1:50.000 y 1:10.000",
    "q.m04#2.o2" to "1:250.000 y 1:500.000",
    "q.m04#2.o3" to "Cualquier escala sirve",
    "q.m04#2.e" to "1:50.000 y 1:10.000 son la pareja habitual: la primera cubre mucha superficie y sirve para planificar el itinerario, la segunda lleva el detalle y sirve para terreno técnico. 1:200.000 se usa de vez en cuando, y 1:10.000 menos, porque la hoja cubre tan poco que sales de ella enseguida.",

    "q.m04#3.p" to "¿Qué significan curvas de nivel muy juntas en un mapa topográfico?",
    "q.m04#3.o0" to "Una pendiente suave",
    "q.m04#3.o1" to "Una pendiente pronunciada",
    "q.m04#3.o2" to "Un valle",
    "q.m04#3.o3" to "Un glaciar",
    "q.m04#3.e" to "Cuanto más juntas están las curvas, más desnivel se gana en la misma distancia horizontal: es decir, más empinado es. Es una habilidad de lectura útil al planificar: puedes marcar los tramos empinados, los rellanos y los posibles emplazamientos de tienda antes de salir.",

    "q.m04#4.p" to "¿Qué indica una curva de nivel cerrada en un mapa topográfico?",
    "q.m04#4.o0" to "Un lago",
    "q.m04#4.o1" to "Un pico independiente",
    "q.m04#4.o2" to "Un glaciar",
    "q.m04#4.o3" to "Un acantilado",
    "q.m04#4.e" to "Una curva cerrada significa que el macizo cae por todos sus lados: la definición misma de pico independiente. Varias curvas cerradas concéntricas indican que la montaña sube por escalones, y la más interna marca la zona de cumbre.",

    "q.m04#5.p" to "[Elección múltiple] ¿A qué hay que prestar atención al usar una brújula?",
    "q.m04#5.o0" to "Mantenerla lo más horizontal posible",
    "q.m04#5.o1" to "Mantenerse lejos de objetos magnéticos",
    "q.m04#5.o2" to "No confundir el sur de la aguja con el norte",
    "q.m04#5.o3" to "Corregir la declinación magnética local",
    "q.m04#5.o4" to "Sujetarla cerca de las hebillas metálicas de la mochila para que no se mueva",
    "q.m04#5.e" to "Los cuatro primeros aparecen explícitamente en el manual. Solo el error del sur produce un desvío de 180°: en terreno complejo eso puede mandarte justo en la dirección contraria sin que te des cuenta.",

    "q.m04#6.p" to "¿Qué es la declinación magnética?",
    "q.m04#6.o0" to "Un defecto de fabricación de la brújula",
    "q.m04#6.o1" to "La diferencia entre el norte magnético y el norte geográfico, que hay que corregir",
    "q.m04#6.o2" to "Un cambio de ángulo causado por la altitud",
    "q.m04#6.o3" to "Una distorsión provocada por la proyección del mapa",
    "q.m04#6.e" to "La aguja apunta al norte magnético mientras los mapas se refieren al norte geográfico, y los dos no coinciden. La declinación varía según la región, así que hay que corregirla al trabajar mapa y brújula juntos: si no, toda la ruta se desplaza.",

    "q.m04#7.p" to "¿Qué representan las líneas de cuadrícula regular de un mapa topográfico?",
    "q.m04#7.o0" to "Las líneas de latitud y longitud",
    "q.m04#7.o1" to "Una cuadrícula UTM (Universal Transverse Mercator)",
    "q.m04#7.o2" to "Las curvas de nivel",
    "q.m04#7.o3" to "Los límites administrativos",
    "q.m04#7.e" to "La cuadrícula no es latitud y longitud sino UTM. Eso importa porque la Tierra es un elipsoide: las celdas de lat/long no son iguales en tamaño a distintas latitudes, mientras que los cuadrados UTM sí, lo que hace sencillo medir distancias y coordenadas.",

    "q.m04#8.p" to "¿Por qué no fiarse solo del GPS?",
    "q.m04#8.o0" to "Porque el GPS no es suficientemente preciso",
    "q.m04#8.o1" to "Porque el aparato puede quedarse sin batería, mojarse, romperse o perder señal",
    "q.m04#8.o2" to "Porque el GPS solo funciona en ciudades",
    "q.m04#8.o3" to "Porque el GPS exige una suscripción",
    "q.m04#8.e" to "El GPS es una ayuda excelente, pero presupone un aparato que funcione. Las baterías se agotan rápido con el frío de altura, y el agua y las caídas son habituales. Mapa y brújula no necesitan energía: por eso siguen siendo obligatorios en la formación de alpinismo.",

    "q.m04#9.p" to "Cuando la visibilidad se derrumba (niebla, pérdida de contraste), ¿qué hay que hacer primero?",
    "q.m04#9.o0" to "Acelerar y salir de ahí",
    "q.m04#9.o1" to "Confirmar de inmediato la posición y el rumbo, y esperar en el sitio si hace falta",
    "q.m04#9.o2" to "Seguir recto según el plan original",
    "q.m04#9.o3" to "Separarse para buscar la ruta",
    "q.m04#9.e" to "El peligro de una pérdida de contraste es perder toda referencia visual, y la gente camina instintivamente en la dirección equivocada. Fija la posición, anota el rumbo y espera si hace falta: mucho más seguro que forzar, y separarse es la peor opción de todas.",
    // ---------- m05 Picos de iniciación ----------
    "q.m05#0.p" to "¿Cuál es la diferencia esencial entre un pico de trekking y un pico técnico?",
    "q.m05#0.o0" to "La altitud",
    "q.m05#0.o1" to "Si hacen falta material y gesto técnico",
    "q.m05#0.o2" to "El país en el que está",
    "q.m05#0.o3" to "Si hace falta permiso",
    "q.m05#0.e" to "La línea divisoria es la exigencia técnica, no la altura. El Kilimanjaro, con 5.895 m, no necesita material técnico, mientras que el Haba Xue Shan, con 5.396 m, exige crampones y piolet por encima de la límite de las nieves. La altitud es solo una dimensión de la dificultad.",

    "q.m05#1.p" to "¿Cómo se llama el punto más alto del Kilimanjaro?",
    "q.m05#1.o0" to "Uhuru Peak",
    "q.m05#1.o1" to "Kibo",
    "q.m05#1.o2" to "Mawenzi",
    "q.m05#1.o3" to "Shira",
    "q.m05#1.e" to "La cumbre es Uhuru Peak, a 5.895 m. El Kilimanjaro es un volcán dormido formado por tres conos —Kibo, Mawenzi y Shira— y Uhuru es el punto más alto del Kibo.",

    "q.m05#2.p" to "¿Qué hace único al Kilimanjaro?",
    "q.m05#2.o0" to "Es el pico de 5.000 m menos ascendido del mundo",
    "q.m05#2.o1" to "Está cerca del ecuador y sin embargo tiene glaciares, atravesando zonas climáticas desde la selva hasta el desierto alpino",
    "q.m05#2.o2" to "Exige material muy técnico",
    "q.m05#2.o3" to "Solo se puede subir un mes al año",
    "q.m05#2.e" to "Ecuador más glaciares convierten el Kilimanjaro en un corredor climático vertical: de la selva al hielo en una sola salida. Eso crea también un problema práctico: un gran desnivel con una subida rápida de altitud, así que la aclimatación se vuelve el desafío principal.",

    "q.m05#3.p" to "¿A qué grupo de picos pertenece el Aotaina?",
    "q.m05#3.o0" to "Siguniang",
    "q.m05#3.o1" to "Los montes San'ao",
    "q.m05#3.o2" to "Gongga",
    "q.m05#3.o3" to "Meili Xue Shan",
    "q.m05#3.e" to "El grupo San'ao, en Heishui (Sichuan), lo forman el Aotaiji (padre de las montañas), el Aotaimei (madre) y el Aotaina (hijo). El Aotaina es el más fácil de los tres y se elige a menudo como primer pico nevado.",

    "q.m05#4.p" to "¿Qué descripción de la altitud del Aotaina es exacta?",
    "q.m05#4.o0" to "Todas las fuentes coinciden en 4.800 m",
    "q.m05#4.o1" to "Altitud oficial 5.211 m, pero medida alrededor de 4.800 m: las fuentes discrepan",
    "q.m05#4.o2" to "Oficial 4.800 m, medida 5.211 m",
    "q.m05#4.o3" to "La altitud nunca se ha discutido",
    "q.m05#4.e" to "Esas discrepancias son habituales en datos de picos: cifras oficiales, valores medidos y distintos criterios de medición varían. La lección práctica es citar la fuente siempre que des una altitud, en lugar de tratar un número como verdad absoluta.",

    "q.m05#5.p" to "¿Cuáles son las altitudes del Da Feng y el Er Feng del Siguniang?",
    "q.m05#5.o0" to "5.025 m y 5.276 m",
    "q.m05#5.o1" to "5.276 m y 5.025 m",
    "q.m05#5.o2" to "5.025 m y 5.355 m",
    "q.m05#5.o3" to "4.850 m y 5.276 m",
    "q.m05#5.e" to "El Da Feng tiene 5.025 m y el Er Feng 5.276 m. Se combinan a menudo como progresión de entrada: primero el Da Feng para coger experiencia de altura, luego el Er Feng, cuyo tramo final necesita una ayuda técnica sencilla: un paso natural hacia la escalada técnica.",

    "q.m05#6.p" to "[Elección múltiple] Al elegir un primer pico nevado, ¿qué factores merece más la pena comparar?",
    "q.m05#6.o0" to "Lo consolidada que esté la ruta y su porcentaje de cumbres",
    "q.m05#6.o1" to "Si el guiado y el apoyo de rescate son fiables",
    "q.m05#6.o2" to "Si la ganancia de altitud está bien pautada",
    "q.m05#6.o3" to "Tu forma física actual y el tiempo del que dispones",
    "q.m05#6.o4" to "Lo popular que sea el pico en redes sociales",
    "q.m05#6.e" to "Los cuatro primeros juntos responden a «¿esta montaña me encaja ahora?». Mirar solo el número de altitud engaña: un pico de 5.000 m con un ritmo sensato y buen apoyo puede ser más seguro que uno de 5.500 m que obliga a tres días precipitados.",

    "q.m05#7.p" to "¿Qué provoca más a menudo el fracaso en un pico de iniciación?",
    "q.m05#7.o0" to "La dificultad técnica",
    "q.m05#7.o1" to "El mal de altura y el tiempo, no la dificultad técnica",
    "q.m05#7.o2" to "Material insuficiente",
    "q.m05#7.o3" to "Una cordada demasiado pequeña",
    "q.m05#7.e" to "Es el punto más subestimado: en picos de iniciación el fracaso casi siempre es «nos quedamos sin piernas» o «el tiempo no esperó», nunca «no pasamos el paso clave». Así que el trabajo real a este nivel es aclimatación, ritmo y forma física, no gestos técnicos.",

    "q.m05#8.p" to "¿Por qué el porcentaje de cumbres es un dato útil al elegir un pico?",
    "q.m05#8.o0" to "Porque refleja lo bonito que es el pico",
    "q.m05#8.o1" to "Porque integra la dificultad de la ruta, el ritmo y el nivel real de apoyo",
    "q.m05#8.o2" to "Porque determina el coste",
    "q.m05#8.o3" to "Porque no tiene nada que ver con la seguridad",
    "q.m05#8.e" to "El porcentaje de cumbres es el producto de muchas cosas: lo dura que es la ruta, si la ganancia de altitud es sensata, lo amplias que son las ventanas meteorológicas, lo fiable que es la logística. Te dice más sobre lo que realmente vas a encontrar que la altitud sola.",

    "q.m05#9.p" to "¿Cuál es la actitud correcta ante un primer pico nevado?",
    "q.m05#9.o0" to "Iniciación significa que no hay riesgo",
    "q.m05#9.o1" to "Iniciación solo significa menor exigencia técnica; los riesgos de altura y de tiempo siguen siendo reales",
    "q.m05#9.o2" to "Los picos de iniciación no necesitan guía",
    "q.m05#9.o3" to "Los picos de iniciación no necesitan preparación física",
    "q.m05#9.e" to "«Iniciación» describe el umbral técnico, no el riesgo total. La altitud misma, un cambio brusco del tiempo y el agotamiento pueden matar a cualquier altura. Tratar la iniciación como «fácil» es justo donde empieza una mala preparación.",

    // ---------- m06 Iniciación técnica ----------
    "q.m06#0.p" to "¿Cuáles son los tres sistemas básicos de la escalada técnica?",
    "q.m06#0.o0" to "Material, forma física, tiempo",
    "q.m06#0.o1" to "Detención, protección, progresión",
    "q.m06#0.o2" to "Ascenso, descenso, descanso",
    "q.m06#0.o3" to "Crampones, piolet, cuerda",
    "q.m06#0.e" to "La detención responde a «qué hago tras perder el pie», la protección a «quién me sujeta si caigo» y la progresión a «cómo avanzo por terreno peligroso». Juntos cierran el circuito: quita uno y la escalada técnica no funciona.",

    "q.m06#1.p" to "¿Cuál es el propósito fundamental de aprender escalada técnica?",
    "q.m06#1.o0" to "Escalar rutas más duras",
    "q.m06#1.o1" to "Convertir un deslizamiento incontrolado en riesgo gestionado",
    "q.m06#1.o2" to "Obtener un certificado",
    "q.m06#1.o3" to "Moverse más rápido",
    "q.m06#1.e" to "La técnica no baja la montaña: cambia lo que ocurre después de un error. Con la detención, un resbalón deja de ser un desastre irreversible; con la protección, un error ya no significa automáticamente una caída. Ese es su valor real.",

    "q.m06#2.p" to "¿Cuál es la forma más eficaz de dominar un gesto técnico?",
    "q.m06#2.o0" to "Ver vídeos didácticos repetidamente",
    "q.m06#2.o1" to "Practicarlo una y otra vez en terreno protegido hasta que sea un reflejo",
    "q.m06#2.o2" to "Leer el manual y memorizar los puntos clave",
    "q.m06#2.o3" to "Aprenderlo de golpe en una pendiente inclinada real",
    "q.m06#2.e" to "Los gestos técnicos hay que ejecutarlos bajo presión, y la presión te devuelve al nivel en el que realmente te entrenaste. Pendiente suave, nieve blanda, salida limpia y un instructor asegurando: cuando están las cuatro cosas, es donde de verdad se aprende una habilidad.",

    "q.m06#3.p" to "¿Por qué no se puede aprender la autodetención con un vídeo?",
    "q.m06#3.o0" to "Porque la calidad del vídeo es mala",
    "q.m06#3.o1" to "Porque es un reflejo que hay que construir con práctica repetida en el terreno",
    "q.m06#3.o2" to "Porque la técnica que se muestra es incorrecta",
    "q.m06#3.o3" to "Porque la autodetención es en realidad sencilla",
    "q.m06#3.e" to "Tras un resbalón tienes uno o dos segundos, sin espacio para pensar. La memoria muscular se compra con repeticiones: por eso todo curso serio insiste en repetirlo hasta poder hacerlo sin pensar.",

    "q.m06#4.p" to "¿Cuáles son los tres elementos de partida del material técnico?",
    "q.m06#4.o0" to "Casco, guantes, gafas",
    "q.m06#4.o1" to "Crampones ajustados a tus botas, un piolet y un arnés",
    "q.m06#4.o2" to "Tienda, saco de dormir, esterilla",
    "q.m06#4.o3" to "GPS, emisora, frontal",
    "q.m06#4.e" to "Los crampones dan agarre, el piolet da detención y apoyo, el arnés te une al sistema de protección. Su punto común: solo crean seguridad cuando están ajustados y se usan como sistema con un compañero; ningún elemento protege por sí solo.",

    "q.m06#5.p" to "Una vez tienes las habilidades técnicas, ¿cuál pasa a ser la capacidad más importante?",
    "q.m06#5.o0" to "La velocidad de escalada",
    "q.m06#5.o1" to "Juzgar cuándo no necesitas en absoluto el material técnico",
    "q.m06#5.o2" to "El mantenimiento del material",
    "q.m06#5.o3" to "Más ganancias de forma física",
    "q.m06#5.e" to "Es el punto más contraintuitivo de la escalada técnica: la habilidad te permite entrar en terreno más duro, mientras que los verdaderos expertos la usan para comprarse la opción de no ir allí. El juicio siempre está por encima de la ejecución.",

    "q.m06#6.p" to "[Elección múltiple] ¿Cuáles de estos casos cuentan como escalada técnica?",
    "q.m06#6.o0" to "Progresar por una pendiente de hielo y detenerse",
    "q.m06#6.o1" to "Cruzar un glaciar encordados",
    "q.m06#6.o2" to "Montar un anclaje de aseguramiento",
    "q.m06#6.o3" to "Rapelar",
    "q.m06#6.o4" to "Caminar por un sendero bien establecido",
    "q.m06#6.e" to "Los cuatro primeros son técnicos: cada uno necesita material, sistemas y formación específica. Caminar simplemente sobre nieve o seguir un sendero establecido no lo es: la distinción es si hacen falta esos sistemas.",

    "q.m06#7.p" to "¿Por qué la capacidad técnica no puede sustituir nunca al juicio?",
    "q.m06#7.o0" to "Porque la capacidad técnica no se puede entrenar",
    "q.m06#7.o1" to "Porque un mal juicio te mete en terreno al que nunca deberías haber entrado, donde la técnica no puede salvarte",
    "q.m06#7.o2" to "Porque el juicio es más fácil de aprender",
    "q.m06#7.o3" to "Porque la técnica solo se aplica a la roca",
    "q.m06#7.e" to "La técnica es lo que usas cuando ya estás en peligro; el juicio decide si entras en el peligro. Los análisis de accidentes rara vez concluyen «el gesto estaba mal»: mucho más a menudo concluyen «no deberían haber estado allí».",

    "q.m06#8.p" to "[Orden] Pon en un orden sensato la secuencia de aprendizaje de la escalada técnica.",
    "q.m06#8.o0" to "Entender el material: cómo funcionan crampones, piolet y arnés",
    "q.m06#8.o1" to "Repetir los gestos básicos en terreno seguro (la autodetención, por ejemplo)",
    "q.m06#8.o2" to "Aprender los sistemas de cuerda: nudos, encordamiento, anclajes",
    "q.m06#8.o3" to "Aplicarlo todo en rutas reales pero controladas",
    "q.m06#8.e" to "La lógica es: protégete primero, luego únete a los demás, luego entra en terreno real. Saltarse un paso deja un hueco en la capacidad: encordarse en un glaciar con la autodetención sin pulir, por ejemplo, multiplica el riesgo para toda la cordada.",

    "q.m06#9.p" to "¿Qué ha conseguido esta unidad?",
    "q.m06#9.o0" to "Completar toda la formación de alta montaña",
    "q.m06#9.o1" to "Sentar la base en entorno, ciencia y material, listo para empezar el gesto técnico",
    "q.m06#9.o2" to "Completar la preparación para 8.000 m",
    "q.m06#9.o3" to "Obtener una certificación de rescate",
    "q.m06#9.e" to "La unidad de iniciación a 5.000 m sirve para poner la base: ciencia del entorno, material, ropa, forma física, práctica de mínimo impacto, meteorología y orientación, y por último escalada técnica. La siguiente unidad empieza de verdad con crampones, piolet, detención y trabajo con cuerda.",
    // ---------- m07 Principios del anclaje ----------
    "q.m07#0.p" to "¿Cuál es la idea central del diseño de un anclaje?",
    "q.m07#0.o0" to "Usar el menor material posible",
    "q.m07#0.o1" to "Que el fallo de un punto de protección no hunda el sistema",
    "q.m07#0.o2" to "Montarlo lo más alto posible",
    "q.m07#0.o3" to "Usar solo protecciones naturales",
    "q.m07#0.e" to "Un anclaje en roca o en nieve nunca es absolutamente seguro, así que el sistema se diseña para tolerar el error en lugar de para ser absolutamente fuerte. Todo lo demás —redundancia, ecualización, ausencia de extensión— no es más que esa idea puesta por escrito.",

    "q.m07#1.p" to "Con dos puntos de protección a 90° entre sí, ¿qué parte de la carga lleva cada uno aproximadamente?",
    "q.m07#1.o0" to "Alrededor del 50 %",
    "q.m07#1.o1" to "Alrededor del 58 %",
    "q.m07#1.o2" to "Alrededor del 71 %",
    "q.m07#1.o3" to "Alrededor del 100 %",
    "q.m07#1.e" to "Son las cifras clave de la tabla del manual: a 0° cada punto lleva un 50 % aproximadamente, a 60° cerca del 58 %, a 90° en torno al 71 %. Cuanto más abierto el ángulo, más fuerza siente cada punto de la misma persona, lo que determina directamente cómo eliges y colocas los puntos.",

    "q.m07#2.p" to "Desde el punto de vista de la carga, ¿cómo debe manejarse el ángulo entre puntos de protección?",
    "q.m07#2.o0" to "Lo más pequeño posible, para que las direcciones de carga sean casi paralelas",
    "q.m07#2.o1" to "Lo más grande posible, para repartir la carga en direcciones distintas",
    "q.m07#2.o2" to "Debe ser de 90°",
    "q.m07#2.o3" to "El ángulo no afecta a la carga",
    "q.m07#2.e" to "Cuanto menor el ángulo, más se acerca el reparto al 50/50; al abrirlo, la carga sobre cada punto sube. La regla habitual «mantener el ángulo de las cintas por debajo de 60°» sale directamente de esas cifras.",

    "q.m07#3.p" to "[Elección múltiple] ¿Qué dimensiones hay que considerar al evaluar un anclaje?",
    "q.m07#3.o0" to "Sólido: cada punto es suficientemente fuerte",
    "q.m07#3.o1" to "Redundante: varios puntos independientes",
    "q.m07#3.o2" to "Ecualizado: la carga se reparte de forma sensata",
    "q.m07#3.o3" to "Sin extensión: un fallo no crea un alargamiento que choque al sistema",
    "q.m07#3.o4" to "Simétrico: una disposición ordenada y visualmente equilibrada",
    "q.m07#3.e" to "Estos cuatro forman el marco básico. El que más se olvida es la ausencia de extensión: deja holgura entre los puntos y un fallo chocha a los restantes. Las cargas de choque son mucho mayores que las estáticas, algo que mucha gente no sabe.",

    "q.m07#4.p" to "[Asociación] Asocia cada tipo de protección a su medio y su método.",
    "q.m07#4.l0" to "Protección natural",
    "q.m07#4.r0" to "Pilares de roca, árboles grandes, bloques: comprobar que están intactos y estables",
    "q.m07#4.l1" to "Protección en nieve",
    "q.m07#4.r1" to "Piquetas, anclajes enterrados, ranuras en T: la fiabilidad depende mucho de la calidad de la nieve y del enterramiento",
    "q.m07#4.l2" to "Protección en hielo",
    "q.m07#4.r2" to "Tornillos de hielo: comprobar que el hielo es compacto, sin huecos ni alveolos",
    "q.m07#4.e" to "Tres medios, tres conjuntos de criterios completamente distintos. Una de las causas de accidente más habituales es juzgar nieve o hielo con reflejos de roca: «parece sólido» no significa casi nada en un manto.",

    "q.m07#5.p" to "¿Cuál de estos casos es redundancia falsa?",
    "q.m07#5.o0" to "Usar dos piezas de distinta resistencia",
    "q.m07#5.o1" to "Dos puntos de protección que en realidad dependen de la misma fisura o del mismo bloque",
    "q.m07#5.o2" to "Unir los puntos con cintas",
    "q.m07#5.o3" to "Colocar tres puntos de protección",
    "q.m07#5.e" to "La redundancia exige fallo independiente. Si dos puntos comparten una fisura, la apertura se los lleva a los dos a la vez: parece que hay dos puntos pero funciona como uno. La redundancia falsa es habitual y letal.",

    "q.m07#6.p" to "¿Por qué pretensar el sistema para conseguir la ausencia de extensión?",
    "q.m07#6.o0" to "Por estética",
    "q.m07#6.o1" to "Para impedir que un fallo choque a los puntos restantes",
    "q.m07#6.o2" to "Para ahorrar cinta",
    "q.m07#6.o3" to "Para desmontarlo más rápido",
    "q.m07#6.e" to "Una carga de choque es mucho mayor que una estática: la misma persona cargando de golpe un punto genera mucha más fuerza que colgada quieta. Un anclaje con holgura parece «más flexible» pero en realidad amplifica un fallo en un choque sobre todo el sistema.",

    "q.m07#7.p" to "[Orden] Pon en un orden sensato los pasos de construcción de un anclaje.",
    "q.m07#7.o0" to "Mirar alrededor y elegir emplazamientos utilizables y mutuamente independientes",
    "q.m07#7.o1" to "Colocar cada punto y comprobar que es fuerte por sí solo",
    "q.m07#7.o2" to "Unir los puntos con cinta o cuerda, controlar el ángulo y pretensar",
    "q.m07#7.o3" to "Revisar todo el sistema: redundancia falsa y extensión",
    "q.m07#7.e" to "El orden es: elegir emplazamientos, construir los puntos, unir el sistema y revisarlo. La revisión no es un trámite: mientras construyes te concentras en cada colocación y es fácil perder de vista la relación de conjunto, por ejemplo dos puntos que comparten un mismo elemento.",

    "q.m07#8.p" to "Al usar protección natural, ¿qué hay que comprobar sobre todo?",
    "q.m07#8.o0" to "Si es suficientemente grande",
    "q.m07#8.o1" to "Si está intacta: ni suelta, ni meteorizada, ni separada de la masa principal",
    "q.m07#8.o2" to "Si queda bien",
    "q.m07#8.o3" to "Si es fácil de cintar",
    "q.m07#8.e" to "El peligro de la protección natural suele ser que parece grande pero ya está suelta. Lo que importa es si forma realmente parte de la masa principal y si hay fisuras o signos de meteorización. Grande, grueso y evidente no significan sólido.",

    "q.m07#9.p" to "¿Por qué construir el anclaje tan rápido como sea razonable?",
    "q.m07#9.o0" to "Para ahorrar energía",
    "q.m07#9.o1" to "Porque el tiempo que se tarda en montarlo es tiempo de exposición al riesgo",
    "q.m07#9.o2" to "Porque los compañeros te meterán prisa",
    "q.m07#9.o3" to "Porque se pierde material",
    "q.m07#9.e" to "Mientras montas un anclaje sueles estar sin protección o mal protegido, así que esa exposición debe ser corta. Por eso la evaluación no mira solo sólido, redundante y ecualizado, sino también eficiencia y oportunidad.",

    "q.m07#10.p" to "¿De qué depende principalmente la fiabilidad de un anclaje en nieve?",
    "q.m07#10.o0" to "De la marca del material",
    "q.m07#10.o1" to "De la calidad de la nieve y de lo bien enterrado que esté",
    "q.m07#10.o2" to "De la altitud",
    "q.m07#10.o3" to "Del color de la cuerda",
    "q.m07#10.e" to "La misma piqueta o el mismo anclaje enterrado aguanta cargas muy distintas en nieve profunda, en nieve húmeda o al borde de un puente de nieve. Los anclajes en nieve exigen leer el manto sobre el terreno, y eso hace también de la protección en nieve una de las habilidades más exigentes.",

    "q.m07#11.p" to "Si un anclaje tiene un solo punto de protección, ¿cuál es el mayor problema?",
    "q.m07#11.o0" to "La carga es demasiado alta",
    "q.m07#11.o1" to "No hay margen alguno: si ese punto falla, el sistema falla",
    "q.m07#11.o2" to "Es incómodo de manejar",
    "q.m07#11.o3" to "Queda feo",
    "q.m07#11.e" to "Un anclaje de punto único entrega tu vida a un factor incierto. A veces es de verdad la única opción —un buen tornillo de hielo, por ejemplo— y entonces el enfoque es hacer ese punto lo mejor posible y reducir al mínimo el tiempo que el sistema depende de él.",

    // ---------- m08 Picos de 5.000 m ----------
    "q.m08#0.p" to "¿Cuál es la altitud de la cumbre principal del Gangshika?",
    "q.m08#0.o0" to "5.005 m",
    "q.m08#0.o1" to "5.150 m",
    "q.m08#0.o2" to "5.254,5 m",
    "q.m08#0.o3" to "5.396 m",
    "q.m08#0.e" to "La cumbre principal está a 5.254,5 m. Fíjate en la jerarquía: tercer pico 5.005 m < pico secundario 5.150 m < cumbre principal 5.254,5 m — tres alturas, tres niveles de dificultad, y por eso el Gangshika se usa a menudo como objetivo escalonado.",

    "q.m08#1.p" to "¿Cuáles son la altitud y el carácter del tercer pico del Gangshika?",
    "q.m08#1.o0" to "5.005 m, técnica de nivel iniciación, en torno al 95 % de cumbres para principiantes",
    "q.m08#1.o1" to "5.254 m, muy técnico",
    "q.m08#1.o2" to "5.150 m, trekking puro",
    "q.m08#1.o3" to "5.396 m, ruta de glaciar",
    "q.m08#1.e" to "El tercer pico está a 5.005 m y es de nivel técnico de iniciación. Un porcentaje de cumbres de principiantes del 95 % indica que la ruta es manejable y la logística está madura: muy adecuado para ponerse material técnico por primera vez.",

    "q.m08#2.p" to "¿Cuál es la importancia geográfica del Gangshika?",
    "q.m08#2.o0" to "El pico más alto de la cordillera del Kunlun",
    "q.m08#2.o1" to "El pico más alto de la parte oriental de la cordillera del Qilian",
    "q.m08#2.o2" to "El pico más alto de la meseta tibetana",
    "q.m08#2.o3" to "El pico más alto de la cordillera del Hengduan",
    "q.m08#2.e" to "El Gangshika es el pico más alto de la parte oriental del Qilian, en el condado de Menyuan, prefectura de Haibei, Qinghai. Es además uno de los picos nevados altos más cercanos a una ciudad en China: la accesibilidad determina directamente lo popular que se vuelve un pico como objetivo de formación.",

    "q.m08#3.p" to "¿Cuáles son la distancia de aproximación y el tiempo típico para el tercer pico del Gangshika?",
    "q.m08#3.o0" to "Unos 3 km / 2 horas",
    "q.m08#3.o1" to "Unos 10 km / 6 horas",
    "q.m08#3.o2" to "Unos 25 km / dos días",
    "q.m08#3.o3" to "Unos 1 km / 30 minutos",
    "q.m08#3.e" to "Unos 10 km y seis horas. Esa carga es justo la adecuada para una primera escalada técnica: no ganas aguantando una caminata larga, sino concentrándote en la técnica y en el juicio.",

    "q.m08#4.p" to "¿Cuál es la altitud del Haba Xue Shan?",
    "q.m08#4.o0" to "5.005 m",
    "q.m08#4.o1" to "5.254 m",
    "q.m08#4.o2" to "5.396 m",
    "q.m08#4.o3" to "5.642 m",
    "q.m08#4.e" to "El Haba tiene 5.396 m, en Shangri-La, Yunnan. Su valor es que por encima de la límite de las nieves hay hielo de verdad, lo que exige crampones y piolet, pero sin la presión estricta de aclimatación de un pico de 6.000 m.",

    "q.m08#5.p" to "¿Dónde exige habilidad técnica el Haba Xue Shan?",
    "q.m08#5.o0" to "Requiere capacidad de escalada en roca",
    "q.m08#5.o1" to "Por encima de la límite de las nieves hay una pendiente de hielo que exige crampones y piolet",
    "q.m08#5.o2" to "Requiere capacidad de buceo",
    "q.m08#5.o3" to "No necesita ningún material técnico",
    "q.m08#5.e" to "La palabra clave del Haba es «hielo por encima de la límite de las nieves». Hay que saber progresar con regularidad sobre hielo con crampones y usar el piolet para el apoyo y la detención: justo lo que cubren las lecciones anteriores de esta unidad de progresión a 5.000 m.",

    "q.m08#6.p" to "¿Cuáles son la altitud y el estatus del Elbrús?",
    "q.m08#6.o0" to "5.642 m, el pico más alto de Europa",
    "q.m08#6.o1" to "5.895 m, el más alto de África",
    "q.m08#6.o2" to "5.254 m, el más alto del Qilian",
    "q.m08#6.o3" to "6.178 m, un pico alto del Kunlun",
    "q.m08#6.e" to "El Elbrús tiene 5.642 m, el pico más alto de Europa, en el Cáucaso ruso. Su lugar en la progresión es particular: clase 5.000 m en altitud, pero exige progresión glaciar y encordarse: un puente clásico entre picos de trekking y picos técnicos.",

    "q.m08#7.p" to "¿Cuáles son los requisitos básicos para subir el Elbrús?",
    "q.m08#7.o0" to "Solo forma física",
    "q.m08#7.o1" to "Crampones y piolet; la progresión glaciar y el encordamiento son requisitos básicos",
    "q.m08#7.o2" to "Oxígeno suplementario",
    "q.m08#7.o3" to "Capacidad de escalada en roca",
    "q.m08#7.e" to "La ruta del Elbrús cruza glaciares, así que el encordamiento, la vigilancia de grietas y el uso de crampones son la base. Se compara a menudo con el Kilimanjaro: los dos de clase 5.000 m, uno puro trekking y otro que exige trabajo técnico real.",

    "q.m08#8.p" to "[Elección múltiple] Al pasar de picos de trekking a picos técnicos, ¿qué capacidades hay que construir primero?",
    "q.m08#8.o0" to "Uso correcto del material técnico (crampones, piolet, arnés)",
    "q.m08#8.o1" to "Gestos técnicos básicos como detener una caída",
    "q.m08#8.o2" to "Progresión glaciar encordada y sistemas básicos de protección",
    "q.m08#8.o3" to "Juicio sobre cuándo no continuar",
    "q.m08#8.o4" to "Comprar material más caro",
    "q.m08#8.e" to "Las tres primeras son capacidades; la cuarta es una restricción. Mucha gente construye solo las tres primeras y acaba más confiada a medida que gana habilidad, lo que sube el riesgo. La formación técnica y la del juicio deben avanzar juntas, y por eso esta unidad empareja lecciones de técnica con lecciones de picos.",

    "q.m08#9.p" to "[Orden] Ordena estos objetivos por dificultad creciente.",
    "q.m08#9.o0" to "Aotaina (trekking, sin dificultad técnica)",
    "q.m08#9.o1" to "Tercer pico del Gangshika (técnica de iniciación)",
    "q.m08#9.o2" to "Haba / Elbrús (mixto, crampones y encordamiento)",
    "q.m08#9.o3" to "Cara sur del Yuzhu (6.000 m mixto)",
    "q.m08#9.e" to "La clave es añadir una sola variable nueva cada vez: sin técnica, luego material técnico, luego su uso sobre hielo real, luego altitud. El error habitual no es saltarse un paso sino maximizar dificultad y altitud a la vez, y así ya no sabes para cuál no estabas preparado.",

    "q.m08#10.p" to "¿Por qué pasar del tercer pico a la cumbre principal es una progresión sensata?",
    "q.m08#10.o0" to "Porque el tercer pico es el más cercano a la cumbre principal",
    "q.m08#10.o1" to "Porque distintas rutas de una misma montaña separan la dificultad técnica de la dificultad ambiental",
    "q.m08#10.o2" to "Porque la cumbre principal es más barata",
    "q.m08#10.o3" to "Porque es más fácil perderse en el tercer pico",
    "q.m08#10.e" to "Progresar en la misma montaña mantiene las variables ambientales —tiempo, accesos, logística, guías— más o menos constantes, así que notas con claridad de dónde viene la dificultad extra. Si cambias de montaña cada vez, nunca sabrás si el límite era la técnica o la aclimatación.",

    "q.m08#11.p" to "¿Cuál es la actitud correcta al elegir un objetivo de progresión de 5.000 m?",
    "q.m08#11.o0" to "Coger el más alto y saltarse los pasos",
    "q.m08#11.o1" to "Añadir una dificultad nueva cada vez y priorizar un apoyo fiable",
    "q.m08#11.o2" to "Coger el más barato",
    "q.m08#11.o3" to "Mirar solo el porcentaje de cumbres, no las exigencias técnicas",
    "q.m08#11.e" to "La capacidad se construye de forma acumulativa, y cada paso saltado multiplica el riesgo. Un apoyo fiable —guías, rescate, plan de retirada— es la base de seguridad común a todos los niveles de entrada: no puede impedir que cometas un error, pero impide que un error sea fatal.",
    // m09 — Medicación en altitud
    "q.m09#0.p" to "¿Cuáles son los dos objetivos básicos de la medicación en altitud?",
    "q.m09#0.o0" to "Curar el mal de altura y sustituir el descenso",
    "q.m09#0.o1" to "Acelerar la aclimatación y ganar tiempo para el descenso",
    "q.m09#0.o2" to "Mejorar la forma física y la resistencia",
    "q.m09#0.o3" to "Prevenir resfriados y mejorar el sueño",
    "q.m09#0.e" to "Mantener separados estos dos objetivos es fundamental: la acetazolamida pertenece al primero (aclimatación más rápida) y la dexametasona y el nifedipino al segundo (ganar tiempo). Tratar un fármaco que solo compra tiempo como prueba de recuperación es el error más peligroso en la atención en altitud.",
    "q.m09#1.p" to "¿La dexametasona influye en la aclimatación?",
    "q.m09#1.o0" to "Sí, la acelera",
    "q.m09#1.o1" to "No, no tiene ningún efecto sobre la aclimatación",
    "q.m09#1.o2" to "Sí, la retrasa",
    "q.m09#1.o3" to "Solo con un uso prolongado",
    "q.m09#1.e" to "El manual es tajante: la dexametasona alivia los síntomas del edema cerebral, no influye en la aclimatación y no trata el edema pulmonar. Solo compra tiempo, y ese tiempo hay que gastarlo descendiendo.",
    "q.m09#2.p" to "¿Qué efecto secundario del nifedipino exige más precaución?",
    "q.m09#2.o0" to "Somnolencia",
    "q.m09#2.o1" to "Una caída rápida de la tensión arterial, de modo que levantarse de golpe puede provocar un desmayo",
    "q.m09#2.o2" to "Acúfenos",
    "q.m09#2.o3" to "Pérdida de apetito",
    "q.m09#2.e" to "Esto es peligroso en situaciones reales: un desmayo por hipotensión ortostática en una pendiente pronunciada o al salir de la tienda de noche puede tener consecuencias más inmediatas que el propio mal de altura. El manual también señala que el nifedipino puede ayudar a los trekkers, pero no es la mejor opción para los escaladores.",
    "q.m09#3.p" to "¿Cuál es la actitud correcta ante la medicación de altitud?",
    "q.m09#3.o0" to "Memorizar la dosis y usarla por cuenta propia",
    "q.m09#3.o1" to "Es una decisión médica: valorarla con un médico y seguir sus indicaciones",
    "q.m09#3.o2" to "Los miembros del equipo pueden compartirla libremente",
    "q.m09#3.o3" to "Los efectos secundarios no afectan al uso",
    "q.m09#3.e" to "Cada fármaco tiene indicaciones, contraindicaciones y efectos secundarios específicos (el nifedipino baja la tensión, la aspirina conlleva riesgo de sangrado, la dexametasona es un esteroide). No son «sentido común de altura» sino intervenciones médicas; de ahí el énfasis repetido en el consejo médico.",
    "q.m09#4.p" to "Los síntomas ceden tras la dexametasona. ¿Qué hay que hacer?",
    "q.m09#4.o0" to "Seguir ascendiendo según lo previsto",
    "q.m09#4.o1" to "No ascender igualmente; descender cuanto antes",
    "q.m09#4.o2" to "Aumentar la dosis y continuar",
    "q.m09#4.o3" to "Suspender el fármaco de inmediato y observar",
    "q.m09#4.e" to "El fármaco elimina los síntomas, pero la causa del edema cerebral —la hipoxia— sigue ahí. La conclusión del manual es clara: aunque los síntomas remitan, no se debe seguir ganando altitud. El descenso es la única acción que elimina la causa.",
    "q.m09#5.p" to "¿Cómo se usa la aspirina para el dolor de cabeza de altura?",
    "q.m09#5.o0" to "Tomarla cuando empieza el dolor",
    "q.m09#5.o1" to "De forma preventiva: empezar pronto y dosificar con regularidad",
    "q.m09#5.o2" to "Solo al acostarse",
    "q.m09#5.o3" to "Solo después de descender",
    "q.m09#5.e" to "El manual indica 320 mg tres veces al día desde el día anterior al ascenso, hasta completar la aclimatación: una pauta preventiva regular, no de tomar cuando duele. Los dos planteamientos responden a lógicas completamente distintas.",
    "q.m09#6.p" to "¿Cuál es la diferencia fundamental entre la acetazolamida y la dexametasona?",
    "q.m09#6.o0" to "Una es barata y la otra cara",
    "q.m09#6.o1" to "Una acelera la aclimatación y la otra solo alivia los síntomas",
    "q.m09#6.o2" to "Una es oral y la otra inyectable",
    "q.m09#6.o3" to "Actúan igual",
    "q.m09#6.e" to "Esta distinción decide todo lo que viene después: con acetazolamida, la mejoría puede interpretarse como una aclimatación real del organismo; con dexametasona, la mejoría solo enmascara. Y la respuesta a si se puede seguir ascendiendo es opuesta en cada caso.",
    "q.m09#7.p" to "[Opción múltiple] ¿Qué afirmaciones sobre la medicación de altitud son correctas?",
    "q.m09#7.o0" to "La medicación no puede sustituir al descenso",
    "q.m09#7.o1" to "La dosis y el momento de administración requieren orientación médica",
    "q.m09#7.o2" to "Fármacos distintos actúan sobre problemas distintos y no deben confundirse",
    "q.m09#7.o3" to "Cuando la medicación enmascara los síntomas, el juicio se vuelve más difícil",
    "q.m09#7.o4" to "Cuando los síntomas ceden se puede seguir ascendiendo con seguridad",
    "q.m09#7.e" to "Las cuatro primeras son clave. La más olvidada es que el enmascaramiento dificulta el juicio: sin síntomas se pierde el indicador más directo y hay que basarse en signos más objetivos —marcha, consciencia, respiración—. Por eso, tras administrar el fármaco, hay que vigilar esos tres aspectos con aún más atención.",
    "q.m09#8.p" to "¿Por qué «sin fármacos, descender ya» suele ser la opción más fiable?",
    "q.m09#8.o0" to "Porque los fármacos no funcionan",
    "q.m09#8.o1" to "Porque el descenso elimina la causa, mientras que los fármacos solo actúan de forma indirecta",
    "q.m09#8.o2" to "Porque los fármacos son caros",
    "q.m09#8.o3" to "Porque los fármacos son incómodos de llevar",
    "q.m09#8.e" to "La causa del mal de altura es la hipoxia, y la hipoxia proviene directamente de la altitud. El descenso elimina la causa; los fármacos solo cambian cómo responde el organismo a ella. Siempre que las condiciones lo permitan, el descenso es la acción prioritaria.",
    "q.m09#9.p" to "[Ordenar] Un miembro del equipo muestra signos de mal de altura grave. ¿Cuál es la secuencia correcta?",
    "q.m09#9.o0" to "Detener el ascenso de inmediato; valorar consciencia, marcha y respiración",
    "q.m09#9.o1" to "Organizar el descenso (al menos 1.000 m), con oxígeno si hay disponible",
    "q.m09#9.o2" to "Administrar el fármaco adecuado (como dexametasona) bajo supervisión médica",
    "q.m09#9.o3" to "Si el descenso es imposible, usar una cámara hiperbárica y pedir rescate",
    "q.m09#9.e" to "El orden marca la prioridad: valorar, descender, apoyar con fármacos y solo después recurrir a medidas que compran tiempo. El error más común en la práctica es invertirlo: buscar primero el fármaco y olvidar que el descenso es el tratamiento definitivo.",
    "q.m09#10.p" to "¿Por qué es tan importante acordar de antemano con un médico el plan de medicación en las salidas de alta montaña?",
    "q.m09#10.o0" to "Porque no se pueden comprar fármacos en la montaña",
    "q.m09#10.o1" to "Porque allí arriba no hay asesoramiento profesional y los vómitos pueden cambiar la vía de administración",
    "q.m09#10.o2" to "Porque los fármacos caducan",
    "q.m09#10.o3" to "Porque los guías lo exigen",
    "q.m09#10.e" to "En altitud no hay médico ni diagnóstico; peor aún, el paciente puede estar vomitando y no tolerar nada por vía oral. El plan —dosis, momento, vía y contraindicaciones— debe acordarse antes de salir.",
    "q.m09#11.p" to "[Emparejar] Relaciona cada fármaco con su acción principal.",
    "q.m09#11.l0" to "Acetazolamida",
    "q.m09#11.r0" to "Acelera la aclimatación; se usa de forma preventiva",
    "q.m09#11.l1" to "Dexametasona",
    "q.m09#11.r1" to "Baja la presión intracraneal y alivia el edema cerebral",
    "q.m09#11.l2" to "Nifedipino",
    "q.m09#11.r2" to "Alivia la vasoconstricción pulmonar; se usa para el edema pulmonar",
    "q.m09#11.e" to "Tres cartas, tres funciones: acetazolamida para la aclimatación, dexametasona para el cerebro, nifedipino para los pulmones. Primero hay que determinar qué problema tiene el paciente y luego elegir la carta, en lugar de tratar cualquier fármaco como una «pastilla genérica de altura».",
    // m10 — Ventana meteorológica
    "q.m10#0.p" to "¿Qué es una ventana meteorológica?",
    "q.m10#0.o0" to "El día con menor probabilidad de precipitación en el pronóstico",
    "q.m10#0.o1" to "El periodo en el que se puede completar el objetivo con seguridad",
    "q.m10#0.o2" to "Las horas con más luz diurna",
    "q.m10#0.o3" to "El momento con menos viento",
    "q.m10#0.e" to "Una ventana meteorológica es una idea combinada: cumple a la vez «el tiempo lo permite» y «el equipo puede hacerlo». Por eso, con el mismo tiempo, la ventana de un equipo fuerte y la de uno débil tienen anchuras completamente distintas: las ventanas son relativas, no absolutas.",
    "q.m10#1.p" to "¿Por qué el pronóstico meteorológico en montaña es relativamente impreciso?",
    "q.m10#1.o0" to "Porque hay muy pocas estaciones meteorológicas",
    "q.m10#1.o1" to "Porque el relieve complejo genera una enorme variación local: distintas altitudes y orientaciones pueden tener tiempos completamente distintos",
    "q.m10#1.o2" to "Porque los predictores son descuidados",
    "q.m10#1.o3" to "Porque no hay datos en altitud",
    "q.m10#1.e" to "El ascenso orográfico, el bloqueo y el flujo alrededor de las crestas dividen el tiempo de forma brusca a pequeña escala: unos kilómetros más allá puede ser otro mundo. El pronóstico regional es solo el contexto; la observación de campo es lo que permite decidir.",
    "q.m10#2.p" to "El espesamiento de las nubes y el descenso de la base nubosa suelen indicar qué?",
    "q.m10#2.o0" to "Que el tiempo mejora",
    "q.m10#2.o1" to "Que el tiempo empeora y que la visibilidad probablemente caerá rápido",
    "q.m10#2.o2" to "Que despejará en breve",
    "q.m10#2.o3" to "Nada en particular",
    "q.m10#2.e" to "Una base nubosa más baja significa humedad creciente y un nivel de condensación descendente, a menudo precursor de un sistema de precipitación. En montaña también significa que la visibilidad está a punto de reducirse, lo cual es un riesgo en sí mismo.",
    "q.m10#3.p" to "¿Por qué importa más la tendencia de la presión que su valor?",
    "q.m10#3.o0" to "Porque el valor siempre es erróneo",
    "q.m10#3.o1" to "Porque el tiempo lo impulsa el cambio de presión y los valores de referencia varían de todos modos con la altitud",
    "q.m10#3.o2" to "Porque las tendencias son más fáciles de recordar",
    "q.m10#3.o3" to "Porque los valores fluctúan demasiado",
    "q.m10#3.e" to "Una misma lectura de presión significa cosas completamente distintas a distinta altitud y en distintos lugares, así que un número aislado carece de referencia. Un descenso sostenido, en cambio, apunta a lo mismo en todas partes: el tiempo está cambiando.",
    "q.m10#4.p" to "¿Qué valor práctico tiene la escala de Beaufort?",
    "q.m10#4.o0" to "Hace que el viento parezca más profesional",
    "q.m10#4.o1" to "Convierte la velocidad del viento en una escala observable y comunicable para juzgar la movilidad y hablar entre nosotros",
    "q.m10#4.o2" to "Mide la precipitación",
    "q.m10#4.o3" to "Estima la temperatura",
    "q.m10#4.e" to "El viento es información que hay que verbalizar: un equipo necesita un lenguaje común para «¿podemos seguir?». Beaufort convierte una velocidad abstracta en signos observables —hojas, nieve arrastrada, la sensación en la cara— de modo que el juicio circula rápido por el grupo.",
    "q.m10#5.p" to "[Opción múltiple] ¿Cuáles de estas son señales de campo de que el tiempo empeora?",
    "q.m10#5.o0" to "La presión baja de forma sostenida",
    "q.m10#5.o1" to "Las nubes espesan rápido y la base desciende",
    "q.m10#5.o2" to "El viento se refuerza de forma notable y cambia de dirección a menudo",
    "q.m10#5.o3" to "Se forman cumulonimbos a lo lejos",
    "q.m10#5.o4" to "La presión sube de forma sostenida y el viento amaina",
    "q.m10#5.e" to "Las cuatro primeras son las principales señales de empeoramiento del manual. Todas describen una tendencia y no un instante, por eso importa observar de forma regular y cronometrada. Solo con algo con lo que comparar significa algo una tendencia.",
    "q.m10#6.p" to "Durante una tormenta, ¿qué comportamiento es más peligroso?",
    "q.m10#6.o0" to "Detenerse y descender",
    "q.m10#6.o1" to "Quedarse en una cresta, una cima o en agua abierta: cualquier lugar expuesto",
    "q.m10#6.o2" to "Guardar el material metálico",
    "q.m10#6.o3" to "Agacharse y esperar",
    "q.m10#6.e" to "Lo peor en una tormenta es ser el objeto más alto del entorno. Las crestas y las cimas son justamente los lugares más expuestos, así que hay que salir en cuanto amenacen los rayos. Mantén el material metálico junto y separado del cuerpo.",
    "q.m10#7.p" to "¿Por qué se suele empezar el ataque a cima antes del amanecer?",
    "q.m10#7.o0" to "Para evitar las aglomeraciones",
    "q.m10#7.o1" to "Porque a primera hora suele ser la parte más estable del día, mientras que por la tarde la convección aumenta y las probabilidades empeoran",
    "q.m10#7.o2" to "Porque a las 3 de la madrugada se tiene más energía",
    "q.m10#7.o3" to "Porque durante el día hace demasiado calor",
    "q.m10#7.e" to "Sigue el ciclo diario: el calentamiento diurno impulsa la convección, de modo que la probabilidad de nubes y precipitación sube por la tarde. Situar la parte más dura y crítica de la ascensión antes del amanecer es comprar una ventana más indulgente.",
    "q.m10#8.p" to "¿Cómo se relaciona la hora límite de regreso con la ventana meteorológica?",
    "q.m10#8.o0" to "No tienen relación",
    "q.m10#8.o1" to "La hora límite debe derivarse de la ventana meteorológica; si la ventana se estrecha, se adelanta",
    "q.m10#8.o2" to "La hora límite es siempre fija",
    "q.m10#8.o3" to "Con buen tiempo no hace falta hora límite",
    "q.m10#8.e" to "La hora límite no es un número fijo: se calcula a partir de la ventana del día. Cuánto falta hasta la cima, cuánto se tarda en descender, cuándo empieza a cerrarse la ventana... calculando hacia atrás se obtiene el último momento para darse la vuelta.",
    "q.m10#9.p" to "[Ordenar] Ordena de forma sensata los pasos de un juicio meteorológico rutinario.",
    "q.m10#9.o0" to "Antes de salir, consultar el pronóstico regional y la tendencia de la presión",
    "q.m10#9.o1" to "Durante la marcha, observar nubes, viento y visibilidad a intervalos regulares",
    "q.m10#9.o2" to "Comparar las observaciones de campo con el pronóstico para juzgar la dirección de la tendencia",
    "q.m10#9.o3" to "Ajustar el plan o darse la vuelta con antelación según esa tendencia",
    "q.m10#9.e" to "El tercer paso es la clave: mucha gente se queda en el segundo, con la sensación de que el tiempo cambia, sin convertirlo en una decisión. Una observación que nunca se convierte en acción no es observación.",
    "q.m10#10.p" to "Cuando la ventana meteorológica se estrecha, ¿qué hay que sacrificar primero?",
    "q.m10#10.o0" to "El material de seguridad",
    "q.m10#10.o1" to "El objetivo de la cima en sí",
    "q.m10#10.o2" to "Los miembros del equipo",
    "q.m10#10.o3" to "El equipo de comunicación",
    "q.m10#10.e" to "Es una cuestión de prioridades: cuando la ventana no admite a la vez la cima y un descenso seguro, lo que se mantiene es el descenso y lo que se descarta es la cima. Eso se decide antes de salir, no en la montaña.",
    "q.m10#11.p" to "¿Qué visión de las condiciones de pérdida de contraste es correcta?",
    "q.m10#11.o0" to "Solo es mala visibilidad, sin peligro",
    "q.m10#11.o1" to "Se pierde toda referencia visual y se camina instintivamente en la dirección equivocada: primero hay que fijar la posición",
    "q.m10#11.o2" to "Trae precipitación",
    "q.m10#11.o3" to "Solo ocurre de noche",
    "q.m10#11.e" to "El peligro de la pérdida de contraste no es que no se vea, sino que uno cree que ve. Sin referencias, el sentido de la orientación se desvía de forma sistemática, así que lo primero es fijar la posición y anotar el rumbo, no seguir caminando.",
    // m11 — Seis miles: Yuzhu, Qizi, Lobuche Este, Island Peak
    "q.m11#0.p" to "¿Cuál es la altitud y la ubicación del Yuzhu?",
    "q.m11#0.o0" to "6.178 m, Golmud, Qinghai, cordillera de Kunlun oriental",
    "q.m11#0.o1" to "6.206 m, Damxung, Tíbet, cordillera de Nyainqêntanglha",
    "q.m11#0.o2" to "6.119 m, Khumbu, Nepal",
    "q.m11#0.o3" to "6.189 m, Khumbu, Nepal",
    "q.m11#0.e" to "El Yuzhu tiene 6.178 m y está en el extremo oriental de Kunlun, dentro de Golmud (Qinghai). Su ruta de la vertiente sur es relativamente suave y el acceso es bueno, y por eso es el primer seis mil de mucha gente.",
    "q.m11#1.p" to "¿Cuál es la altitud y la cordillera del Qizi?",
    "q.m11#1.o0" to "6.178 m, cordillera de Kunlun",
    "q.m11#1.o1" to "6.206 m, cordillera de Nyainqêntanglha",
    "q.m11#1.o2" to "6.119 m, Himalaya",
    "q.m11#1.o3" to "6.189 m, Karakórum",
    "q.m11#1.e" to "El Qizi tiene 6.206 m y está en la cordillera de Nyainqêntanglha, en Damxung (Tíbet). Su rasgo distintivo son las pendientes de nieve estables y un acceso sencillo: pendientes estables significan que el riesgo de alud y de grieta es comparativamente manejable, lo que lo hace apto para el entrenamiento de progresión.",
    "q.m11#2.p" to "¿Cuál es la altitud y la ubicación del Lobuche Este?",
    "q.m11#2.o0" to "6.119 m, Khumbu, Nepal",
    "q.m11#2.o1" to "6.189 m, Khumbu, Nepal",
    "q.m11#2.o2" to "6.206 m, Damxung, Tíbet",
    "q.m11#2.o3" to "6.178 m, Golmud, Qinghai",
    "q.m11#2.e" to "El Lobuche Este tiene 6.119 m y está en la región de Khumbu (Nepal), justo al lado de la ruta de trekking del Everest. Esa posición significa aclimatación y logística consolidadas, y sus pendientes de nieve más inclinadas lo convierten en un buen paso hacia mayor altitud.",
    "q.m11#3.p" to "¿Cuál es el rasgo técnico más típico del Island Peak (Imja Tse)?",
    "q.m11#3.o0" to "No requiere ningún material técnico",
    "q.m11#3.o1" to "Encordarse y progresar sobre grietas",
    "q.m11#3.o2" to "Requiere oxígeno suplementario",
    "q.m11#3.o3" to "Requiere capacidad de escalada en roca",
    "q.m11#3.e" to "El Island Peak, con 6.189 m, es un seis mil técnico clásico: hay que encordarse y hay que gestionar grietas. Por eso también se usa como preparación para los siete mil: pone en uso real el sistema de progresión glaciar con cordada.",
    "q.m11#4.p" to "Comparado con los 5.000 m, ¿qué riesgo aumenta más a 6.000 m?",
    "q.m11#4.o0" to "La caída de piedras",
    "q.m11#4.o1" to "La presión de aclimatación y el riesgo de mal de altura",
    "q.m11#4.o2" to "Los insectos",
    "q.m11#4.o3" to "El peso del material",
    "q.m11#4.e" to "Por encima de 6.000 m la incidencia y la gravedad del mal de altura aumentan de forma notable, y por eso esta unidad trata el mal de altura como capítulo central. Técnicamente el salto puede ser gradual, pero el salto fisiológico es real.",
    "q.m11#5.p" to "[Opción múltiple] ¿Qué deberías dominar ya antes de un seis mil?",
    "q.m11#5.o0" to "El uso básico de crampones y piolet",
    "q.m11#5.o1" to "Los nudos básicos y la progresión encordado",
    "q.m11#5.o2" to "Reconocer y manejar el mal de altura",
    "q.m11#5.o3" to "Una noción básica del riesgo de grieta",
    "q.m11#5.o4" to "Liderar hielo WI5 de forma autónoma",
    "q.m11#5.e" to "Las cuatro primeras corresponden a las unidades de iniciación y progresión de los cinco mil. La unidad de los seis mil no las vuelve a enseñar: las pone en un entorno más duro. Ir directamente a los 6.000 m con bases débiles multiplica el riesgo.",
    "q.m11#6.p" to "¿Por qué la vertiente sur del Yuzhu suele ser el primer objetivo de seis mil?",
    "q.m11#6.o0" to "Porque es lo más barato",
    "q.m11#6.o1" to "Porque la ruta es relativamente suave y el acceso y la logística están resueltos, así que puedes centrarte en la aclimatación",
    "q.m11#6.o2" to "Porque no tiene ningún peligro",
    "q.m11#6.o3" to "Porque no necesita guía",
    "q.m11#6.e" to "El valor de un primer objetivo es añadir una sola variable nueva. La vertiente sur mantiene la dificultad técnica dentro de un rango manejable para que te concentres en el reto real: la aclimatación. Si eliges un seis mil técnicamente exigente, no podrás saber qué falló.",
    "q.m11#7.p" to "[Ordenar] Ordena estos objetivos de menor a mayor altitud.",
    "q.m11#7.o0" to "Lobuche Este (6.119 m)",
    "q.m11#7.o1" to "Yuzhu (6.178 m)",
    "q.m11#7.o2" to "Island Peak (6.189 m)",
    "q.m11#7.o3" to "Qizi (6.206 m)",
    "q.m11#7.e" to "La diferencia de altitud es mínima: de 6.119 a 6.206 m, menos de 90 m. Y eso lo deja claro: en la franja de los seis mil hay que elegir por tipo de ruta, por apoyo y por los propios puntos débiles, no por el número de altura.",
    "q.m11#8.p" to "¿Por qué hay que dar por hecho que hay grietas a 6.000 m?",
    "q.m11#8.o0" to "Porque las grietas hacen ruido",
    "q.m11#8.o1" to "Porque los puentes de nieve pueden quedar completamente cubiertos por nieve reciente y parecer terreno normal",
    "q.m11#8.o2" to "Porque las grietas solo aparecen de noche",
    "q.m11#8.o3" to "Porque las grietas son fáciles de identificar",
    "q.m11#8.e" to "Eso es justo lo que hace letales a las grietas: a diferencia de la caída de piedras, no avisan. La mentalidad correcta a 6.000 m es «están en todas partes», y se gestiona el riesgo con cordadas y material, no juzgando por si parece seguro.",
    "q.m11#9.p" to "Al elegir un seis mil, ¿qué importa más que la altitud?",
    "q.m11#9.o0" to "Lo famosa que sea la montaña",
    "q.m11#9.o1" to "El tipo de ruta (trekking / mixta / técnica), las condiciones de apoyo y el ritmo de ascensión",
    "q.m11#9.o2" to "El coste",
    "q.m11#9.o3" to "La popularidad en redes sociales",
    "q.m11#9.e" to "Montañas de altitud parecida pueden diferir enormemente en exigencia técnica y presión de aclimatación. Solo combinando tipo de ruta, apoyo y ritmo de ascensión se responde a «¿esta montaña es adecuada para mí ahora?».",
    "q.m11#10.p" to "¿Qué visión del umbral técnico de los seis mil es correcta?",
    "q.m11#10.o0" to "Es muy bajo; solo importa la forma física",
    "q.m11#10.o1" to "No es alto, pero no se puede empezar de cero: las técnicas de progresión glaciar son obligatorias",
    "q.m11#10.o2" to "Hay que tener base de escalada en roca",
    "q.m11#10.o3" to "Hay que saber usar oxígeno suplementario",
    "q.m11#10.e" to "El perfil típico de un seis mil: dificultad técnica moderada, pero ya debes saber encordarte, valorar el riesgo de grieta y moverte de forma autónoma por un glaciar. Es donde empieza el «puedo protegerme con un sistema», no donde ves a otros hacerlo.",
    "q.m11#11.p" to "¿Por qué la mejor temporada de una montaña es tan decisiva para el plan?",
    "q.m11#11.o0" to "Porque los permisos son más baratos fuera de temporada",
    "q.m11#11.o1" to "Porque la ventana escalable depende mucho de los patrones meteorológicos estacionales; la temporada equivocada puede no ofrecer casi ninguna ventana",
    "q.m11#11.o2" to "Porque la temporada cambia el color de la nieve",
    "q.m11#11.o3" to "Porque los guías solo trabajan en temporada alta",
    "q.m11#11.e" to "Las razones varían según la montaña: unas temporadas evitan las precipitaciones del monzón, otras evitan el frío y el viento extremos del invierno. Entender por qué funciona una temporada importa mucho más que memorizar un mes, sobre todo porque el cambio climático está desplazando estos patrones.",
    // m12 — Sistemas de rescate y ventaja mecánica
    "q.m12#0.p" to "¿Por qué un sistema en Z 3:1 triplica la fuerza de tracción?",
    "q.m12#0.o0" to "Porque usa una cuerda más gruesa",
    "q.m12#0.o1" to "Porque la combinación de prusik y polea multiplica por tres la distancia que tiras",
    "q.m12#0.o2" to "Porque la gravedad ayuda",
    "q.m12#0.o3" to "Porque las poleas ahorran esfuerzo de forma automática",
    "q.m12#0.e" to "La ventaja mecánica consiste básicamente en cambiar distancia por fuerza: tiras tres metros de cuerda y la carga sube uno. El precio es la velocidad, y en un rescate de grieta ese precio es del todo aceptable.",
    "q.m12#1.p" to "¿Cuál es la función principal de la polea en un sistema de rescate?",
    "q.m12#1.o0" to "Aportar fuerza extra",
    "q.m12#1.o1" to "Reducir las pérdidas por rozamiento de la cuerda y mejorar la eficiencia del sistema",
    "q.m12#1.o2" to "Fijar la cuerda",
    "q.m12#1.o3" to "Proteger la cuerda del desgaste",
    "q.m12#1.e" to "El rozamiento es el enemigo oculto de la ventaja mecánica: cada reenvío se lleva parte de la fuerza. Una polea convierte el rozamiento por deslizamiento en rozamiento por rodadura, y así el 3:1 teórico se acerca al 3:1 real.",
    "q.m12#2.p" to "¿Se puede montar un sistema de rescate sin poleas?",
    "q.m12#2.o0" to "En absoluto",
    "q.m12#2.o1" to "Sí, con mosquetones, pero el rozamiento aumenta de forma notable y la eficiencia baja",
    "q.m12#2.o2" to "Sí, solo con cuerda y con la misma eficiencia",
    "q.m12#2.o3" to "No, hay que esperar a tener material",
    "q.m12#2.e" to "Los mosquetones pueden sustituir a las poleas, y por eso muchos equipos consideran obligatorios los mosquetones de repuesto. La diferencia es que la ventaja real queda muy por debajo del valor teórico; saberlo permite prepararse mental y físicamente cuando el material está incompleto.",
    "q.m12#3.p" to "[Opción múltiple] ¿Qué incluye el manual como material estándar de rescate de cordada?",
    "q.m12#3.o0" to "2–3 estacas de nieve o tornillos de hielo",
    "q.m12#3.o1" to "2–5 mosquetones y 2–5 anillos de cinta",
    "q.m12#3.o2" to "1 polea de aseguramiento",
    "q.m12#3.o3" to "2–3 prusiks y 1 bloqueador",
    "q.m12#3.o4" to "1 hornillo portátil y una bombona de gas",
    "q.m12#3.e" to "La línea clave de esa lista es que cada miembro de la cordada debe llevar material de rescate suficiente: es equipo personal, no material común del grupo. Cuando alguien cae, lo que llevas en el arnés es el único material disponible.",
    "q.m12#4.p" to "¿Cómo frena un bloqueador?",
    "q.m12#4.o0" to "Con un muelle que aprisiona la cuerda",
    "q.m12#4.o1" to "Por rozamiento inverso entre los dientes de acero y la cuerda",
    "q.m12#4.o2" to "Por atracción magnética",
    "q.m12#4.o3" to "Por el propio peso de la cuerda",
    "q.m12#4.e" to "Entender el mecanismo importa en el uso: como los dientes de acero muerden las fibras, una fuerza excesiva daña la cuerda y puede cortar fibras en el punto cargado. Por eso el manual insiste en usarlo con un método de frenado asistido siempre que sea posible.",
    "q.m12#5.p" to "¿Qué pasa si tironeas de un bloqueador con demasiada fuerza?",
    "q.m12#5.o0" to "Nada en absoluto",
    "q.m12#5.o1" to "Los dientes de acero dañan la cuerda",
    "q.m12#5.o2" to "El bloqueador se atasca",
    "q.m12#5.o3" to "El bloqueador se suelta",
    "q.m12#5.e" to "Los dientes frenan por rozamiento inverso, así que una fuerza grande marca la funda y, de forma acumulada, puede crear un punto de rotura. Verás a bastante gente tironeando del bloqueador por costumbre: cambiar un hábito por un riesgo.",
    "q.m12#6.p" to "[Ordenar] Ordena de forma sensata los pasos para montar un sistema en Z 3:1.",
    "q.m12#6.o0" to "Confirmar que la reunión es sólida y transferirle el peso del escalador caído",
    "q.m12#6.o1" to "Colocar el prusik principal en la cuerda cargada y añadir un prusik de respaldo",
    "q.m12#6.o2" to "Conectar una polea o un mosquetón al prusik para formar el recorrido en Z",
    "q.m12#6.o3" to "Revisar todo el sistema y después izar, retensando tras cada tirón",
    "q.m12#6.e" to "El primer paso es la base: sin transferir el peso, las manos siguen comprometidas sujetando la detención. Y el último —retensar tras cada tirón— se salta con facilidad, y así hay quien iza durante mucho rato y luego retrocede.",
    "q.m12#7.p" to "[Emparejar] Relaciona cada elemento de rescate con su función en el sistema.",
    "q.m12#7.l0" to "Prusik",
    "q.m12#7.r0" to "Agarre en un solo sentido, para que el sistema avance y no retroceda",
    "q.m12#7.l1" to "Polea",
    "q.m12#7.r1" to "Reduce las pérdidas por rozamiento y mejora la eficiencia",
    "q.m12#7.l2" to "Polea de aseguramiento",
    "q.m12#7.r2" to "Bloquea en un sentido; sirve para controlar el destensado y el tensado",
    "q.m12#7.l3" to "Bloqueador",
    "q.m12#7.r3" to "Sube por la cuerda; también sirve para fijar el sistema",
    "q.m12#7.e" to "Cuatro funciones distintas: el prusik da el comportamiento unidireccional, la polea recorta el rozamiento, el dispositivo de aseguramiento da el control y el bloqueador da la movilidad. Si falta uno, el sistema queda ineficiente o incontrolable.",
    "q.m12#8.p" to "¿Por qué añadir un prusik de respaldo junto al principal?",
    "q.m12#8.o0" to "Por estética",
    "q.m12#8.o1" to "Porque un prusik puede fallar por hielo, suciedad o diámetros desajustados, y el fallo hace perder la ventaja al instante",
    "q.m12#8.o2" to "Porque la normativa lo exige",
    "q.m12#8.o3" to "Para evitar que la cuerda se retuerza",
    "q.m12#8.e" to "Un prusik funciona por rozamiento, y el rozamiento depende de muchas cosas. Si el principal resbala, el escalador caído vuelve a caer sin aviso; el respaldo está para atrapar ese instante.",
    "q.m12#9.p" to "¿Cómo elegir entre un sistema 2:1 y uno 3:1?",
    "q.m12#9.o0" to "El 2:1 siempre es mejor",
    "q.m12#9.o1" to "Según la gente disponible, la longitud de cuerda y el terreno: más ventaja exige más cuerda y es más lento",
    "q.m12#9.o2" to "El 3:1 siempre es mejor",
    "q.m12#9.o3" to "Son idénticos",
    "q.m12#9.e" to "La ventaja mecánica no es buena sin condiciones: el 3:1 necesita más cuerda, y en un rescate de grieta la cuerda suele ser escasa. La elección real es el sistema que puedes completar con la cuerda y la gente que tienes, no el teóricamente óptimo.",
    "q.m12#10.p" to "¿Por qué un sistema de ventaja mecánica nunca puede sustituir al criterio?",
    "q.m12#10.o0" to "Porque los sistemas se rompen",
    "q.m12#10.o1" to "Porque un sistema solo multiplica la fuerza; no decide si izar ni en qué dirección",
    "q.m12#10.o2" to "Porque los sistemas pesan",
    "q.m12#10.o3" to "Porque necesitan mucha gente",
    "q.m12#10.e" to "La parte difícil de un rescate nunca es la física, sino el criterio: por dónde, sobre qué borde y si el accidentado puede sobrevivir a ello. El sistema es una herramienta; la dirección la ponen las personas. Con la dirección equivocada, más fuerza lo empeora.",
    "q.m12#11.p" to "¿Cuál de estas causas no hace fallar un prusik?",
    "q.m12#11.o0" to "Diámetros de cuerda desajustados",
    "q.m12#11.o1" to "Hielo o suciedad",
    "q.m12#11.o2" to "Muy pocas vueltas",
    "q.m12#11.o3" to "Que la cuerda principal sea de color más claro",
    "q.m12#11.e" to "El diámetro, la limpieza y el número de vueltas afectan directamente al rozamiento; el color no tiene nada que ver con la mecánica. También muestra que la fiabilidad de un prusik no se juzga a ojo: se comprueba la combinación de antemano y se prueba en el terreno.",
    "q.m12#12.p" to "¿Por qué se usa a menudo una polea de aseguramiento en lugar de una polea simple?",
    "q.m12#12.o0" to "Porque pesa menos",
    "q.m12#12.o1" to "Porque bloquea en un sentido, de modo que se controla la suelta sin que el sistema retroceda",
    "q.m12#12.o2" to "Porque es más barata",
    "q.m12#12.o3" to "Porque el color se ve mejor",
    "q.m12#12.e" to "En un rescate a menudo hay que izar y ajustar a la vez, y una polea simple gira libre en los dos sentidos: si sueltas, pierdes lo ganado. Un elemento que bloquea en un sentido convierte el mantenimiento de la posición en una propiedad del sistema. Un ejemplo claro de cómo la elección del material afecta a la seguridad operativa.",
    "q.m12#13.p" to "Completa: la ventaja mecánica del sistema en Z es ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "tres",
    "q.m12#13.e" to "3:1. El valor práctico de ese número es estimar la carga: un adulto con material puede pesar 80–100 kg, así que a 3:1 todavía hay que tirar con unos 30 kg de fuerza, mucho más duro de lo que parece; por eso un rescate necesita varias personas.",
    "q.m12#14.p" to "[Opción múltiple] ¿Qué debe cubrir la revisión tras montar el sistema?",
    "q.m12#14.o0" to "Que las vueltas del prusik y la dirección de carga son correctas",
    "q.m12#14.o1" to "Que las poleas y los mosquetones están cerrados",
    "q.m12#14.o2" to "Que los puntos de unión están en la parte correcta del arnés",
    "q.m12#14.o3" to "Que hay respaldo y la cuerda no está atascada",
    "q.m12#14.o4" to "Que la cuerda y la ropa de los compañeros son del mismo color",
    "q.m12#14.e" to "Las cuatro comprobaciones corresponden a cuatro errores clásicos: prusik al revés, mosquetón abierto, enganchado en la anilla equivocada, sin respaldo. Los fallos del sistema de rescate rara vez son falta de conocimientos: son un paso olvidado a oscuras y con estrés. Usa una lista de comprobación, no la memoria.",
    "q.m12#15.p" to "¿Por qué hay que ensayar el sistema de rescate antes de salir?",
    "q.m12#15.o0" to "Para aprobar una evaluación",
    "q.m12#15.o1" to "Porque el rescate real ocurre en altitud, con frío y oscuridad, y se ejecuta por instinto",
    "q.m12#15.o2" to "Para familiarizarse con el material",
    "q.m12#15.o3" to "Porque la normativa fija unas horas de ensayo",
    "q.m12#15.e" to "Las condiciones de un rescate real son casi siempre las peores posibles: viento, manos frías, poca luz, un compañero que empeora. En esas condiciones solo se ejecutan las acciones que has repetido muchas veces; aprender sobre la marcha no es una opción.",
    // m13 — Autorrescate, rayos y tormentas
    "q.m13#0.p" to "¿Por qué el autorrescate es un requisito ineludible a 7.000 m?",
    "q.m13#0.o0" to "Porque los compañeros no están dispuestos a rescatarte",
    "q.m13#0.o1" to "Porque en condiciones de altitud los compañeros pueden no llegar a tiempo: tienes que ser capaz de resolver tu propia situación",
    "q.m13#0.o2" to "Porque el material de rescate es insuficiente",
    "q.m13#0.o3" to "Porque la normativa lo exige",
    "q.m13#0.e" to "Cuanto más alto, más caro y más lento es el rescate. Un compañero puede estar luchando contra su propio mal de altura y el tiempo puede impedir cualquier movimiento. Dejarlo todo en manos de un rescate externo es aceptar una premisa que nadie puede garantizar.",
    "q.m13#1.p" to "¿Cuál es el principio básico del ascenso con prusiks?",
    "q.m13#1.o0" to "Subir tirando con la fuerza de los brazos",
    "q.m13#1.o1" to "Alternar dos prusiks: uno soporta el peso mientras el otro asciende por la cuerda",
    "q.m13#1.o2" to "Hacerlo solo con un bloqueador",
    "q.m13#1.o3" to "Sujetar la cuerda entre las piernas",
    "q.m13#1.e" to "Un solo prusik solo mantiene la posición, no puede desplazarse, así que hay que alternar dos: mientras el inferior soporta el peso, el superior asciende, y viceversa. Este movimiento alterno hay que entrenarlo en un entorno seguro; decidirá, en el momento en que más lo necesites, si subes o no.",
    "q.m13#2.p" to "¿Por qué debe haber siempre al menos un prusik cargado durante el ascenso con prusiks?",
    "q.m13#2.o0" to "Para ahorrar esfuerzo",
    "q.m13#2.o1" to "Porque soltar los dos a la vez te hace retroceder hasta el punto de partida o caer sin más",
    "q.m13#2.o2" to "Para mantener la cuerda ordenada",
    "q.m13#2.o3" to "Para subir más rápido",
    "q.m13#2.e" to "Es la regla de los tres puntos aplicada a la cuerda: mantén siempre un punto de apoyo fiable. En una grieta, un resbalón no solo resta fuerzas, sino que puede hacer que la cuerda se hunda más en el labio de nieve y aumentar la dificultad de todo el rescate.",
    "q.m13#3.p" to "[Ordenar] Ordena correctamente los cuatro pasos de un rescate de cordada.",
    "q.m13#3.o0" to "Autodetener la caída de inmediato y estabilizarse",
    "q.m13#3.o1" to "Montar una reunión independiente",
    "q.m13#3.o2" to "Transferir la carga a la reunión",
    "q.m13#3.o3" to "Izar con un sistema 3:1",
    "q.m13#3.e" to "Estos cuatro pasos los aprendiste en la unidad de los seis mil; aquí lo que importa es ejecutarlos bajo presión. La mayor diferencia entre el ensayo y la realidad: en la realidad hay que completar los tres primeros pasos en decenas de segundos, mientras que en el ensayo quizá tardaste cinco minutos.",
    "q.m13#4.p" to "¿A qué distancia deben situarse los miembros del equipo si les sorprende una tormenta?",
    "q.m13#4.o0" to "Juntos y apiñados",
    "q.m13#4.o1" to "Unos 50 m",
    "q.m13#4.o2" to "Unos 500 m",
    "q.m13#4.o3" to "Sin límite",
    "q.m13#4.e" to "El manual sugiere unos 50 m de separación: la idea es evitar que un rayo hiera a varias personas a la vez, de modo que alguien quede en condiciones de prestar primeros auxilios. Detrás del número hay una idea sencilla: no apostarlo todo en un mismo punto.",
    "q.m13#5.p" to "¿Cuál es la única forma eficaz de reducir el peligro durante una tormenta?",
    "q.m13#5.o0" to "Tirar el material metálico, como los piolets",
    "q.m13#5.o1" to "Abandonar cuanto antes los puntos altos y el terreno expuesto, manteniéndose lo más bajo posible",
    "q.m13#5.o2" to "Agacharse y abrazarse las rodillas",
    "q.m13#5.o3" to "Abrir todas las cremalleras",
    "q.m13#5.e" to "El manual rechaza expresamente varias prácticas habituales: no hay pruebas de que objetos metálicos pequeños como piolets o varillas de tienda atraigan los rayos, así que no pierdas tiempo deshaciéndote de ellos. Lo que sí funciona es cambiar de posición: pasar de ser el objeto más alto del entorno a una parte discreta del paisaje.",
    "q.m13#6.p" to "Si oyes truenos, el rayo está a no más de:",
    "q.m13#6.o0" to "3 km",
    "q.m13#6.o1" to "10–16 km",
    "q.m13#6.o2" to "30 km",
    "q.m13#6.o3" to "50 km",
    "q.m13#6.e" to "Oír truenos significa que el rayo está a menos de 10–16 km, ya dentro del rango en el que hay que reaccionar. Ver el rayo significa que la distancia no supera unos 24 km: dos cifras, dos niveles de respuesta distintos.",
    "q.m13#7.p" to "¿Cómo se estima la distancia del rayo a partir del retardo entre el destello y el trueno?",
    "q.m13#7.o0" to "Segundos × 0,34 = distancia en km",
    "q.m13#7.o1" to "Segundos ÷ 0,34 = distancia en km",
    "q.m13#7.o2" to "Segundos × 3,4 = distancia en km",
    "q.m13#7.o3" to "No se puede estimar",
    "q.m13#7.e" to "El sonido viaja en el aire a unos 0,34 km por segundo, así que cada segundo contado tras el destello equivale aproximadamente a 0,34 km. Su valor práctico: sin ningún equipo puedes saber si la tormenta se acerca o se aleja.",
    "q.m13#8.p" to "¿Atraen los rayos los objetos metálicos pequeños (piolet, varillas de tienda)?",
    "q.m13#8.o0" to "Sí; hay que tirarlos de inmediato",
    "q.m13#8.o1" to "No hay pruebas de que lo hagan, así que no pierdas tiempo deshaciéndote de ellos",
    "q.m13#8.o2" to "Sí, pero solo en altitud",
    "q.m13#8.o3" to "Solo cuando están mojados",
    "q.m13#8.e" to "Es un mito clásico de la alta montaña. El manual es tajante: no hay pruebas que lo respalden, así que no gastes un tiempo precioso en deshacerte del material. Lo que hay que hacer es abandonar la posición expuesta cuanto antes: esa es la variable decisiva.",
    "q.m13#9.p" to "¿Cuál es el mejor lugar para resguardarse durante una tormenta?",
    "q.m13#9.o0" to "Una cima",
    "q.m13#9.o1" to "El interior de un bosque, lejos de la cima y de la cresta, pero nunca apoyado contra un árbol",
    "q.m13#9.o2" to "El centro de una ladera herbosa",
    "q.m13#9.o3" to "Dentro de una tienda",
    "q.m13#9.e" to "El interior del bosque funciona porque hay objetos más altos a tu alrededor y, a la vez, no estás pegado a un conductor. El contraejemplo es acampar en una cresta abierta: el manual lo califica de extrema insensatez, porque significa instalarse deliberadamente en el punto más alto del entorno.",
    "q.m13#10.p" to "¿Por qué no hay que acampar en una cresta mientras crecen los cúmulos?",
    "q.m13#10.o0" to "Porque hace mucho viento",
    "q.m13#10.o1" to "Porque un cúmulo que se convierte en cumulonimbo significa rayos, y una cresta es el lugar más expuesto de todos",
    "q.m13#10.o2" to "Porque la visibilidad es mala",
    "q.m13#10.o3" to "Porque el terreno es irregular",
    "q.m13#10.e" to "El paso de cúmulo a cumulonimbo a menudo solo tarda una o dos horas. Acampar en una cresta te sitúa en primera línea de la trayectoria de la tormenta, con todo el material y las tiendas, en un estado en el que una evacuación rápida es casi imposible.",
    "q.m13#11.p" to "Alguien acaba de recibir el impacto de un rayo. ¿Cuál es la primera prioridad?",
    "q.m13#11.o0" to "Revisar primero las lesiones externas",
    "q.m13#11.o1" to "Comprobar de inmediato la respiración y el pulso, iniciar la reanimación si hace falta y pedir ayuda médica cuanto antes",
    "q.m13#11.o2" to "Cambiarle primero la ropa mojada por ropa seca",
    "q.m13#11.o3" to "Trasladarle primero a un terreno más bajo",
    "q.m13#11.e" to "Un impacto puede provocar parada cardiaca y lesiones internas sin dejar ninguna señal visible. Por eso comprobar respiración y pulso va antes que cualquier otra cosa; e incluso un paciente consciente debe ser evacuado, porque el efecto de la corriente sobre el corazón puede aparecer más tarde.",
    "q.m13#12.p" to "[Opción múltiple] ¿Qué suele incluir la capacidad de autorrescate?",
    "q.m13#12.o0" to "Ascender con prusiks",
    "q.m13#12.o1" to "Autodetención y autoprotección",
    "q.m13#12.o2" to "Montar una reunión sin ayuda de un compañero",
    "q.m13#12.o3" to "Juzgar cuándo esperar en el sitio y cuándo salir por tus propios medios",
    "q.m13#12.o4" to "Escalar en libre sin protección",
    "q.m13#12.e" to "Las tres primeras son habilidades; la cuarta es criterio. Fíjate sobre todo en «juzgar cuándo esperar en el sitio y cuándo salir por tus propios medios»: no toda situación exige salir por tus propios medios; si estás lesionado o el tiempo empeora, quedarse a esperar rescate puede ser más seguro que moverse a la ligera.",
    "q.m13#13.p" to "¿Por qué «que me rescate mi compañero» no puede ser tu estrategia principal de seguridad?",
    "q.m13#13.o0" to "Porque los compañeros pueden no querer",
    "q.m13#13.o1" to "Porque el compañero puede estar él mismo en peligro, lesionado o sin poder moverse",
    "q.m13#13.o2" to "Porque no hay material de rescate suficiente",
    "q.m13#13.o3" to "Porque la normativa no lo permite",
    "q.m13#13.e" to "Encordarse sirve para protegerse mutuamente, pero no puedes dar por hecho que tu compañero tenga capacidad de reserva. En altitud, que un miembro del equipo cargue con los problemas de dos a menudo supera lo posible; por eso el autorrescate es un requisito y el rescate por el compañero es un extra.",
    // m14 — Juicio del peligro y toma de decisiones
    "q.m14#0.p" to "¿Qué pregunta intenta responder de verdad el juicio del peligro?",
    "q.m14#0.o0" to "¿Hay peligro?",
    "q.m14#0.o1" to "¿Este riesgo es aceptable y en base a qué?",
    "q.m14#0.o2" to "¿Qué magnitud tiene el peligro?",
    "q.m14#0.o3" to "¿Se asustarán mis compañeros?",
    "q.m14#0.e" to "«¿Hay peligro?» casi siempre se responde «sí»: ninguna actividad de montaña está libre de riesgo. La pregunta real es si ese riesgo merece la pena frente a lo que se gana y en qué lo basamos. Y justo por eso el juicio debe poder decirse en voz alta y someterse a discusión.",
    "q.m14#1.p" to "¿Qué es la «cadena de accidente»?",
    "q.m14#1.o0" to "El número de víctimas de un accidente",
    "q.m14#1.o1" to "Un proceso en el que varios errores pequeños se acumulan en secuencia hasta que se produce el accidente",
    "q.m14#1.o2" to "La cronología de un rescate",
    "q.m14#1.o3" to "Una cadena de fallos de material",
    "q.m14#1.e" to "Lo más valioso del concepto es que convierte el accidente de mala suerte en un proceso sobre el que se puede intervenir. Cambia una sola elección en cualquier eslabón y el resultado cambia.",
    "q.m14#2.p" to "¿Cuál es la forma más eficaz de romper la cadena de accidente?",
    "q.m14#2.o0" to "Tomar una decisión más conservadora en cualquier eslabón",
    "q.m14#2.o1" to "Centrarse solo en el último eslabón",
    "q.m14#2.o2" to "Llevar más material",
    "q.m14#2.o3" to "Mejorar la forma física del equipo",
    "q.m14#2.e" to "Sirve cualquier eslabón: salir antes, darse la vuelta a tiempo, no recortar la protección para ahorrar tiempo. Es también la razón de que el margen valga más que el remedio: el margen actúa pronto en la cadena y el remedio suele llegar al último eslabón.",
    "q.m14#3.p" to "[Opción múltiple] ¿Cuáles de estos son sesgos de decisión habituales?",
    "q.m14#3.o0" to "Coste irrecuperable",
    "q.m14#3.o1" to "Presión del grupo",
    "q.m14#3.o2" to "Fijación en el objetivo",
    "q.m14#3.o3" to "Normalización del riesgo",
    "q.m14#3.o4" to "Confianza en las marcas de material",
    "q.m14#3.e" to "Los cuatro actúan combinados: ya hemos invertido mucho (coste irrecuperable), todos los demás siguen subiendo (presión del grupo), ya casi estamos (fijación en el objetivo) y la última vez salió bien (normalización del riesgo). Cuando aparecen los cuatro a la vez, el juicio se inclina casi inevitablemente hacia asumir el riesgo.",
    "q.m14#4.p" to "¿Cómo influye el coste irrecuperable en las decisiones de montaña?",
    "q.m14#4.o0" to "Hace que la gente sea más prudente",
    "q.m14#4.o1" to "Habiendo invertido ya tanto tiempo y dinero, cuesta admitir que hay que renunciar",
    "q.m14#4.o2" to "Mejora la forma física",
    "q.m14#4.o3" to "No influye",
    "q.m14#4.e" to "Lo que define el coste irrecuperable es que no se puede recuperar, y sin embargo psicológicamente se convierte en una razón para seguir invirtiendo. En la montaña, unido a la fijación en el objetivo, transforma una retirada racional en «abandonar», y la gente tiene una resistencia natural a abandonar.",
    "q.m14#5.p" to "¿Qué es la «normalización del riesgo»?",
    "q.m14#5.o0" to "Mantener el peligro dentro de un rango aceptable",
    "q.m14#5.o1" to "Tras pasar varias veces una condición dada sin incidentes, reclasificarla inconscientemente como «segura»",
    "q.m14#5.o2" to "Aprender métodos de evaluación del riesgo",
    "q.m14#5.o3" to "Usar una escala de riesgo normalizada",
    "q.m14#5.e" to "La normalización del riesgo ocurre despacio, y por eso quien la sufre apenas la nota. El mismo escalador puede ser extremadamente cuidadoso la primera vez en una pendiente fuerte y ya no encordarse a la décima: la pendiente no ha cambiado, el juicio sí.",
    "q.m14#6.p" to "¿Por qué la regla de la mayoría es problemática en entornos de alto riesgo?",
    "q.m14#6.o0" to "Porque es ineficaz",
    "q.m14#6.o1" to "Porque la regla de la mayoría permite que se silencie una preocupación legítima de la minoría",
    "q.m14#6.o2" to "Porque votar no siempre es justo",
    "q.m14#6.o3" to "Porque los equipos tienen tamaños distintos",
    "q.m14#6.e" to "Las señales de peligro a menudo solo las perciben una o dos personas —alguien vio una grieta en la capa de nieve— y esa observación es información en manos de una minoría pero letal si es cierta. Decidir su suerte por votación ignora sistemáticamente las señales de baja probabilidad y alta consecuencia.",
    "q.m14#7.p" to "¿Por qué prevalece «la opinión más conservadora»?",
    "q.m14#7.o0" to "Porque la gente conservadora tiene más experiencia",
    "q.m14#7.o1" to "Porque ante la incertidumbre, el coste de equivocarse por lo conservador es mucho menor que el de equivocarse por lo arriesgado",
    "q.m14#7.o2" to "Porque la normativa lo exige",
    "q.m14#7.o3" to "Para que todos queden contentos",
    "q.m14#7.e" to "Es un caso de manual de coste asimétrico: ser conservador puede costar una salida perdida, ser arriesgado puede costar la vida. Cuando los costes son asimétricos, la decisión debe inclinarse hacia el lado cuyo coste es controlable; y esa inclinación hay que acordarla antes de salir, porque en el terreno es muy difícil de ejecutar.",
    "q.m14#8.p" to "[Emparejar] Relaciona cada sesgo de decisión con su expresión típica.",
    "q.m14#8.l0" to "Coste irrecuperable",
    "q.m14#8.r0" to "Hemos llegado hasta aquí; volver ahora sería un desperdicio",
    "q.m14#8.l1" to "Presión del grupo",
    "q.m14#8.r1" to "Todos quieren seguir; me daría vergüenza decir que deberíamos renunciar",
    "q.m14#8.l2" to "Fijación en el objetivo",
    "q.m14#8.r2" to "Es solo el último tramo",
    "q.m14#8.l3" to "Normalización del riesgo",
    "q.m14#8.r3" to "La última vez salió bien",
    "q.m14#8.e" to "Curiosamente, estas cuatro frases aparecen constantemente en los análisis de accidentes, y quienes las dicen suelen ser escaladores con experiencia. Eso es justamente lo importante: no son problemas de principiantes, son problemas de cómo está construida la cognición humana.",
    "q.m14#9.p" to "¿Por qué «más experiencia» no significa «juzga con más precisión»?",
    "q.m14#9.o0" to "Porque la experiencia te vuelve más lento",
    "q.m14#9.o1" to "Porque la experiencia eleva poco a poco tu tolerancia al riesgo",
    "q.m14#9.o2" to "Porque la experiencia no importa",
    "q.m14#9.o3" to "Porque los veteranos son más testarudos",
    "q.m14#9.e" to "La experiencia trae familiaridad, y la familiaridad embota la alerta. Por eso los equipos con experiencia necesitan más restricciones externas, no menos: horas límite de regreso fijas, umbrales meteorológicos cuantificados, reglas que contrarresten una intuición ya embotada.",
    "q.m14#10.p" to "[Ordenar] ¿Cuál es un proceso sólido para decidir una retirada?",
    "q.m14#10.o0" to "Revisar las señales objetivas acordadas antes de salir (hora, tiempo, estado del equipo)",
    "q.m14#10.o1" to "Verificar si las condiciones reales han activado alguna de ellas",
    "q.m14#10.o2" to "Que la persona designada de antemano decida la retirada",
    "q.m14#10.o3" to "Ejecutar la retirada y avisar a quienes esperan en casa",
    "q.m14#10.e" to "El valor del proceso es revisar primero el criterio y después la situación, no al revés. Invertir el orden hace que el criterio se vaya recortando al ritmo del ánimo en el terreno hasta quedar en «esperemos un poco más».",
    "q.m14#11.p" to "¿Por qué designar de antemano quién tiene autoridad para decidir la retirada?",
    "q.m14#11.o0" to "Para que sea más fácil repartir culpas",
    "q.m14#11.o1" to "Porque es muy difícil que alguien actúe por iniciativa propia contra el ánimo del grupo",
    "q.m14#11.o2" to "Para reforzar la autoridad del líder",
    "q.m14#11.o3" to "Para dejar constancia del proceso",
    "q.m14#11.e" to "Retirarse significa negar la expectativa de todo el equipo, y eso es muy difícil de iniciar dentro de un ambiente de grupo. Convierte «pedir la retirada» en un deber otorgado de antemano en lugar de un acto de valor personal: solo entonces ocurre de verdad.",
    "q.m14#12.p" to "¿Cuándo hay que plantearse terminar la salida?",
    "q.m14#12.o0" to "Nunca, mientras la cima siga siendo posible",
    "q.m14#12.o1" to "Cuando se ha activado cualquiera de las señales objetivas acordadas de antemano",
    "q.m14#12.o2" to "Solo cuando un miembro del equipo está lesionado",
    "q.m14#12.o3" to "Siempre que lo decida la persona menos en forma",
    "q.m14#12.e" to "Activada significa parar: ese es todo el sentido de los criterios cuantificados. Convierte la decisión de «¿deberíamos?» en «¿se ha activado?». La primera exige discutir y convencer; la segunda solo requiere verificar hechos, y por eso se puede ejecutar de verdad en el terreno.",
    "q.m14#13.p" to "¿Cuál es el antídoto más eficaz contra la fijación en el objetivo?",
    "q.m14#13.o0" to "La fuerza de voluntad personal",
    "q.m14#13.o1" to "Cuantificar los criterios antes de salir, de modo que «relajarlos» sea un acto explícito que haya que justificar ante los compañeros",
    "q.m14#13.o2" to "No fijarse ningún objetivo",
    "q.m14#13.o3" to "Llevar más material",
    "q.m14#13.e" to "Los sesgos psicológicos no se evitan recordándose a uno mismo que no debe caer en ellos. El método que funciona es hacer de «darse la vuelta cuando llegue la hora» la opción por defecto, de modo que quien quiera continuar deba dar razones activamente: se invierte la carga de la prueba de un solo golpe.",
    "q.m14#14.p" to "¿Por qué «nadie objetó» no equivale a «todos estaban de acuerdo»?",
    "q.m14#14.o0" to "Porque puede que no oyeran",
    "q.m14#14.o1" to "Porque el silencio puede significar solo no querer estropear el ambiente, con dudas reales sin decir",
    "q.m14#14.o2" to "Porque alguien estaba dormido",
    "q.m14#14.o3" to "Porque las objeciones fueron ignoradas",
    "q.m14#14.e" to "Por eso los buenos equipos fabrican disidencia a propósito: el líder pregunta abiertamente «¿quién cree que no deberíamos seguir?», o pasa uno por uno pidiendo a cada cual que fije posición. El silencio en la montaña no significa acuerdo: solo significa que no se dijo nada.",
    "q.m14#15.p" to "Completa: al decidir bajo incertidumbre, hay que adoptar primero la opinión más ( ).",
    "q.m14#15.a0" to "conservadora",
    "q.m14#15.e" to "«Primero lo conservador» es una regla que se puede ejecutar directamente en el terreno: no hay que juzgar qué argumento es más fuerte, solo qué opción es más conservadora. El precio es posiblemente una salida perdida, un precio que merece la pena pagar.",
    "q.m14#16.p" to "Situación: el tiempo empeora en un día de cima a 7.000 m",
    "q.m14#16.c" to "Es el día de cima a 7.000 m y habéis salido a las 3 de la madrugada. A las 8 llegáis a un punto a unas dos horas de la cima. El viento ha arreciado claramente, entran nubes desde el oeste y la temperatura baja. Un miembro del equipo ha empezado a toser de forma persistente y se está quedando visiblemente atrás.",
    "q.m14#16.e" to "El núcleo de esta situación no es ninguna respuesta aislada, sino la secuencia: verificar los hechos, identificar las señales de peligro, resistir la atracción psicológica y después ejecutar bien la retirada. Los dos pasos que más probablemente fallan son el primero (se omite) y el tercero (lo secuestra la emoción).",
    "q.m14#16.s0.p" to "Paso 1: ¿cuál es el primer juicio que hay que hacer ahora mismo?",
    "q.m14#16.s0.o0" to "Confirmar el estado del equipo y la tendencia del tiempo, y contrastarlos con las señales de regreso acordadas antes de salir",
    "q.m14#16.s0.o1" to "Acelerar y hacer cima antes de que empeore el tiempo",
    "q.m14#16.s0.o2" to "Esperar en el sitio a que mejore el tiempo",
    "q.m14#16.s0.o3" to "Bajar solo al miembro más lento",
    "q.m14#16.s0.e" to "Toda decisión debe empezar verificando hechos: cómo está el equipo, si el tiempo mejora o empeora, si se ha activado alguna señal prevista. Omite esto y deja que la emoción decida por ti.",
    "q.m14#16.s1.p" to "Paso 2: un miembro del equipo tiene tos persistente. ¿Cuál es la respuesta más razonable?",
    "q.m14#16.s1.o0" to "Es solo el aire frío que irrita las vías respiratorias: seguir caminando",
    "q.m14#16.s1.o1" to "En altitud esto exige alta sospecha de edema pulmonar: dejar de ascender y descender cuanto antes",
    "q.m14#16.s1.o2" to "Dar un jarabe para la tos y continuar",
    "q.m14#16.s1.o3" to "Dejar que descanse 10 minutos y luego continuar",
    "q.m14#16.s1.e" to "A 7.000 m, una tos persistente en reposo o con esfuerzo ligero es una señal que exige alta sospecha. A esta altitud, el coste de «observarlo un poco más» puede superar con creces el coste de descender de inmediato.",
    "q.m14#16.s2.p" to "Paso 3: estás a dos horas de la cima y decides darte la vuelta. ¿Cuál es la mayor resistencia psicológica?",
    "q.m14#16.s2.o0" to "Falta de forma física",
    "q.m14#16.s2.o1" to "El coste irrecuperable y la fijación en el objetivo: «hemos llegado hasta aquí»",
    "q.m14#16.s2.o2" to "Problemas de material",
    "q.m14#16.s2.o3" to "Desconocimiento de la ruta",
    "q.m14#16.s2.e" to "Exactamente por eso existen las horas límite de regreso: trasladan la decisión a un momento en el que todavía eres racional. Cuando aparece el «solo un poco más», lo que necesitas no es un juicio nuevo, sino contrastar con la regla acordada de antemano.",
    "q.m14#16.s3.p" to "Paso 4: ¿cómo hay que organizar al equipo durante el descenso?",
    "q.m14#16.s3.o0" to "Que los más en forma vayan por delante a preparar el campamento",
    "q.m14#16.s3.o1" to "Mantenerse juntos como equipo, que el más fuerte abra y marque el ritmo, y avisar a quienes esperan en casa del estado del grupo",
    "q.m14#16.s3.o2" to "Separarse para descender más rápido",
    "q.m14#16.s3.o3" to "Dejar que el más débil camine despacio solo",
    "q.m14#16.s3.e" to "En altitud, en cuanto un equipo se estira pierde la cobertura mutua, y el descenso es precisamente la fase de más accidentes. Ir agrupados, que alguien controle el ritmo y mantener informado al exterior: los tres son imprescindibles.",
    // m15 — Lectura de nubes y pronósticos profesionales
    "q.m15#0.p" to "¿Cuál es el valor esencial de leer las nubes?",
    "q.m15#0.o0" to "Hace que el alpinismo parezca más profesional",
    "q.m15#0.o1" to "Te da tiempo de antelación ante un cambio de tiempo",
    "q.m15#0.o2" to "Sustituye al pronóstico meteorológico",
    "q.m15#0.o3" to "Sirve para medir la altitud",
    "q.m15#0.e" to "Un pronóstico te avisa con un día de antelación, pero el tiempo en montaña cambia rápido a pequeña escala. Las nubes son el pronóstico justo encima de tu cabeza: la antelación puede ser de solo una o dos horas, y esa hora o dos es exactamente la ventana en la que decides si das media vuelta.",
    "q.m15#1.p" to "¿Qué indica el desarrollo vertical de los cúmulos?",
    "q.m15#1.o0" to "Tiempo estable",
    "q.m15#1.o1" to "Convección fuerte, que puede evolucionar a cumulonimbo",
    "q.m15#1.o2" to "Que va a refrescar de inmediato",
    "q.m15#1.o3" to "Que el viento en superficie amaina",
    "q.m15#1.e" to "El cúmulo en sí no es peligroso, pero es una señal que crece. Lo importante no es anotar que hay cúmulos, sino verlos crecer, elevarse y oscurecerse: ese proceso es la atmósfera acumulando energía.",
    "q.m15#2.p" to "¿Qué significa un yunque en un cumulonimbo?",
    "q.m15#2.o0" to "Que aún se está formando",
    "q.m15#2.o1" to "Que ha alcanzado la madurez: son posibles rayos, granizo y precipitación intensa",
    "q.m15#2.o2" to "Que está a punto de disiparse",
    "q.m15#2.o3" to "Que solo hay viento fuerte en altura",
    "q.m15#2.e" to "El yunque es la cúspide de la nube cizallada y aplanada por el viento en altura, lo que significa que la corriente ascendente ha llegado a la tropopausa y ya no puede subir más: es la firma de una tormenta en madurez. Cuando ves un yunque, tu tiempo de reacción ya es corto.",
    "q.m15#3.p" to "¿A qué hora del día se forman sobre todo los cúmulos?",
    "q.m15#3.o0" to "Al amanecer",
    "q.m15#3.o1" to "A media mañana",
    "q.m15#3.o2" to "Por la tarde",
    "q.m15#3.o3" to "De madrugada",
    "q.m15#3.e" to "La causa es el calentamiento solar: el suelo se calienta a lo largo del día y genera corrientes ascendentes y convección. Ese es el mecanismo físico que hay detrás de «sal temprano, baja a tiempo», no solo una máxima popular.",
    "q.m15#4.p" to "¿Qué indican normalmente las nubes lenticulares (en forma de seta o de disco)?",
    "q.m15#4.o0" to "Tiempo en calma",
    "q.m15#4.o1" to "Viento fuerte",
    "q.m15#4.o2" to "Lluvia inminente",
    "q.m15#4.o3" to "Subida de temperatura",
    "q.m15#4.e" to "Las lenticulares son nubes de onda estacionaria que se forman cuando el aire cruza una cresta; su sola existencia demuestra velocidades de viento altas en altura. En montaña eso significa que las crestas expuestas pueden recibir rachas muy fuertes, y las rachas son la causa directa de perder el equilibrio.",
    "q.m15#5.p" to "Los cirros (nubes altas y filamentosas) que aumentan de forma notable suelen indicar:",
    "q.m15#5.o0" to "Que se acerca un sistema meteorológico",
    "q.m15#5.o1" to "Que termina el episodio de frío",
    "q.m15#5.o2" to "Que el viento va a caer",
    "q.m15#5.o3" to "Que el UV se debilitará",
    "q.m15#5.e" to "Los cirros son a menudo el borde delantero de un sistema meteorológico: cuando aparecen, el tiempo aún no ha cambiado, pero el cambio está en camino. Esa antelación es valiosa, sobre todo para un itinerario que necesita regresar pronto.",
    "q.m15#6.p" to "El estrato que baja, con la base nubosa descendiendo claramente, ¿qué efecto tiene más directamente?",
    "q.m15#6.o0" to "Sube la temperatura",
    "q.m15#6.o1" to "La visibilidad se deteriora rápido y el juicio del terreno se vuelve difícil",
    "q.m15#6.o2" to "El viento amaina",
    "q.m15#6.o3" to "Cesa la precipitación",
    "q.m15#6.e" to "Un estrato que baja no trae lluvia, trae pérdida de visión; y perder visión es un riesgo en sí mismo: puede que ya estés fuera de ruta, que te acerques a una cornisa o que no encuentres el desvío de la retirada.",
    "q.m15#7.p" to "[Opción múltiple] ¿Qué cambios en las nubes indican que el tiempo empeora?",
    "q.m15#7.o0" to "La nubosidad aumenta rápido y la capa se espesa",
    "q.m15#7.o1" to "La base nubosa sigue bajando",
    "q.m15#7.o2" to "Las nubes se oscurecen con un desarrollo vertical evidente",
    "q.m15#7.o3" to "Aparece un yunque",
    "q.m15#7.o4" to "La nubosidad empieza a disminuir y el cielo despeja",
    "q.m15#7.e" to "Esas cuatro son etapas de un mismo proceso: aumenta la cobertura, baja la base, el cuerpo se oscurece y se eleva, aparece un yunque. Reconocerlas en orden convierte «el tiempo cambió» de un instante en un proceso del que puedes recibir aviso previo.",
    "q.m15#8.p" to "¿Por qué las nubes se desarrollan con más violencia en montaña que en llanura?",
    "q.m15#8.o0" to "Porque hay más altura y más frío",
    "q.m15#8.o1" to "Porque el terreno empuja el aire hacia arriba e intensifica la convección",
    "q.m15#8.o2" to "Porque el UV es más fuerte",
    "q.m15#8.o3" to "Porque el aire es más fino",
    "q.m15#8.e" to "El viento que choca con una montaña se ve forzado a subir como si lo empujaran por una rampa; el ascenso produce enfriamiento y condensación directamente, así que la nube se forma más rápido y de forma más local que sobre una llanura. Por eso el tiempo en montaña puede cambiar por completo en muy poco tiempo.",
    "q.m15#9.p" to "¿Cómo se distingue si una nube se está desarrollando o disipando?",
    "q.m15#9.o0" to "Por su color",
    "q.m15#9.o1" to "Observando de forma continua si su volumen, su altura y el contorno de sus bordes crecen y se endurecen",
    "q.m15#9.o2" to "Por la temperatura",
    "q.m15#9.o3" to "Por el espesor de la nieve",
    "q.m15#9.e" to "La clave es la observación continua: una mirada te da un estado, dos miradas te dan una tendencia. Una nube que se desarrolla gana volumen, su cima sube y sus bordes se afilan; una que se disipa hace lo contrario. Por eso levantar la vista a intervalos fijos cuesta casi nada y vale mucho.",
    "q.m15#10.p" to "[Emparejar] Relaciona cada tipo de nube con su significado meteorológico.",
    "q.m15#10.l0" to "Cumulonimbo (con yunque)",
    "q.m15#10.r0" to "Tormenta, granizo y precipitación intensa",
    "q.m15#10.l1" to "Nube lenticular",
    "q.m15#10.r1" to "Viento fuerte en altura, rachas violentas en las crestas",
    "q.m15#10.l2" to "Cirros",
    "q.m15#10.r2" to "Se acerca un sistema meteorológico",
    "q.m15#10.l3" to "Estrato bajo",
    "q.m15#10.r3" to "La visibilidad cae y el juicio del terreno se vuelve difícil",
    "q.m15#10.e" to "Estos cuatro cubren los cuatro tipos de información meteorológica que más se encuentran en montaña. Una advertencia: leer nubes requiere práctica con imágenes, y esta app hoy solo tiene preguntas de texto; la identificación de nubes con imágenes llegará cuando el sistema de imágenes esté listo.",
    "q.m15#11.p" to "¿Por qué hay que combinar la lectura de nubes con la tendencia de la presión?",
    "q.m15#11.o0" to "Por completitud de los datos",
    "q.m15#11.o1" to "Porque las nubes muestran el estado presente y la tendencia de la presión muestra la dirección del cambio",
    "q.m15#11.o2" to "Porque el barómetro es más preciso",
    "q.m15#11.o3" to "Para calcular la altitud",
    "q.m15#11.e" to "Son dimensiones distintas: las nubes dicen qué hay ahora, la presión dice hacia dónde va. Con las nubes solas es fácil malinterpretar «está empeorando» como «solo está nublado por ahora»; añade la tendencia y el cuadro se completa.",
    "q.m15#12.p" to "¿Qué causa principalmente la pérdida de contraste?",
    "q.m15#12.o0" to "Nevada excesiva",
    "q.m15#12.o1" to "Que nube, niebla y superficie de nieve tienen un color parecido, de modo que desaparece el límite entre suelo y cielo",
    "q.m15#12.o2" to "Temperatura extremadamente baja",
    "q.m15#12.o3" to "UV excesivo",
    "q.m15#12.e" to "La pérdida de contraste no es nieve intensa, es ausencia de contraste. Cuando nieve y nube tienen un brillo parecido, el horizonte desaparece y tu percepción de distancia y de pendiente falla por completo; de ahí que sea mucho más peligrosa que una nevada normal.",
    "q.m15#13.p" to "¿Por qué un pronóstico del tipo «chubascos aislados» es de utilidad limitada en montaña?",
    "q.m15#13.o0" to "Porque los pronósticos son inexactos",
    "q.m15#13.o1" to "Porque la escala de variación del tiempo en montaña es mucho menor que la malla del pronóstico, así que las condiciones en el terreno pueden ser completamente distintas",
    "q.m15#13.o2" to "Porque los escaladores no leen pronósticos",
    "q.m15#13.o3" to "Porque la precipitación no importa",
    "q.m15#13.e" to "La malla del pronóstico puede medir decenas de kilómetros, mientras que las dos vertientes de una misma cresta pueden tener tiempos completamente distintos. El pronóstico te da el riesgo de fondo; el juicio sobre el terreno decide si hoy puedes moverte. Ninguno sustituye al otro.",
    "q.m15#14.p" to "El pronóstico dice «soleado», pero ves cúmulos creciendo rápido en vertical. ¿A quién crees?",
    "q.m15#14.o0" to "Al pronóstico: seguir según lo previsto",
    "q.m15#14.o1" to "A tu propia observación: decidir suponiendo que puede empeorar",
    "q.m15#14.o2" to "Hacer la media de los dos",
    "q.m15#14.o3" to "Seguir observando otra hora",
    "q.m15#14.e" to "Un pronóstico es grueso tanto en antelación como en escala, mientras que la observación es aquí y ahora. Cuando entran en conflicto, gana la evidencia sobre el terreno; esa es la postura básica de todo el sistema de juicio meteorológico: el pronóstico pone el fondo, el terreno pone la acción.",
    "q.m15#15.p" to "Completa: tras ver un rayo, cada segundo contado equivale a unos ( ) kilómetros.",
    "q.m15#15.a0" to "0,34",
    "q.m15#15.a1" to "0.34",
    "q.m15#15.a2" to "cero coma tres cuatro",
    "q.m15#15.e" to "0,34 km por segundo es la velocidad del sonido en el aire. Esta conversión convierte contar segundos en una herramienta utilizable: sin ningún equipo puedes saber si la tormenta se acerca o se aleja.",
    "q.m15#16.p" to "[Opción múltiple] ¿En qué situaciones conviene plantearte seriamente descender de inmediato?",
    "q.m15#16.o0" to "Un cúmulo se ha convertido en cumulonimbo con yunque",
    "q.m15#16.o1" to "Un «whumpf» de colapso en el manto nivoso",
    "q.m15#16.o2" to "La visibilidad cae rápido y ya no puedes fijar tu posición",
    "q.m15#16.o3" to "Un miembro del equipo muestra síntomas de altura que empeoran progresivamente",
    "q.m15#16.o4" to "Un miembro del equipo dice que está algo cansado y quiere diez minutos de descanso",
    "q.m15#16.e" to "Estas cuatro vienen de cuatro dimensiones —tiempo, manto nivoso, navegación y fisiología— y lo que comparten es que todas son progresivas, lo que significa que el coste ahora es mucho menor que el coste dentro de diez minutos. Cuanto antes decidas descender, más barato sale.",
    "q.m15#17.p" to "Haz clic en la curva del gráfico que representa el nivel de congelación.",
    "q.m15#17.e" to "La curva del nivel de congelación es una de las informaciones más útiles de este pronóstico: marca la altitud en la que la precipitación pasa de lluvia a nieve. Una curva ascendente significa que llega aire más cálido y húmedo y que la precipitación pasará de nieve a lluvia; una curva descendente significa que hay aire frío y que el terreno alto pasará a nieve. Para juzgar si encontrarás nevada en tu altitud, vale más que leer las cifras de temperatura.",
    "q.m15#18.p" to "Este es el pronóstico de la misma montaña en la que la temporada terminó antes de tiempo. ¿Cuál es la nevada total, en centímetros, de los tres periodos del viernes 25 (AM / PM / noche)? Introduce la suma.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm. Casi 2,8 m de nieve en un solo día significa que la ruta queda completamente enterrada, que el peligro de alud sube de golpe y que los campamentos corren riesgo de ser aplastados. Con esa magnitud la pregunta ya no es si puedes hacer cima, sino si puedes evacuar con seguridad; es la forma típica en que un ciclón termina una temporada antes de tiempo.",
    "q.m15#19.p" to "Situación: leer un pronóstico de alta montaña",
    "q.m15#19.c" to "Un guía te pone delante dos pronósticos del Manaslu: uno de una ventana de ascensión normal y otro del registro de una temporada que terminó antes de tiempo. Entenderlos importa más que memorizar cualquier cifra.",
    "q.m15#19.e" to "El juicio meteorológico nunca se queda realmente en «qué tiempo hará mañana», sino en «podemos movernos en esta ventana». La misma interfaz, una diciendo continúa y otra diciendo para: la diferencia no está en leer el gráfico, sino en saber en qué condiciones hay que parar.",
    "q.m15#19.s0.p" to "Paso 1: en el pronóstico de la ventana normal, ¿qué representan los bloques rosas de la fila de altitud de cima (8.163 m)?",
    "q.m15#19.s0.o0" to "La nevada prevista para ese periodo",
    "q.m15#19.s0.o1" to "La lluvia de ese periodo",
    "q.m15#19.s0.o2" to "La temperatura de sensación de ese periodo",
    "q.m15#19.s0.o3" to "La velocidad del viento de ese periodo",
    "q.m15#19.s0.e" to "El rosa es nieve y el azul es lluvia; el pronóstico marca el tipo de precipitación por separado en cada altitud precisamente porque su pregunta central es si nevará o lloverá en tu altitud. En la fila superior los bloques son pequeños y dispersos, así que la cima recibe nieve ligera ocasional y sin gran magnitud.",
    "q.m15#19.s1.p" to "Paso 2: comparado con el pronóstico de fin de temporada, ¿cuál es el cambio más llamativo?",
    "q.m15#19.s1.o0" to "Solo baja la temperatura",
    "q.m15#19.s1.o1" to "La nevada y la velocidad del viento aumentan de golpe, y la precipitación cubre todas las franjas de altitud",
    "q.m15#19.s1.o2" to "La lluvia sustituye a la nieve",
    "q.m15#19.s1.o3" to "El nivel de congelación sube mucho",
    "q.m15#19.s1.e" to "La nevada pasa de 1–4 cm dispersos a 280 cm en un día, el viento de 25–30 km/h a 55–60 km/h, y la banda de precipitación atraviesa todos los niveles desde 8.163 m hasta 1.500 m. Las tres cosas a la vez son la firma de un sistema meteorológico que pasa justo por encima de ti.",
    "q.m15#19.s2.p" to "Paso 3: si tu equipo estuviera dentro de una ventana de pronóstico así, ¿cuál es la decisión correcta?",
    "q.m15#19.s2.o0" to "Acelerar el ataque a cima antes de que el tiempo empeore del todo",
    "q.m15#19.s2.o1" to "Detener de inmediato el intento de cima, descender según el plan y prepararse para evacuar",
    "q.m15#19.s2.o2" to "Esperar en el campo alto a que mejore el tiempo",
    "q.m15#19.s2.o3" to "Dividirse en dos grupos: uno ataca la cima y otro se queda",
    "q.m15#19.s2.e" to "Cuando un pronóstico muestra un sistema que pasa justo por encima y no una fluctuación breve, «esperar a que pase» suele significar varios días más expuesto en altitud, algo que ni las provisiones ni las tiendas pueden sostener. Por eso muchas temporadas no terminan con «lo conseguimos» sino con «tuvimos que salir»; y la información necesaria para tomar esa decisión es exactamente la que dan estos dos gráficos.",
    "q.m15#20.p" to "Situación: leer un pronóstico horario",
    "q.m15#20.c" to "Este es un pronóstico horario de un día en el Gongga Shan (7.556 m). Su densidad de información es mucho mayor que la de un resumen de 16 días, pero también es más fácil leer la fila equivocada; la clave es saber qué dice realmente cada fila.",
    "q.m15#20.e" to "Un pronóstico horario responde lo que un resumen no puede: qué periodo concreto es aprovechable. El nivel de congelación fija el tipo de precipitación, la temperatura de sensación fija si una persona puede aguantar, y la velocidad del viento y el sol fijan cuán ancha es la ventana. Solo leídos juntos dan una decisión ejecutable.",
    "q.m15#20.s0.p" to "Paso 1: la fila Freeze muestra el nivel de congelación entre 4.895 y 5.304 m, mientras que la cima del Gongga está a 7.556 m. ¿Qué significa esa combinación?",
    "q.m15#20.s0.o0" to "Toda la precipitación en la montaña cae en forma de nieve",
    "q.m15#20.s0.o1" to "Habrá lluvia en la cima",
    "q.m15#20.s0.o2" to "También nevará por debajo del nivel de congelación",
    "q.m15#20.s0.o3" to "No se puede juzgar el tipo de precipitación con esto",
    "q.m15#20.s0.e" to "El nivel de congelación es la línea lluvia/nieve. Se mantiene estable en 4.900–5.300 m mientras todas las rutas de ascensión quedan por encima. Es decir, toda la ruta está por encima del nivel de congelación, así que cualquier precipitación llega en forma de nieve. Una sola cifra responde «qué forma de precipitación voy a encontrar», y por eso el nivel de congelación es más útil que un dato de temperatura.",
    "q.m15#20.s1.p" to "Paso 2: la fila Feels °C muestra −18 a −21, mientras que Max / Min °C es solo −10 a −11. ¿Qué explica principalmente esa diferencia?",
    "q.m15#20.s1.o0" to "Un error del pronóstico",
    "q.m15#20.s1.o1" to "El enfriamiento por viento: cuanto más fuerte el viento, más baja la temperatura sentida",
    "q.m15#20.s1.o2" to "La diferencia de temperatura causada por la altitud",
    "q.m15#20.s1.o3" to "El efecto del cambio de humedad",
    "q.m15#20.s1.e" to "La velocidad del viento en ese mismo periodo es de 20–30 km/h. El viento sobre la piel desnuda acelera la pérdida de calor, así que la temperatura de sensación queda casi 10 °C por debajo de la temperatura real del aire. En altitud, si puedes permanecer fuera lo decide la temperatura de sensación, no la del aire. Los mismos −10 °C son algo completamente distinto con viento y sin viento.",
    "q.m15#20.s2.p" to "Paso 3: con este pronóstico (viento 20–30 km/h, nevada dispersa 2/1/1 cm, sensación en torno a −20 °C, luz de 6:56 a 19:15), ¿cuál es tu juicio sobre la ventana?",
    "q.m15#20.s2.o0" to "Las condiciones son severas: abandonar cualquier movimiento",
    "q.m15#20.s2.o1" to "Es una ventana comparativamente aprovechable; el reto principal es el frío y el enfriamiento por viento, no la precipitación",
    "q.m15#20.s2.o2" to "Demasiada precipitación: hay riesgo de alud",
    "q.m15#20.s2.o3" to "No hay datos suficientes para juzgar",
    "q.m15#20.s2.e" to "Un viento de 20–30 km/h sigue dentro del rango aprovechable, y la nevada es de solo unos centímetros. La presión real viene de una temperatura de sensación en torno a −20 °C, así que de lo que hay que protegerse es de congelaciones e hipotermia. La lógica de este tipo de ventana: precipitación y viento están bien, el problema es la temperatura y la duración. Así que acorta la exposición, refuerza el aislamiento de las extremidades y adelanta la hora límite de regreso.",
    "q.m15#21.p" to "En ese mismo pronóstico del Gongga la temperatura real del aire es de unos −11 °C y la sensación mínima de −21 °C. ¿Cuál es la diferencia en grados Celsius?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C: −11 − (−21) = 10. Esa diferencia es en sí misma información para decidir: vístete para la temperatura de sensación, no para la del aire. También explica cómo hay gente que se congela a −10 °C: se vistió para el número del gráfico.",
    "q.m15#22.p" to "Este pronóstico muestra la velocidad del viento con círculos verdes. ¿Qué significa lo más probable?",
    "q.m15#22.o0" to "Que la velocidad del viento de ese periodo está dentro del rango adecuado para escalar",
    "q.m15#22.o1" to "Que la velocidad del viento de ese periodo ha alcanzado un nivel peligroso",
    "q.m15#22.o2" to "Que hay lluvia en ese periodo",
    "q.m15#22.o3" to "Que faltan datos de viento para ese periodo",
    "q.m15#22.e" to "Los servicios profesionales de meteorología de montaña suelen codificar por colores la velocidad del viento según su efecto sobre el movimiento. 20–30 km/h en verde significa que cae en la franja de «se puede avanzar»; por encima, el color pasa a amarillo o rojo.\nPero el color es la sugerencia del proveedor, no tu criterio. Rutas distintas y equipos distintos toleran el mismo viento de forma distinta. Leer el número importa más que leer el color.",
    "q.m15#23.p" to "Esta interfaz profesional muestra temperaturas para 8000 / 6000 / 4000 / 2000 m en cuatro filas paralelas. ¿Cuál es el valor principal de ese diseño?",
    "q.m15#23.o0" to "Puedes leer directamente el pronóstico de tu propia altitud, sin extrapolar desde datos de llanura",
    "q.m15#23.o1" to "Hace que la página parezca más rica",
    "q.m15#23.o2" to "Demuestra que las cuatro filas no tienen relación",
    "q.m15#23.o3" to "Solo para facilitar la impresión en papel",
    "q.m15#23.e" to "Un pronóstico corriente da datos de un solo lugar, normalmente la ciudad o el aeropuerto más cercano. Hay que extrapolar montaña arriba con un gradiente térmico: un paso fácil de equivocar y que además tira el detalle del terreno.\nUn servicio profesional de montaña hace lo contrario: primero corta la montaña por altitudes y luego pronostica cada franja. Solo tienes que buscar la fila de la altitud a la que estarás mañana y leerla. También es una prueba sencilla de si un servicio meteorológico es adecuado: ¿corta por altitudes?",
    "q.m15#24.p" to "En el gráfico, la fila «Cloud base (m)» muestra un guion (—) en la mayoría de los periodos. ¿Cuál es la lectura correcta?",
    "q.m15#24.o0" to "La base nubosa es cero en ese periodo, es decir, la nube está en el suelo",
    "q.m15#24.o1" to "No se dan datos de base nubosa para ese periodo; no debe interpretarse como «base nubosa = 0»",
    "q.m15#24.o2" to "Significa que no hay ninguna nube en ese periodo",
    "q.m15#24.o3" to "Significa que la base nubosa está por encima de la cima",
    "q.m15#24.e" to "En una tabla meteorológica, «en blanco» y «cero» son dos cosas completamente distintas. En blanco significa que no hay datos de ese elemento en ese periodo: puede que no esté cubierto o que no se pueda dar una estimación con sentido. No significa que el valor sea cero.\nTomar un blanco por cero lleva a conclusiones como «nube en el suelo, visibilidad terrible» que no tienen nada que ver con los hechos. Con cualquier tabla meteorológica, separa primero las dos cosas. Es el error más fácil de cometer al leer un pronóstico y el que menos se señala.",
    "q.m15#25.p" to "En la fila de viento de esta interfaz, las cifras van acompañadas de flechas. ¿Qué muestran lo más probable?",
    "q.m15#25.o0" to "La tendencia de la velocidad del viento",
    "q.m15#25.o1" to "La dirección del viento",
    "q.m15#25.o2" to "La probabilidad de precipitación",
    "q.m15#25.o3" to "Si la temperatura sube o baja",
    "q.m15#25.e" to "Velocidad y dirección deben leerse juntas en altitud. Los mismos 30 km/h se sienten completamente distintos en la cara de barlovento y en la de sotavento, y también afectan de forma distinta al manto nivoso: el viento transporta nieve a las laderas de sotavento y la acumula en placas. Es una de las informaciones más importantes para juzgar el peligro de alud.\nLeer solo el número y no la dirección es tirar la mitad de la información. Las interfaces profesionales ponen la flecha junto al número precisamente porque los dos no se pueden leer por separado.",
    "q.m15#26.p" to "En este gráfico de pronóstico de 16 días, los marcadores rojos (Snow) se agrupan en torno a la franja de 6.000 m, mientras que los azules (Rain) aparecen por debajo de 5.000 m. ¿Qué indica?",
    "q.m15#26.o0" to "Que la línea lluvia/nieve está aproximadamente entre 5.500 y 6.000 m",
    "q.m15#26.o1" to "Que en la montaña solo cae nieve, nunca lluvia",
    "q.m15#26.o2" to "Que la lluvia continúa hasta la cima",
    "q.m15#26.o3" to "Que no se puede juzgar con este gráfico",
    "q.m15#26.e" to "Este gráfico no te dice qué cae dónde en una hora dada; responde directamente en qué franja de altitud aterriza la precipitación. Para un escalador esa es exactamente la información que importa.\nRojo en la franja de 6.000 m y azul solo por debajo de 5.000 m sitúan la línea lluvia/nieve aproximadamente entre 5.500 y 6.000 m. Combinado con la curva violeta del nivel de congelación de la leyenda (que baja de unos 6.000 m a unos 4.800 m), también se ve que la línea seguirá descendiendo a lo largo del periodo: las franjas que ahora reciben lluvia irán pasando a nieve.\nLa misma cantidad de precipitación tiene un efecto completamente distinto en una salida según caiga en forma de lluvia o de nieve.",
    "q.m15#27.p" to "En el pronóstico horario del mismo gráfico aparece un icono de rayo a las 5 de la tarde. ¿Qué señala eso en altitud?",
    "q.m15#27.o0" to "Es solo un icono: no requiere un tratamiento especial",
    "q.m15#27.o1" to "Riesgo de tormenta: programar el movimiento para la mañana y abandonar crestas y terreno expuesto por la tarde",
    "q.m15#27.o2" to "Viene lluvia fuerte: basta con llevar una chaqueta impermeable",
    "q.m15#27.o3" to "La velocidad del viento subirá a un nivel peligroso",
    "q.m15#27.e" to "Las tormentas de tarde son frecuentes en altitud y realmente peligrosas. El relieve obliga a subir el aire y los cúmulos crecen rápido por la tarde. Así que «sal temprano» no solo tiene que ver con la nieve más dura: también con abandonar el terreno expuesto antes de que se formen las tormentas.\nPuntos clave en una tormenta: mantenerse lejos de cimas, crestas, árboles aislados y agua; no tumbarse plano en el suelo; separar al equipo unos 50 m para que un rayo no hiera a varias personas. La distancia del rayo se estima en kilómetros como segundos entre destello y trueno × 0,34.",
    "q.m15#28.p" to "Sobre si una fuente de datos de terreno tiene marcador de cima, ¿cuál es el equilibrio correcto?",
    "q.m15#28.o0" to "Un marcador siempre significa mayor precisión: fiarse solo de los mapas que lo tienen",
    "q.m15#28.o1" to "Los marcadores son útiles para situarse y comunicarse rápido, pero el juicio preciso del terreno sigue requiriendo curvas de nivel",
    "q.m15#28.o2" to "Un mapa sin marcadores es inútil",
    "q.m15#28.o3" to "Los marcadores solo estorban al leer: ignorarlos",
    "q.m15#28.e" to "En este mapa de Google del Muztagh Ata la cima está marcada directamente con un alfiler rojo. Eso es muy útil para orientarse y comunicarse: sabes al instante dónde está el objetivo y puedes decirle a un compañero exactamente a qué punto te refieres.\nPero un marcador no responde cuán inclinada es esta ladera ni dónde puede ir un campamento. El juicio preciso del terreno sigue dependiendo de las curvas de nivel, y el marcador no interviene en él.\nEl enfoque práctico: usa el marcador para localizar rápido y luego usa curvas de nivel de alta resolución (la versión SRTM, por ejemplo) para leer el ángulo de pendiente y el detalle del terreno. Cada cosa hace su trabajo.",
    // m16 — Nieve y aludes avanzados, terreno y mapas
    "q.m16#0.p" to "¿Qué tres escalas debe combinar el juicio avanzado de aludes?",
    "q.m16#0.o0" to "Temperatura, velocidad del viento y precipitación",
    "q.m16#0.o1" to "Pronóstico regional, terreno y manto nivoso",
    "q.m16#0.o2" to "Altitud, ángulo de pendiente y sol",
    "q.m16#0.o3" to "Tamaño del equipo, material y tiempo",
    "q.m16#0.e" to "Las tres responden a preguntas distintas: el pronóstico dice cuán peligroso es el día en conjunto, el terreno dice si esta ladera puede retener nieve y deslizar, el manto nivoso dice si está inestable ahora mismo. Con solo el pronóstico estás juzgando la ladera que pisas con una media regional.",
    "q.m16#1.p" to "¿En qué nivel de peligro de alud se producen más accidentes?",
    "q.m16#1.o0" to "1 (Débil)",
    "q.m16#1.o1" to "3 (Notable)",
    "q.m16#1.o2" to "5 (Extremo)",
    "q.m16#1.o3" to "No hay diferencias",
    "q.m16#1.e" to "Con nivel 5 la gente se queda fuera, así que en realidad hay menos accidentes; con nivel 3 el terreno «parece transitable», así que mucha gente entra en terreno de aludes. La condición más peligrosa nunca es la extrema, sino la moderada que se subestima.",
    "q.m16#2.p" to "¿En qué rango de pendiente se produce la mayoría de los aludes?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "No hay un patrón",
    "q.m16#2.e" to "Alrededor del 96 % de los aludes se producen entre 30° y 50°, y la mayoría se concentra entre 34° y 45°. Ese es justamente el rango por el que pasan más a menudo las rutas de ascensión: bastante inclinado para deslizar, bastante suave para retener nieve.",
    "q.m16#3.p" to "[Opción múltiple] ¿Qué prácticas son correctas al cruzar terreno de aludes?",
    "q.m16#3.o0" to "Mantener distancia y cruzar de uno en uno",
    "q.m16#3.o1" to "Colocar un vigía en una posición segura",
    "q.m16#3.o2" to "Planificar la vía de escape de antemano",
    "q.m16#3.o3" to "Cruzar todo el equipo junto y rápido para reducir la exposición",
    "q.m16#3.e" to "Las dos primeras limitan el riesgo a una persona; la tercera garantiza una salida si algo pasa. «Todos a la vez» hace lo contrario: convierte el riesgo de sepultar quizá a uno en sepultar quizá a todo el equipo, y por eso es la peor opción.",
    "q.m16#4.p" to "¿Dónde debe situarse el vigía?",
    "q.m16#4.o0" to "En la misma ladera que se cruza",
    "q.m16#4.o1" to "En un lugar desde el que vea claramente a quien cruza y esté él mismo a salvo",
    "q.m16#4.o2" to "En lo más alto de la ladera",
    "q.m16#4.o3" to "En el fondo del valle",
    "q.m16#4.e" to "El vigía tiene dos funciones: no perder de vista a la persona (para saber dónde ha quedado sepultada) y actuar de inmediato si algo pasa. Situarse en la ladera o en el fondo del valle lo convierte en la segunda víctima; la seguridad del propio vigía es condición previa para hacer su trabajo.",
    "q.m16#5.p" to "¿Para qué sirve cavar una calicata de nieve?",
    "q.m16#5.o0" to "Para descansar",
    "q.m16#5.o1" to "Para ver directamente la estructura de capas, la posición de la capa débil y las diferencias de dureza",
    "q.m16#5.o2" to "Para medir la temperatura",
    "q.m16#5.o3" to "Para hacer fotografías",
    "q.m16#5.e" to "Un alud necesita una capa débil y una placa encima, y esa estructura solo se ve cuando la cortas. Una calicata convierte una estructura interna invisible en evidencia visible: el paso clave de inferir el riesgo a observarlo.",
    "q.m16#6.p" to "¿Por qué es peligroso «seguir las huellas de los que van delante»?",
    "q.m16#6.o0" to "Porque las huellas no se ven bien",
    "q.m16#6.o1" to "Porque las huellas pueden tener horas y el manto nivoso ha cambiado hace rato",
    "q.m16#6.o2" to "Porque puedes equivocarte de ruta",
    "q.m16#6.o3" to "Porque las huellas estorban al caminar",
    "q.m16#6.e" to "El estado del manto nivoso cambia continuamente con la temperatura, el viento y la nevada: unas horas bastan para pasar de «apenas estable» a «a punto de dispararse». Las huellas solo demuestran que alguien pasó entonces; no dicen nada sobre si es seguro ahora.",
    "q.m16#7.p" to "¿Cómo influye el transporte eólico en el peligro de alud?",
    "q.m16#7.o0" to "El viento aplana la nieve y reduce el riesgo",
    "q.m16#7.o1" to "El viento transporta nieve a las laderas de sotavento, forma placas adicionales y capas débiles que disparan el riesgo",
    "q.m16#7.o2" to "El viento no tiene nada que ver con los aludes",
    "q.m16#7.o3" to "El viento solo afecta a la visibilidad",
    "q.m16#7.e" to "El viento es el generador de aludes más subestimado: en poco tiempo puede mover mucha nieve a las laderas de sotavento, construir placas gruesas y crear capas débiles dentro de ellas. Por eso, incluso sin nevada, puede aparecer peligro nuevo de alud tras un viento fuerte.",
    "q.m16#8.p" to "¿Cuál es el peligro principal de una cornisa de nieve?",
    "q.m16#8.o0" to "Estorba la vista",
    "q.m16#8.o1" to "Puede colapsar en cualquier momento por sí sola, y su colapso puede desencadenar un alud en la ladera de debajo",
    "q.m16#8.o2" to "Su color es distinto al de la superficie de la nieve",
    "q.m16#8.o3" to "Bloquea la ruta",
    "q.m16#8.e" to "Una cornisa es peligrosa por partida doble: si te pones encima puedes caer con ella, y si pasas por debajo puede venirse encima con mucha nieve. Lo habitual es rodearla por el lado opuesto al borde de la cornisa y no descansar nunca sobre ella.",
    "q.m16#9.p" to "[Ordenar] ¿Cuál es el procedimiento completo para cruzar terreno de aludes?",
    "q.m16#9.o0" to "Consultar el pronóstico de aludes del día antes de salir y marcar las laderas a evitar",
    "q.m16#9.o1" to "Observar señales de campo en la aproximación (grietas, ruidos de colapso, superficies cargadas por el viento)",
    "q.m16#9.o2" to "Asignar el vigía, el orden de cruce y la vía de escape",
    "q.m16#9.o3" to "Cruzar de uno en uno, manteniendo distancia, y reagruparse en un punto seguro",
    "q.m16#9.e" to "Los tres primeros pasos ocurren antes de entrar: ahí es donde está realmente el trabajo de seguridad frente a aludes. Cuando ya estás en la ladera quedan muy pocas opciones, y la mayoría de los accidentes se remontan a haberse saltado los dos primeros pasos.",
    "q.m16#10.p" to "¿Por qué el rescate de alud deben hacerlo de inmediato los compañeros?",
    "q.m16#10.o0" to "Porque el rescate profesional es caro",
    "q.m16#10.o1" to "Porque la ventana de supervivencia de una persona sepultada es de solo unos quince minutos",
    "q.m16#10.o2" to "Porque los equipos profesionales no suben",
    "q.m16#10.o3" to "Porque los compañeros conocen mejor el terreno",
    "q.m16#10.e" to "Una ventana de quince minutos significa que las únicas personas que pueden salvarte son las que están a tu lado. Por eso el trío de aludes hay que llevarlo y hay que practicarlo: llevar material que no sabes usar es lo mismo que no llevar nada.",
    "q.m16#11.p" to "[Emparejar] Relaciona cada nivel de peligro de alud con su significado.",
    "q.m16#11.l0" to "Nivel 1",
    "q.m16#11.r0" to "Débil: poco probable el desencadenamiento natural y humano",
    "q.m16#11.l1" to "Nivel 3",
    "q.m16#11.r1" to "Notable: posible el desencadenamiento humano, y el más fácil de subestimar",
    "q.m16#11.l2" to "Nivel 4",
    "q.m16#11.r2" to "Fuerte: probable el desencadenamiento natural; evitar el terreno de aludes",
    "q.m16#11.l3" to "Nivel 5",
    "q.m16#11.r3" to "Extremo: muy probables aludes naturales generalizados",
    "q.m16#11.e" to "Detrás de cada número hay una combinación de probabilidad de desencadenamiento y tamaño de las consecuencias. El error clásico del principiante es tratar el nivel 3 como «está bien», y es justamente el nivel donde se concentran los accidentes.",
    "q.m16#12.p" to "¿Cuál es la función y los límites de un airbag de alud?",
    "q.m16#12.o0" to "Evita por completo el sepultamiento; no tiene límites",
    "q.m16#12.o1" to "Mejora la probabilidad de quedar más cerca de la superficie, pero no sustituye a ARVA, sonda y pala ni evita los traumatismos",
    "q.m16#12.o2" to "Solo sirve en estaciones de esquí",
    "q.m16#12.o3" to "Pide ayuda automáticamente",
    "q.m16#12.e" to "El principio es más volumen, más probabilidad de quedar cerca de la superficie: mejora las probabilidades de supervivencia, no las garantiza. Y una parte importante de las muertes por alud se debe a traumatismos y no a asfixia, y por eso un airbag nunca puede ser tu única dependencia.",
    "q.m16#13.p" to "¿Por qué las laderas que «no parecen tan inclinadas» son a menudo las más peligrosas?",
    "q.m16#13.o0" to "Porque la nieve es más profunda",
    "q.m16#13.o1" to "Porque entre 34° y 45° es donde se concentran los aludes, y el ojo humano subestima el ángulo de pendiente",
    "q.m16#13.o2" to "Porque va poca gente",
    "q.m16#13.o3" to "Porque el ángulo cambia rápido",
    "q.m16#13.e" to "Sin referencia, la gente estima el ángulo de pendiente con un error grande y a menudo lee 35° donde hay 25°. Y 30°–35° es justamente la franja que «parece transitable pero puede deslizar». Un inclinómetro y un mapa de curvas de nivel son el remedio para ese sesgo.",
    "q.m16#14.p" to "[Opción múltiple] ¿Qué debe completar el equipo antes de entrar en terreno de aludes?",
    "q.m16#14.o0" to "Confirmar que todos saben usar ARVA, sonda y pala",
    "q.m16#14.o1" to "Acordar el orden de cruce y el vigía",
    "q.m16#14.o2" to "Acordar un punto de reunión y una vía de escape",
    "q.m16#14.o3" to "Comprobar que los ARVA están emitiendo",
    "q.m16#14.o4" to "Pisotear fuerte y repetidamente para probar la estabilidad del manto",
    "q.m16#14.e" to "Las cuatro primeras son comprobaciones finales antes de entrar y solo cuestan minutos. Importan porque, una vez en la ladera, tu única opción que queda es esperar que no ocurra.",
    "q.m16#15.p" to "El manto nivoso emite un «whumpf» de colapso. ¿Cuál es la respuesta correcta?",
    "q.m16#15.o0" to "Seguir: es solo la nieve asentándose",
    "q.m16#15.o1" to "Detenerse de inmediato y reevaluar: una capa débil ha empezado a fallar",
    "q.m16#15.o2" to "Cruzar más rápido",
    "q.m16#15.o3" to "Descansar diez minutos en el sitio",
    "q.m16#15.e" to "Un whumpf es evidencia directa de que una capa débil está colapsando: significa que una carga muy ligera acaba de provocar un fallo local. Continuar es en la práctica preguntar si un poco más hará caer todo.",
    "q.m16#16.p" to "Completa: alrededor del 96 % de los aludes se producen en pendientes de 30°–50°, y la mayoría se concentra entre 34° y ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "cuarenta y cinco",
    "q.m16#16.e" to "34°–45°. Merece la pena recordar el rango porque es a la vez el punto caliente de los aludes y el gradiente que más a menudo cruzan las rutas de ascensión: es la superposición de esos dos hechos lo que convierte el alud en uno de los peligros objetivos dominantes del alpinismo.",
    "q.m16#17.p" to "Situación: cruzar un tramo de terreno de aludes",
    "q.m16#17.c" to "La ruta debe cruzar una ladera de nieve de unos 35° y unos 200 m de longitud. El pronóstico de aludes de hoy es Notable (nivel 3), con 30 cm de nieve reciente, viento del noroeste y la ladera orientada al sureste.",
    "q.m16#17.e" to "Esta situación prueba todo el flujo de trabajo frente a aludes: leer terreno y manto nivoso, completar la preparación antes de entrar y después usar la formación para controlar las consecuencias. Ningún paso aislado es difícil; lo difícil es ejecutarlos todos delante de una ladera que parece transitable.",
    "q.m16#17.s0.p" to "Paso 1: ¿qué merece más precaución en esta ladera?",
    "q.m16#17.s0.o0" to "La caída de piedras",
    "q.m16#17.s0.o1" to "Las placas cargadas por el viento y el propio ángulo de la pendiente",
    "q.m16#17.s0.o2" to "La temperatura alta",
    "q.m16#17.s0.o3" to "La vegetación del suelo",
    "q.m16#17.s0.e" to "35° cae de lleno en el punto caliente 34°–45°; el viento del noroeste transporta nieve a la ladera de sotavento (aquí la cara sureste) y forma placa adicional. Dos factores que se suman son la combinación clásica de «parece transitable, puede deslizar».",
    "q.m16#17.s1.p" to "Paso 2: al aproximarse a la ladera, ¿qué hay que hacer primero?",
    "q.m16#17.s1.o0" to "Empezar a cruzar de inmediato",
    "q.m16#17.s1.o1" to "Observar primero las señales de campo y después fijar el vigía, el orden de cruce y la vía de escape",
    "q.m16#17.s1.o2" to "Pisotear fuerte la ladera para probarla",
    "q.m16#17.s1.o3" to "Cruzar todo el equipo rápido",
    "q.m16#17.s1.e" to "Toda la preparación va antes de entrar. Pisotear fuerte no verifica la estabilidad: puede disparar directamente un manto que ya está cerca de su punto crítico.",
    "q.m16#17.s2.p" to "Paso 3: ¿cómo debe organizarse el equipo durante el cruce?",
    "q.m16#17.s2.o0" to "De uno en uno, con los demás esperando en un punto seguro",
    "q.m16#17.s2.o1" to "Todos de la mano juntos",
    "q.m16#17.s2.o2" to "De dos en dos para vigilarse mutuamente",
    "q.m16#17.s2.o3" to "En fila, muy juntos",
    "q.m16#17.s2.e" to "De uno en uno se limita el riesgo a una persona y el vigía puede concentrarse en observar a una sola. Exponer al equipo entero a la vez amplifica la consecuencia de sepultar quizá a uno a sepultar quizá a todos.",
    "q.m16#18.p" to "Haz clic en la zona aproximada de la cima del Manaslu en el mapa.",
    "q.m16#18.e" to "Una cima en un mapa de curvas de nivel es inconfundible: las curvas cerradas se aprietan hacia dentro anillo tras anillo mientras las etiquetas suben (7600 → 7750 → 7900 → 7950…). Encuentra el punto encerrado por anillos de curvas cerradas pequeñas y tendrás el terreno más alto.\nAl contrario, donde las curvas se abren hacia fuera y las etiquetas bajan, aquello es cuesta abajo; lo cual, de paso, te dice por qué lado discurre la ruta.",
    "q.m16#19.p" to "En ese mismo mapa las curvas del lado noreste a este están extremadamente juntas. ¿Qué indica?",
    "q.m16#19.o0" to "Que ese lado es muy inclinado y es un punto caliente de caída de seracs y de piedras",
    "q.m16#19.o1" to "Que ese lado es suave y bueno para acampar",
    "q.m16#19.o2" to "Que ese lado es más bajo y por tanto menos arriesgado",
    "q.m16#19.o3" to "Que curvas juntas significan que el terreno allí es llano",
    "q.m16#19.e" to "Cuanto más juntas las curvas, mayor el cambio de elevación en la misma distancia horizontal, es decir, más inclinada la ladera. En este mapa el lado noreste baja de 7.950 m a 5.750 m con docenas de curvas comprimidas en una corta distancia horizontal: una cara empinada clásica.\nAl planificar una ruta, esta habilidad de lectura influye directamente en dos cosas: si pasas por zonas de caída de seracs y piedras, y si existe terreno de retirada utilizable si algo va mal. Las zonas más suaves y con curvas espaciadas son donde es más probable que quepa un campamento.",
    "q.m16#20.p" to "Situación: comparar dos fuentes de datos de terreno",
    "q.m16#20.c" to "Un guía te da dos mapas del terreno de la misma montaña: uno de Google Maps y otro generado a partir de datos de elevación SRTM de la NASA. Ninguno es erróneo, pero no son igual de capaces de responder a tus preguntas.",
    "q.m16#20.e" to "La diferencia esencial entre conjuntos de datos de terreno no es la exactitud, sino el intervalo de curvas, porque el intervalo fija cuán fino se ve un cambio de pendiente. La intuición tiene valor —construye rápido una impresión de conjunto— pero decidir si un tramo concreto es inclinado o transitable vuelve siempre a la densidad de curvas, que se puede cuantificar y comparar.",
    "q.m16#20.s0.p" to "Paso 1: en este mapa de Google las etiquetas de curvas marcan 6200, 6400, 6600, 6800… ¿Cuál es el intervalo de curvas?",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "Las etiquetas contiguas difieren en 200 m, así que este sistema sube 200 m entre líneas. Un intervalo de 200 m está bien para la forma general, pero el detalle del terreno entre líneas —un escalón rocoso de 40 m, por ejemplo— simplemente desaparece del mapa.",
    "q.m16#20.s1.p" to "Paso 2: el mapa SRTM usa un intervalo de 50 m. Comparado con el de Google de 200 m, ¿cuál es su ventaja más sustancial?",
    "q.m16#20.s1.o0" to "Se ve más bonito",
    "q.m16#20.s1.o1" to "Las líneas están más juntas en la misma distancia horizontal, y resuelven el cambio de pendiente cuatro veces más fino",
    "q.m16#20.s1.o2" to "Los colores son más vivos",
    "q.m16#20.s1.o3" to "Las etiquetas están en letra más grande",
    "q.m16#20.s1.e" to "Cuanto menor el intervalo, más detalle del terreno puedes resolver. Juzgar si una ladera es transitable depende precisamente de la densidad de curvas: con 200 m de separación, un escalón de 150 m se suaviza hasta parecer una pendiente suave, mientras que con 50 m se dibuja tal como es.\nPor eso la evaluación del terreno en rutas técnicas se apoya en fuentes de alta resolución como SRTM.",
    "q.m16#20.s2.p" to "Paso 3: la versión de Google tiene luces y sombras marcadas y parece tridimensional. ¿Cómo hay que tratar ese sombreado al juzgar la inclinación?",
    "q.m16#20.s2.o0" to "Cuanto más oscura la sombra, más inclinada la ladera: usarlo directamente como evidencia",
    "q.m16#20.s2.o1" to "El sombreado solo refleja la iluminación y la orientación; no puede usarse directamente como medida de pendiente",
    "q.m16#20.s2.o2" to "El sombreado marca las zonas con nieve",
    "q.m16#20.s2.o3" to "El sombreado marca el terreno por encima de 7.000 m",
    "q.m16#20.s2.e" to "El sombreado de relieve simula cómo ilumina el sol una ladera desde una dirección dada. Oscuro significa que la ladera mira al lado opuesto a la luz, no que sea inclinada. Una ladera suave orientada al norte puede ser más oscura que una ladera inclinada orientada al sur.\nUsar el sombreado como sustituto de la pendiente es una mala lectura frecuente y realmente peligrosa. El sombreado va bien para la impresión de conjunto; para cuantificar la pendiente, lee la densidad de curvas y, a ser posible, contrasta con datos de alta resolución con etiquetas de altitud.",
    "q.m16#21.p" to "Sobre la afirmación «Google Maps es intuitivo pero impreciso, SRTM es preciso pero no intuitivo», ¿cuál es la comprensión correcta?",
    "q.m16#21.o0" to "SRTM es más exacto, así que Google Maps no tiene valor",
    "q.m16#21.o1" to "Deben usarse juntos: construir la impresión de conjunto con el mapa intuitivo y después hacer juicios cuantificados con curvas de nivel de alta resolución",
    "q.m16#21.o2" to "Google Maps es más intuitivo, así que hay que fiarse primero de él al juzgar pendientes",
    "q.m16#21.o3" to "Solo se diferencian en el color; la información es la misma",
    "q.m16#21.e" to "Las dos fuentes resuelven problemas distintos. El sombreado de relieve y las etiquetas de lugar de Google construyen rápido el sentido espacial: dónde está la montaña, su forma aproximada, por dónde va la ruta. Las curvas de 50 m del SRTM permiten juicios cuantificados: cuántos grados tiene esta pendiente, si hay algún sitio para un campamento.\nFiltrar con el mapa intuitivo y confirmar con el de alta resolución: esa es la división práctica. Usar solo uno es o lento o erróneo.",
    "q.m16#22.p" to "Haz clic en la zona aproximada de la cima del Everest en el mapa.",
    "q.m16#22.e" to "Para encontrar una cima, busca la curva cerrada etiquetada más alta. Aquí las etiquetas cercanas a esta zona suben a 8600 y 8700 m con anillos que se aprietan hacia dentro; el más interno es la cima (8.848 m).\nCuidado en separar «alto» de «inclinado»: el terreno de cima a menudo no es la parte más empinada de la montaña; lo más empinado es donde las curvas están más juntas. Esa distinción importa para el riesgo de la ruta: llegar arriba pone a prueba aclimatación y forma física, mientras que el riesgo técnico se concentra en unas pocas laderas de subida y bajada.",
    "q.m16#23.p" to "Entre las curvas cerradas y densas del Everest y del Lhotse del mismo mapa hay una zona donde las curvas se espacian de forma notable y el terreno baja ligeramente. ¿Qué es, en términos de terreno?",
    "q.m16#23.o0" to "El nacimiento de un glaciar",
    "q.m16#23.o1" to "El collado entre las dos cumbres",
    "q.m16#23.o2" to "El punto más alto de la cresta",
    "q.m16#23.o3" to "Un acantilado vertical",
    "q.m16#23.e" to "Entre dos puntos altos cerrados y densos, donde las curvas se espacian y el terreno baja, hay un collado. El que hay entre el Everest y el Lhotse es el Collado Sur, a unos 7.900 m, donde se sitúa el cuarto campamento de la ruta sur: la última parada antes del ataque a cima.\nReconocer collados en un mapa de curvas es muy práctico. Suelen significar viento fuerte y exposición pero terreno relativamente suave: bueno para un campamento, malo para quedarse, y por eso los campamentos de cima suelen estar en un collado y se abandonan esa misma noche.",
    "q.m16#24.p" to "Haz clic en la zona aproximada de la cima del Muztagh Ata en el mapa.",
    "q.m16#24.e" to "La forma de la cima del Muztagh Ata es representativa: un domo, ancho y suave arriba, donde la curva cerrada más alta está muy extendida en lugar de anidada y apretada como en un pico afilado. Para encontrar este tipo de cima, busca la etiqueta de altitud más alta (aquí 7.500 m) y el anillo cerrado en el que se encuentra.\nLa forma influye directamente en la experiencia de ascensión. Un domo significa que el tramo de cima no es inclinado pero lleva mucho tiempo; con poco relieve y sin referencias evidentes, es fácil perder el sentido de la orientación en el campo de nieve durante el descenso. Es un riesgo que se menciona a menudo en relación con el Muztagh Ata.",
    // m17 — Gestión del campamento de altura
    "q.m17#0.p" to "¿Cuál es el objetivo central de la gestión de un campamento de altura?",
    "q.m17#0.o0" to "Hacer el campamento cómodo",
    "q.m17#0.o1" to "Mantener la capacidad de lucha con el menor coste posible",
    "q.m17#0.o2" to "Ahorrar combustible",
    "q.m17#0.o3" to "Conseguir buenas fotografías",
    "q.m17#0.e" to "En altitud cada unidad de energía es un recurso limitado, y el campamento es el único lugar que la devuelve. Así que toda decisión de campamento debería responder a la misma pregunta: ¿esto dejará al equipo en mejor forma mañana?",
    "q.m17#1.p" to "¿Cuál es la primera consideración al elegir el emplazamiento del campamento?",
    "q.m17#1.o0" to "Las vistas",
    "q.m17#1.o1" to "Evitar canales de alud, zonas de caída de seracs, terreno bajo cornisas y grietas",
    "q.m17#1.o2" to "Estar cerca del agua",
    "q.m17#1.o3" to "Estar cerca del inicio de la ruta",
    "q.m17#1.e" to "La primera regla del emplazamiento es no recibir el impacto de un peligro objetivo, porque el campamento es donde te quedas horas o un día entero y apenas puedes moverte rápido. Las vistas y la comodidad son variables secundarias.",
    "q.m17#2.p" to "¿Por qué no hay que acampar bajo una cornisa de nieve?",
    "q.m17#2.o0" to "Porque el suelo es irregular",
    "q.m17#2.o1" to "Porque una cornisa puede romperse en cualquier momento y lanzar una masa de nieve y hielo directamente sobre el campamento",
    "q.m17#2.o2" to "Porque hace viento",
    "q.m17#2.o3" to "Porque no se ve el paisaje",
    "q.m17#2.e" to "El colapso de una cornisa no avisa de forma predecible: puede caer con el calor de la tarde o en la hora más fría antes del amanecer. Poner el campamento debajo significa aceptar una amenaza continua que no puedes vigilar ni anticipar.",
    "q.m17#3.p" to "[Opción múltiple] ¿Qué zonas debe evitar un campamento?",
    "q.m17#3.o0" to "Debajo de un canal de alud",
    "q.m17#3.o1" to "Justo debajo o justo encima de una cornisa",
    "q.m17#3.o2" to "Campos de grietas evidentes",
    "q.m17#3.o3" to "Al alcance de la caída de seracs",
    "q.m17#3.o4" to "Un mirador abierto con buenas vistas",
    "q.m17#3.e" to "Las cuatro primeras son casos en los que un peligro objetivo cae justo sobre el campamento. Lo que comparten es que son difíciles de vigilar y que, si ocurren, la consecuencia es de nivel de equipo; por eso los criterios de emplazamiento de un campamento deben ser más conservadores que los de una ruta.",
    "q.m17#4.p" to "¿Cómo hay que repartir el combustible y la comida?",
    "q.m17#4.o0" to "Todo en manos de una sola persona",
    "q.m17#4.o1" to "En paquetes por día, con una reserva de emergencia aparte",
    "q.m17#4.o2" to "Todo en la puerta de la tienda",
    "q.m17#4.o3" to "Repartido a partes iguales por persona, sin margen",
    "q.m17#4.e" to "Empaquetar por día hace que el consumo sea rastreable, y la reserva garantiza que siempre haya energía suficiente para descender con seguridad. En montaña el combustible no sirve solo para cocinar: también es cómo derrites nieve para obtener agua, secas la ropa y mantienes la temperatura corporal.",
    "q.m17#5.p" to "¿Por qué mantener una reserva de emergencia?",
    "q.m17#5.o0" to "Porque la comida se estropea",
    "q.m17#5.o1" to "Para garantizar combustible y comida para un descenso seguro en cualquier circunstancia",
    "q.m17#5.o2" to "Porque la tienda lo exige",
    "q.m17#5.o3" to "Para aligerar la carga a la vuelta",
    "q.m17#5.e" to "La reserva apunta al peor caso: que el tiempo se dé la vuelta, que te obliguen a quedarte un día más, que alguien se lesione y necesite un descenso lento. Si todos los recursos se asignan a un calendario ideal, cualquier retraso te deja sin provisiones y sin capacidad de movimiento.",
    "q.m17#6.p" to "¿Cómo hay que tratar los aparatos electrónicos (móvil, cámara, pilas del frontal) durante la noche?",
    "q.m17#6.o0" to "Dejarlos fuera de la tienda",
    "q.m17#6.o1" to "Pegados al cuerpo o dentro del saco para que no se enfríen",
    "q.m17#6.o2" to "En el bolsillo más exterior de la mochila",
    "q.m17#6.o3" to "No hace falta hacer nada",
    "q.m17#6.e" to "Las baterías de litio pierden mucha capacidad con el frío y pueden apagarse del todo. Mantenerlas calientes no es proteger el aparato: es asegurarte de que mañana el frontal ilumine y el GPS encienda. Son material de seguridad, no objetos personales.",
    "q.m17#7.p" to "¿Qué hay que hacer con la ropa mojada?",
    "q.m17#7.o0" to "Colgarla fuera para que se seque por congelación",
    "q.m17#7.o1" to "Mantenerla pegada al cuerpo o dentro del saco para que se seque con el calor corporal",
    "q.m17#7.o2" to "Amontonarla en un rincón de la tienda",
    "q.m17#7.o3" to "Meterla directamente en la mochila",
    "q.m17#7.e" to "De noche las temperaturas en altitud son extremadamente bajas, así que la ropa mojada colgada fuera se congela dura. Secarla contra el cuerpo no es completo, pero al menos mañana no estará helada: un caso clásico de tratar el calor corporal como un recurso.",
    "q.m17#8.p" to "¿Por qué hay que mantener siempre el campamento en un estado que permita recoger e irse de inmediato?",
    "q.m17#8.o0" to "Para que la salida sea cómoda",
    "q.m17#8.o1" to "Porque el tiempo o el estado de un miembro del equipo pueden exigir una evacuación de emergencia en cualquier momento",
    "q.m17#8.o2" to "Para ahorrar tiempo de mochila",
    "q.m17#8.o3" to "Para mantener las cosas ordenadas",
    "q.m17#8.e" to "La ventana meteorológica en el campo alto puede cerrarse de golpe, y un miembro del equipo puede desarrollar síntomas de altura de repente. En ese momento, cuánto tardas en ponerte en marcha decide cuánto riesgo cargas; y el material repartido por toda la tienda puede costarte media hora extra.",
    "q.m17#9.p" to "¿Cuál NO es una causa principal de dormir mal en altitud?",
    "q.m17#9.o0" to "La respiración periódica, que provoca despertares breves repetidos",
    "q.m17#9.o1" to "La hipoxia y el aumento de la frecuencia cardiaca",
    "q.m17#9.o2" to "El frío y la incomodidad",
    "q.m17#9.o3" to "Que la tienda sea de un color demasiado claro",
    "q.m17#9.e" to "Las tres primeras son causas fisiológicas reales, y la respiración periódica es la más típica: en altitud la respiración nocturna se vuelve intermitente de forma involuntaria y te saca una y otra vez del sueño ligero. La calidad del sueño afecta directamente a la aclimatación, así que dormir mal no es un asunto menor.",
    "q.m17#10.p" to "[Ordenar] ¿Cuál es una secuencia correcta para instalar y abandonar un campamento?",
    "q.m17#10.o0" to "Antes de llegar, revisar el entorno en busca de amenazas de alud, caída de seracs y cornisas",
    "q.m17#10.o1" to "Fijar la posición de la tienda, allanar el suelo y asegurarla",
    "q.m17#10.o2" to "Repartir provisiones, derretir nieve para agua y planificar el horario de mañana y el descanso",
    "q.m17#10.o3" to "Antes de salir, inventariar material y basura y restaurar el lugar",
    "q.m17#10.e" to "El primer paso es el que más se salta, sobre todo con cansancio, cuando cualquier trozo llano parece un buen sitio. Pero una vez montado el campamento, moverlo cuesta carísimo, así que mirar alrededor antes de elegir el punto debería volverse un hábito fijo.",
    "q.m17#11.p" to "¿Por qué el campamento es también un eje para la retirada?",
    "q.m17#11.o0" to "Porque el campamento tiene provisiones",
    "q.m17#11.o1" to "Porque retirarse suele significar volver primero al campamento y luego decidir si seguir bajando o esperar el tiempo",
    "q.m17#11.o2" to "Porque el campamento tiene equipo de comunicación",
    "q.m17#11.o3" to "Porque el guía está en el campamento",
    "q.m17#11.e" to "Bajar de altura rara vez es una carrera continua: vuelves al campamento más cercano para recuperarte, observar y decidir. Eso significa que el propio campamento debe ser un destino fiable, no un sitio al que te daría miedo volver.",
    "q.m17#12.p" to "¿Por qué hay que ventilar la tienda?",
    "q.m17#12.o0" to "Para no pasar calor",
    "q.m17#12.o1" to "Para evitar la acumulación de monóxido de carbono y la escarcha interior, y prevenir asfixia e intoxicación",
    "q.m17#12.o2" to "Para entrar y salir más fácilmente",
    "q.m17#12.o3" to "Para reducir la resistencia al viento",
    "q.m17#12.e" to "Cocinar con hornillo en altitud puede elevar rápido el monóxido de carbono en una tienda cerrada, y esa intoxicación tiende a ocurrir mientras duermes, con síntomas —dolor de cabeza, fatiga— casi imposibles de distinguir del mal de altura. Por eso la ventilación es un requisito ineludible.",
    "q.m17#13.p" to "¿Cuál es la mayor preocupación al usar un hornillo dentro de la tienda?",
    "q.m17#13.o0" to "Fugas de combustible",
    "q.m17#13.o1" to "La intoxicación por monóxido de carbono",
    "q.m17#13.o2" to "Derretir la tienda",
    "q.m17#13.o3" to "El ruido",
    "q.m17#13.e" to "El monóxido de carbono es incoloro e inodoro, y sus primeros síntomas —dolor de cabeza, somnolencia— se solapan mucho con el mal de altura. Eso es justo lo que lo hace peligroso: la gente se duerme creyendo que es solo el mal de altura. Usar hornillo exige siempre ventilación.",
    "q.m17#14.p" to "[Opción múltiple] ¿Qué cuestiones de salud hay que mantener activamente en el campamento?",
    "q.m17#14.o0" to "Beber suficiente agua (derritiendo nieve)",
    "q.m17#14.o1" to "Comer lo suficiente, incluso sin apetito",
    "q.m17#14.o2" to "Mantener la ropa seca",
    "q.m17#14.o3" to "Vigilar el estado y la marcha de los demás",
    "q.m17#14.o4" to "Sustituir las comidas por café y bebidas energéticas",
    "q.m17#14.e" to "Las tres primeras son autocuidado; la cuarta es cuidado del equipo, y a menudo es más eficaz que las tres anteriores: los primeros signos de mal de altura (marcha insegura, respuestas lentas) son difíciles de notar en uno mismo y evidentes para un compañero de un vistazo.",
    "q.m17#15.p" to "Completa: por encima del campo alto, el combustible y la comida se empaquetan normalmente por ( ), con una reserva de emergencia aparte.",
    "q.m17#15.a0" to "día",
    "q.m17#15.a1" to "días",
    "q.m17#15.a2" to "cada día",
    "q.m17#15.a3" to "por día",
    "q.m17#15.e" to "Empaquetado por día. Eso hace que el avance del consumo sea evidente de un vistazo y te permite ver «cuántos días quedan» en el momento en que el plan se retrasa, en lugar de darte cuenta solo cuando ya se ha acabado.",
    // m18 — Montañas de siete mil
    "q.m18#0.p" to "¿Cuál es la altitud del Muztagh Ata?",
    "q.m18#0.o0" to "6.812 m",
    "q.m18#0.o1" to "7.126 m",
    "q.m18#0.o2" to "7.134 m",
    "q.m18#0.o3" to "7.509 m",
    "q.m18#0.e" to "El Muztagh Ata tiene 7.509 m y está en el condado de Akto, Xinjiang. Es la primera opción como objetivo de siete mil para muchos equipos y la más alta de las cuatro montañas de esta lección.",
    "q.m18#1.p" to "¿Por qué al Muztagh Ata se le llama «Padre de las montañas de hielo»?",
    "q.m18#1.o0" to "Porque es el pico más alto del mundo",
    "q.m18#1.o1" to "Porque sus glaciares y su volumen de nieve son enormes, así que de lejos parece un inmenso casquete de hielo",
    "q.m18#1.o2" to "Porque fue el primer siete mil en ser escalado",
    "q.m18#1.o3" to "Porque es una montaña sagrada en la leyenda local",
    "q.m18#1.e" to "El nombre viene de su aspecto: la cima está cubierta por un enorme casquete de hielo y las laderas de nieve son muy anchas, así que de lejos se lee como un macizo blanco. Esa imagen también explica su carácter como ascensión: laderas de nieve largas, ángulo moderado, pero mucho tiempo.",
    "q.m18#2.p" to "¿Cuáles son las características técnicas de escalar el Muztagh Ata?",
    "q.m18#2.o0" to "Casi todo paredes de hielo verticales, extremadamente técnico",
    "q.m18#2.o1" to "Laderas de nieve interminables con dificultad técnica moderada, pero muy exigente en aclimatación y forma física",
    "q.m18#2.o2" to "Casi no requiere material técnico",
    "q.m18#2.o3" to "Terreno principalmente de escalada en roca",
    "q.m18#2.e" to "Es un perfil clásico de siete mil: la ruta en sí puede no ser difícil, pero los días largos acarreando material en altitud amplifican cualquier pequeño problema. Así que la preparación real se centra en aclimatación y forma física, no en técnica de alto nivel.",
    "q.m18#3.p" to "¿Cuál es la altitud real del Ama Dablam?",
    "q.m18#3.o0" to "6.812 m",
    "q.m18#3.o1" to "7.126 m",
    "q.m18#3.o2" to "7.509 m",
    "q.m18#3.o3" to "8.027 m",
    "q.m18#3.e" to "El Ama Dablam tiene 6.812 m y está en la región de Khumbu (Nepal). Por altitud es un seis mil, pero está en la unidad de los siete mil porque su dificultad técnica está a la altura de picos por encima de 7.000 m.",
    "q.m18#4.p" to "¿Por qué el Ama Dablam, con solo 6.812 m, está en la unidad de los siete mil?",
    "q.m18#4.o0" to "Porque administrativamente se clasifica como siete mil",
    "q.m18#4.o1" to "Porque su terreno mixto de roca y nieve, muy inclinado y expuesto, sitúa su dificultad a la altura de picos por encima de 7.000 m",
    "q.m18#4.o2" to "Porque su porcentaje de cima es muy bajo",
    "q.m18#4.o3" to "Porque está en una cordillera de siete mil",
    "q.m18#4.e" to "Este es el punto más importante de la lección: la dificultad de una montaña no es su altitud. El Ama Dablam es la prueba clásica: más bajo que muchos sietes mil, pero su umbral técnico y su carga psicológica pueden ser mayores. Elegir montaña solo por la altitud es peligroso.",
    "q.m18#5.p" to "¿Cuáles son la altitud y la ubicación del pico Lenin?",
    "q.m18#5.o0" to "7.126 m, Nepal",
    "q.m18#5.o1" to "7.134 m, meseta del Pamir",
    "q.m18#5.o2" to "7.509 m, Xinjiang",
    "q.m18#5.o3" to "6.812 m, Khumbu, Nepal",
    "q.m18#5.e" to "El pico Lenin tiene 7.134 m, en la meseta del Pamir. Es uno de los sietes mil más suaves y por eso se usa a menudo como primer objetivo de esa altura.",
    "q.m18#6.p" to "¿Cuál es la altitud del Himlung Himal?",
    "q.m18#6.o0" to "7.126 m",
    "q.m18#6.o1" to "7.134 m",
    "q.m18#6.o2" to "7.509 m",
    "q.m18#6.o3" to "6.812 m",
    "q.m18#6.e" to "El Himlung Himal tiene 7.126 m y está en Nepal. Su ruta mezcla laderas de nieve y paredes de hielo, lo que lo hace popular entre los sietes mil nepalíes.",
    "q.m18#7.p" to "[Ordenar] Ordena estas montañas de menor a mayor altitud.",
    "q.m18#7.o0" to "Ama Dablam (6.812 m)",
    "q.m18#7.o1" to "Himlung Himal (7.126 m)",
    "q.m18#7.o2" to "Pico Lenin (7.134 m)",
    "q.m18#7.o3" to "Muztagh Ata (7.509 m)",
    "q.m18#7.e" to "Este orden deja al descubierto un error habitual: ordenando por altitud, el Ama Dablam va antes que el Muztagh Ata, pero la dificultad técnica real puede ser la contraria. Repito: la altitud es solo una variable entre muchas.",
    "q.m18#8.p" to "[Opción múltiple] ¿Qué cambia principalmente a 7.000 m respecto a 6.000 m?",
    "q.m18#8.o0" to "Aclimatación más larga, con más rotaciones de campo alto",
    "q.m18#8.o1" to "Ventanas meteorológicas más estrechas, así que el momento importa más",
    "q.m18#8.o2" to "Retirada más difícil, lo que convierte el autorrescate en requisito ineludible",
    "q.m18#8.o3" to "Terreno en general más técnico y más expuesto",
    "q.m18#8.o4" to "El oxígeno suplementario pasa a ser material estándar",
    "q.m18#8.e" to "Estos cuatro se multiplican, no se suman: una mala aclimatación te hace perder la ventana, perder la ventana obliga a retirarse en peores condiciones, y la retirada se ve amplificada por la altitud y el terreno técnico. Por eso los 7.000 m se llaman la línea divisoria.",
    "q.m18#9.p" to "¿Por qué los 7.000 m se llaman una «línea divisoria»?",
    "q.m18#9.o0" to "Porque solo hace falta piolet por encima de 7.000 m",
    "q.m18#9.o1" to "Porque a partir de ahí técnica, criterio, forma física y logística actúan a la vez, y ninguna fortaleza aislada puede compensar",
    "q.m18#9.o2" to "Porque los glaciares solo se ven por encima de 7.000 m",
    "q.m18#9.o3" to "Porque los equipos comerciales solo operan por encima de 7.000 m",
    "q.m18#9.e" to "Los fallos a 5.000 m suelen tener una sola causa (aclimatación o forma física); a 6.000 m las causas empiezan a acumularse; a 7.000 m todo tiene que estar en su sitio. Por eso esta unidad reúne técnica, criterio, tiempo, autorrescate y gestión del campamento: siempre fueron un solo sistema.",
    "q.m18#10.p" to "¿Qué es lo que más importa al elegir un objetivo de siete mil?",
    "q.m18#10.o0" to "La altitud",
    "q.m18#10.o1" to "Un buen encaje global de tipo de ruta, logística, plan de aclimatación y opciones de retirada",
    "q.m18#10.o2" to "El coste",
    "q.m18#10.o3" to "El porcentaje de cima",
    "q.m18#10.e" to "Ningún elemento aislado basta: más alto no es necesariamente más difícil, un porcentaje de cima alto no es necesariamente más seguro, barato no es necesariamente buena relación calidad-precio. El juicio real es si la combinación de esos cuatro es algo que yo, tal como soy ahora, puedo sostener.",
    "q.m18#11.p" to "En el Muztagh Ata, ¿por qué las «laderas de nieve interminables» son en sí mismas un riesgo?",
    "q.m18#11.o0" to "Porque las laderas resbalan demasiado",
    "q.m18#11.o1" to "Porque la exposición prolongada a la altitud erosiona poco a poco forma física y criterio, y la distancia de retirada es larga",
    "q.m18#11.o2" to "Porque las laderas producen aludes con frecuencia",
    "q.m18#11.o3" to "Porque no se puede encordar en laderas de nieve",
    "q.m18#11.e" to "«No es difícil pero es muy largo» es el modelo de riesgo clásico de los siete mil: no ofrece un paso clave único, pero te va desgastando. Una exposición larga significa que forma física, atención y calidad de las decisiones bajan despacio, y ese margen perdido es exactamente tu margen de seguridad.",
    "q.m18#12.p" to "[Emparejar] Relaciona cada montaña con su carácter típico.",
    "q.m18#12.l0" to "Muztagh Ata",
    "q.m18#12.r0" to "Padre de las montañas de hielo: laderas de nieve interminables, una prueba de aclimatación y forma física",
    "q.m18#12.l1" to "Ama Dablam",
    "q.m18#12.r1" to "Roca y nieve mixtas y muy inclinadas, gran exposición, un campo de pruebas para ochomiles",
    "q.m18#12.l2" to "Pico Lenin",
    "q.m18#12.r2" to "Meseta del Pamir; comparativamente suave entre los siete mil",
    "q.m18#12.l3" to "Himlung Himal",
    "q.m18#12.r3" to "En Nepal; mezcla de laderas de nieve y paredes de hielo",
    "q.m18#12.e" to "Estos cuatro perfiles corresponden a cuatro prioridades de preparación distintas: Muztagh Ata para aclimatación, Ama Dablam para técnica y psicología, pico Lenin como peldaño, Himlung como prueba completa. Verlos juntos permite elegir según tu propio punto débil.",
    "q.m18#13.p" to "Si el objetivo es un ochomil, ¿cuál es la forma más sensata de elegir entre las opciones de siete mil?",
    "q.m18#13.o0" to "Elegir el más alto",
    "q.m18#13.o1" to "Elegir el que cubre tu propio punto débil (técnica, aclimatación o exposición)",
    "q.m18#13.o2" to "Elegir el más barato",
    "q.m18#13.o3" to "Elegir el de mayor porcentaje de cima",
    "q.m18#13.e" to "Tratar los siete mil como campo de entrenamiento de tus puntos débiles vale más que tratarlos como un ascenso de nivel. Si flojeas en técnica, elige Ama Dablam; si aclimatas mal, elige Muztagh Ata con sus laderas largas y sus rotaciones de campo alto consolidadas.",
    "q.m18#14.p" to "¿Cuál es la visión correcta del periodo de preparación para un siete mil?",
    "q.m18#14.o0" to "Más o menos igual que para un seis mil",
    "q.m18#14.o1" to "Claramente más largo, y requiere suficientes rotaciones de campo alto y tiempo de aclimatación",
    "q.m18#14.o2" to "Solo hace falta entrenamiento físico",
    "q.m18#14.o3" to "Puede empezar justo después de la ascensión anterior",
    "q.m18#14.e" to "La aclimatación es acumulativa, y los 7.000 m suelen exigir varias rotaciones de campo alto. Montar un itinerario ajustado sin presupuestar tiempo de aclimatación es la razón directa por la que muchos equipos de siete mil no hacen cima, o tienen accidentes.",
    "q.m18#15.p" to "¿Por qué esta unidad sitúa el «juicio del peligro» después de las lecciones técnicas?",
    "q.m18#15.o0" to "Porque el criterio es más fácil que la técnica",
    "q.m18#15.o1" to "Porque la capacidad técnica te da confianza para entrar en terreno más difícil, lo que hace más necesario el criterio para contenerla",
    "q.m18#15.o2" to "Por límites de espacio en el temario",
    "q.m18#15.o3" to "Porque la técnica no importa",
    "q.m18#15.e" to "Es un diseño realista: cuanto más hábil eres, más difíciles son las rutas que puedes intentar, así que la necesidad de limitarte sube en vez de bajar. Poner el criterio después de la técnica reproduce ese orden en la realidad: primero la capacidad, luego la contención.",
    // m19 — La zona de la muerte
    "q.m19#0.p" to "La «zona de la muerte» suele referirse a:",
    "q.m19#0.o0" to "Por encima de 7.000 m",
    "q.m19#0.o1" to "Por encima de 8.000 m",
    "q.m19#0.o2" to "Por encima de 5.500 m",
    "q.m19#0.o3" to "Por encima de 6.000 m",
    "q.m19#0.e" to "Por encima de 8.000 m se llama zona de la muerte por una razón simple: la presión parcial de oxígeno es tan baja que ninguna cantidad de aclimatación permite al cuerpo mantenerse en equilibrio mucho tiempo. No es retórica, es un hecho fisiológico, y es la línea divisoria más fundamental entre 8.000 y 7.000 m.",
    "q.m19#1.p" to "A 8.000 m, la presión atmosférica es aproximadamente qué fracción del nivel del mar?",
    "q.m19#1.o0" to "Un medio",
    "q.m19#1.o1" to "Dos tercios",
    "q.m19#1.o2" to "Un tercio",
    "q.m19#1.o3" to "Un quinto",
    "q.m19#1.e" to "Alrededor de un tercio. Eso significa que cada respiración aporta solo cerca del treinta por ciento de las moléculas de oxígeno disponibles al nivel del mar, mientras que escalar exige varias veces el oxígeno del reposo. Esa brecha entre aporte y demanda es el origen de todos los riesgos de los 8.000 m.",
    "q.m19#2.p" to "¿Por qué el cuerpo humano no puede permanecer mucho tiempo por encima de 8.000 m?",
    "q.m19#2.o0" to "Porque hace demasiado frío",
    "q.m19#2.o1" to "Porque la presión parcial de oxígeno está por debajo del umbral necesario para sostener el metabolismo, así que el cuerpo se deteriora de forma sostenida",
    "q.m19#2.o2" to "Porque no hay comida suficiente",
    "q.m19#2.o3" to "Porque el viento es demasiado fuerte",
    "q.m19#2.e" to "Quedarse mucho tiempo significa consumir más de lo que reparas: incluso en reposo el cuerpo pierde músculo y peso y el rendimiento cognitivo baja. Por eso un itinerario de 8.000 m debe ser entrar rápido y salir rápido: no existe la opción de esperar a que mejoren las condiciones.",
    "q.m19#3.p" to "¿Qué capacidad afecta primero la hipoxia?",
    "q.m19#3.o0" to "La fuerza de las piernas",
    "q.m19#3.o1" to "El criterio y la cognición",
    "q.m19#3.o2" to "La visión",
    "q.m19#3.o3" to "La audición",
    "q.m19#3.e" to "Es el mecanismo más peligroso a 8.000 m: quien tiene el criterio deteriorado no puede juzgar que su criterio está deteriorado. Al contrario, las piernas débiles las notas al instante, mientras que el pensamiento «puedo seguir» puede ser ya un producto de la hipoxia.",
    "q.m19#4.p" to "¿Por qué el deterioro del criterio es especialmente peligroso a 8.000 m?",
    "q.m19#4.o0" to "Porque puedes perderte",
    "q.m19#4.o1" to "Porque tienes que usar un criterio ya deteriorado para decidir si continúas o te retiras",
    "q.m19#4.o2" to "Porque afecta a tus compañeros",
    "q.m19#4.o3" to "Porque te vuelve más lento",
    "q.m19#4.e" to "Es una trampa recursiva: justo cuando hace falta una decisión crítica —continuar o retirarse— tu capacidad de decidir es la menos fiable. «Vamos un poco más y vemos» puede ser razonable a 4.000 m; a 8.000 m puede ser ya un error dictado por la hipoxia.",
    "q.m19#5.p" to "[Opción múltiple] ¿Cuáles son signos típicos del deterioro cognitivo por hipoxia?",
    "q.m19#5.o0" to "Reacciones más lentas, habla pastosa",
    "q.m19#5.o1" to "Errores de cálculo y de criterio",
    "q.m19#5.o2" to "Que la valoración del riesgo se vuelva demasiado optimista",
    "q.m19#5.o3" to "Cambios de humor, irritabilidad o apatía",
    "q.m19#5.o4" to "Menor sensación de congelación en dedos de manos y pies",
    "q.m19#5.e" to "Los cuatro primeros son típicos y comparten un rasgo: quien los sufre apenas los nota. Por eso lo fiable es externalizar: listas de comprobación en lugar de memoria, horas fijas en lugar de «me parece que va bien», y compañeros que se vigilan en lugar de autoevaluarse.",
    "q.m19#6.p" to "¿Cuál es el antídoto más eficaz contra el deterioro del criterio?",
    "q.m19#6.o0" to "Usar la fuerza de voluntad para mantenerse alerta",
    "q.m19#6.o1" to "Externalizar las decisiones en listas escritas de antemano y reglas fijas (hora, oxígeno restante, umbrales meteorológicos)",
    "q.m19#6.o2" to "Beber más agua caliente",
    "q.m19#6.o3" to "Ir más despacio",
    "q.m19#6.e" to "La fuerza de voluntad es justo lo primero que erosiona la hipoxia. El método fiable es escribir las reglas mientras aún funcionas: a qué hora hay que dar media vuelta, cuánto oxígeno restante obliga a descender; después solo hay que verificar hechos, no volver a juzgar.",
    "q.m19#7.p" to "¿Por qué un itinerario de 8.000 m insiste en «salir temprano, volver temprano»?",
    "q.m19#7.o0" to "Para evitar aglomeraciones",
    "q.m19#7.o1" to "Porque la probabilidad de que el tiempo empeore sube por la tarde, y el frío y el viento consumen rápido energía y oxígeno",
    "q.m19#7.o2" to "Porque la ruta es más corta por la mañana",
    "q.m19#7.o3" to "Por costumbre de los guías",
    "q.m19#7.e" to "A 8.000 m el coste de «tarde» se multiplica: el mismo terreno exige el doble de esfuerzo por la tarde, y cuando cae la noche bajan a la vez la temperatura y el criterio. «Descender demasiado tarde» es casi siempre el punto de partida común de esa cadena de accidente.",
    "q.m19#8.p" to "¿Por qué los 8.000 m exigen «simplificar la toma de decisiones»?",
    "q.m19#8.o0" to "Para ahorrar tiempo",
    "q.m19#8.o1" to "Porque los recursos cognitivos son limitados y hay que reservarlos para las decisiones que de verdad importan",
    "q.m19#8.o2" to "Porque en altitud no apetece pensar",
    "q.m19#8.o3" to "Porque los compañeros decidirán por ti",
    "q.m19#8.e" to "En la práctica: sitios y orden fijos para el material, procedimientos convertidos en listas, el horario fijado de antemano. Convertir «qué me pongo hoy, qué hago primero» en una opción por defecto que no exige pensar es lo que preserva criterio para decisiones como continuar o retirarse.",
    "q.m19#9.p" to "¿Por qué incluso los escaladores con experiencia necesitan listas de comprobación a 8.000 m?",
    "q.m19#9.o0" to "Porque la memoria no es fiable",
    "q.m19#9.o1" to "Porque la hipoxia daña primero la memoria de trabajo, y una lista no depende de la memoria",
    "q.m19#9.o2" to "Porque la normativa lo exige",
    "q.m19#9.o3" to "Para ayudar a aprender a los principiantes",
    "q.m19#9.e" to "La lógica es la misma que en aviación: en entornos de alta carga y alta consecuencia no puedes confiar en «seguramente no se me olvidará». Una lista no es una ayuda didáctica para novatos, sino un seguro contra los errores que también cometen los expertos.",
    "q.m19#10.p" to "¿Qué causa principalmente la pérdida continua de peso en altitud?",
    "q.m19#10.o0" to "Que la comida sabe mal",
    "q.m19#10.o1" to "Que el cuerpo sigue degradando su propio tejido bajo la hipoxia, mientras el apetito reducido implica una ingesta insuficiente",
    "q.m19#10.o2" to "La cantidad de ejercicio",
    "q.m19#10.o3" to "La falta de agua",
    "q.m19#10.e" to "Actúan dos factores juntos: la hipoxia pone al cuerpo en un estado en el que la degradación supera a la síntesis, y el propio mal de altura suprime el apetito. Por eso poder comer en altitud es una capacidad, no un placer.",
    "q.m19#11.p" to "¿Por qué se duerme mal a 8.000 m?",
    "q.m19#11.o0" to "Porque la tienda es incómoda",
    "q.m19#11.o1" to "Porque el bajo nivel de oxígeno provoca respiración periódica, con pausas repetidas que te sacan del sueño",
    "q.m19#11.o2" to "Porque hace viento",
    "q.m19#11.o3" to "Porque has dormido demasiado durante el día",
    "q.m19#11.e" to "La respiración periódica es el fenómeno clásico del sueño en altitud: un impulso respiratorio inestable produce ciclos repetidos de apnea y sobresalto. La calidad del sueño afecta directamente a la aclimatación y a la energía del día siguiente, así que poder dormir es una competencia central en el campo alto.",
    "q.m19#12.p" to "[Ordenar] Ordena los efectos de la hipoxia sobre el organismo según su aparición habitual.",
    "q.m19#12.o0" to "Respiración más rápida y frecuencia cardiaca elevada (compensación)",
    "q.m19#12.o1" to "Descenso de la resistencia en esfuerzos prolongados",
    "q.m19#12.o2" to "Deterioro del criterio y de la capacidad aritmética",
    "q.m19#12.o3" to "Alteración de la consciencia, ataxia",
    "q.m19#12.e" to "Los dos primeros son el cuerpo intentando adaptarse; los dos últimos son el cuerpo fallando. El peligroso es el tercero: aparece antes de cualquier cambio evidente de consciencia, así que «parece normal» no significa «piensa con claridad».",
    "q.m19#13.p" to "¿Cuál es la forma más directa y fiable de contrarrestar la hipoxia a 8.000 m?",
    "q.m19#13.o0" to "Comer más",
    "q.m19#13.o1" to "Usar oxígeno suplementario",
    "q.m19#13.o2" to "Descansar más",
    "q.m19#13.o3" to "Ir más despacio",
    "q.m19#13.e" to "Las otras opciones actúan reduciendo el consumo o acelerando la aclimatación, mientras que el oxígeno suplementario eleva directamente la presión parcial de oxígeno inspirado: cambia la variable raíz. Por eso el oxígeno es material de seguridad estándar a 8.000 m.",
    "q.m19#14.p" to "¿Cuál es la comprensión correcta del «límite de la aclimatación»?",
    "q.m19#14.o0" to "La aclimatación puede continuar indefinidamente",
    "q.m19#14.o1" to "La aclimatación tiene un techo; por encima de cierta altitud ninguna cantidad compensa por completo",
    "q.m19#14.o2" to "La aclimatación tarda un día",
    "q.m19#14.o3" to "La aclimatación no tiene relación con la altitud",
    "q.m19#14.e" to "La aclimatación es un proceso con límite, no una curva que sube sin fin. Esa es la razón de fondo por la que los 8.000 m dependen del oxígeno y de una estrategia de entrar y salir rápido: no por falta de preparación, sino por la ausencia fisiológica de la opción «aclimatar y luego quedarse».",
    "q.m19#15.p" to "¿Por qué la causa de fondo de los accidentes a 8.000 m rara vez es un solo evento?",
    "q.m19#15.o0" to "Por mala suerte",
    "q.m19#15.o1" to "Porque la hipoxia debilita a la vez criterio, energía y coordinación, dejando varios eslabones frágiles al mismo tiempo",
    "q.m19#15.o2" to "Porque el material es inadecuado",
    "q.m19#15.o3" to "Porque hay demasiada gente",
    "q.m19#15.e" to "A baja altitud un error suele dejar margen para recuperarse; a 8.000 m criterio, energía y control motor bajan juntos, así que los errores pequeños se encadenan directamente hacia el accidente. La estrategia de seguridad a 8.000 m debe ser, por tanto, más capas de protección, no simplemente más cuidado.",
    "q.m19#16.p" to "[Opción múltiple] ¿Cuáles son las principales causas de muerte a 8.000 m?",
    "q.m19#16.o0" to "Aludes y caída de seracs",
    "q.m19#16.o1" to "Caídas",
    "q.m19#16.o2" to "Hipotermia",
    "q.m19#16.o3" to "Mal de altura y sus complicaciones",
    "q.m19#16.o4" to "Lesiones ambientales como ceguera de la nieve y quemaduras solares",
    "q.m19#16.e" to "Las cuatro primeras son frecuentes y a menudo se acumulan: una caída te deja sin poder autorrescatarte, luego la espera al frío, luego la hipotermia, luego el empeoramiento del mal de altura. Por eso la preparación para 8.000 m no puede centrarse solo en el mal de altura, sino incluir técnica, criterio y sistemas.",
    "q.m19#17.p" to "Completa: por encima de 8.000 m se llama la «zona de la ( )».",
    "q.m19#17.a0" to "muerte",
    "q.m19#17.a1" to "muerte",
    "q.m19#17.e" to "La zona de la muerte. El valor práctico del término es la restricción dura que transmite: aquí no existe la opción de esperar o aflojar. Todo plan, cálculo de provisiones y decisión debe diseñarse en torno a pasar lo más rápido posible.",
    "q.m19#18.p" to "A 8.000 m notas que «de verdad quieres seguir a la cima». ¿Qué hay que hacer?",
    "q.m19#18.o0" to "Confiar en el instinto y seguir subiendo",
    "q.m19#18.o1" to "Tratarlo como un posible signo de subestimación del riesgo por hipoxia y revisar de inmediato las condiciones de regreso fijadas de antemano",
    "q.m19#18.o2" to "Acelerar y llegar arriba",
    "q.m19#18.o3" to "Dejar que decidan los compañeros",
    "q.m19#18.e" to "Es una situación muy representativa: unas ganas intensas de continuar pueden ser simple deseo a baja altitud, pero a 8.000 m pueden ser señal de criterio deteriorado. La única referencia fiable entonces no es cómo te sientes, sino las condiciones objetivas escritas antes de salir.",
    // m20 — Oxígeno suplementario
    "q.m20#0.p" to "¿Cuál es la función principal del oxígeno suplementario a 8.000 m?",
    "q.m20#0.o0" to "Sustituir el entrenamiento físico",
    "q.m20#0.o1" to "Elevar el oxígeno en sangre, bajar el riesgo de mal de altura y mejorar la movilidad y el criterio",
    "q.m20#0.o2" to "Mantenerte caliente",
    "q.m20#0.o3" to "Reducir el peso de la mochila",
    "q.m20#0.e" to "El elemento que más se olvida, y el más crítico para la seguridad, es la mejora del criterio, porque contrarresta directamente el factor más peligroso a 8.000 m. Por eso el oxígeno es material de seguridad estándar a esta altitud y no un simple ahorro de esfuerzo.",
    "q.m20#1.p" to "¿Cuáles son los componentes de un sistema de oxígeno suplementario?",
    "q.m20#1.o0" to "Botella, regulador, caudalímetro, mascarilla o gafas nasales",
    "q.m20#1.o1" to "Botella y mochila",
    "q.m20#1.o2" to "Mascarilla y capa de aislamiento",
    "q.m20#1.o3" to "Regulador y casco",
    "q.m20#1.e" to "Cada parte tiene su función: la botella almacena, el regulador baja la alta presión a un rango seguro, el caudalímetro fija el caudal y la mascarilla o las gafas lo entregan. Un fallo en cualquier punto hace que inhales menos de lo que crees; por eso el sistema se revisa en cada tramo.",
    "q.m20#2.p" to "¿Qué caudal es habitual en uso de escalada?",
    "q.m20#2.o0" to "0,5–1 L/min",
    "q.m20#2.o1" to "2–4 L/min",
    "q.m20#2.o2" to "8–10 L/min",
    "q.m20#2.o3" to "Más de 15 L/min",
    "q.m20#2.e" to "2–4 L/min es el rango habitual en escalada; la cifra exacta depende de la altitud, el esfuerzo y la respuesta individual. Un caudal mayor es más cómodo pero consume más rápido: un equilibrio que decide directamente cuánto tiempo puedes quedarte a 8.000 m.",
    "q.m20#3.p" to "¿Por qué hay que calcular aparte una reserva de emergencia en la planificación del oxígeno?",
    "q.m20#3.o0" to "Para llevar un poco de más",
    "q.m20#3.o1" to "Porque los retrasos, apoyar a un compañero o un fallo del sistema pueden consumir oxígeno extra",
    "q.m20#3.o2" to "Porque las botellas tienen fugas",
    "q.m20#3.o3" to "Porque la normativa lo exige",
    "q.m20#3.e" to "El error clásico de planificación de oxígeno es «lo justo para llegar a la cima». Los horarios reales casi siempre son más lentos que lo previsto, y los compañeros pueden quedarse cortos o el sistema puede tener fugas. Sin reserva, cualquier desviación te deja jugándotela en la altitud más peligrosa.",
    "q.m20#4.p" to "¿Qué puede pasar cuando se acaba el oxígeno?",
    "q.m20#4.o0" to "Nada en absoluto",
    "q.m20#4.o1" to "Que el estado empeore rápido, porque el cuerpo se ha adaptado a una concentración inspirada de oxígeno más alta",
    "q.m20#4.o2" to "Que el mal de altura aparece al instante",
    "q.m20#4.o3" to "Que el sistema cambia solo al aire ambiente",
    "q.m20#4.e" to "Pasar de golpe de oxígeno enriquecido a la presión parcial ambiente equivale a ganar un buen tramo de altitud en un instante a 8.000 m. Si estás lejos del campamento y ya agotado, la cosa puede volverse peligrosa rápido; por eso el margen de oxígeno debe mantenerse conservador.",
    "q.m20#5.p" to "[Opción múltiple] ¿Qué disciplina se aplica al uso de un sistema de oxígeno?",
    "q.m20#5.o0" to "Revisar el caudal y las conexiones en cada tramo",
    "q.m20#5.o1" to "Usar el caudal previsto; no subirlo a capricho",
    "q.m20#5.o2" to "Registrar lo que queda y el tiempo estimado que da",
    "q.m20#5.o3" to "Acordar de antemano con qué cantidad restante hay que descender",
    "q.m20#5.o4" to "Poner el caudal al máximo cuando te encuentras mal",
    "q.m20#5.e" to "La cuarta es la más importante: convierte «descender con esta cantidad restante» en un número fijado de antemano en lugar de una discusión sobre el terreno. Cuando llegue el momento, la persona que necesita esa regla puede haber perdido ya la capacidad de juzgar con precisión.",
    "q.m20#6.p" to "¿Por qué usar oxígeno no es «hacer trampa»?",
    "q.m20#6.o0" to "Porque las reglas lo permiten",
    "q.m20#6.o1" to "Porque por encima de 8.000 m el cuerpo está fuera del rango fisiológico que puede compensar a largo plazo, así que usar oxígeno es la respuesta estándar a ese hecho",
    "q.m20#6.o2" to "Porque todo el mundo lo hace",
    "q.m20#6.o3" to "Porque mejora el porcentaje de cima",
    "q.m20#6.e" to "La palabra trampa supone que con un poco más de esfuerzo se puede pasar del límite, pero el límite a 8.000 m es física y fisiología, no una regla. El oxígeno eleva algo el techo fisiológico; no cambia el hecho de que no puedes quedarte mucho tiempo.",
    "q.m20#7.p" to "¿Cuál es la diferencia principal entre mascarilla y gafas nasales?",
    "q.m20#7.o0" to "La mascarilla entrega una concentración más estable, pero es más agobiante y limita la visión al moverse",
    "q.m20#7.o1" to "Las gafas nasales pueden dar una concentración más alta",
    "q.m20#7.o2" to "Son idénticas",
    "q.m20#7.o3" to "La mascarilla pesa menos",
    "q.m20#7.e" to "La mascarilla sella mejor y mantiene una concentración estable, pero añade resistencia al respirar, se empaña con facilidad y es incómoda en movimiento; las gafas nasales son cómodas y dejan ver bien, pero la concentración inspirada real depende mucho de cómo respiras. La elección depende del terreno, la intensidad y la tolerancia personal: no es simplemente cuál es mejor.",
    "q.m20#8.p" to "¿Qué equilibrio implica subir o bajar el caudal?",
    "q.m20#8.o0" to "Comodidad frente a tiempo de autonomía",
    "q.m20#8.o1" to "Peso frente a precio",
    "q.m20#8.o2" to "No hay ningún equilibrio",
    "q.m20#8.o3" to "Altitud frente a temperatura",
    "q.m20#8.e" to "Más caudal significa un cuerpo más cómodo y un criterio mejor preservado, pero menos tiempo antes de quedarse sin gas. Un plan de oxígeno es, en la práctica, un presupuesto de cuánto tiempo puedes estar arriba, y eso fija directamente la ventana del día de cima y la hora límite de regreso.",
    "q.m20#9.p" to "¿Por qué el peso de las botellas se convierte en un problema logístico?",
    "q.m20#9.o0" to "Porque abultan",
    "q.m20#9.o1" to "Porque tanto la botella como el gas pesan, y por encima del campo alto todo hay que subirlo a fuerza de personas",
    "q.m20#9.o2" to "Porque no se pueden facturar",
    "q.m20#9.o3" to "Porque se rompen con facilidad",
    "q.m20#9.e" to "En altitud el coste de cada kilogramo se multiplica, y una botella es pesada e incompresible. Por eso la planificación del oxígeno debe diseñarse junto con la disposición de los campamentos y la mano de obra disponible: no es una cuestión de material aislada.",
    "q.m20#10.p" to "¿Por qué hay que almacenar oxígeno en el campo alto de antemano?",
    "q.m20#10.o0" to "Para aligerar el día de cima y garantizar que entonces haya oxígeno disponible",
    "q.m20#10.o1" to "Para evitar robos",
    "q.m20#10.o2" to "Porque allí arriba hace más frío",
    "q.m20#10.o3" to "Para ahorrar dinero",
    "q.m20#10.e" to "El día de cima es cuando estás más al límite y menos en forma; no puedes además subir el oxígeno cargado. Así que hay que acarrearlo por tandas de antemano, lo que significa que cantidad de oxígeno, mano de obra y ventana meteorológica quedan atados en la fase de planificación.",
    "q.m20#11.p" to "¿Qué hay que hacer si el sistema de oxígeno falla en ruta?",
    "q.m20#11.o0" to "Seguir subiendo y arreglarlo en casa",
    "q.m20#11.o1" to "Evaluar de inmediato el oxígeno restante y tu altitud, y después seguir el plan: descender o pasar al sistema de reserva",
    "q.m20#11.o2" to "Subir el caudal para intentar arreglarlo",
    "q.m20#11.o3" to "Desmontarlo y repararlo",
    "q.m20#11.e" to "Un fallo de oxígeno significa que de repente operas en condiciones de mayor altitud, sin protección. Atenderlo va por delante de todo lo demás: primero decide si la reserva te permite continuar y, si no, desciende. A 8.000 m, volver abajo es una decisión con sentido, no un fracaso.",
    "q.m20#12.p" to "[Ordenar] ¿Cuál es la secuencia de comprobación del sistema de oxígeno el día de cima?",
    "q.m20#12.o0" to "Confirmar la presión de la botella y el tiempo estimado que da",
    "q.m20#12.o1" to "Revisar regulador, tubo y mascarilla o gafas en busca de daños",
    "q.m20#12.o2" to "Abrir el caudal y confirmar que el gas sale de verdad",
    "q.m20#12.o3" to "Registrar la cantidad restante y avisar a los compañeros y a quienes esperan en casa",
    "q.m20#12.e" to "Las tres primeras son comprobaciones técnicas; la cuarta es comunicación de equipo, y esta última importa especialmente en altitud: si tus compañeros conocen tu margen de oxígeno, pueden notar tu deterioro antes que tú.",
    "q.m20#13.p" to "¿Por qué el oxígeno no puede sustituir a la aclimatación?",
    "q.m20#13.o0" to "Porque el oxígeno es demasiado caro",
    "q.m20#13.o1" to "Porque la aclimatación es la compensación fisiológica del propio cuerpo, mientras que el oxígeno solo eleva la concentración inspirada",
    "q.m20#13.o2" to "Porque el oxígeno deja de funcionar",
    "q.m20#13.o3" to "Porque el oxígeno solo sirve para el mal de altura",
    "q.m20#13.e" to "La aclimatación cambia cómo usa el oxígeno el cuerpo; el oxígeno cambia cuánto entra. No puedes obtener lo primero de lo segundo. Por eso descender, subir despacio y disponer de tiempo suficiente de aclimatación siguen siendo requisitos no negociables a 8.000 m.",
    "q.m20#14.p" to "[Opción múltiple] ¿Cuáles son fallos habituales de un sistema de oxígeno?",
    "q.m20#14.o0" to "Hielo u obstrucción en la conexión",
    "q.m20#14.o1" to "Fugas en el tubo",
    "q.m20#14.o2" to "Averías del regulador que dan un caudal inexacto",
    "q.m20#14.o3" to "Dificultad para abrir la válvula de la botella",
    "q.m20#14.o4" to "Que la botella pese más de lo esperado",
    "q.m20#14.e" to "Los cuatro tienen que ver con el frío, el hielo y el manejo torpe, y todos ocurren en altitud, con cansancio, cuando son más difíciles de resolver. Por eso no basta con llevar un sistema de reserva: también hace falta un plan de decisión para el fallo.",
    "q.m20#15.p" to "¿Por qué hay que incorporar el plan de oxígeno al itinerario?",
    "q.m20#15.o0" to "Por apariencia",
    "q.m20#15.o1" to "Porque la cantidad de oxígeno determina directamente la hora límite de regreso viable y la permanencia máxima",
    "q.m20#15.o2" to "Para registrar los gastos",
    "q.m20#15.o3" to "Para que sea más fácil justificar los reembolsos",
    "q.m20#15.e" to "El oxígeno no es «llevo algo y listo», es un presupuesto cuantificado: cuántas botellas, a qué caudal, para cuántas horas. Esas cifras fijan a su vez la hora límite de regreso, así que hay que planificarlas con el horario y no en una lista aparte.",
    "q.m20#16.p" to "Completa: el caudal típico en escalada es de unos 2 a ( ) L/min.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "cuatro",
    "q.m20#16.e" to "2–4 L/min. El rango es el equilibrio entre mantener un oxígeno en sangre adecuado y conservar gas. La gestión del oxígeno es, al final, un problema continuo de asignación de recursos.",
    "q.m20#17.p" to "¿Qué hay que hacer si a un compañero se le está acabando el oxígeno?",
    "q.m20#17.o0" to "Seguir a por la cima: sálvese quien pueda",
    "q.m20#17.o1" to "Compartir la información y las cantidades restantes de inmediato y después seguir el plan: descender juntos o redistribuir el oxígeno",
    "q.m20#17.o2" to "Dejar que lo resuelva",
    "q.m20#17.o3" to "Darle todo tu oxígeno",
    "q.m20#17.e" to "Quedarse corto es un evento de nivel de equipo, no personal: afecta a la velocidad de descenso y a la cobertura mutua. Las peores opciones son los dos extremos: seguir a por la cima o ceder toda tu propia reserva. La respuesta sensata es redistribuir recursos y priorizar que todos bajen.",
    "q.m20#18.p" to "Una botella utilizable contiene 1.200 litros. Con un caudal de 3 L/min, ¿cuántos minutos durará aproximadamente?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "Unos 400 minutos (aproximadamente 6,7 horas): 1200 ÷ 3 = 400. Cálculos así importan directamente el día de cima: determinan cuánto tiempo puedes estar a 8.000 m y, por tanto, a qué hora hay que fijar la hora límite de regreso.",
    "q.m20#19.p" to "Plan de cima: 5 horas de subida, 3 de bajada, caudal de 2 L/min, más 60 minutos de reserva de emergencia. ¿Qué volumen total de oxígeno se necesita, en litros?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 litros: (5 + 3) horas × 60 min × 2 L/min = 960 litros, más 60 × 2 = 120 litros de reserva, en total 1080. Calcular subida, bajada y reserva como tres partes separadas es la disciplina más básica de la planificación de oxígeno; contar solo si hay bastante para subir es el error más común.",
    // m21 — Los catorce ochomiles
    "q.m21#0.p" to "¿Cuántos ochomiles hay en el mundo?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Catorce, todos dentro del Himalaya y del Karakórum. Ese número es el origen del objetivo alpinístico conocido como «los catorce ochomiles».",
    "q.m21#1.p" to "¿En qué países están los catorce ochomiles?",
    "q.m21#1.o0" to "China, Nepal, India, Pakistán",
    "q.m21#1.o1" to "China, Nepal, Bután, India",
    "q.m21#1.o2" to "Nepal, Pakistán, Afganistán, Tayikistán",
    "q.m21#1.o3" to "China, India, Pakistán, Myanmar",
    "q.m21#1.e" to "Cuatro países: China, Nepal, India y Pakistán. Entender esa distribución importa, porque condiciona permisos, logística, rescate y riesgo político, y todo eso forma parte de la planificación de un ochomil.",
    "q.m21#2.p" to "¿Cuál es la altitud del Everest?",
    "q.m21#2.o0" to "8.611 m",
    "q.m21#2.o1" to "8.848 m",
    "q.m21#2.o2" to "8.586 m",
    "q.m21#2.o3" to "8.516 m",
    "q.m21#2.e" to "8.848 m (la medición conjunta China–Nepal de 2020 dio 8.848,86 m). Como techo del mundo, es también el que tiene la infraestructura comercial más desarrollada, pero madurez significa logística y rutas maduras, no riesgo bajo: las aglomeraciones, el coste y la dificultad de juzgar bien son peligros reales.",
    "q.m21#3.p" to "¿Qué lugar ocupa el Annapurna I en la historia de los ochomiles?",
    "q.m21#3.o0" to "El último en ser escalado",
    "q.m21#3.o1" to "El primer ochomil en ser escalado",
    "q.m21#3.o2" to "El de menor tasa de mortalidad",
    "q.m21#3.o3" to "El más fácil de escalar",
    "q.m21#3.e" to "El Annapurna I tiene 8.091 m y se escaló por primera vez en 1950: el primer ochomil de la historia. Su tasa de mortalidad ha estado entre las más altas durante mucho tiempo. Haber sido el primero no tiene nada que ver con ser fácil.",
    "q.m21#4.p" to "¿Qué distingue al Shishapangma?",
    "q.m21#4.o0" to "Está en Nepal",
    "q.m21#4.o1" to "Es el único ochomil íntegramente en China, y el último de los catorce en ser escalado",
    "q.m21#4.o2" to "Es el más alto",
    "q.m21#4.o3" to "Es el más fácil",
    "q.m21#4.e" to "El Shishapangma tiene 8.027 m, en el Tíbet, y es el único ochomil que queda por completo dentro de China; lo escaló por primera vez un equipo chino en 1964 y es el último de los catorce en haber sido hollado.",
    "q.m21#5.p" to "¿Cuál es la relación entre el Lhotse y el Everest?",
    "q.m21#5.o0" to "Están muy separados",
    "q.m21#5.o1" to "El Lhotse es contiguo al Everest y a menudo comparte la misma ruta de aproximación",
    "q.m21#5.o2" to "El Lhotse es más alto que el Everest",
    "q.m21#5.o3" to "Están en cordilleras distintas",
    "q.m21#5.e" to "El Lhotse tiene 8.516 m, está inmediatamente al lado del Everest y, desde el sur, los dos comparten buena parte de la ruta y de los campamentos. Por eso a menudo se consideran dentro de un mismo itinerario a efectos de logística y aclimatación.",
    "q.m21#6.p" to "¿Cuál es la valoración habitual del Cho Oyu?",
    "q.m21#6.o0" to "El ochomil más técnico",
    "q.m21#6.o1" to "Generalmente se le considera uno de los ochomiles menos técnicos",
    "q.m21#6.o2" to "El ochomil con mayor tasa de mortalidad",
    "q.m21#6.o3" to "Ningún equipo comercial lo escala",
    "q.m21#6.e" to "El Cho Oyu tiene 8.188 m y, con una ruta relativamente suave y una logística madura, suele considerarse uno de los ochomiles menos técnicos. Pero «relativamente fácil» sigue significando operar en la zona de la muerte durante días: la magnitud no se puede subestimar.",
    "q.m21#7.p" to "¿Por qué es conocido el Nanga Parbat?",
    "q.m21#7.o0" to "Por sus rutas suaves",
    "q.m21#7.o1" to "Por un desnivel vertical enorme y un riesgo de alud severo",
    "q.m21#7.o2" to "Por los permisos más baratos",
    "q.m21#7.o3" to "Por la mejor logística",
    "q.m21#7.e" to "El Nanga Parbat tiene 8.126 m y se le conoce como la «Montaña Desnuda»: se levanta una distancia inmensa directamente desde el valle, con un riesgo de alud y de caída de piedras muy marcado. Su coste histórico en vidas es alto incluso para los estándares de los ochomiles.",
    "q.m21#8.p" to "[Emparejar] Relaciona cada pico con su altitud.",
    "q.m21#8.l0" to "Everest",
    "q.m21#8.r0" to "8.848 m",
    "q.m21#8.l1" to "Kangchenjunga",
    "q.m21#8.r1" to "8.586 m",
    "q.m21#8.l2" to "Lhotse",
    "q.m21#8.r2" to "8.516 m",
    "q.m21#8.l3" to "Makalu",
    "q.m21#8.r3" to "8.485 m",
    "q.m21#8.e" to "Son el primero, el tercero, el cuarto y el quinto pico más altos del mundo. No memorices solo las cifras: recuerda el orden y a qué cordillera pertenece cada uno. Las cifras se pueden consultar; la imagen de conjunto hay que tenerla en la cabeza.",
    "q.m21#9.p" to "¿Por qué «los catorce» se ha convertido en un objetivo alpinístico reconocido?",
    "q.m21#9.o0" to "Porque es un número redondo",
    "q.m21#9.o1" to "Porque resulta ser un límite completo de la escalada de alta montaña, y el número está al alcance de una vida",
    "q.m21#9.o2" to "Porque las empresas comerciales lo promocionaron",
    "q.m21#9.o3" to "Porque la UIAA lo exige",
    "q.m21#9.e" to "Lo distintivo de los catorce es que tienen un límite objetivo e inequívoco (por encima de 8.000 m), un número finito y se pueden enumerar uno a uno. Eso hace que el objetivo sea a la vez claro y de por vida, y por eso se convirtió en la referencia.",
    "q.m21#10.p" to "[Opción múltiple] ¿Qué se necesita normalmente para hacer cima en un ochomil?",
    "q.m21#10.o0" to "Un ciclo completo de aclimatación con rotaciones de campo alto",
    "q.m21#10.o1" to "Capacidad técnica y experiencia en progresión glaciar",
    "q.m21#10.o2" to "Un sistema fiable de oxígeno y de logística",
    "q.m21#10.o3" to "Forma física y criterio validados a 7.000 m",
    "q.m21#10.o4" to "Un equipo profesional de rodaje",
    "q.m21#10.e" to "Los cuatro corresponden a cuatro dimensiones: fisiológica (aclimatación), técnica, logística y experiencia acumulada. Todas actúan a la vez a 8.000 m; si falta una, se convierte en eslabón débil, y los eslabones débiles se amplifican rápido en altitud.",
    "q.m21#11.p" to "El Dhaulagiri, el Manaslu y el Annapurna están en qué país?",
    "q.m21#11.o0" to "China",
    "q.m21#11.o1" to "Nepal",
    "q.m21#11.o2" to "Pakistán",
    "q.m21#11.o3" to "India",
    "q.m21#11.e" to "Los tres están en Nepal. Nepal concentra el mayor número de ochomiles, y por eso su industria de la escalada está tan desarrollada, y también por eso afronta una presión constante en permisos, gestión y protección ambiental.",
    "q.m21#12.p" to "¿Por qué las «rutas comerciales maduras» en ochomiles siguen siendo peligrosas?",
    "q.m21#12.o0" to "Porque son caras",
    "q.m21#12.o1" to "Porque la altitud en sí no se puede cambiar, y las aglomeraciones, las esperas y un rescate difícil crean riesgos nuevos",
    "q.m21#12.o2" to "Porque los guías no son profesionales",
    "q.m21#12.o3" to "Porque el material es malo",
    "q.m21#12.e" to "La comercialización resuelve la logística y el conocimiento de la ruta, pero no puede bajar la altitud. Al contrario, que muchos equipos empujen en la misma ventana genera colas, y esperar a 8.000 m significa quemar oxígeno y calor corporal de más.",
    "q.m21#13.p" to "[Ordenar] Ordena estos picos de mayor a menor.",
    "q.m21#13.o0" to "Everest (8.848)",
    "q.m21#13.o1" to "Kangchenjunga (8.586)",
    "q.m21#13.o2" to "Makalu (8.485)",
    "q.m21#13.o3" to "Annapurna I (8.091)",
    "q.m21#13.e" to "Detrás del orden está el tramo del número uno al número diez del mundo. Recordar el orden es más útil que recordar cifras exactas: al hablar de rutas, logística y dificultad, lo que sueles necesitar es la posición relativa.",
    "q.m21#14.p" to "¿Por qué estudiar la historia de las primeras ascensiones al aprender sobre ochomiles?",
    "q.m21#14.o0" to "Para los exámenes",
    "q.m21#14.o1" to "Porque las primeras ascensiones suelen dejar al descubierto las dificultades centrales y los tipos de riesgo del pico",
    "q.m21#14.o2" to "Para memorizar nombres",
    "q.m21#14.o3" to "No tiene nada que ver con escalar",
    "q.m21#14.e" to "Los fracasos y las pérdidas de los primeros equipos señalan justamente las dificultades principales de una montaña: tramos de alud recurrentes, tramos de viento violento, partes de ruta expuestas. Leer la historia de las primeras ascensiones como un expediente de riesgos es mucho más útil que leerla como un relato.",
    "q.m21#15.p" to "[Opción múltiple] ¿Cuáles de estos son ochomiles del Himalaya?",
    "q.m21#15.o0" to "Everest",
    "q.m21#15.o1" to "Annapurna I",
    "q.m21#15.o2" to "Shishapangma",
    "q.m21#15.o3" to "K2",
    "q.m21#15.e" to "Los tres primeros están en el Himalaya; el K2 está en el Karakórum. Las dos cordilleras son geográficamente contiguas pero geológicamente distintas, y sus temporadas y patrones meteorológicos difieren; por eso los catorce suelen tratarse agrupados por cordillera.",
    "q.m21#16.p" to "¿Cómo afecta el título de «pico más alto del mundo» a la estrategia?",
    "q.m21#16.o0" to "En nada",
    "q.m21#16.o1" to "Significa la mayor atención mediática y comercial, y por tanto la mayor densidad de equipos y riesgo de aglomeración",
    "q.m21#16.o2" to "Significa la ruta más fácil",
    "q.m21#16.o3" to "Significa el rescate más fácil",
    "q.m21#16.e" to "La atención trae recursos y también multitudes. Cuando muchos equipos se concentran en una ventana, las esperas, las colas y la presión psicológica de no querer perder el turno se convierten en fuentes adicionales de riesgo: un problema de estrategia propio del pico más alto.",
    "q.m21#17.p" to "Completa: en el mundo hay ( ) picos por encima de 8.000 m.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "catorce",
    "q.m21#17.e" to "Catorce. Un número pequeño, y sin embargo define todo el límite de la escalada de alta montaña; por eso «los catorce» se sigue tratando como un objetivo que merece una vida.",
    // m22 — Karakórum y escala de dificultad
    "q.m22#0.p" to "¿Cuántos ochomiles hay en el Karakórum?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Cuatro: K2, Gasherbrum I, Gasherbrum II y Broad Peak. También se les conoce como K2, K4, K5 y K3; la K significa Karakórum.",
    "q.m22#1.p" to "¿Cuáles son la altitud y la posición del K2?",
    "q.m22#1.o0" to "8.611 m, segundo más alto del mundo, y entre los ochomiles más técnicos y mortales",
    "q.m22#1.o1" to "8.848 m, el más alto del mundo",
    "q.m22#1.o2" to "8.586 m, tercero más alto del mundo",
    "q.m22#1.o3" to "8.051 m, uno de los más fáciles",
    "q.m22#1.e" to "El K2 tiene 8.611 m, segundo más alto del mundo. Se le considera ampliamente uno de los ochomiles más duros y peligrosos, y por eso se le llama «la montaña de los escaladores»: aquí la técnica y el criterio pesan mucho más que el apoyo logístico.",
    "q.m22#2.p" to "¿Por qué el Karakórum y el Himalaya suelen tener temporadas de escalada distintas?",
    "q.m22#2.o0" to "Por sus distintas latitudes y longitudes",
    "q.m22#2.o1" to "Porque les afectan sistemas climáticos distintos: el Karakórum está más influido por los vientos del oeste",
    "q.m22#2.o2" to "Por sus distintas altitudes",
    "q.m22#2.o3" to "Por normativas distintas",
    "q.m22#2.e" to "La mejor temporada del Himalaya la marca sobre todo el ciclo del monzón, mientras que el Karakórum está más afectado por los vientos del oeste y la precipitación orográfica. Eso decide cuándo ir; y con la temporada equivocada, ni el mejor equipo verá una ventana de cima.",
    "q.m22#3.p" to "¿Cómo se llama también el Broad Peak?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "El Broad Peak es también el K3, con 8.051 m. Su terreno es relativamente abierto, pero las nevadas son copiosas y los vientos fuertes frecuentes; históricamente ha registrado varios accidentes por haberlo subestimado.",
    "q.m22#4.p" to "¿Cómo se llaman también el Gasherbrum I y el II?",
    "q.m22#4.o0" to "K4 y K5",
    "q.m22#4.o1" to "K5 y K4",
    "q.m22#4.o2" to "K2 y K3",
    "q.m22#4.o3" to "K3 y K4",
    "q.m22#4.e" to "El Gasherbrum I es el K5 (8.080 m) y el Gasherbrum II es el K4 (8.035 m): la numeración no sigue el orden de altitud, y eso es justo lo que la hace confusa. Recuerda que los números K no están ordenados por altura y no te equivocarás.",
    "q.m22#5.p" to "Los catorce ochomiles están todos en qué dos cordilleras?",
    "q.m22#5.o0" to "Himalaya y Tian Shan",
    "q.m22#5.o1" to "Himalaya y Karakórum",
    "q.m22#5.o2" to "Karakórum y Alpes",
    "q.m22#5.o3" to "Nyainqêntanglha y Himalaya",
    "q.m22#5.e" to "Todos están en el Himalaya y el Karakórum, cordilleras geográficamente contiguas pero sometidas a sistemas climáticos distintos. Lo cual vuelve a mostrar que a 8.000 m la geografía en sí es información clave.",
    "q.m22#6.p" to "[Emparejar] Relaciona cada pico con su altitud.",
    "q.m22#6.l0" to "K2",
    "q.m22#6.r0" to "8.611 m",
    "q.m22#6.l1" to "Nanga Parbat",
    "q.m22#6.r1" to "8.126 m",
    "q.m22#6.l2" to "Gasherbrum I",
    "q.m22#6.r2" to "8.080 m",
    "q.m22#6.l3" to "Shishapangma",
    "q.m22#6.r3" to "8.027 m",
    "q.m22#6.e" to "Son el segundo, el noveno, el undécimo y el decimocuarto pico más altos. Abarcan un rango amplio y comparten la misma condición dentro de «por encima de 8.000 m», que es justamente lo peculiar de esta clase: un límite claro con una variación interna enorme.",
    "q.m22#7.p" to "¿Cuál es la visión correcta de la relación entre ránking de ochomiles y dificultad?",
    "q.m22#7.o0" to "Más alto siempre significa más difícil",
    "q.m22#7.o1" to "La dificultad la fijan sobre todo el terreno técnico, el clima y la logística, y no se corresponde directamente con el ránking de altitud",
    "q.m22#7.o2" to "Más bajo siempre significa más fácil",
    "q.m22#7.o3" to "La dificultad no se puede comparar en absoluto",
    "q.m22#7.e" to "Es la idea más importante que da la panorámica de los catorce: el Cho Oyu, con 8.188 m, se considera relativamente fácil, mientras que el K2, con 8.611 m, está entre los más duros: menos de 500 m de diferencia de altitud y umbrales reales a mundos de distancia.",
    "q.m22#8.p" to "[Opción múltiple] ¿Qué determina la dificultad real de un ochomil?",
    "q.m22#8.o0" to "El terreno técnico y la exposición",
    "q.m22#8.o1" to "El clima y las ventanas meteorológicas",
    "q.m22#8.o2" to "La logística y la aproximación",
    "q.m22#8.o3" to "La viabilidad del rescate",
    "q.m22#8.o4" to "El ránking de altitud del pico",
    "q.m22#8.e" to "Los cuatro importan. La viabilidad del rescate se ignora a menudo: una montaña donde el rescate es casi imposible tiene un nivel de riesgo completamente distinto aunque la ruta no sea difícil, porque no hay margen cuando algo va mal.",
    "q.m22#9.p" to "[Ordenar] Ordena estos picos de mayor a menor.",
    "q.m22#9.o0" to "K2 (8.611)",
    "q.m22#9.o1" to "Nanga Parbat (8.126)",
    "q.m22#9.o2" to "Gasherbrum I (8.080)",
    "q.m22#9.o3" to "Shishapangma (8.027)",
    "q.m22#9.e" to "Este orden cubre la segunda mitad de los catorce. Sumado al orden de la lección anterior, ya tienes la secuencia completa de altitudes, que es la base para juzgar a qué escalón pertenece cada montaña.",
    "q.m22#10.p" to "¿Por qué «los catorce» es un objetivo tan exigente?",
    "q.m22#10.o0" to "Porque es extremadamente caro",
    "q.m22#10.o1" to "Porque exige sostener técnica, forma física, aclimatación y criterio durante muchos años, con sistemas logísticos en varios países",
    "q.m22#10.o2" to "Porque lleva demasiado tiempo",
    "q.m22#10.o3" to "Porque los permisos son difíciles de conseguir",
    "q.m22#10.e" to "Los catorce suelen llevar más de una década, durante la cual el cuerpo envejece y las circunstancias de la vida cambian. No pone a prueba solo la capacidad de escalar, sino la constancia del mantenimiento a largo plazo y de la gestión del riesgo.",
    "q.m22#11.p" to "¿Por qué el éxito a 8.000 m depende a menudo de la ventana meteorológica más que de la técnica?",
    "q.m22#11.o0" to "Porque la técnica no importa",
    "q.m22#11.o1" to "Porque incluso con técnica suficiente, esperar mucho tiempo en altitud consume tu margen de seguridad",
    "q.m22#11.o2" to "Porque la técnica se aprende en la montaña",
    "q.m22#11.o3" to "Porque los guías lo resuelven todo",
    "q.m22#11.e" to "Es la realidad de los 8.000 m: la técnica es solo la entrada, y la ventana decide si puedes pasar mientras aún tienes capacidad. Por eso los itinerarios de ochomil suelen presupuestar días de reserva generosos.",
    "q.m22#12.p" to "Si solo pudieras elegir un ochomil como primero, ¿cuál es el planteamiento más sensato?",
    "q.m22#12.o0" to "Ir directamente al K2 y quitárselo de encima",
    "q.m22#12.o1" to "Elegir uno con ruta madura, logística fiable y rescate viable, y dedicar esa «primera vez» a acumular experiencia",
    "q.m22#12.o2" to "Elegir simplemente el más bajo",
    "q.m22#12.o3" to "Elegir cualquiera; todos son iguales",
    "q.m22#12.e" to "El valor de un primer ochomil es aprender tu estado real en la zona de la muerte: cómo usas el oxígeno, cuánto baja tu criterio, cuál es tu ritmo. Gastarlo en una montaña más dura significa poner a prueba varios desconocidos a la vez.",
    "q.m22#13.p" to "[Opción múltiple] ¿Cuáles de estos son ochomiles del Karakórum?",
    "q.m22#13.o0" to "K2",
    "q.m22#13.o1" to "Gasherbrum I",
    "q.m22#13.o2" to "Gasherbrum II",
    "q.m22#13.o3" to "Broad Peak",
    "q.m22#13.o4" to "Manaslu",
    "q.m22#13.e" to "Los cuatro son del Karakórum; de hecho son todos los ochomiles de esa cordillera. Por eso «los cuatro del Karakórum» es una expresión fija, y con los diez del Himalaya suman exactamente catorce.",
    "q.m22#14.p" to "¿Cuál es el beneficio más práctico de estudiar los catorce en conjunto?",
    "q.m22#14.o0" to "Poder recitar todas las altitudes",
    "q.m22#14.o1" to "Entender por qué dificultad y altitud no son lo mismo, y usar eso para valorar tus propios objetivos",
    "q.m22#14.o2" to "Poder guiar a otros",
    "q.m22#14.o3" to "Poder escribir guías de rutas",
    "q.m22#14.e" to "El valor real es construir una visión multidimensional de la dificultad: las dimensiones técnica, climática, logística y de rescate determinan juntas el umbral real de una montaña. El mismo marco sirve para elegir entre cinco miles y seises miles.",
    "q.m22#15.p" to "¿Por qué la propia aproximación a un ochomil puede ser un factor de riesgo?",
    "q.m22#15.o0" to "Porque lleva mucho tiempo",
    "q.m22#15.o1" to "Porque la aproximación cruza a menudo glaciares y terreno de aludes mientras el equipo aún no está bien aclimatado",
    "q.m22#15.o2" to "Porque el paisaje es pobre",
    "q.m22#15.o3" to "Porque requiere permisos",
    "q.m22#15.e" to "La aproximación suele ocurrir en la fase de ascenso, cuando la aclimatación es peor y el criterio menos estable, y además hay que gestionar grietas y terreno de aludes. Ese periodo doblemente vulnerable es cuando se producen muchos accidentes.",
    "q.m22#16.p" to "Si estuvieras construyendo tu propia lista de objetivos de ochomil, ¿qué deberías determinar primero?",
    "q.m22#16.o0" to "Los nombres de las montañas que quieres",
    "q.m22#16.o1" to "Tus propios puntos débiles (técnica, aclimatación, criterio o experiencia logística), y después buscar picos que los cubran",
    "q.m22#16.o2" to "El presupuesto",
    "q.m22#16.o3" to "La duración de tus vacaciones",
    "q.m22#16.e" to "Elegir por punto débil trata los 8.000 m como un camino de crecimiento y no como una colección de logros. La misma montaña vale cosas distintas para personas distintas, según cuál de tus carencias cubra.",
    // m23 — Situaciones integradas
    "q.m23#0.p" to "[Situación] Un compañero a 4.500 m tiene dolor de cabeza y náuseas e insiste en que «con un día más de aclimatación estaré bien para subir». Desde el punto de vista de la ciencia ambiental, ¿cuál es el juicio correcto?",
    "q.m23#0.o0" to "Un día más lo arreglará seguro: animarle a seguir",
    "q.m23#0.o1" to "Los síntomas significan que la compensación es insuficiente; no seguir ascendiendo mientras los síntomas persistan",
    "q.m23#0.o2" to "Dar medicación y seguir ascendiendo",
    "q.m23#0.o3" to "Basta con descender 100 m",
    "q.m23#0.e" to "La cadena empieza en la causalidad más básica: baja presión → baja presión parcial de oxígeno → el cuerpo necesita tiempo. Los síntomas son la señal de que el tiempo no basta, y un día más no garantiza mejorar; lo correcto es dejar de ascender, no apostar al mañana.",
    "q.m23#1.p" to "[Opción múltiple] Un miembro del equipo se dirige a una ladera de nieve dura a 5.000 m. ¿Qué elementos hay que confirmar?",
    "q.m23#1.o0" to "Crampones estrictamente ajustados a las botas",
    "q.m23#1.o1" to "Un piolet proporcionado a su estatura",
    "q.m23#1.o2" to "Gafas de glaciar UV400 y protector solar de factor alto",
    "q.m23#1.o3" to "Capas de aislamiento y cortavientos coherentes con el sistema de capas",
    "q.m23#1.o4" to "Cámara y baterías de repuesto para las fotos de cima",
    "q.m23#1.e" to "Los cuatro corresponden a cuatro tipos de riesgo: resbalar (crampones), detenerse (piolet), UV (gafas y protector) e hipotermia (capas). La forma correcta de revisar el material es construir la lista desde los riesgos, no coger cosas por costumbre.",
    "q.m23#2.p" to "[Emparejar] Relaciona cada capa del sistema de vestimenta con su función.",
    "q.m23#2.l0" to "Primera capa",
    "q.m23#2.r0" to "Aleja el sudor de la piel y te mantiene seco",
    "q.m23#2.l1" to "Capa intermedia",
    "q.m23#2.r1" to "Retiene una capa de aire para abrigar (el forro polar aísla incluso mojado)",
    "q.m23#2.l2" to "Capa exterior",
    "q.m23#2.r2" to "Impermeable, cortavientos y transpirable; te protege del tiempo",
    "q.m23#2.l3" to "Plumífero (en frío extremo)",
    "q.m23#2.r3" to "El abrigo más eficiente en un entorno seco",
    "q.m23#2.e" to "Cada capa hace un trabajo. Cuando ves esa división entiendes por qué «más capas es más calor» es falso: si te saltas la capa que evacua el sudor, llevas tu propio microclima húmedo encima, y una capa exterior no transpirable encierra el vapor dentro.",
    "q.m23#3.p" to "[Situación] Al subir una ladera de nieve, el de delante pisa escalones irregulares. ¿Cuál es la consecuencia más probable?",
    "q.m23#3.o0" to "El equipo avanza más rápido",
    "q.m23#3.o1" to "Los de atrás tienen que reajustar el equilibrio constantemente, gastan más energía y pierden estabilidad",
    "q.m23#3.o2" to "La ladera colapsará",
    "q.m23#3.o3" to "Ningún efecto",
    "q.m23#3.e" to "Los escalones son la base del equipo. Escalones irregulares obligan a todos a buscar apoyos continuamente, encima de la capacidad de equilibrio que ya es escasa en altitud: un caso de manual de problemas pequeños que se acumulan en riesgo grande.",
    "q.m23#4.p" to "[Ordenar] Ordena correctamente la secuencia de autodetención con piolet.",
    "q.m23#4.o0" to "Agarrar el piolet con firmeza, confirmando que la presa es correcta",
    "q.m23#4.o1" to "Girarse sobre el vientre, mirando a la nieve",
    "q.m23#4.o2" to "Clavar la punta en la nieve usando el peso del cuerpo",
    "q.m23#4.o3" to "Levantar los pies para que los crampones no se enganchen y te hagan rodar",
    "q.m23#4.e" to "Esta secuencia es la base de todo el sistema técnico. Tiene que salir sin pensar: en una caída real tu capacidad de pensar tiene una ventana de uno o dos segundos, y esos dos segundos los ocupa por completo la memoria muscular.",
    "q.m23#5.p" to "[Situación] Un escalador cae en una ladera de nieve dura y la detención falla. ¿Cuál es la causa más probable al analizarlo?",
    "q.m23#5.o0" to "El piolet era demasiado corto",
    "q.m23#5.o1" to "La punta no pudo morder en nieve dura, y una ladera de nieve dura debería haberse protegido con cuerda fija",
    "q.m23#5.o2" to "Las botas eran las equivocadas",
    "q.m23#5.o3" to "No llevaban guantes",
    "q.m23#5.e" to "El éxito de la detención baja de forma notable en nieve dura y hielo; es el límite de la propia técnica. Así que la pregunta real suele ser anterior: ¿por qué estábamos en una ladera inclinada de nieve dura sin ningún sistema de protección?",
    "q.m23#6.p" to "[Opción múltiple] ¿Qué riesgos se pasan por alto con facilidad durante el descenso?",
    "q.m23#6.o0" to "La forma física que baja y debilita el control de las piernas",
    "q.m23#6.o1" to "La alerta que cae una vez logrado el objetivo",
    "q.m23#6.o2" to "La nieve que se hiela o se ablanda, así que las condiciones difieren de las de la subida",
    "q.m23#6.o3" to "La luz que se va reduciendo visibilidad y criterio",
    "q.m23#6.o4" to "Que las rutas de descenso suelen ser más cortas que las de subida",
    "q.m23#6.e" to "Junta esos cuatro y tendrás la explicación de por qué tantos accidentes ocurren bajando. El descenso no es el viaje a casa con el trabajo hecho: es un tramo que necesita su propio plan y conlleva un riesgo comparable.",
    "q.m23#7.p" to "[Situación] La válvula de la bolsa de hidratación se hiela rápido con el frío. ¿Qué hay que hacer?",
    "q.m23#7.o0" to "Pasar a una cantimplora aislada de boca ancha y, tras cada sorbo, soplar el agua hacia atrás o guardarla invertida",
    "q.m23#7.o1" to "Seguir usándola y esperar a que se descongele",
    "q.m23#7.o2" to "Llevar la bolsa por fuera de la mochila",
    "q.m23#7.o3" to "Dejar de beber",
    "q.m23#7.e" to "Una técnica pequeña pero crítica: la deshidratación en altitud no suele ser «no llevé agua», sino «el agua se congeló y no pude beber». Diseñar un sistema de bebida que no se congele es lo que de verdad significa estar preparado para hidratarse.",
    "q.m23#8.p" to "Completa: la temperatura baja aproximadamente ( ) °C por cada 1.000 m de ascenso.",
    "q.m23#8.a0" to "6,5",
    "q.m23#8.a1" to "6.5",
    "q.m23#8.e" to "6,5 °C. Este número recorre todo el curso: explica el límite de las nieves, fija el grosor que necesita tu aislamiento y determina cómo cambian las condiciones de alud y de hielo. Entenderlo significa poder razonar con él.",
    "q.m23#9.p" to "[Situación] A 5.000 m las gafas se empañan mucho y ya no puedes leer el terreno. ¿Cuál es el riesgo más importante?",
    "q.m23#9.o0" to "Es solo una incomodidad",
    "q.m23#9.o1" to "Pierdes la base del juicio del terreno y puedes desviarte hacia una ladera inclinada, una cornisa o un campo de grietas",
    "q.m23#9.o2" to "Te dará ceguera de la nieve",
    "q.m23#9.o3" to "Tus compañeros se quejarán",
    "q.m23#9.e" to "«No ver» significa en realidad perder la evidencia con la que juzgas. En terreno de nieve complejo, uno o dos apoyos equivocados pueden costar muy caro. Por eso «¿veo con claridad?» debe tratarse como un criterio duro de fiabilidad del material.",
    "q.m23#10.p" to "[Opción múltiple] Un miembro del equipo pierde el apetito de forma severa en altitud. ¿Qué hay que hacer?",
    "q.m23#10.o0" to "Comer activamente en pequeñas cantidades y a menudo, eligiendo alimentos ricos en hidratos y fáciles de digerir",
    "q.m23#10.o1" to "Asegurar una ingesta de líquidos constante y adecuada",
    "q.m23#10.o2" to "Tratar la pérdida de apetito como una posible señal de aclimatación que hay que vigilar",
    "q.m23#10.o3" to "Sustituir las comidas por grandes cantidades de café y bebidas energéticas",
    "q.m23#10.e" to "Las tres primeras son correctas; la cuarta es errónea de una forma muy representativa: la cafeína da una sensación temporal pero no sustituye la energía. En altitud, una ingesta energética insuficiente debilita directamente la aclimatación y crea un círculo vicioso.",
    "q.m23#11.p" to "[Situación] En una ladera de nieve a 5.000 m el móvil pasa del 40 % a apagarse de golpe. ¿Cuál es la respuesta más sensata?",
    "q.m23#11.o0" to "Calentarlo contra el cuerpo y volver a encenderlo",
    "q.m23#11.o1" to "Encenderlo una y otra vez",
    "q.m23#11.o2" to "Renunciar a la electrónica",
    "q.m23#11.o3" to "Usar lo que queda de batería para enviar un mensaje de socorro",
    "q.m23#11.e" to "Es el comportamiento típico de una batería de litio con frío: la capacidad se derrumba sin que la carga se haya ido. Calentarla contra el cuerpo suele devolverle la energía. La lección: gestionar la electrónica como material de seguridad que puede fallar sin aviso.",
    "q.m23#12.p" to "[Ordenar] Ordena de forma sensata una revisión completa del material.",
    "q.m23#12.o0" to "Construir la lista desde los riesgos (qué exige el terreno, el tiempo y la altitud)",
    "q.m23#12.o1" to "Revisar cada elemento en cuanto a completitud y estado de funcionamiento",
    "q.m23#12.o2" to "Ponerse y probar los elementos críticos (crampones, arnés, casco, frontal)",
    "q.m23#12.o3" to "Registrar y comunicar a los compañeros el estado del material y el plan de reserva",
    "q.m23#12.e" to "La clave es el paso tres, la prueba real: completo no significa que funcione. Una hebilla de crampón mal asentada o una pila vieja en el frontal solo aparecen cuando te lo pones y lo usas.",
    "q.m23#13.p" to "[Situación] El equipo decide descender por el tiempo, pero un miembro insiste en continuar argumentando «hemos llegado hasta aquí». ¿Cuál es la mejor forma de manejarlo?",
    "q.m23#13.o0" to "Respetar su decisión y dejar que siga solo",
    "q.m23#13.o1" to "Insistir en que todo el equipo descienda junto: no se permite ir solo en altitud, y la terquedad allí arriba puede ser ella misma hipoxia",
    "q.m23#13.o2" to "Someterlo a votación",
    "q.m23#13.o3" to "Hacerle esperar una hora y luego decidir",
    "q.m23#13.e" to "Dos razones: ir solo en altitud es extremadamente arriesgado, y «hemos llegado hasta aquí» es la formulación de manual del coste irrecuperable; en altitud, esa emoción y el criterio deteriorado tienden a ir entrelazados, así que no puede tratarse como un dato fiable.",
    "q.m23#14.p" to "Sobre si la gente más en forma es más propensa al mal de altura, ¿qué es correcto?",
    "q.m23#14.o0" to "Cuanto mejor estás en forma, menos probable es que te dé",
    "q.m23#14.o1" to "El mal de altura no tiene relación directa con la forma física; se relaciona con el ritmo de ascenso, la altitud de pernocta y la respuesta individual",
    "q.m23#14.o2" to "Cuanto mejor estás en forma, más probable es que te dé",
    "q.m23#14.o3" to "Solo le da a la gente poco en forma",
    "q.m23#14.e" to "Confundir forma física con aclimatación es el error de principiante más común. De hecho, la gente más en forma puede meterse en más problemas precisamente porque camina más rápido y sube más alto: una trampa muy real.",
    "q.m23#15.p" to "[Opción múltiple] ¿Qué prácticas reducen de verdad el riesgo de caída?",
    "q.m23#15.o0" to "Usar el piolet para autoprotegerse de forma continua mientras se avanza",
    "q.m23#15.o1" to "Mantener un ritmo constante y sostenible, sin esfuerzos bruscos",
    "q.m23#15.o2" to "Avanzar al ritmo del miembro más lento del equipo",
    "q.m23#15.o3" to "Instalar cuerdas fijas en laderas de nieve dura y de hielo",
    "q.m23#15.o4" to "Frenar menos y bajar más rápido",
    "q.m23#15.e" to "Los cuatro corresponden a técnica personal, control del ritmo, coordinación de equipo y protección con sistemas. Prevenir caídas nunca es una sola acción, sino toda una capa de seguros sobre seguros.",
    "q.m23#16.p" to "[Situación] Durante un descanso en una ladera de nieve, un miembro del equipo deja el piolet clavado y se aleja. ¿Qué riesgo crea?",
    "q.m23#16.o0" to "Que se puede perder el piolet",
    "q.m23#16.o1" to "Que si cae, no tiene ninguna herramienta para detenerse",
    "q.m23#16.o2" to "Que alguien lo pise",
    "q.m23#16.o3" to "Ningún riesgo",
    "q.m23#16.e" to "Las caídas ocurren muy rápido, y el piolet es tu único medio de detención. Dejarlo en la nieve significa renunciar temporalmente a esa capacidad, y en una ladera de nieve «temporalmente» es justo el intervalo más peligroso.",
    "q.m23#17.p" to "¿Qué capacidad central evalúa esta lección?",
    "q.m23#17.o0" to "Memorizar todas las cifras",
    "q.m23#17.o1" to "Combinar conocimientos de entorno, material, vestimenta y técnica de movimiento para juzgar bien una situación concreta",
    "q.m23#17.o2" to "Recitar toda la terminología",
    "q.m23#17.o3" to "Conocer bien las marcas de material",
    "q.m23#17.e" to "Es la lógica de diseño de todo el curso: los datos aislados son fáciles de memorizar, pero en la montaña te enfrentas a problemas de combinación. Saber encadenar varios conocimientos en una situación concreta es lo que significa dominio real.",
    // m24 — Autoevaluación final
    "q.m24#0.p" to "[Situación] Un compañero ha caído en una grieta y tu cuerpo sostiene su peso solo. ¿Qué va primero?",
    "q.m24#0.o0" to "Empezar a izar de inmediato",
    "q.m24#0.o1" to "Montar una reunión y transferir primero la carga, y luego pensar en izar",
    "q.m24#0.o2" to "Pedir ayuda primero",
    "q.m24#0.o3" to "Hacer una foto para el registro",
    "q.m24#0.e" to "Mientras el peso esté sobre ti, no tienes capacidad de operar el sistema. Así que reunión, luego transferencia, luego izar: el orden no se puede invertir. Es la regla más práctica de todo el sistema de rescate, y el paso que más se salta bajo estrés.",
    "q.m24#1.p" to "[Emparejar] Relaciona cada nudo con su uso.",
    "q.m24#1.l0" to "Ocho",
    "q.m24#1.r0" to "Unir el arnés a una reunión",
    "q.m24#1.l1" to "Pescador doble",
    "q.m24#1.r1" to "Unir dos cuerdas o hacer un anillo de cordín",
    "q.m24#1.l2" to "Prusik",
    "q.m24#1.r2" to "Nudo de fricción, agarra en un solo sentido",
    "q.m24#1.l3" to "As de guía",
    "q.m24#1.r3" to "Unirse a una reunión; habitual en náutica",
    "q.m24#1.e" to "Estos cuatro cubren la mayor parte de la progresión glaciar y de la protección básica. El sentido de evaluarlos: hay que saber hacerlos a oscuras y con guantes.",
    "q.m24#2.p" to "[Situación] El ángulo de cinta entre dos anclajes está cerca de 100°. ¿Qué significa?",
    "q.m24#2.o0" to "La carga se reparte más uniformemente",
    "q.m24#2.o1" to "La carga sobre cada anclaje sube de forma notable (cuanto más abierto el ángulo, mayor la carga por anclaje)",
    "q.m24#2.o2" to "No tiene ningún efecto",
    "q.m24#2.o3" to "La cuerda se equilibra sola automáticamente",
    "q.m24#2.e" to "Las cifras son intuitivas: alrededor del 50 % por anclaje a 0°, alrededor del 58 % a 60° y alrededor del 71 % a 90°. A 100° cada anclaje carga muchísimo, y por eso la práctica mantiene el ángulo dentro de 60°.",
    "q.m24#3.p" to "[Opción múltiple] ¿Qué debe tener un sistema de reunión adecuado?",
    "q.m24#3.o0" to "Cada punto individual, sólido",
    "q.m24#3.o1" to "Independencia de fallo entre puntos (sin redundancia falsa)",
    "q.m24#3.o2" to "Reparto razonable de la carga, pretensado",
    "q.m24#3.o3" to "Montaje rápido, para acortar la exposición",
    "q.m24#3.o4" to "El menor número de puntos posible para ahorrar material",
    "q.m24#3.e" to "Los tres primeros son requisitos de seguridad; el cuarto es un requisito de eficiencia, y la eficiencia también es seguridad, porque el propio montaje es tiempo expuesto al riesgo.",
    "q.m24#4.p" to "[Situación] Un compañero empieza a tambalearse al caminar y está confuso. ¿Cuál es la prioridad?",
    "q.m24#4.o0" to "Dar oxígeno y observar",
    "q.m24#4.o1" to "Descender de inmediato y administrar dexametasona bajo supervisión médica",
    "q.m24#4.o2" to "Seguir ascendiendo para llegar antes al campamento",
    "q.m24#4.o3" to "Tomar analgésicos y descansar",
    "q.m24#4.e" to "La ataxia y la alteración de la consciencia son los signos centrales del ECA, una urgencia médica. El descenso es el único tratamiento definitivo; la dexametasona solo compra tiempo para el descenso: no son alternativas.",
    "q.m24#5.p" to "[Opción múltiple] ¿Qué afirmaciones sobre la medicación de altitud son correctas?",
    "q.m24#5.o0" to "La dexametasona no influye en la aclimatación ni trata el edema pulmonar",
    "q.m24#5.o1" to "La acetazolamida acelera la aclimatación; se empieza un día antes del ascenso y se suspende unos dos días después",
    "q.m24#5.o2" to "El nifedipino puede provocar una caída rápida de la tensión arterial",
    "q.m24#5.o3" to "La medicación no puede sustituir al descenso",
    "q.m24#5.o4" to "La acetazolamida puede sustituir el proceso de aclimatación del organismo",
    "q.m24#5.e" to "Las cuatro primeras son puntos clave, y su conclusión común es que la medicación no puede sustituir al descenso: se tome lo que se tome, el descenso sigue siendo el tratamiento fundamental. Los fármacos solo compran las condiciones para ello.",
    "q.m24#6.p" to "[Situación] Un miembro del equipo deja de tiritar con el frío y arrastra las palabras. ¿Qué NO hay que hacer?",
    "q.m24#6.o0" to "Cambiarle la ropa mojada y abrigarle",
    "q.m24#6.o1" to "Hacerle caminar para que genere calor",
    "q.m24#6.o2" to "Recalentar primero el tronco",
    "q.m24#6.o3" to "Evitar manipularlo con brusquedad",
    "q.m24#6.e" to "«Dejar de tiritar» significa hipotermia moderada o peor, y un corazón frío es muy susceptible a las arritmias. Hacer caminar al paciente o manipularlo con brusquedad puede desencadenarla directamente: la regla más contraintuitiva de los primeros auxilios en hipotermia.",
    "q.m24#7.p" to "[Ordenar] Ordena los cuatro pasos de un rescate de cordada.",
    "q.m24#7.o0" to "Autodetener la caída y estabilizarse",
    "q.m24#7.o1" to "Montar una reunión independiente",
    "q.m24#7.o2" to "Transferir la carga a la reunión",
    "q.m24#7.o3" to "Izar con un sistema 3:1",
    "q.m24#7.e" to "Los cuatro no se pueden reordenar. En un examen quizá puedas recitarlos; en la realidad hay que completar los tres primeros en decenas de segundos: ese es el umbral real de este conocimiento.",
    "q.m24#8.p" to "[Situación] El pronóstico dice «nublado», pero ves cúmulos creciendo rápido en vertical. ¿Qué hay que hacer?",
    "q.m24#8.o0" to "Fiarse del pronóstico y seguir el plan",
    "q.m24#8.o1" to "Decidir suponiendo que puede empeorar, y plantearte descender antes",
    "q.m24#8.o2" to "Esperar una hora y volver a mirar",
    "q.m24#8.o3" to "Seguir subiendo pero más rápido",
    "q.m24#8.e" to "Un pronóstico da el fondo regional; la nube que tienes delante es evidencia del aquí y ahora. Cuando entran en conflicto, gana el terreno. Tanto más cuanto que el desarrollo de cúmulos en altitud se mide a menudo en minutos.",
    "q.m24#9.p" to "[Opción múltiple] ¿Qué prácticas son correctas al cruzar terreno de aludes?",
    "q.m24#9.o0" to "Cruzar de uno en uno, manteniendo distancia",
    "q.m24#9.o1" to "Colocar un vigía en una posición segura",
    "q.m24#9.o2" to "Planificar de antemano la vía de escape y el punto de reunión",
    "q.m24#9.o3" to "Cruzar todo el equipo junto y rápido para reducir la exposición",
    "q.m24#9.e" to "Las tres primeras limitan el riesgo a una persona; «todos a la vez» lo amplifica al nivel de equipo: de sepultar quizá a uno a sepultar quizá a todos, y por eso es la opción menos aceptable.",
    "q.m24#10.p" to "[Situación] El equipo está a una hora de la cima pero ya ha pasado la hora límite de regreso. ¿Qué es correcto?",
    "q.m24#10.o0" to "Continuar a la cima, si solo es una hora",
    "q.m24#10.o1" to "Dar media vuelta de inmediato: toda la utilidad de una hora límite es que funcione justo en el «solo un poco más»",
    "q.m24#10.o2" to "Ampliarla media hora",
    "q.m24#10.o3" to "Dejar que siga el miembro más en forma",
    "q.m24#10.e" to "Lo que esta pregunta prueba de verdad es para qué sirve una hora límite. Si solo se obedece cuando todo es fácil y se puede relajar en el «solo un poco más», entonces nunca existió, y es justo ahí donde ocurren los accidentes.",
    "q.m24#11.p" to "[Opción múltiple] ¿Cuáles son prácticas correctas de decisión de equipo en entornos de alto riesgo?",
    "q.m24#11.o0" to "Cuantificar las señales de retirada antes de salir",
    "q.m24#11.o1" to "Que prevalezca la opinión más conservadora",
    "q.m24#11.o2" to "Invitar a propósito a la disidencia (por ejemplo, preguntando uno por uno)",
    "q.m24#11.o3" to "La regla de la mayoría",
    "q.m24#11.e" to "Las tres primeras forman juntas el mecanismo contra el error colectivo; la regla de la mayoría hace lo contrario: silencia la preocupación legítima de la minoría, y a menudo es esa minoría la que notó antes la señal de peligro.",
    "q.m24#12.p" to "[Situación] Las comunicaciones están caídas y debías contactar con quienes esperan en casa hace una hora. ¿Qué hay que hacer?",
    "q.m24#12.o0" to "Seguir según lo previsto y esperar a que vuelva la señal",
    "q.m24#12.o1" to "Aplicar el plan de pérdida de contacto acordado antes de salir (por ejemplo, esperar en el punto de encuentro)",
    "q.m24#12.o2" to "Separarse para buscar cobertura",
    "q.m24#12.o3" to "Que todos desciendan de inmediato",
    "q.m24#12.e" to "Perder las comunicaciones en montaña es normal, no un accidente, y por eso debe tener un plan antes de salir. Con plan, la pérdida de contacto es una rama conocida; sin plan, se convierte en desconcierto sobre el terreno.",
    "q.m24#13.p" to "[Ordenar] Ordena la secuencia completa de atención a una persona gravemente lesionada.",
    "q.m24#13.o0" to "Asegurar la escena y evitar un segundo accidente",
    "q.m24#13.o1" to "Valorar consciencia, respiración y circulación; atender las amenazas vitales",
    "q.m24#13.o2" to "Pedir ayuda e informar de la ubicación exacta y las lesiones",
    "q.m24#13.o3" to "Aislar, inmovilizar y seguir observando mientras se espera la evacuación o el rescate profesional",
    "q.m24#13.e" to "El orden encarna primero la seguridad, después el tratamiento, con el aviso saliendo en paralelo y el mantenimiento después. El error más común en la práctica es saltarse el paso uno y lanzarse directamente al accidentado: la vía clásica a crear un segundo accidentado.",
    "q.m24#14.p" to "[Opción múltiple] ¿Qué habilidades de la escalada técnica deben practicarse en el terreno?",
    "q.m24#14.o0" to "La autodetención con piolet",
    "q.m24#14.o1" to "Los prusiks y los sistemas de cordada",
    "q.m24#14.o2" to "El montaje de reuniones",
    "q.m24#14.o3" to "La secuencia de rescate en grieta",
    "q.m24#14.o4" to "Memorizar los nombres y las altitudes de los catorce ochomiles",
    "q.m24#14.e" to "Ninguna de las cuatro se adquiere leyendo. Comparten que deben ejecutarse bajo presión, que no admiten casi margen de error y que dependen de la memoria muscular. Por eso esta app las marca repetidamente como pendientes de evaluación por un instructor.",
    "q.m24#15.p" to "[Situación] Has superado todas las evaluaciones teóricas. ¿Cómo debes considerar tu capacidad ahora?",
    "q.m24#15.o0" to "Ya puedes escalar un ochomil de forma autónoma",
    "q.m24#15.o1" to "Tienes una base teórica y un marco de juicio, pero cada habilidad técnica sigue necesitando una evaluación práctica de un instructor antes de usarla",
    "q.m24#15.o2" to "Puedes trabajar como guía",
    "q.m24#15.o3" to "Aprobar la teoría significa que la capacidad ya está",
    "q.m24#15.e" to "Es la afirmación más importante de todo el curso: comprender la teoría no es tener capacidad en el terreno. Esta app construye un marco cognitivo y de juicio; lo que de verdad te salva en una cara de hielo es el movimiento que has repetido varios cientos de veces en terreno seguro.",
    "q.m24#16.p" to "Después de completar todo el curso, ¿cuál es el activo central que has construido?",
    "q.m24#16.o0" to "Una lista de material",
    "q.m24#16.o1" to "Un marco de pensamiento para reconocer el riesgo, valorarlo y decidir, incluido saber cuándo no continuar",
    "q.m24#16.o2" to "Un certificado de montaña",
    "q.m24#16.o3" to "Un montón de datos",
    "q.m24#16.e" to "Desde lo básico de los 5.000 m hasta la evaluación final de los 8.000 m, el curso repite una cosa: la seguridad no es producto de la técnica sino del criterio, y la técnica existe para dar margen al criterio.",
    "q.m24#17.p" to "Completa: al decidir bajo incertidumbre, hay que adoptar primero la opinión más ( ).",
    "q.m24#17.a0" to "conservadora",
    "q.m24#17.e" to "«Primero lo conservador» es el principio de cierre de todo el curso: lo bastante simple para aplicarlo en el terreno y lo bastante fuerte para contrarrestar la mayoría de los sesgos cognitivos. La montaña siempre está; tú no.",
    // m25 — Cómo te ves a ti y al equipo
    "q.m25#0.p" to "Después de subir notas presión en la cabeza y te falta el aire, mientras el equipo sigue ascendiendo según lo previsto. ¿Qué hay que hacer?",
    "q.m25#0.o0" to "Aguantar: has llegado hasta aquí",
    "q.m25#0.o1" to "Parar y decírselo con sinceridad al guía o a tus compañeros, y después descansar y observar",
    "q.m25#0.o2" to "Tomar algo por tu cuenta y seguir el ritmo del equipo",
    "q.m25#0.o3" to "Acelerar: llegar antes al campamento lo arreglará",
    "q.m25#0.e" to "Hay dos cosas que nunca se deben hacer con las señales del cuerpo en altitud: esconderlas y automedicarse. El primer paso correcto es decir cómo te sientes con sinceridad y después parar a descansar y observar.\nNo es debilidad: el guía solo puede juzgar si lo sabe, y tú necesitas un periodo de observación para distinguir si aquello cede o empeora.",
    "q.m25#1.p" to "¿Por qué la frase «hemos llegado hasta aquí» es peligrosa en una salida de altura?",
    "q.m25#1.o0" to "Porque hace perder tiempo",
    "q.m25#1.o1" to "Porque convierte el tiempo ya invertido en una razón para seguir asumiendo riesgo",
    "q.m25#1.o2" to "Porque afecta al ambiente del equipo",
    "q.m25#1.o3" to "Porque suena poco profesional",
    "q.m25#1.e" to "Es pensamiento de coste irrecuperable de manual: hemos caminado hasta aquí, hemos gastado tanto, hemos pedido tantos días de vacaciones, así que no puede ser para nada.\nPero el riesgo no baja por lo mucho que hayas invertido. Lo gastado no se recupera, mientras que el coste de continuar puede ser más cosas que tampoco se recuperan.",
    "q.m25#2.p" to "Te das cuenta de que claramente no puedes seguir el ritmo del equipo y llevas un rato forzándolo. ¿Cuál es la mejor actitud?",
    "q.m25#2.o0" to "Apretar los dientes y aguantar para no frenar a los demás",
    "q.m25#2.o1" to "Decirlo con sinceridad y pedir al equipo que avance al ritmo del más lento",
    "q.m25#2.o2" to "Bajar el ritmo en silencio y fingir que todo va bien",
    "q.m25#2.o3" to "No decírselo a nadie y descender solo",
    "q.m25#2.e" to "Forzar el ritmo en altitud es un descubierto oculto: el coste inmediato es solo cansancio, pero se acumula hasta el desplome del día siguiente. Y un equipo que avanza al ritmo del más rápido arrastra a todos al límite.\nLo correcto es fijar el ritmo en lo que el más lento puede sostener, y eso protege a la vez al individuo y al equipo.",
    "q.m25#3.p" to "Un compañero dice que se encuentra algo raro pero insiste en que «está bien, puedo caminar». ¿Qué hay que hacer?",
    "q.m25#3.o0" to "Confiar en su criterio y seguir caminando",
    "q.m25#3.o1" to "Tomarlo en serio y decírselo al guía",
    "q.m25#3.o2" to "No interferir: dejar que decida él",
    "q.m25#3.o3" to "No tomarlo en serio: mucha gente dice eso",
    "q.m25#3.e" to "El malestar en altitud tiene un rasgo cruel: el criterio se afecta primero, así que «creo que estoy bien» pierde valor allí arriba.\nInformar al guía del estado de tu compañero es lo responsable: si de verdad no es nada, el coste es una comprobación de más; si no lo es, puede que seas el único que se dio cuenta a tiempo.",
    "q.m25#4.p" to "Antes de salir el guía dice que la ruta de mañana hay que pasarla encordados. Alguien piensa que «una pendiente tan suave no lo necesita». ¿Cuál es la comprensión correcta?",
    "q.m25#4.o0" to "Una pendiente suave de verdad no necesita cuerda",
    "q.m25#4.o1" to "Decidir si se va encordado es cosa del guía: él tiene la información del terreno y del manto nivoso",
    "q.m25#4.o2" to "Encordarse sirve sobre todo para ir ordenados",
    "q.m25#4.o3" to "Debe decidirlo el más en forma",
    "q.m25#4.e" to "Ver «suave» desde lejos y estar allí mirando el reparto de grietas, puentes de nieve y fisuras ocultas son dos cosas distintas. El guía tiene información que tú no tienes: ese es justamente su valor.\nEn las decisiones técnicas, dejar juzgar a quien tiene más información es la regla básica tanto de eficiencia como de seguridad.",
    "q.m25#5.p" to "Caminando en medio del equipo descubres que se te ha acabado el agua, pero el siguiente punto de avituallamiento está a dos horas. ¿Qué hay que hacer?",
    "q.m25#5.o0" to "Callarse y no molestar a nadie",
    "q.m25#5.o1" to "Decírselo de inmediato al jefe de cordada y ver si se puede coordinar",
    "q.m25#5.o2" to "Pedir agua al compañero más cercano sin decírselo al jefe de cordada",
    "q.m25#5.o3" to "Beber menos y seguir",
    "q.m25#5.e" to "Quedarse corto de agua o de comida es información de nivel de equipo, no una minucia personal: condiciona el juicio del jefe sobre el ritmo y el avituallamiento.\nPedir a un compañero en privado parece no dar importancia, pero corta la información: el jefe sigue creyendo que el equipo está bien y puede apretar según lo previsto.",
    "q.m25#6.p" to "¿Qué significa de verdad «lento es rápido» en altitud?",
    "q.m25#6.o0" to "Caminar despacio garantiza la cima",
    "q.m25#6.o1" to "Un ritmo constante y sostenible ahorra más tiempo, y es más seguro, que los arranques repetidos",
    "q.m25#6.o2" to "Lo lento es para acomodar a los menos en forma",
    "q.m25#6.o3" to "En altitud la velocidad no importa",
    "q.m25#6.e" to "En altitud el aporte de oxígeno es limitado, y los esfuerzos explosivos repetidos acumulan lactato rápido y empeoran la hipoxia.\nUn ritmo constante es en realidad más rápido: elimina la necesidad de paradas frecuentes de recuperación y reduce la probabilidad de tener que darse la vuelta por gasto excesivo. La frase describe el metabolismo energético, no es un consuelo.",
    "q.m25#7.p" to "Llegas al campamento dos horas más tarde de lo previsto y ya es de noche. ¿Qué hay que hacer?",
    "q.m25#7.o0" to "Seguir de noche hasta el campamento siguiente",
    "q.m25#7.o1" to "Acampar donde estás y comunicar tu posición a quienes esperan en casa",
    "q.m25#7.o2" to "Volver solo a buscar a algún rezagado",
    "q.m25#7.o3" to "Seguir caminando hasta alcanzar al grupo de delante",
    "q.m25#7.e" to "Avanzar de noche en altitud combina los peores factores: oscuridad, cansancio, frío e incapacidad de leer el terreno. Acampar donde estás es la decisión sensata.\nPero debe incluir una cosa más: comunicar tu posición al exterior. Así, si hace falta rescate, al menos alguien sabe dónde buscar. Actuar solo, en cambio, le cuesta al equipo dos personas de golpe.",
    "q.m25#8.p" to "Un compañero empeora claramente en la marcha y se va quedando atrás. El equipo se divide entre esperar o mandar a algunos por delante. ¿Cuál es el planteamiento más sensato?",
    "q.m25#8.o0" to "Que todo el equipo siga al ritmo original",
    "q.m25#8.o1" to "No separarse nunca: que todo el equipo baje el ritmo",
    "q.m25#8.o2" to "Asignar a una persona con experiencia para acompañarle mientras los demás siguen y se mantiene el contacto",
    "q.m25#8.o3" to "Dejar que camine despacio solo y reunirse en el campamento",
    "q.m25#8.e" to "Separarse conlleva su propio riesgo en altitud, pero con gente suficiente, asignar al más experimentado para acompañar al más lento mientras el resto sigue suele ser más sensato que frenar a todos o forzar a todos.\nTres cosas son imprescindibles: que alguien se quede con él, que se mantenga la comunicación y que el grupo de delante conozca la situación y la hora de llegada prevista. Quedarse completamente solo es la peor opción.",
    "q.m25#9.p" to "¿Cuál es la comprensión correcta del lugar de la cima en toda la salida?",
    "q.m25#9.o0" to "La cima es el final de la salida",
    "q.m25#9.o1" to "La cima es solo la mitad de la salida; el descenso es donde se concentra el riesgo",
    "q.m25#9.o2" to "La cima es lo único que importa",
    "q.m25#9.o3" to "Sin cima, la salida ha fracasado",
    "q.m25#9.e" to "Muchos accidentes ocurren en el descenso, porque la alerta cae una vez logrado el objetivo mientras la forma física ya está al límite.\nTratar la cima como «la mitad» significa presupuestar en el plan el mismo tiempo, energía y protección para el descenso, en lugar de gastarlo todo en subir.",
    "q.m25#10.p" to "Situación: las primeras 24 horas en altitud",
    "q.m25#10.c" to "Es tu primer trekking peak de 5.000 m. Después de llegar a un campamento a 4.300 m, pasan varias cosas en las siguientes 24 horas.",
    "q.m25#10.e" to "El sentido de estos cuatro pasos no es conocimiento médico, sino dos hábitos: decirlo con sinceridad y reevaluar. Lo que de verdad empuja a la gente al peligro en una salida de altura no es un juicio malo, sino una cadena de pequeñas decisiones —aguantar, no molestar— que se van acumulando.",
    "q.m25#10.s0.p" to "Paso 1: por la noche te aparece dolor de cabeza y pierdes el apetito. Un compañero dice que «es normal, duerme y se te pasa». ¿Qué hay que hacer?",
    "q.m25#10.s0.o0" to "Hacerle caso y dormir para que se pase",
    "q.m25#10.s0.o1" to "Decirle al guía con sinceridad cómo te sientes y después descansar, comer y beber en pequeñas cantidades y a menudo según las indicaciones",
    "q.m25#10.s0.o2" to "Buscar alguna medicina por tu cuenta y no decírselo a nadie",
    "q.m25#10.s0.o3" to "Tomar una copa para dormir mejor",
    "q.m25#10.s0.e" to "El dolor de cabeza y la pérdida de apetito son frecuentes en altitud, pero frecuente no significa que se pueda ignorar. Informar con sinceridad más medidas básicas —descanso, líquidos, algo de comida en pequeñas cantidades— es la respuesta estándar.\nLa clave es que el guía tiene que saberlo en el momento en que cambia tu estado, no descubrirlo a la mañana siguiente.",
    "q.m25#10.s1.p" to "Paso 2: casi no duermes en toda la noche. Por la mañana el equipo se prepara para seguir ascendiendo. ¿Qué eliges?",
    "q.m25#10.s1.o0" to "No decir nada y limitarte a seguir",
    "q.m25#10.s1.o1" to "Informar de cómo has dormido y dejar que el guía valore si se continúa",
    "q.m25#10.s1.o2" to "Decidir por tu cuenta quedarte atrás sin decírselo al equipo",
    "q.m25#10.s1.o3" to "Pedir a todo el equipo que pare y espere a que te recuperes",
    "q.m25#10.s1.e" to "Dormir mal es una de las molestias más comunes en altitud; por sí sola normalmente no justifica detener el ascenso, pero debe entrar en la valoración en lugar de cargarse en silencio.\nEl guía la sopesará junto con el dolor de cabeza, el apetito y cómo te mueves. Ese es el valor de su experiencia.",
    "q.m25#10.s2.p" to "Paso 3: el equipo sigue y te encuentras algo mejor que ayer, pero caminas despacio. ¿De qué mentalidad hay que desconfiar ahora?",
    "q.m25#10.s2.o0" to "Preocuparte de que se rían de ti",
    "q.m25#10.s2.o1" to "La sensación de «no puede ser para nada»: te hace resistirte a parar cuando deberías",
    "q.m25#10.s2.o2" to "Las ganas de hacer fotos",
    "q.m25#10.s2.o3" to "La preocupación por el tiempo",
    "q.m25#10.s2.e" to "El coste irrecuperable se dispara sobre todo el segundo día: lo has pasado mal toda la noche, así que renunciar ahora haría que ese sufrimiento no sirviera de nada.\nEsa lógica convierte un coste ya pagado en una razón para continuar, en lugar de en una señal para reevaluar.",
    "q.m25#10.s3.p" to "Paso 4: al final no haces cima; te das la vuelta a una hora de ella. ¿Cómo hay que ver esta salida?",
    "q.m25#10.s3.o0" to "Un fracaso: mejor no volver",
    "q.m25#10.s3.o1" to "Una experiencia útil de aclimatación; darse la vuelta fue criterio, no fracaso",
    "q.m25#10.s3.o2" to "Fue culpa de tus compañeros por frenarte",
    "q.m25#10.s3.o3" to "La próxima vez, cima pase lo que pase",
    "q.m25#10.s3.e" to "La aclimatación se construye con exposición repetida; una primera salida a 4.000–5.000 m nunca debía tener la cima como único objetivo.\nY saber darse la vuelta cuando toca es la capacidad más valorada de este deporte. Te llevará más lejos que cualquier cima afortunada.",
    "q.m25#11.p" to "Situación: presión del grupo",
    "q.m25#11.c" to "Cuarto día de la salida; el tiempo empieza a cambiar y el equipo está dividido. Tu propio criterio difiere algo del del grupo.",
    "q.m25#11.e" to "Esta situación trata de expresar una reserva. Es difícil en la práctica porque el coste parece social —estropear el ambiente, no encajar— mientras que el beneficio es invisible: un accidente que no ocurrió. Recuerda esos tres puntos y la próxima vez hablarás antes.",
    "q.m25#11.s0.p" to "Paso 1: algunos argumentan «apretemos, quizá mañana haga mejor tiempo»; otros quieren descender. Tú te inclinas por descender, pero no quieres ser quien lo estropee. ¿Qué hay que hacer?",
    "q.m25#11.s0.o0" to "Callarse y seguir la corriente",
    "q.m25#11.s0.o1" to "Exponer tu juicio y el razonamiento que hay detrás",
    "q.m25#11.s0.o2" to "Quejarse en privado y dejarlo ahí",
    "q.m25#11.s0.o3" to "Fingir que apoyas continuar y guardarte las dudas",
    "q.m25#11.s0.e" to "La minoría silenciosa es un habitual en los análisis de accidentes. Tener una reserva y no expresarla significa que el equipo decide con información incompleta.\nEl coste de hablar es pequeño, quizá cero; el coste del silencio puede ser muy grande.",
    "q.m25#11.s1.p" to "Paso 2: tras la discusión el equipo decide continuar, pero tú sigues sin verlo claro. ¿Y ahora?",
    "q.m25#11.s1.o0" to "Cumplir de forma pasiva y hacer lo mínimo",
    "q.m25#11.s1.o1" to "Dejar clara tu reserva y confirmar las condiciones de regreso y el plan de retirada del equipo",
    "q.m25#11.s1.o2" to "Descender solo de inmediato",
    "q.m25#11.s1.o3" to "No decir nada más pero guardar el resentimiento",
    "q.m25#11.s1.e" to "Una vez tomada la decisión quedan tres cosas: dejar constancia clara (no estaba de acuerdo, porque…), confirmar que las condiciones de retirada son explícitas y asegurarte de que sigues dispuesto y capaz de ejecutar.\nUna reserva no es cumplimiento pasivo: tras decir lo tuyo, haces tu parte como es debido.",
    "q.m25#11.s2.p" to "Paso 3: resulta que tu preocupación era acertada y el equipo desciende antes de tiempo. ¿Qué valor tiene esta experiencia?",
    "q.m25#11.s2.o0" to "Demuestra que eres mejor que los demás",
    "q.m25#11.s2.o1" to "Confirma que expresar una reserva a tiempo es eficaz y no daña las relaciones",
    "q.m25#11.s2.o2" to "Demuestra que en el futuro deberías actuar por tu cuenta",
    "q.m25#11.s2.o3" to "No mucho, ya que no hiciste cima",
    "q.m25#11.s2.e" to "Mucha gente teme la primera vez que expresa una reserva que se le vea como alguien que no encaja. En realidad un buen equipo acaba con más confianza mutua por ello, porque demuestra que alguien está dispuesto a decir la verdad.\nGuarda esta experiencia; la próxima vez hablarás antes.",
)
